            migrationBuilder.Sql("""
                INSERT INTO "SpellComponents" ("Label", "Key", "Value", "Html", "SpellId") VALUES
                    ('Level', 'level', '{"levelNumber":"8","label":"8th"}', '<div> <div> Level </div> <div> 8th </div> </div>', '346557dd-e582-4c53-9462-68ae47bd33dc'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Action","kind":"action","value":1,"unit":"action","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Action </div> </div>', '346557dd-e582-4c53-9462-68ae47bd33dc'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"150 ft. (30 ft.)","kind":"distance","distanceValue":150,"distanceUnit":"ft","area":{"shape":null,"value":30,"unit":"ft"}}', '<div> <div> Range/Area </div> <div> 150 ft. <span>(30 ft. <i></i>)</span> </div> </div>', '346557dd-e582-4c53-9462-68ae47bd33dc'::uuid),
                    ('Components', 'components', '{"text":"V, S, M *","verbal":true,"somatic":true,"material":{"required":true,"description":"a bit of sponge","consumed":false,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S, M *</span> </div> </div>', '346557dd-e582-4c53-9462-68ae47bd33dc'::uuid),
                    ('Duration', 'duration', '{"text":"Instantaneous","kind":"instantaneous","value":null,"unit":null,"concentration":false,"endCondition":null}', '<div> <div>Duration</div> <div> Instantaneous </div> </div>', '346557dd-e582-4c53-9462-68ae47bd33dc'::uuid),
                    ('School', 'school', 'Necromancy', '<div> <div> School </div> <div> Necromancy </div> </div>', '346557dd-e582-4c53-9462-68ae47bd33dc'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"CON Save","kind":"save","attackType":null,"ability":"CON"}', '<div> <div> Attack/Save </div> <div> <i></i> <span>CON Save</span> </div> </div>', '346557dd-e582-4c53-9462-68ae47bd33dc'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Necrotic","damageTypes":["Necrotic"]}', '<div> <div> Damage/Effect </div> <div> <i></i> Necrotic </div> </div>', '346557dd-e582-4c53-9462-68ae47bd33dc'::uuid),
                    ('Description', 'description', '["You draw the moisture from every creature in a 30-foot cube centered on a point you choose within range. Each creature in that area must make a Constitution saving throw. Constructs and undead aren’t affected, and plants and water elementals make this saving throw with disadvantage. A creature takes 12d8 necrotic damage on a failed save, or half as much damage on a successful one.","Nonmagical plants in the area that aren’t creatures, such as trees and shrubs, wither and die instantly."]', '<div> <p>You draw the moisture from every creature in a 30-foot cube centered on a point you choose within range. Each creature in that area must make a Constitution saving throw. Constructs and undead aren’t affected, and plants and water elementals make this saving throw with disadvantage. A creature takes 12d8 necrotic damage on a failed save, or half as much damage on a successful one.</p> <p>Nonmagical plants in the area that aren’t creatures, such as trees and shrubs, wither and die instantly.</p> <span>* - (a bit of sponge)</span> </div>', '346557dd-e582-4c53-9462-68ae47bd33dc'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', '346557dd-e582-4c53-9462-68ae47bd33dc'::uuid),
                    ('Spell Tags', 'spellTags', '["Damage"]', '', '346557dd-e582-4c53-9462-68ae47bd33dc'::uuid),
                    ('Available For', 'availableFor', '["Sorcerer (Legacy)","Wizard (Legacy)","Sorcerer","Wizard"]', '', '346557dd-e582-4c53-9462-68ae47bd33dc'::uuid),
                    ('Source', 'source', 'Elemental Evil Player''s Companion, pg. 150', '', '346557dd-e582-4c53-9462-68ae47bd33dc'::uuid),
                    ('Source URL', 'url', 'https://www.dndbeyond.com/spells/2367-abi-dalzims-horrid-wilting', '', '346557dd-e582-4c53-9462-68ae47bd33dc'::uuid),
                    ('Image', 'imageUrl', 'https://www.dndbeyond.com/attachments/2/720/necromancy.png', '', '346557dd-e582-4c53-9462-68ae47bd33dc'::uuid),
                    ('Level', 'level', '{"levelNumber":"1","label":"1st"}', '<div> <div> Level </div> <div> 1st </div> </div>', '71c376e9-5c94-4c24-b6c6-580416b26abb'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Reaction *","kind":"reaction","value":1,"unit":"action","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Reaction * </div> </div>', '71c376e9-5c94-4c24-b6c6-580416b26abb'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"Self","kind":"self","distanceValue":null,"distanceUnit":null,"area":null}', '<div> <div> Range/Area </div> <div> Self </div> </div>', '71c376e9-5c94-4c24-b6c6-580416b26abb'::uuid),
                    ('Components', 'components', '{"text":"S","verbal":false,"somatic":true,"material":{"required":false,"description":null,"consumed":null,"costGp":null}}', '<div> <div> Components </div> <div> <span>S</span> </div> </div>', '71c376e9-5c94-4c24-b6c6-580416b26abb'::uuid),
                    ('Duration', 'duration', '{"text":"1 Round","kind":"timed","value":1,"unit":"round","concentration":false,"endCondition":null}', '<div> <div>Duration</div> <div> 1 Round </div> </div>', '71c376e9-5c94-4c24-b6c6-580416b26abb'::uuid),
                    ('School', 'school', 'Abjuration', '<div> <div> School </div> <div> Abjuration </div> </div>', '71c376e9-5c94-4c24-b6c6-580416b26abb'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"None","kind":"none","attackType":null,"ability":null}', '<div> <div> Attack/Save </div> <div> <span>None</span> </div> </div>', '71c376e9-5c94-4c24-b6c6-580416b26abb'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Acid (...)","damageTypes":["Acid"]}', '<div> <div> Damage/Effect </div> <div> <i></i> Acid (...) </div> </div>', '71c376e9-5c94-4c24-b6c6-580416b26abb'::uuid),
                    ('Description', 'description', '["The spell captures some of the incoming energy, lessening its effect on you and storing it for your next melee attack. You have resistance to the triggering damage type until the start of your next turn. Also, the first time you hit with a melee attack on your next turn, the target takes an extra 1d6 damage of the triggering type, and the spell ends.","At Higher Levels. When you cast this spell using a spell slot of 2nd level or higher, the extra damage increases by 1d6 for each slot level above 1st."]', '<div> <p>The spell captures some of the incoming energy, lessening its effect on you and storing it for your next melee attack. You have resistance to the triggering damage type until the start of your next turn. Also, the first time you hit with a melee attack on your next turn, the target takes an extra 1d6 damage of the triggering type, and the spell ends.</p> <p><strong><em>At Higher Levels.</em></strong> When you cast this spell using a spell slot of 2nd level or higher, the extra damage increases by 1d6 for each slot level above 1st.</p> <span>* - which you take when you take acid, cold, fire, lightning, or thunder damage</span> </div>', '71c376e9-5c94-4c24-b6c6-580416b26abb'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '* - which you take when you take acid, cold, fire, lightning, or thunder damage', '', '71c376e9-5c94-4c24-b6c6-580416b26abb'::uuid),
