                    ('Attack/Save', 'attackSave', '{"text":"DEX Save","kind":"save","attackType":null,"ability":"DEX"}', '<div> <div> Attack/Save </div> <div> <i></i> <span>DEX Save</span> </div> </div>', '86aa1af7-e6bb-4792-95e5-fe0ad5865136'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Fire","damageTypes":["Fire"]}', '<div> <div> Damage/Effect </div> <div> <i></i> Fire </div> </div>', '86aa1af7-e6bb-4792-95e5-fe0ad5865136'::uuid),
                    ('Description', 'description', '["A line of roaring flame 30 feet long and 5 feet wide emanates from you in a direction you choose. Each creature in the line must make a Dexterity saving throw. A creature takes 3d8 fire damage on a failed save, or half as much damage on a successful one.","At Higher Levels. When you cast this spell using a spell slot of 3rd level or higher, the damage increases by 1d8 for each slot level above 2nd."]', '<div> <p><span>A line of roaring flame 30 feet long and 5 feet wide emanates from you in a direction you choose. Each creature in the line must make a Dexterity saving throw. A creature takes 3d8 fire damage on a failed save, or half as much damage on a successful one.</span></p> <p><b>At Higher Levels. </b>When you cast this spell using a spell slot of 3rd level or higher, the damage increases by 1d8 for each slot level above 2nd.</p> <span>* - (a red dragon''s scale)</span> </div>', '86aa1af7-e6bb-4792-95e5-fe0ad5865136'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', '86aa1af7-e6bb-4792-95e5-fe0ad5865136'::uuid),
