                    ('Attack/Save', 'attackSave', '{"text":"None","kind":"none","attackType":null,"ability":null}', '<div> <div> Attack/Save </div> <div> <span>None</span> </div> </div>', 'dcfcc926-e40f-4687-921a-104acba03ff1'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Buff","damageTypes":[]}', '<div> <div> Damage/Effect </div> <div> Buff </div> </div>', 'dcfcc926-e40f-4687-921a-104acba03ff1'::uuid),
                    ('Description', 'description', '["Choose up to three creatures within range. Each target’s Hit Point maximum and current Hit Points increase by 5 for the duration.","Using a Higher-Level Spell Slot. Each target’s Hit Points increase by 5 for each spell slot level above 2."]', '<div> <p>Choose up to three creatures within range. Each target’s Hit Point maximum and current Hit Points increase by 5 for the duration.</p> <p><strong><em>Using a Higher-Level Spell Slot.</em></strong> Each target’s Hit Points increase by 5 for each spell slot level above 2.</p> <span>* - (a strip of white cloth)</span> </div>', 'dcfcc926-e40f-4687-921a-104acba03ff1'::uuid),
