                    ('Level', 'level', '{"levelNumber":"1","label":"1st"}', '<div> <div> Level </div> <div> 1st </div> </div>', '4d50c119-493d-475d-a06b-c4ccc9a4bae5'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Minute Ritual","kind":"timed","value":1,"unit":"minute","trigger":null,"ritual":true}', '<div> <div> Casting Time </div> <div> 1 Minute <i>Ritual</i> </div> </div>', '4d50c119-493d-475d-a06b-c4ccc9a4bae5'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"30 ft. (20 ft.)","kind":"distance","distanceValue":30,"distanceUnit":"ft","area":{"shape":null,"value":20,"unit":"ft"}}', '<div> <div> Range/Area </div> <div> 30 ft. <span>(20 ft. <i></i>)</span> </div> </div>', '4d50c119-493d-475d-a06b-c4ccc9a4bae5'::uuid),
                    ('Components', 'components', '{"text":"V, S, M *","verbal":true,"somatic":true,"material":{"required":true,"description":"a bell and silver wire","consumed":false,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S, M *</span> </div> </div>', '4d50c119-493d-475d-a06b-c4ccc9a4bae5'::uuid),
                    ('Duration', 'duration', '{"text":"8 Hours","kind":"timed","value":8,"unit":"hour","concentration":false,"endCondition":null}', '<div> <div>Duration</div> <div> 8 Hours </div> </div>', '4d50c119-493d-475d-a06b-c4ccc9a4bae5'::uuid),
                    ('School', 'school', 'Abjuration', '<div> <div> School </div> <div> Abjuration </div> </div>', '4d50c119-493d-475d-a06b-c4ccc9a4bae5'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"None","kind":"none","attackType":null,"ability":null}', '<div> <div> Attack/Save </div> <div> <span>None</span> </div> </div>', '4d50c119-493d-475d-a06b-c4ccc9a4bae5'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Detection","damageTypes":[]}', '<div> <div> Damage/Effect </div> <div> Detection </div> </div>', '4d50c119-493d-475d-a06b-c4ccc9a4bae5'::uuid),
                    ('Description', 'description', '["You set an alarm against intrusion. Choose a door, a window, or an area within range that is no larger than a 20-foot Cube. Until the spell ends, an alarm alerts you whenever a creature touches or enters the warded area. When you cast the spell, you can designate creatures that won’t set off the alarm. You also choose whether the alarm is audible or mental:","Audible Alarm. The alarm produces the sound of a handbell for 10 seconds within 60 feet of the warded area.","Mental Alarm. You are alerted by a mental ping if you are within 1 mile of the warded area. This ping awakens you if you’re asleep."]', '<div> <p>You set an alarm against intrusion. Choose a door, a window, or an area within range that is no larger than a 20-foot Cube. Until the spell ends, an alarm alerts you whenever a creature touches or enters the warded area. When you cast the spell, you can designate creatures that won’t set off the alarm. You also choose whether the alarm is audible or mental:</p> <p><strong>Audible Alarm.</strong> The alarm produces the sound of a handbell for 10 seconds within 60 feet of the warded area.</p> <p><strong>Mental Alarm.</strong> You are alerted by a mental ping if you are within 1 mile of the warded area. This ping awakens you if you’re asleep.</p> <span>* - (a bell and silver wire)</span> </div>', '4d50c119-493d-475d-a06b-c4ccc9a4bae5'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', '4d50c119-493d-475d-a06b-c4ccc9a4bae5'::uuid),
                    ('Spell Tags', 'spellTags', '["Detection"]', '', '4d50c119-493d-475d-a06b-c4ccc9a4bae5'::uuid),
                    ('Available For', 'availableFor', '["Ranger (Legacy)","Wizard (Legacy)","Artificer (Legacy)","Ranger","Wizard","Artificer","Paladin - Oath of the Watchers (TCoE)","Sorcerer - Clockwork Sorcery"]', '', '4d50c119-493d-475d-a06b-c4ccc9a4bae5'::uuid),
