                    ('Image', 'imageUrl', 'https://www.dndbeyond.com/attachments/2/707/abjuration.png', '', '4d50c119-493d-475d-a06b-c4ccc9a4bae5'::uuid),
                    ('Level', 'level', '{"levelNumber":"2","label":"2nd"}', '<div> <div> Level </div> <div> 2nd </div> </div>', '34daf26b-18fc-44a7-ac77-cd8cd079f773'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Action","kind":"action","value":1,"unit":"action","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Action </div> </div>', '34daf26b-18fc-44a7-ac77-cd8cd079f773'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"Self","kind":"self","distanceValue":null,"distanceUnit":null,"area":null}', '<div> <div> Range/Area </div> <div> Self </div> </div>', '34daf26b-18fc-44a7-ac77-cd8cd079f773'::uuid),
                    ('Components', 'components', '{"text":"V, S","verbal":true,"somatic":true,"material":{"required":false,"description":null,"consumed":null,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S</span> </div> </div>', '34daf26b-18fc-44a7-ac77-cd8cd079f773'::uuid),
                    ('Duration', 'duration', '{"text":"Concentration 1 Hour","kind":"timed","value":1,"unit":"hour","concentration":true,"endCondition":null}', '<div> <div>Duration</div> <div> <i>Concentration</i> 1 Hour </div> </div>', '34daf26b-18fc-44a7-ac77-cd8cd079f773'::uuid),
                    ('School', 'school', 'Transmutation', '<div> <div> School </div> <div> Transmutation </div> </div>', '34daf26b-18fc-44a7-ac77-cd8cd079f773'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"None","kind":"none","attackType":null,"ability":null}', '<div> <div> Attack/Save </div> <div> <span>None</span> </div> </div>', '34daf26b-18fc-44a7-ac77-cd8cd079f773'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Shapechanging","damageTypes":[]}', '<div> <div> Damage/Effect </div> <div> Shapechanging </div> </div>', '34daf26b-18fc-44a7-ac77-cd8cd079f773'::uuid),
                    ('Description', 'description', '["You alter your physical form. Choose one of the following options. Its effects last for the duration, during which you can take a Magic action to replace the option you chose with a different one.","Aquatic Adaptation. You sprout gills and grow webs between your fingers. You can breathe underwater and gain a Swim Speed equal to your Speed.","Change Appearance. You alter your appearance. You decide what you look like, including your height, weight, facial features, sound of your voice, hair length, coloration, and other distinguishing characteristics. You can make yourself appear as a member of another species, though none of your statistics change. You can’t appear as a creature of a different size, and your basic shape stays the same; if you’re bipedal, you can’t use this spell to become quadrupedal, for instance. For the duration, you can take a Magic action to change your appearance in this way again.","Natural Weapons. You grow claws (Slashing), fangs (Piercing), horns (Piercing), or hooves (Bludgeoning). When you use your Unarmed Strike to deal damage with that new growth, it deals 1d6 damage of the type in parentheses instead of dealing the normal damage for your Unarmed Strike, and you use your spellcasting ability modifier for the attack and damage rolls rather than using Strength."]', '<div> <p>You alter your physical form. Choose one of the following options. Its effects last for the duration, during which you can take a <a>Magic</a> action to replace the option you chose with a different one.</p> <p><strong><em>Aquatic Adaptation.</em></strong> You sprout gills and grow webs between your fingers. You can breathe underwater and gain a Swim Speed equal to your Speed.</p> <p><strong><em>Change Appearance.</em></strong> You alter your appearance. You decide what you look like, including your height, weight, facial features, sound of your voice, hair length, coloration, and other distinguishing characteristics. You can make yourself appear as a member of another species, though none of your statistics change. You can’t appear as a creature of a different size, and your basic shape stays the same; if you’re bipedal, you can’t use this spell to become quadrupedal, for instance. For the duration, you can take a <a>Magic</a> action to change your appearance in this way again.</p> <p><strong><em>Natural Weapons.</em></strong> You grow claws (Slashing), fangs (Piercing), horns (Piercing), or hooves (Bludgeoning). When you use your Unarmed Strike to deal damage with that new growth, it deals 1d6 damage of the type in parentheses instead of dealing the normal damage for your Unarmed Strike, and you use your spellcasting ability modifier for the attack and damage rolls rather than using Strength.</p> </div>', '34daf26b-18fc-44a7-ac77-cd8cd079f773'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', '34daf26b-18fc-44a7-ac77-cd8cd079f773'::uuid),
                    ('Spell Tags', 'spellTags', '["Shapechanging"]', '', '34daf26b-18fc-44a7-ac77-cd8cd079f773'::uuid),
