                    ('Source', 'source', 'Player’s Handbook, pg. 239', '', '34daf26b-18fc-44a7-ac77-cd8cd079f773'::uuid),
                    ('Source URL', 'url', 'https://www.dndbeyond.com/spells/2618846-alter-self', '', '34daf26b-18fc-44a7-ac77-cd8cd079f773'::uuid),
                    ('Image', 'imageUrl', 'https://www.dndbeyond.com/attachments/2/722/transmutation.png', '', '34daf26b-18fc-44a7-ac77-cd8cd079f773'::uuid),
                    ('Level', 'level', '{"levelNumber":"1","label":"1st"}', '<div> <div> Level </div> <div> 1st </div> </div>', '113f714d-0a05-4021-b046-735d14dcdcde'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Action","kind":"action","value":1,"unit":"action","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Action </div> </div>', '113f714d-0a05-4021-b046-735d14dcdcde'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"30 ft.","kind":"distance","distanceValue":30,"distanceUnit":"ft","area":null}', '<div> <div> Range/Area </div> <div> 30 ft. </div> </div>', '113f714d-0a05-4021-b046-735d14dcdcde'::uuid),
                    ('Components', 'components', '{"text":"V, S, M *","verbal":true,"somatic":true,"material":{"required":true,"description":"a morsel of food","consumed":false,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S, M *</span> </div> </div>', '113f714d-0a05-4021-b046-735d14dcdcde'::uuid),
                    ('Duration', 'duration', '{"text":"24 Hours","kind":"timed","value":24,"unit":"hour","concentration":false,"endCondition":null}', '<div> <div>Duration</div> <div> 24 Hours </div> </div>', '113f714d-0a05-4021-b046-735d14dcdcde'::uuid),
                    ('School', 'school', 'Enchantment', '<div> <div> School </div> <div> Enchantment </div> </div>', '113f714d-0a05-4021-b046-735d14dcdcde'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"WIS Save","kind":"save","attackType":null,"ability":"WIS"}', '<div> <div> Attack/Save </div> <div> <i></i> <span>WIS Save</span> </div> </div>', '113f714d-0a05-4021-b046-735d14dcdcde'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Charmed","damageTypes":[]}', '<div> <div> Damage/Effect </div> <div> <i></i> Charmed </div> </div>', '113f714d-0a05-4021-b046-735d14dcdcde'::uuid),
                    ('Description', 'description', '["Target a Beast that you can see within range. The target must succeed on a Wisdom saving throw or have the Charmed condition for the duration. If you or one of your allies deals damage to the target, the spell ends.","Using a Higher-Level Spell Slot. You can target one additional Beast for each spell slot level above 1."]', '<div> <p>Target a Beast that you can see within range. The target must succeed on a Wisdom saving throw or have the <a>Charmed</a> condition for the duration. If you or one of your allies deals damage to the target, the spell ends.</p> <p><strong><em>Using a Higher-Level Spell Slot.</em></strong> You can target one additional Beast for each spell slot level above 1.</p> <span>* - (a morsel of food)</span> </div>', '113f714d-0a05-4021-b046-735d14dcdcde'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', '113f714d-0a05-4021-b046-735d14dcdcde'::uuid),
                    ('Spell Tags', 'spellTags', '["Control","Social"]', '', '113f714d-0a05-4021-b046-735d14dcdcde'::uuid),
                    ('Available For', 'availableFor', '["Bard (Legacy)","Druid (Legacy)","Ranger (Legacy)","Bard","Druid","Ranger","Cleric - Nature Domain (PHB)","Warlock - Horned King Patron"]', '', '113f714d-0a05-4021-b046-735d14dcdcde'::uuid),
                    ('Source', 'source', 'Player’s Handbook, pg. 239', '', '113f714d-0a05-4021-b046-735d14dcdcde'::uuid),
                    ('Source URL', 'url', 'https://www.dndbeyond.com/spells/2618847-animal-friendship', '', '113f714d-0a05-4021-b046-735d14dcdcde'::uuid),
                    ('Image', 'imageUrl', 'https://www.dndbeyond.com/attachments/2/702/enchantment.png', '', '113f714d-0a05-4021-b046-735d14dcdcde'::uuid),
                    ('Level', 'level', '{"levelNumber":"2","label":"2nd"}', '<div> <div> Level </div> <div> 2nd </div> </div>', '75e5de35-e094-4139-be03-6d99136d0e5c'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Action Ritual","kind":"action","value":1,"unit":"action","trigger":null,"ritual":true}', '<div> <div> Casting Time </div> <div> 1 Action <i>Ritual</i> </div> </div>', '75e5de35-e094-4139-be03-6d99136d0e5c'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"30 ft.","kind":"distance","distanceValue":30,"distanceUnit":"ft","area":null}', '<div> <div> Range/Area </div> <div> 30 ft. </div> </div>', '75e5de35-e094-4139-be03-6d99136d0e5c'::uuid),
                    ('Components', 'components', '{"text":"V, S, M *","verbal":true,"somatic":true,"material":{"required":true,"description":"a morsel of food","consumed":false,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S, M *</span> </div> </div>', '75e5de35-e094-4139-be03-6d99136d0e5c'::uuid),
                    ('Duration', 'duration', '{"text":"24 Hours","kind":"timed","value":24,"unit":"hour","concentration":false,"endCondition":null}', '<div> <div>Duration</div> <div> 24 Hours </div> </div>', '75e5de35-e094-4139-be03-6d99136d0e5c'::uuid),
                    ('School', 'school', 'Enchantment', '<div> <div> School </div> <div> Enchantment </div> </div>', '75e5de35-e094-4139-be03-6d99136d0e5c'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"CHA Save","kind":"save","attackType":null,"ability":"CHA"}', '<div> <div> Attack/Save </div> <div> <i></i> <span>CHA Save</span> </div> </div>', '75e5de35-e094-4139-be03-6d99136d0e5c'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Communication (...)","damageTypes":[]}', '<div> <div> Damage/Effect </div> <div> Communication (...) </div> </div>', '75e5de35-e094-4139-be03-6d99136d0e5c'::uuid),
                    ('Description', 'description', '["A Tiny Beast of your choice that you can see within range must succeed on a Charisma saving throw, or it attempts to deliver a message for you (if the target’s Challenge Rating isn’t 0, it automatically succeeds). You specify a location you have visited and a recipient who matches a general description, such as “a person dressed in the uniform of the town guard” or “a red-haired dwarf wearing a pointed hat.” You also communicate a message of up to twenty-five words. The Beast travels for the duration toward the specified location, covering about 25 miles per 24 hours or 50 miles if the Beast can fly.","When the Beast arrives, it delivers your message to the creature that you described, mimicking your communication. If the Beast doesn’t reach its destination before the spell ends, the message is lost, and the Beast returns to where you cast the spell.","Using a Higher-Level Spell Slot. The spell’s duration increases by 48 hours for each spell slot level above 2."]', '<div> <p>A Tiny Beast of your choice that you can see within range must succeed on a Charisma saving throw, or it attempts to deliver a message for you (if the target’s Challenge Rating isn’t 0, it automatically succeeds). You specify a location you have visited and a recipient who matches a general description, such as “a person dressed in the uniform of the town guard” or “a red-haired dwarf wearing a pointed hat.” You also communicate a message of up to twenty-five words. The Beast travels for the duration toward the specified location, covering about 25 miles per 24 hours or 50 miles if the Beast can fly.</p> <p>When the Beast arrives, it delivers your message to the creature that you described, mimicking your communication. If the Beast doesn’t reach its destination before the spell ends, the message is lost, and the Beast returns to where you cast the spell.</p> <p><strong><em>Using a Higher-Level Spell Slot.</em></strong> The spell’s duration increases by 48 hours for each spell slot level above 2.</p> <span>* - (a morsel of food)</span> </div>', '75e5de35-e094-4139-be03-6d99136d0e5c'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', '75e5de35-e094-4139-be03-6d99136d0e5c'::uuid),
                    ('Spell Tags', 'spellTags', '["Communication","Social"]', '', '75e5de35-e094-4139-be03-6d99136d0e5c'::uuid),
                    ('Available For', 'availableFor', '["Bard (Legacy)","Druid (Legacy)","Ranger (Legacy)","Bard","Druid","Ranger"]', '', '75e5de35-e094-4139-be03-6d99136d0e5c'::uuid),
                    ('Source', 'source', 'Player’s Handbook, pg. 240', '', '75e5de35-e094-4139-be03-6d99136d0e5c'::uuid),
                    ('Source URL', 'url', 'https://www.dndbeyond.com/spells/2618850-animal-messenger', '', '75e5de35-e094-4139-be03-6d99136d0e5c'::uuid),
                    ('Image', 'imageUrl', 'https://www.dndbeyond.com/attachments/2/702/enchantment.png', '', '75e5de35-e094-4139-be03-6d99136d0e5c'::uuid),
                    ('Level', 'level', '{"levelNumber":"8","label":"8th"}', '<div> <div> Level </div> <div> 8th </div> </div>', 'c7a9f844-340e-4c0f-acb4-1d341ac4f960'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Action","kind":"action","value":1,"unit":"action","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Action </div> </div>', 'c7a9f844-340e-4c0f-acb4-1d341ac4f960'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"30 ft.","kind":"distance","distanceValue":30,"distanceUnit":"ft","area":null}', '<div> <div> Range/Area </div> <div> 30 ft. </div> </div>', 'c7a9f844-340e-4c0f-acb4-1d341ac4f960'::uuid),
                    ('Components', 'components', '{"text":"V, S","verbal":true,"somatic":true,"material":{"required":false,"description":null,"consumed":null,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S</span> </div> </div>', 'c7a9f844-340e-4c0f-acb4-1d341ac4f960'::uuid),
                    ('Duration', 'duration', '{"text":"24 Hours","kind":"timed","value":24,"unit":"hour","concentration":false,"endCondition":null}', '<div> <div>Duration</div> <div> 24 Hours </div> </div>', 'c7a9f844-340e-4c0f-acb4-1d341ac4f960'::uuid),
                    ('School', 'school', 'Transmutation', '<div> <div> School </div> <div> Transmutation </div> </div>', 'c7a9f844-340e-4c0f-acb4-1d341ac4f960'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"None","kind":"none","attackType":null,"ability":null}', '<div> <div> Attack/Save </div> <div> <span>None</span> </div> </div>', 'c7a9f844-340e-4c0f-acb4-1d341ac4f960'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Shapechanging","damageTypes":[]}', '<div> <div> Damage/Effect </div> <div> Shapechanging </div> </div>', 'c7a9f844-340e-4c0f-acb4-1d341ac4f960'::uuid),
                    ('Description', 'description', '["Choose any number of willing creatures that you can see within range. Each target shape-shifts into a Large or smaller Beast of your choice that has a Challenge Rating of 4 or lower. You can choose a different form for each target. On later turns, you can take a Magic action to transform the targets again.","A target’s game statistics are replaced by the chosen Beast’s statistics, but the target retains its creature type; Hit Points; Hit Point Dice; alignment; ability to communicate; and Intelligence, Wisdom, and Charisma scores. The target’s actions are limited by the Beast form’s anatomy, and it can’t cast spells. The target’s equipment melds into the new form, and the target can’t use any of that equipment while in that form.","The target gains a number of Temporary Hit Points equal to the Hit Points of the first form into which it shape-shifts. These Temporary Hit Points vanish if any remain when the spell ends. The transformation lasts for the duration or until the target ends it as a Bonus Action."]', '<div> <p>Choose any number of willing creatures that you can see within range. Each target <a>shape-shifts</a> into a Large or smaller Beast of your choice that has a Challenge Rating of 4 or lower. You can choose a different form for each target. On later turns, you can take a <a>Magic</a> action to transform the targets again.</p> <p>A target’s game statistics are replaced by the chosen Beast’s statistics, but the target retains its creature type; Hit Points; Hit Point Dice; alignment; ability to communicate; and Intelligence, Wisdom, and Charisma scores. The target’s actions are limited by the Beast form’s anatomy, and it can’t cast spells. The target’s equipment melds into the new form, and the target can’t use any of that equipment while in that form.</p> <p>The target gains a number of <a>Temporary Hit Points</a> equal to the Hit Points of the first form into which it shape-shifts. These Temporary Hit Points vanish if any remain when the spell ends. The transformation lasts for the duration or until the target ends it as a Bonus Action.</p> </div>', 'c7a9f844-340e-4c0f-acb4-1d341ac4f960'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', 'c7a9f844-340e-4c0f-acb4-1d341ac4f960'::uuid),
                    ('Spell Tags', 'spellTags', '["Shapechanging"]', '', 'c7a9f844-340e-4c0f-acb4-1d341ac4f960'::uuid),
                    ('Available For', 'availableFor', '["Druid (Legacy)","Druid"]', '', 'c7a9f844-340e-4c0f-acb4-1d341ac4f960'::uuid),
                    ('Source', 'source', 'Player’s Handbook, pg. 240', '', 'c7a9f844-340e-4c0f-acb4-1d341ac4f960'::uuid),
                    ('Source URL', 'url', 'https://www.dndbeyond.com/spells/2618851-animal-shapes', '', 'c7a9f844-340e-4c0f-acb4-1d341ac4f960'::uuid),
                    ('Image', 'imageUrl', 'https://www.dndbeyond.com/attachments/2/722/transmutation.png', '', 'c7a9f844-340e-4c0f-acb4-1d341ac4f960'::uuid),
                    ('Level', 'level', '{"levelNumber":"3","label":"3rd"}', '<div> <div> Level </div> <div> 3rd </div> </div>', 'ea6386f3-2515-45d0-8e5f-6ab2c8d5148f'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Minute","kind":"timed","value":1,"unit":"minute","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Minute </div> </div>', 'ea6386f3-2515-45d0-8e5f-6ab2c8d5148f'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"10 ft.","kind":"distance","distanceValue":10,"distanceUnit":"ft","area":null}', '<div> <div> Range/Area </div> <div> 10 ft. </div> </div>', 'ea6386f3-2515-45d0-8e5f-6ab2c8d5148f'::uuid),
                    ('Components', 'components', '{"text":"V, S, M *","verbal":true,"somatic":true,"material":{"required":true,"description":"a drop of blood, a piece of flesh, and a pinch of bone dust","consumed":false,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S, M *</span> </div> </div>', 'ea6386f3-2515-45d0-8e5f-6ab2c8d5148f'::uuid),
                    ('Duration', 'duration', '{"text":"Instantaneous","kind":"instantaneous","value":null,"unit":null,"concentration":false,"endCondition":null}', '<div> <div>Duration</div> <div> Instantaneous </div> </div>', 'ea6386f3-2515-45d0-8e5f-6ab2c8d5148f'::uuid),
                    ('School', 'school', 'Necromancy', '<div> <div> School </div> <div> Necromancy </div> </div>', 'ea6386f3-2515-45d0-8e5f-6ab2c8d5148f'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"None","kind":"none","attackType":null,"ability":null}', '<div> <div> Attack/Save </div> <div> <span>None</span> </div> </div>', 'ea6386f3-2515-45d0-8e5f-6ab2c8d5148f'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Creation","damageTypes":[]}', '<div> <div> Damage/Effect </div> <div> Creation </div> </div>', 'ea6386f3-2515-45d0-8e5f-6ab2c8d5148f'::uuid),
                    ('Description', 'description', '["Choose a pile of bones or a corpse of a Medium or Small Humanoid within range. The target becomes an Undead creature: a Skeleton if you chose bones or a Zombie if you chose a corpse (see appendix B for the stat blocks).","On each of your turns, you can take a Bonus Action to mentally command any creature you made with this spell if the creature is within 60 feet of you (if you control multiple creatures, you can command any of them at the same time, issuing the same command to each one). You decide what action the creature will take and where it will move on its next turn, or you can issue a general command, such as to guard a chamber or corridor. If you issue no commands, the creature takes the Dodge action and moves only to avoid harm. Once given an order, the creature continues to follow it until its task is complete.","The creature is under your control for 24 hours, after which it stops obeying any command you’ve given it. To maintain control of the creature for another 24 hours, you must cast this spell on the creature again before the current 24-hour period ends. This use of the spell reasserts your control over up to four creatures you have animated with this spell rather than animating a new creature.","Using a Higher-Level Spell Slot. You animate or reassert control over two additional Undead creatures for each spell slot level above 3. Each of the creatures must come from a different corpse or pile of bones."]', '<div> <p>Choose a pile of bones or a corpse of a Medium or Small Humanoid within range. The target becomes an Undead creature: a <a>Skeleton</a> if you chose bones or a <a>Zombie</a> if you chose a corpse (see appendix B for the stat blocks).</p> <p>On each of your turns, you can take a Bonus Action to mentally command any creature you made with this spell if the creature is within 60 feet of you (if you control multiple creatures, you can command any of them at the same time, issuing the same command to each one). You decide what action the creature will take and where it will move on its next turn, or you can issue a general command, such as to guard a chamber or corridor. If you issue no commands, the creature takes the <a>Dodge</a> action and moves only to avoid harm. Once given an order, the creature continues to follow it until its task is complete.</p> <p>The creature is under your control for 24 hours, after which it stops obeying any command you’ve given it. To maintain control of the creature for another 24 hours, you must cast this spell on the creature again before the current 24-hour period ends. This use of the spell reasserts your control over up to four creatures you have animated with this spell rather than animating a new creature.</p> <p><strong><em>Using a Higher-Level Spell Slot.</em></strong> You animate or reassert control over two additional Undead creatures for each spell slot level above 3. Each of the creatures must come from a different corpse or pile of bones.</p> <span>* - (a drop of blood, a piece of flesh, and a pinch of bone dust)</span> </div>', 'ea6386f3-2515-45d0-8e5f-6ab2c8d5148f'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', 'ea6386f3-2515-45d0-8e5f-6ab2c8d5148f'::uuid),
                    ('Spell Tags', 'spellTags', '["Creation"]', '', 'ea6386f3-2515-45d0-8e5f-6ab2c8d5148f'::uuid),
                    ('Available For', 'availableFor', '["Cleric (Legacy)","Wizard (Legacy)","Cleric","Wizard","Cleric - Death Domain (DMG)","Druid - Circle of Spores (TCoE)","Paladin - Oathbreaker (DMG)"]', '', 'ea6386f3-2515-45d0-8e5f-6ab2c8d5148f'::uuid),
                    ('Source', 'source', 'Player’s Handbook, pg. 240', '', 'ea6386f3-2515-45d0-8e5f-6ab2c8d5148f'::uuid),
                    ('Source URL', 'url', 'https://www.dndbeyond.com/spells/2618853-animate-dead', '', 'ea6386f3-2515-45d0-8e5f-6ab2c8d5148f'::uuid),
                    ('Image', 'imageUrl', 'https://www.dndbeyond.com/attachments/2/720/necromancy.png', '', 'ea6386f3-2515-45d0-8e5f-6ab2c8d5148f'::uuid),
                    ('Level', 'level', '{"levelNumber":"5","label":"5th"}', '<div> <div> Level </div> <div> 5th </div> </div>', '339b90cc-7f56-4621-9dde-a1036b317c1a'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Action","kind":"action","value":1,"unit":"action","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Action </div> </div>', '339b90cc-7f56-4621-9dde-a1036b317c1a'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"120 ft.","kind":"distance","distanceValue":120,"distanceUnit":"ft","area":null}', '<div> <div> Range/Area </div> <div> 120 ft. </div> </div>', '339b90cc-7f56-4621-9dde-a1036b317c1a'::uuid),
                    ('Components', 'components', '{"text":"V, S","verbal":true,"somatic":true,"material":{"required":false,"description":null,"consumed":null,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S</span> </div> </div>', '339b90cc-7f56-4621-9dde-a1036b317c1a'::uuid),
                    ('Duration', 'duration', '{"text":"Concentration 1 Minute","kind":"timed","value":1,"unit":"minute","concentration":true,"endCondition":null}', '<div> <div>Duration</div> <div> <i>Concentration</i> 1 Minute </div> </div>', '339b90cc-7f56-4621-9dde-a1036b317c1a'::uuid),
                    ('School', 'school', 'Transmutation', '<div> <div> School </div> <div> Transmutation </div> </div>', '339b90cc-7f56-4621-9dde-a1036b317c1a'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"None","kind":"none","attackType":null,"ability":null}', '<div> <div> Attack/Save </div> <div> <span>None</span> </div> </div>', '339b90cc-7f56-4621-9dde-a1036b317c1a'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Creation (...)","damageTypes":[]}', '<div> <div> Damage/Effect </div> <div> Creation (...) </div> </div>', '339b90cc-7f56-4621-9dde-a1036b317c1a'::uuid),
                    ('Description', 'description', '["Objects animate at your command. Choose a number of nonmagical objects within range that aren’t being worn or carried, aren’t fixed to a surface, and aren’t Gargantuan. The maximum number of objects is equal to your spellcasting ability modifier; for this number, a Medium or smaller target counts as one object, a Large target counts as two, and a Huge target counts as three.","Each target animates, sprouts legs, and becomes a Construct that uses the Animated Object stat block; this creature is under your control until the spell ends or until it is reduced to 0 Hit Points. Each creature you make with this spell is an ally to you and your allies. In combat, it shares your Initiative count and takes its turn immediately after yours.","Until the spell ends, you can take a Bonus Action to mentally command any creature you made with this spell if the creature is within 500 feet of you (if you control multiple creatures, you can command any of them at the same time, issuing the same command to each one). If you issue no commands, the creature takes the Dodge action and moves only to avoid harm. When the creature drops to 0 Hit Points, it reverts to its object form, and any remaining damage carries over to that form.","Using a Higher-Level Spell Slot. The creature’s Slam damage increases by 1d4 (Medium or smaller), 1d6 (Large), or 1d12 (Huge) for each spell slot level above 5.","Huge or Smaller Construct, Unaligned","AC 15","HP 10 (Medium or smaller), 20 (Large), 40 (Huge)","Speed 30 ft.","Immunities Poison, Psychic; Charmed , Exhaustion , Frightened , Paralyzed , Poisoned","Senses Blindsight 30 ft.; Passive Perception 6","Languages Understands the languages you know","CR None (XP 0; PB equals your Proficiency Bonus)","Actions","Slam. Melee Attack Roll: Bonus equals your spell attack modifier, reach 5 ft. Hit: Force damage equal to 1d4 + 3 (Medium or smaller), 2d6 + 3 + your spellcasting ability modifier (Large), or 2d12 + 3 + your spellcasting ability modifier (Huge)."]', '<div> <p>Objects animate at your command. Choose a number of nonmagical objects within range that aren’t being worn or carried, aren’t fixed to a surface, and aren’t Gargantuan. The maximum number of objects is equal to your spellcasting ability modifier; for this number, a Medium or smaller target counts as one object, a Large target counts as two, and a Huge target counts as three.</p> <p>Each target animates, sprouts legs, and becomes a Construct that uses the <strong>Animated Object</strong> stat block; this creature is under your control until the spell ends or until it is reduced to 0 Hit Points. Each creature you make with this spell is an ally to you and your allies. In combat, it shares your Initiative count and takes its turn immediately after yours.</p> <p>Until the spell ends, you can take a Bonus Action to mentally command any creature you made with this spell if the creature is within 500 feet of you (if you control multiple creatures, you can command any of them at the same time, issuing the same command to each one). If you issue no commands, the creature takes the <a>Dodge</a> action and moves only to avoid harm. When the creature drops to 0 Hit Points, it reverts to its object form, and any remaining damage carries over to that form.</p> <p><strong><em>Using a Higher-Level Spell Slot.</em></strong> The creature’s Slam damage increases by 1d4 (Medium or smaller), 1d6 (Large), or 1d12 (Huge) for each spell slot level above 5.</p> <div> <h4>Animated Object</h4> <p>Huge or Smaller Construct, Unaligned</p> <p><strong>AC</strong> 15</p> <p><strong>HP</strong> 10 (Medium or smaller), 20 (Large), 40 (Huge)</p> <p><strong>Speed</strong> 30 ft.</p> <div> <table> <thead> <tr> <th> </th> <th> </th> <th>Mod</th> <th>Save</th> </tr> </thead> <tbody> <tr> <th>STR</th> <td>16</td> <td>+3</td> <td>+3</td> </tr> <tr> <th>DEX</th> <td>10</td> <td>+0</td> <td>+0</td> </tr> <tr> <th>CON</th> <td>10</td> <td>+0</td> <td>+0</td> </tr> </tbody> </table> <table> <thead> <tr> <th> </th> <th> </th> <th>Mod</th> <th>Save</th> </tr> </thead> <tbody> <tr> <th>INT</th> <td>3</td> <td>−4</td> <td>−4</td> </tr> <tr> <th>WIS</th> <td>3</td> <td>−4</td> <td>−4</td> </tr> <tr> <th>CHA</th> <td>1</td> <td>−5</td> <td>−5</td> </tr> </tbody> </table> </div> <p><strong>Immunities</strong> Poison, Psychic; <a>Charmed</a>, <a>Exhaustion</a>, <a>Frightened</a>, <a>Paralyzed</a>, <a>Poisoned</a></p> <p><strong>Senses</strong> <a>Blindsight</a> 30 ft.; Passive Perception 6</p> <p><strong>Languages</strong> Understands the languages you know</p> <p><strong>CR</strong> None (XP 0; PB equals your Proficiency Bonus)</p> <p>Actions</p> <p><strong><em>Slam.</em></strong> <em>Melee Attack Roll:</em> Bonus equals your spell attack modifier, reach 5 ft. <em>Hit:</em> Force damage equal to 1d4 + 3 (Medium or smaller), 2d6 + 3 + your spellcasting ability modifier (Large), or 2d12 + 3 + your spellcasting ability modifier (Huge).</p> </div> </div>', '339b90cc-7f56-4621-9dde-a1036b317c1a'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', '339b90cc-7f56-4621-9dde-a1036b317c1a'::uuid),
                    ('Spell Tags', 'spellTags', '["Creation","Damage"]', '', '339b90cc-7f56-4621-9dde-a1036b317c1a'::uuid),
                    ('Available For', 'availableFor', '["Bard (Legacy)","Sorcerer (Legacy)","Wizard (Legacy)","Artificer (Legacy)","Bard","Sorcerer","Wizard","Artificer","Cleric - Forge Domain (XGtE)"]', '', '339b90cc-7f56-4621-9dde-a1036b317c1a'::uuid),
                    ('Source', 'source', 'Player’s Handbook, pg. 240', '', '339b90cc-7f56-4621-9dde-a1036b317c1a'::uuid),
                    ('Source URL', 'url', 'https://www.dndbeyond.com/spells/2618855-animate-objects', '', '339b90cc-7f56-4621-9dde-a1036b317c1a'::uuid),
