                    ('Casting Time', 'castingTime', '{"text":"1 Bonus Action","kind":"bonus_action","value":1,"unit":"action","trigger":null,"ritual":false}', '', '886d2d27-8e63-46e4-b932-a08206d34619'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"Self","kind":"self","distanceValue":null,"distanceUnit":null,"area":null}', '', '886d2d27-8e63-46e4-b932-a08206d34619'::uuid),
                    ('Components', 'components', '{"text":"V, S, M *","verbal":true,"somatic":true,"material":{"required":true,"description":null,"consumed":null,"costGp":null}}', '', '886d2d27-8e63-46e4-b932-a08206d34619'::uuid),
                    ('Duration', 'duration', '{"text":"1 Hour","kind":"timed","value":1,"unit":"hour","concentration":false,"endCondition":null}', '', '886d2d27-8e63-46e4-b932-a08206d34619'::uuid),
                    ('School', 'school', 'Abjuration', '', '886d2d27-8e63-46e4-b932-a08206d34619'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"None","kind":"none","attackType":null,"ability":null}', '', '886d2d27-8e63-46e4-b932-a08206d34619'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Cold","damageTypes":["Cold"]}', '', '886d2d27-8e63-46e4-b932-a08206d34619'::uuid),
                    ('Description', 'description', '["Protective magical frost surrounds you. You gain 5 Temporary Hit Points. If a creature hits you with a melee attack roll before the spell ends, the creature takes 5 Cold damage. The spell ends early if you have no Temporary Hit Points.","Using a Higher-Level Spell Slot. The Temporary Hit Points and the Cold damage both increase by 5 for each spell slot level above 1."]', '<p>Protective magical frost surrounds you. You gain 5 Temporary Hit Points. If a creature hits you with a melee attack roll before the spell ends, the creature takes 5 Cold damage. The spell ends early if you have no Temporary Hit Points.</p> <p>Using a Higher-Level Spell Slot. The Temporary Hit Points and the Cold damage both increase by 5 for each spell slot level above 1.</p>', '886d2d27-8e63-46e4-b932-a08206d34619'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', '886d2d27-8e63-46e4-b932-a08206d34619'::uuid),
                    ('Spell Tags', 'spellTags', '[]', '', '886d2d27-8e63-46e4-b932-a08206d34619'::uuid),
                    ('Available For', 'availableFor', '["Warlock"]', '', '886d2d27-8e63-46e4-b932-a08206d34619'::uuid),
                    ('Source', 'source', 'Player’s Handbook (2024)', '', '886d2d27-8e63-46e4-b932-a08206d34619'::uuid),
                    ('Source URL', 'url', 'https://www.dndbeyond.com/spells/2618870-armor-of-agathys', '', '886d2d27-8e63-46e4-b932-a08206d34619'::uuid),
                    ('Image', 'imageUrl', '', '', '886d2d27-8e63-46e4-b932-a08206d34619'::uuid),
                    ('Level', 'level', '{"levelNumber":"1","label":"1st"}', '', '765d4bd8-5f5a-45d5-a932-323e9d02cd9f'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Action","kind":"action","value":1,"unit":"action","trigger":null,"ritual":false}', '', '765d4bd8-5f5a-45d5-a932-323e9d02cd9f'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"Self (10 ft. )","kind":"self","distanceValue":null,"distanceUnit":null,"area":{"shape":null,"value":10,"unit":"ft"}}', '', '765d4bd8-5f5a-45d5-a932-323e9d02cd9f'::uuid),
                    ('Components', 'components', '{"text":"V, S","verbal":true,"somatic":true,"material":{"required":false,"description":null,"consumed":null,"costGp":null}}', '', '765d4bd8-5f5a-45d5-a932-323e9d02cd9f'::uuid),
                    ('Duration', 'duration', '{"text":"Instantaneous","kind":"instantaneous","value":null,"unit":null,"concentration":false,"endCondition":null}', '', '765d4bd8-5f5a-45d5-a932-323e9d02cd9f'::uuid),
                    ('School', 'school', 'Conjuration', '', '765d4bd8-5f5a-45d5-a932-323e9d02cd9f'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"STR Save","kind":"save","attackType":null,"ability":"STR"}', '', '765d4bd8-5f5a-45d5-a932-323e9d02cd9f'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Necrotic","damageTypes":["Necrotic"]}', '', '765d4bd8-5f5a-45d5-a932-323e9d02cd9f'::uuid),
                    ('Description', 'description', '["Invoking Hadar, you cause tendrils to erupt from yourself. Each creature in a 10-foot Emanation originating from you makes a Strength saving throw. On a failed save, a target takes 2d6 Necrotic damage and can’t take Reactions until the start of its next turn. On a successful save, a target takes half as much damage only.","Using a Higher-Level Spell Slot. The damage increases by 1d6 for each spell slot level above 1."]', '<p>Invoking Hadar, you cause tendrils to erupt from yourself. Each creature in a 10-foot Emanation originating from you makes a Strength saving throw. On a failed save, a target takes 2d6 Necrotic damage and can’t take Reactions until the start of its next turn. On a successful save, a target takes half as much damage only.</p> <p>Using a Higher-Level Spell Slot. The damage increases by 1d6 for each spell slot level above 1.</p>', '765d4bd8-5f5a-45d5-a932-323e9d02cd9f'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', '765d4bd8-5f5a-45d5-a932-323e9d02cd9f'::uuid),
                    ('Spell Tags', 'spellTags', '[]', '', '765d4bd8-5f5a-45d5-a932-323e9d02cd9f'::uuid),
                    ('Available For', 'availableFor', '["Warlock"]', '', '765d4bd8-5f5a-45d5-a932-323e9d02cd9f'::uuid),
                    ('Source', 'source', 'Player’s Handbook (2024)', '', '765d4bd8-5f5a-45d5-a932-323e9d02cd9f'::uuid),
                    ('Source URL', 'url', 'https://www.dndbeyond.com/spells/2618871-arms-of-hadar', '', '765d4bd8-5f5a-45d5-a932-323e9d02cd9f'::uuid),
                    ('Image', 'imageUrl', '', '', '765d4bd8-5f5a-45d5-a932-323e9d02cd9f'::uuid),
                    ('Level', 'level', '{"levelNumber":"4","label":"4th"}', '', 'd9cc192c-7df3-467e-9a9b-017f3cf6d031'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Action","kind":"action","value":1,"unit":"action","trigger":null,"ritual":false}', '', 'd9cc192c-7df3-467e-9a9b-017f3cf6d031'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"Self 15 ft. ( )","kind":"self","distanceValue":null,"distanceUnit":null,"area":null}', '', 'd9cc192c-7df3-467e-9a9b-017f3cf6d031'::uuid),
                    ('Components', 'components', '{"text":"V, S, M *","verbal":true,"somatic":true,"material":{"required":true,"description":null,"consumed":null,"costGp":null}}', '', 'd9cc192c-7df3-467e-9a9b-017f3cf6d031'::uuid),
                    ('Duration', 'duration', '{"text":"Concentration 1 Round","kind":"timed","value":1,"unit":"round","concentration":true,"endCondition":null}', '', 'd9cc192c-7df3-467e-9a9b-017f3cf6d031'::uuid),
                    ('School', 'school', 'Conjuration', '', 'd9cc192c-7df3-467e-9a9b-017f3cf6d031'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"WIS Save","kind":"save","attackType":null,"ability":"WIS"}', '', 'd9cc192c-7df3-467e-9a9b-017f3cf6d031'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Bludgeoning","damageTypes":["Bludgeoning"]}', '', 'd9cc192c-7df3-467e-9a9b-017f3cf6d031'::uuid),
                    ('Description', 'description', '["🏹 Arrow of the Veilwood","4th-level conjuration (Veilwood Archery) Casting Time: 1 action Range: Self (15-foot line) Components: V, S, M (a carved Veilwood feather and a drop of moonlit dew) Duration: 1 round Saving Throw: Wisdom save Damage Type: Force Classes: Veilwood Ranger, VeilWood Druid, Veilwood Sorcerer, Veilwood Rogue (Veilwood lineage or subclass) 🌿 Description: You conjure a spectral arrow forged from the ancient magic of the Veilwood, infused with the will of the forest and the precision of elven archery. The arrow launches in a straight line 15 feet long and 5 feet wide, piercing through enemies and echoing with the whisper of leaves. Each creature in the line must make a Wisdom saving throw. On a failed save, the creature takes 6d8 force damage and is pushed 10 feet away from you as if struck by a gust of ethereal wind. On a successful save, the creature takes half damage and is not pushed. If the arrow passes through a space occupied by natural foliage, it leaves behind a shimmering trail of Veilwood energy. Until the start of your next turn, allies who move through this trail gain advantage on Dexterity saving throws and +10 feet of movement speed. 🌙 At Higher Levels When you cast this spell using a spell slot of 5th level or higher, the damage increases by 1d8 for each slot level above 4th. 🧝‍♂️ Lore The Arrow of the Veilwood is a sacred technique taught only to those who have earned the trust of the forest spirits. Tharion Veyrhalas, last Warden of the Moonshade Glade, was said to have crafted this spell after meditating beneath the Whispering Tree for seven nights. It is not merely a weapon—it is the forest’s judgment.","To keep the spell relevant as you level up, here’s how it scales:","Damage Increase: When cast using a spell slot of 5th level or higher , the spell deals +1d8 force damage per slot level above 4th.","Optional Add-on (Homebrew Flavor): At 6th level or higher , you could add:","These are optional, but they can add more Veilwood mystique and strategic value."]', '<p>🏹 Arrow of the Veilwood</p> <p>4th-level conjuration (Veilwood Archery) Casting Time: 1 action Range: Self (15-foot line) Components: V, S, M (a carved Veilwood feather and a drop of moonlit dew) Duration: 1 round Saving Throw: Wisdom save Damage Type: Force Classes: Veilwood Ranger, VeilWood Druid, Veilwood Sorcerer, Veilwood Rogue (Veilwood lineage or subclass) 🌿 Description: You conjure a spectral arrow forged from the ancient magic of the Veilwood, infused with the will of the forest and the precision of elven archery. The arrow launches in a straight line 15 feet long and 5 feet wide, piercing through enemies and echoing with the whisper of leaves. Each creature in the line must make a Wisdom saving throw. On a failed save, the creature takes 6d8 force damage and is pushed 10 feet away from you as if struck by a gust of ethereal wind. On a successful save, the creature takes half damage and is not pushed. If the arrow passes through a space occupied by natural foliage, it leaves behind a shimmering trail of Veilwood energy. Until the start of your next turn, allies who move through this trail gain advantage on Dexterity saving throws and +10 feet of movement speed. 🌙 At Higher Levels When you cast this spell using a spell slot of 5th level or higher, the damage increases by 1d8 for each slot level above 4th. 🧝‍♂️ Lore The Arrow of the Veilwood is a sacred technique taught only to those who have earned the trust of the forest spirits. Tharion Veyrhalas, last Warden of the Moonshade Glade, was said to have crafted this spell after meditating beneath the Whispering Tree for seven nights. It is not merely a weapon—it is the forest’s judgment.</p> <p>To keep the spell relevant as you level up, here’s how it scales:</p> <p>Damage Increase: When cast using a spell slot of 5th level or higher , the spell deals +1d8 force damage per slot level above 4th.</p> <p>Optional Add-on (Homebrew Flavor): At 6th level or higher , you could add:</p> <p>These are optional, but they can add more Veilwood mystique and strategic value.</p>', 'd9cc192c-7df3-467e-9a9b-017f3cf6d031'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', 'd9cc192c-7df3-467e-9a9b-017f3cf6d031'::uuid),
                    ('Spell Tags', 'spellTags', '[]', '', 'd9cc192c-7df3-467e-9a9b-017f3cf6d031'::uuid),
                    ('Available For', 'availableFor', '[]', '', 'd9cc192c-7df3-467e-9a9b-017f3cf6d031'::uuid),
                    ('Source', 'source', 'Homebrew (D&D Beyond)', '', 'd9cc192c-7df3-467e-9a9b-017f3cf6d031'::uuid),
                    ('Source URL', 'url', 'https://www.dndbeyond.com/spells/3033813-arrow-of-the-veilwood', '', 'd9cc192c-7df3-467e-9a9b-017f3cf6d031'::uuid),
                    ('Image', 'imageUrl', '', '', 'd9cc192c-7df3-467e-9a9b-017f3cf6d031'::uuid),
                    ('Level', 'level', '{"levelNumber":"Cantrip","label":"Cantrip"}', '', '9619e32d-dec8-4de1-a0be-1c80077bf050'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Action","kind":"action","value":1,"unit":"action","trigger":null,"ritual":false}', '', '9619e32d-dec8-4de1-a0be-1c80077bf050'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"Self","kind":"self","distanceValue":null,"distanceUnit":null,"area":null}', '', '9619e32d-dec8-4de1-a0be-1c80077bf050'::uuid),
                    ('Components', 'components', '{"text":"V, S, M *","verbal":true,"somatic":true,"material":{"required":true,"description":null,"consumed":null,"costGp":null}}', '', '9619e32d-dec8-4de1-a0be-1c80077bf050'::uuid),
                    ('Duration', 'duration', '{"text":"1 Minute","kind":"timed","value":1,"unit":"minute","concentration":false,"endCondition":null}', '', '9619e32d-dec8-4de1-a0be-1c80077bf050'::uuid),
                    ('School', 'school', 'Divination', '', '9619e32d-dec8-4de1-a0be-1c80077bf050'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"None","kind":"none","attackType":null,"ability":null}', '', '9619e32d-dec8-4de1-a0be-1c80077bf050'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"","damageTypes":[]}', '', '9619e32d-dec8-4de1-a0be-1c80077bf050'::uuid),
                    ('Description', 'description', '["You focus your aim on a distant target, waiting for the perfect moment to strike.","Choose a creature you can see within the maximum range of a bow of your choice. If the target remains within the same 5ft space for at least 3 consecutive rounds (18 seconds), you can make a ranged weapon attack against it with the bow as part of the spell.","This attack can target a creature at the bows long range without suffering disadvantage, and you make the attack with advantage.","If the target leaves the space before the attack is made, the spell ends with no effects.","\"Snipe em'' Jonny\" - Blake the artificer to Kevin the ranger while focusing on the hobgoblin warlord having a sit-down."]', '<p>You focus your aim on a distant target, waiting for the perfect moment to strike.</p> <p>Choose a creature you can see within the maximum range of a bow of your choice. If the target remains within the same 5ft space for at least 3 consecutive rounds (18 seconds), you can make a ranged weapon attack against it with the bow as part of the spell.</p> <p>This attack can target a creature at the bows long range without suffering disadvantage, and you make the attack with advantage.</p> <p>If the target leaves the space before the attack is made, the spell ends with no effects.</p> <p>"Snipe em'' Jonny" - Blake the artificer to Kevin the ranger while focusing on the hobgoblin warlord having a sit-down.</p>', '9619e32d-dec8-4de1-a0be-1c80077bf050'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', '9619e32d-dec8-4de1-a0be-1c80077bf050'::uuid),
                    ('Spell Tags', 'spellTags', '[]', '', '9619e32d-dec8-4de1-a0be-1c80077bf050'::uuid),
                    ('Available For', 'availableFor', '[]', '', '9619e32d-dec8-4de1-a0be-1c80077bf050'::uuid),
                    ('Source', 'source', 'Homebrew (D&D Beyond)', '', '9619e32d-dec8-4de1-a0be-1c80077bf050'::uuid),
                    ('Source URL', 'url', 'https://www.dndbeyond.com/spells/3241342-arrow-snipe', '', '9619e32d-dec8-4de1-a0be-1c80077bf050'::uuid),
                    ('Image', 'imageUrl', '', '', '9619e32d-dec8-4de1-a0be-1c80077bf050'::uuid),
                    ('Level', 'level', '{"levelNumber":"9","label":"9th"}', '<div> <div> Level </div> <div> 9th </div> </div>', '959c8e13-0c99-4840-8e8f-2804475e0f52'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Hour","kind":"timed","value":1,"unit":"hour","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Hour </div> </div>', '959c8e13-0c99-4840-8e8f-2804475e0f52'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"10 ft.","kind":"distance","distanceValue":10,"distanceUnit":"ft","area":null}', '<div> <div> Range/Area </div> <div> 10 ft. </div> </div>', '959c8e13-0c99-4840-8e8f-2804475e0f52'::uuid),
                    ('Components', 'components', '{"text":"V, S, M *","verbal":true,"somatic":true,"material":{"required":true,"description":"for each of the spell’s targets, one jacinth worth 1,000+ GP and one silver bar worth 100+ GP, all of which the spell consumes","consumed":true,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S, M *</span> </div> </div>', '959c8e13-0c99-4840-8e8f-2804475e0f52'::uuid),
                    ('Duration', 'duration', '{"text":"Until Dispelled","kind":"until_dispelled","value":null,"unit":null,"concentration":false,"endCondition":"Until Dispelled"}', '<div> <div>Duration</div> <div> Until Dispelled </div> </div>', '959c8e13-0c99-4840-8e8f-2804475e0f52'::uuid),
                    ('School', 'school', 'Necromancy', '<div> <div> School </div> <div> Necromancy </div> </div>', '959c8e13-0c99-4840-8e8f-2804475e0f52'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"None","kind":"none","attackType":null,"ability":null}', '<div> <div> Attack/Save </div> <div> <span>None</span> </div> </div>', '959c8e13-0c99-4840-8e8f-2804475e0f52'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Teleportation","damageTypes":[]}', '<div> <div> Damage/Effect </div> <div> Teleportation </div> </div>', '959c8e13-0c99-4840-8e8f-2804475e0f52'::uuid),
                    ('Description', 'description', '["You and up to eight willing creatures within range project your astral bodies into the Astral Plane (the spell ends instantly if you are already on that plane). Each target’s body is left behind in a state of suspended animation; it has the Unconscious condition, doesn’t need food or air, and doesn’t age.","A target’s astral form resembles its body in almost every way, replicating its game statistics and possessions. The principal difference is the addition of a silvery cord that trails from between the shoulder blades of the astral form. The cord fades from view after 1 foot. If the cord is cut—which happens only when an effect states that it does so—the target’s body and astral form both die.","A target’s astral form can travel through the Astral Plane. The moment an astral form leaves that plane, the target’s body and possessions travel along the silver cord, causing the target to re-enter its body on the new plane.","Any damage or other effects that apply to an astral form have no effect on the target’s body and vice versa. If a target’s body or astral form drops to 0 Hit Points, the spell ends for that target. The spell ends for all the targets if you take a Magic action to dismiss it.","When the spell ends for a target who isn’t dead, the target reappears in its body and exits the state of suspended animation."]', '<div> <p>You and up to eight willing creatures within range project your astral bodies into the Astral Plane (the spell ends instantly if you are already on that plane). Each target’s body is left behind in a state of suspended animation; it has the <a>Unconscious</a> condition, doesn’t need food or air, and doesn’t age.</p> <p>A target’s astral form resembles its body in almost every way, replicating its game statistics and possessions. The principal difference is the addition of a silvery cord that trails from between the shoulder blades of the astral form. The cord fades from view after 1 foot. If the cord is cut—which happens only when an effect states that it does so—the target’s body and astral form both die.</p> <p>A target’s astral form can travel through the Astral Plane. The moment an astral form leaves that plane, the target’s body and possessions travel along the silver cord, causing the target to re-enter its body on the new plane.</p> <p>Any damage or other effects that apply to an astral form have no effect on the target’s body and vice versa. If a target’s body or astral form drops to 0 Hit Points, the spell ends for that target. The spell ends for all the targets if you take a <a>Magic</a> action to dismiss it.</p> <p>When the spell ends for a target who isn’t dead, the target reappears in its body and exits the state of suspended animation.</p> <span>* - (for each of the spell’s targets, one jacinth worth 1,000+ GP and one silver bar worth 100+ GP, all of which the spell consumes)</span> </div>', '959c8e13-0c99-4840-8e8f-2804475e0f52'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', '959c8e13-0c99-4840-8e8f-2804475e0f52'::uuid);
                """);

            migrationBuilder.Sql("""
                INSERT INTO "SpellComponents" ("Label", "Key", "Value", "Html", "SpellId") VALUES
                    ('Spell Tags', 'spellTags', '["Teleportation"]', '', '959c8e13-0c99-4840-8e8f-2804475e0f52'::uuid),
                    ('Available For', 'availableFor', '["Cleric (Legacy)","Warlock (Legacy)","Wizard (Legacy)","Cleric","Warlock","Wizard"]', '', '959c8e13-0c99-4840-8e8f-2804475e0f52'::uuid),
                    ('Source', 'source', 'Player’s Handbook, pg. 243', '', '959c8e13-0c99-4840-8e8f-2804475e0f52'::uuid),
                    ('Source URL', 'url', 'https://www.dndbeyond.com/spells/2618878-astral-projection', '', '959c8e13-0c99-4840-8e8f-2804475e0f52'::uuid),
                    ('Image', 'imageUrl', 'https://www.dndbeyond.com/attachments/2/720/necromancy.png', '', '959c8e13-0c99-4840-8e8f-2804475e0f52'::uuid),
                    ('Level', 'level', '{"levelNumber":"2","label":"2nd"}', '<div> <div> Level </div> <div> 2nd </div> </div>', '56ffc8dc-0c64-427b-88b4-1c04074e5e8d'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Minute Ritual","kind":"timed","value":1,"unit":"minute","trigger":null,"ritual":true}', '<div> <div> Casting Time </div> <div> 1 Minute <i>Ritual</i> </div> </div>', '56ffc8dc-0c64-427b-88b4-1c04074e5e8d'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"Self","kind":"self","distanceValue":null,"distanceUnit":null,"area":null}', '<div> <div> Range/Area </div> <div> Self </div> </div>', '56ffc8dc-0c64-427b-88b4-1c04074e5e8d'::uuid),
                    ('Components', 'components', '{"text":"V, S, M *","verbal":true,"somatic":true,"material":{"required":true,"description":"specially marked sticks, bones, cards, or other divinatory tokens worth 25+ GP","consumed":false,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S, M *</span> </div> </div>', '56ffc8dc-0c64-427b-88b4-1c04074e5e8d'::uuid),
                    ('Duration', 'duration', '{"text":"Instantaneous","kind":"instantaneous","value":null,"unit":null,"concentration":false,"endCondition":null}', '<div> <div>Duration</div> <div> Instantaneous </div> </div>', '56ffc8dc-0c64-427b-88b4-1c04074e5e8d'::uuid),
                    ('School', 'school', 'Divination', '<div> <div> School </div> <div> Divination </div> </div>', '56ffc8dc-0c64-427b-88b4-1c04074e5e8d'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"None","kind":"none","attackType":null,"ability":null}', '<div> <div> Attack/Save </div> <div> <span>None</span> </div> </div>', '56ffc8dc-0c64-427b-88b4-1c04074e5e8d'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Foreknowledge","damageTypes":[]}', '<div> <div> Damage/Effect </div> <div> Foreknowledge </div> </div>', '56ffc8dc-0c64-427b-88b4-1c04074e5e8d'::uuid),
                    ('Description', 'description', '["You receive an omen from an otherworldly entity about the results of a course of action that you plan to take within the next 30 minutes. The DM chooses the omen from the Omens table.","The spell doesn’t account for circumstances, such as other spells, that might change the results.","If you cast the spell more than once before finishing a Long Rest, there is a cumulative 25 percent chance for each casting after the first that you get no answer."]', '<div> <p>You receive an omen from an otherworldly entity about the results of a course of action that you plan to take within the next 30 minutes. The DM chooses the omen from the Omens table.</p> <table><caption>Omens</caption> <thead> <tr> <th>Omen</th> <th>For Results That Will Be...</th> </tr> </thead> <tbody> <tr> <td>Weal</td> <td>Good</td> </tr> <tr> <td>Woe</td> <td>Bad</td> </tr> <tr> <td>Weal and woe</td> <td>Good and bad</td> </tr> <tr> <td>Indifference</td> <td>Neither good nor bad</td> </tr> </tbody> </table> <p>The spell doesn’t account for circumstances, such as other spells, that might change the results.</p> <p>If you cast the spell more than once before finishing a Long Rest, there is a cumulative 25 percent chance for each casting after the first that you get no answer.</p> <span>* - (specially marked sticks, bones, cards, or other divinatory tokens worth 25+ GP)</span> </div>', '56ffc8dc-0c64-427b-88b4-1c04074e5e8d'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', '56ffc8dc-0c64-427b-88b4-1c04074e5e8d'::uuid),
                    ('Spell Tags', 'spellTags', '["Foreknowledge"]', '', '56ffc8dc-0c64-427b-88b4-1c04074e5e8d'::uuid),
                    ('Available For', 'availableFor', '["Cleric (Legacy)","Druid (Legacy)","Wizard (Legacy)","Cleric","Druid","Wizard","Cleric - Knowledge Domain (Legacy)","Illrigger - Architect of Ruin","Paladin - Oath of the Open Sea (TCSR)"]', '', '56ffc8dc-0c64-427b-88b4-1c04074e5e8d'::uuid),
                    ('Source', 'source', 'Player’s Handbook, pg. 244', '', '56ffc8dc-0c64-427b-88b4-1c04074e5e8d'::uuid),
                    ('Source URL', 'url', 'https://www.dndbeyond.com/spells/2618882-augury', '', '56ffc8dc-0c64-427b-88b4-1c04074e5e8d'::uuid),
                    ('Image', 'imageUrl', 'https://www.dndbeyond.com/attachments/2/709/divination.png', '', '56ffc8dc-0c64-427b-88b4-1c04074e5e8d'::uuid),
                    ('Level', 'level', '{"levelNumber":"4","label":"4th"}', '<div> <div> Level </div> <div> 4th </div> </div>', 'f9d0b07b-472f-451f-8a7a-0a6c37c503df'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Action","kind":"action","value":1,"unit":"action","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Action </div> </div>', 'f9d0b07b-472f-451f-8a7a-0a6c37c503df'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"Self (30 ft.)","kind":"self","distanceValue":null,"distanceUnit":null,"area":{"shape":null,"value":30,"unit":"ft"}}', '<div> <div> Range/Area </div> <div> Self <span>(30 ft. <i></i>)</span> </div> </div>', 'f9d0b07b-472f-451f-8a7a-0a6c37c503df'::uuid),
                    ('Components', 'components', '{"text":"V","verbal":true,"somatic":false,"material":{"required":false,"description":null,"consumed":null,"costGp":null}}', '<div> <div> Components </div> <div> <span>V</span> </div> </div>', 'f9d0b07b-472f-451f-8a7a-0a6c37c503df'::uuid),
                    ('Duration', 'duration', '{"text":"Concentration 10 Minutes","kind":"timed","value":10,"unit":"minute","concentration":true,"endCondition":null}', '<div> <div>Duration</div> <div> <i>Concentration</i> 10 Minutes </div> </div>', 'f9d0b07b-472f-451f-8a7a-0a6c37c503df'::uuid),
                    ('School', 'school', 'Abjuration', '<div> <div> School </div> <div> Abjuration </div> </div>', 'f9d0b07b-472f-451f-8a7a-0a6c37c503df'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"None","kind":"none","attackType":null,"ability":null}', '<div> <div> Attack/Save </div> <div> <span>None</span> </div> </div>', 'f9d0b07b-472f-451f-8a7a-0a6c37c503df'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Healing (...)","damageTypes":[]}', '<div> <div> Damage/Effect </div> <div> Healing (...) </div> </div>', 'f9d0b07b-472f-451f-8a7a-0a6c37c503df'::uuid),
                    ('Description', 'description', '["An aura radiates from you in a 30-foot Emanation for the duration. While in the aura, you and your allies have Resistance to Necrotic damage, and your Hit Point maximums can’t be reduced. If an ally with 0 Hit Points starts its turn in the aura, that ally regains 1 Hit Point."]', '<div> <p>An aura radiates from you in a 30-foot <a>Emanation</a> for the duration. While in the aura, you and your allies have Resistance to Necrotic damage, and your Hit Point maximums can’t be reduced. If an ally with 0 Hit Points starts its turn in the aura, that ally regains 1 Hit Point.</p> </div>', 'f9d0b07b-472f-451f-8a7a-0a6c37c503df'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', 'f9d0b07b-472f-451f-8a7a-0a6c37c503df'::uuid),
