                    ('Components', 'components', '{"text":"V","verbal":true,"somatic":false,"material":{"required":false,"description":null,"consumed":null,"costGp":null}}', '', '65409ecc-a83b-4101-bba0-4781d8956798'::uuid),
                    ('Duration', 'duration', '{"text":"Concentration 10 Minutes","kind":"timed","value":10,"unit":"minute","concentration":true,"endCondition":null}', '', '65409ecc-a83b-4101-bba0-4781d8956798'::uuid),
                    ('School', 'school', 'Abjuration', '', '65409ecc-a83b-4101-bba0-4781d8956798'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"None","kind":"none","attackType":null,"ability":null}', '', '65409ecc-a83b-4101-bba0-4781d8956798'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Buff (...)","damageTypes":[]}', '', '65409ecc-a83b-4101-bba0-4781d8956798'::uuid),
                    ('Description', 'description', '["An aura radiates from you in a 30-foot Emanation for the duration. While in the aura, you and your allies have Resistance to Poison damage and Advantage on saving throws to avoid or end effects that include the Blinded, Charmed, Deafened, Frightened, Paralyzed, Poisoned, or Stunned condition."]', '<p>An aura radiates from you in a 30-foot Emanation for the duration. While in the aura, you and your allies have Resistance to Poison damage and Advantage on saving throws to avoid or end effects that include the Blinded, Charmed, Deafened, Frightened, Paralyzed, Poisoned, or Stunned condition.</p>', '65409ecc-a83b-4101-bba0-4781d8956798'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', '65409ecc-a83b-4101-bba0-4781d8956798'::uuid),
                    ('Spell Tags', 'spellTags', '[]', '', '65409ecc-a83b-4101-bba0-4781d8956798'::uuid),
                    ('Available For', 'availableFor', '["Cleric","Paladin"]', '', '65409ecc-a83b-4101-bba0-4781d8956798'::uuid),
                    ('Source', 'source', 'Player’s Handbook (2024)', '', '65409ecc-a83b-4101-bba0-4781d8956798'::uuid),
                    ('Source URL', 'url', 'https://www.dndbeyond.com/spells/2618888-aura-of-purity', '', '65409ecc-a83b-4101-bba0-4781d8956798'::uuid),
                    ('Image', 'imageUrl', '', '', '65409ecc-a83b-4101-bba0-4781d8956798'::uuid),
                    ('Level', 'level', '{"levelNumber":"3","label":"3rd"}', '', '14735c95-e8b1-4640-8083-881cb32d5733'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Action","kind":"action","value":1,"unit":"action","trigger":null,"ritual":false}', '', '14735c95-e8b1-4640-8083-881cb32d5733'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"Self (30 ft. )","kind":"self","distanceValue":null,"distanceUnit":null,"area":{"shape":null,"value":30,"unit":"ft"}}', '', '14735c95-e8b1-4640-8083-881cb32d5733'::uuid),
                    ('Components', 'components', '{"text":"V","verbal":true,"somatic":false,"material":{"required":false,"description":null,"consumed":null,"costGp":null}}', '', '14735c95-e8b1-4640-8083-881cb32d5733'::uuid),
                    ('Duration', 'duration', '{"text":"Concentration 1 Minute","kind":"timed","value":1,"unit":"minute","concentration":true,"endCondition":null}', '', '14735c95-e8b1-4640-8083-881cb32d5733'::uuid),
                    ('School', 'school', 'Abjuration', '', '14735c95-e8b1-4640-8083-881cb32d5733'::uuid),
