                    ('Source URL', 'url', 'https://www.dndbeyond.com/spells/3056809-bardic-spell-song-ribbon-of-reckoning', '', '801d4e98-1b55-48bb-b938-6bb04c41934a'::uuid),
                    ('Image', 'imageUrl', '', '', '801d4e98-1b55-48bb-b938-6bb04c41934a'::uuid),
