                    ('Casting Time', 'castingTime', '{"text":"1 Bonus Action","kind":"bonus_action","value":1,"unit":"action","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Bonus Action </div> </div>', '3595163b-c4d8-4776-a467-a77b34dc64ce'::uuid),
