                    ('Components', 'components', '{"text":"V, S, M *","verbal":true,"somatic":true,"material":{"required":true,"description":"a handful of oak bark","consumed":false,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S, M *</span> </div> </div>', '3595163b-c4d8-4776-a467-a77b34dc64ce'::uuid),
                    ('Duration', 'duration', '{"text":"1 Hour","kind":"timed","value":1,"unit":"hour","concentration":false,"endCondition":null}', '<div> <div>Duration</div> <div> 1 Hour </div> </div>', '3595163b-c4d8-4776-a467-a77b34dc64ce'::uuid),
                    ('School', 'school', 'Transmutation', '<div> <div> School </div> <div> Transmutation </div> </div>', '3595163b-c4d8-4776-a467-a77b34dc64ce'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"None","kind":"none","attackType":null,"ability":null}', '<div> <div> Attack/Save </div> <div> <span>None</span> </div> </div>', '3595163b-c4d8-4776-a467-a77b34dc64ce'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Buff (...)","damageTypes":[]}', '<div> <div> Damage/Effect </div> <div> Buff (...) </div> </div>', '3595163b-c4d8-4776-a467-a77b34dc64ce'::uuid),
                    ('Description', 'description', '["You touch a willing creature. Until the spell ends, the target’s skin assumes a bark-like appearance, and the target has an Armor Class of 17 if its AC is lower than that."]', '<div> <p>You touch a willing creature. Until the spell ends, the target’s skin assumes a bark-like appearance, and the target has an Armor Class of 17 if its AC is lower than that.</p> <span>* - (a handful of oak bark)</span> </div>', '3595163b-c4d8-4776-a467-a77b34dc64ce'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', '3595163b-c4d8-4776-a467-a77b34dc64ce'::uuid),
