                    ('Components', 'components', '{"text":"V, S, M *","verbal":true,"somatic":true,"material":{"required":true,"description":"a key ring with no keys","consumed":false,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S, M *</span> </div> </div>', '209388ec-41f2-4b0d-8224-012e10c34e81'::uuid),
                    ('Duration', 'duration', '{"text":"Instantaneous","kind":"instantaneous","value":null,"unit":null,"concentration":false,"endCondition":null}', '<div> <div>Duration</div> <div> Instantaneous </div> </div>', '209388ec-41f2-4b0d-8224-012e10c34e81'::uuid),
                    ('School', 'school', 'Enchantment', '<div> <div> School </div> <div> Enchantment </div> </div>', '209388ec-41f2-4b0d-8224-012e10c34e81'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"INT Save","kind":"save","attackType":null,"ability":"INT"}', '<div> <div> Attack/Save </div> <div> <i></i> <span>INT Save</span> </div> </div>', '209388ec-41f2-4b0d-8224-012e10c34e81'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Psychic","damageTypes":["Psychic"]}', '<div> <div> Damage/Effect </div> <div> <i></i> Psychic </div> </div>', '209388ec-41f2-4b0d-8224-012e10c34e81'::uuid),
                    ('Description', 'description', '["You blast the mind of a creature that you can see within range. The target makes an Intelligence saving throw.","On a failed save, the target takes 10d12 Psychic damage and can’t cast spells or take the Magic action. At the end of every 30 days, the target repeats the save, ending the effect on a success. The effect can also be ended by the Greater Restoration , Heal , or Wish spell.","On a successful save, the target takes half as much damage only."]', '<div> <p>You blast the mind of a creature that you can see within range. The target makes an Intelligence saving throw.</p> <p>On a failed save, the target takes 10d12 Psychic damage and can’t cast spells or take the <a>Magic</a> action. At the end of every 30 days, the target repeats the save, ending the effect on a success. The effect can also be ended by the <a>Greater Restoration</a>, <a>Heal</a>, or <a>Wish</a> spell.</p> <p>On a successful save, the target takes half as much damage only.</p> <span>* - (a key ring with no keys)</span> </div>', '209388ec-41f2-4b0d-8224-012e10c34e81'::uuid),
