                    ('Level', 'level', '{"levelNumber":"6","label":"6th"}', '<div> <div> Level </div> <div> 6th </div> </div>', '63019fe2-9bdb-4aad-94bb-62a2fe252254'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Action","kind":"action","value":1,"unit":"action","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Action </div> </div>', '63019fe2-9bdb-4aad-94bb-62a2fe252254'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"90 ft.","kind":"distance","distanceValue":90,"distanceUnit":"ft","area":null}', '<div> <div> Range/Area </div> <div> 90 ft. </div> </div>', '63019fe2-9bdb-4aad-94bb-62a2fe252254'::uuid),
                    ('Components', 'components', '{"text":"V, S","verbal":true,"somatic":true,"material":{"required":false,"description":null,"consumed":null,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S</span> </div> </div>', '63019fe2-9bdb-4aad-94bb-62a2fe252254'::uuid),
                    ('Duration', 'duration', '{"text":"Concentration 10 Minutes","kind":"timed","value":10,"unit":"minute","concentration":true,"endCondition":null}', '<div> <div>Duration</div> <div> <i>Concentration</i> 10 Minutes </div> </div>', '63019fe2-9bdb-4aad-94bb-62a2fe252254'::uuid),
                    ('School', 'school', 'Evocation', '<div> <div> School </div> <div> Evocation </div> </div>', '63019fe2-9bdb-4aad-94bb-62a2fe252254'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"DEX Save","kind":"save","attackType":null,"ability":"DEX"}', '<div> <div> Attack/Save </div> <div> <i></i> <span>DEX Save</span> </div> </div>', '63019fe2-9bdb-4aad-94bb-62a2fe252254'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Force","damageTypes":["Force"]}', '<div> <div> Damage/Effect </div> <div> <i></i> Force </div> </div>', '63019fe2-9bdb-4aad-94bb-62a2fe252254'::uuid),
                    ('Description', 'description', '["You create a wall of whirling blades made of magical energy. The wall appears within range and lasts for the duration. You make a straight wall up to 100 feet long, 20 feet high, and 5 feet thick, or a ringed wall up to 60 feet in diameter, 20 feet high, and 5 feet thick. The wall provides Three-Quarters Cover , and its space is Difficult Terrain .","Any creature in the wall’s space makes a Dexterity saving throw, taking 6d10 Force damage on a failed save or half as much damage on a successful one. A creature also makes that save if it enters the wall’s space or ends it turn there. A creature makes that save only once per turn."]', '<div> <p>You create a wall of whirling blades made of magical energy. The wall appears within range and lasts for the duration. You make a straight wall up to 100 feet long, 20 feet high, and 5 feet thick, or a ringed wall up to 60 feet in diameter, 20 feet high, and 5 feet thick. The wall provides <a>Three-Quarters Cover</a>, and its space is <a>Difficult Terrain</a>.</p> <p>Any creature in the wall’s space makes a Dexterity saving throw, taking 6d10 Force damage on a failed save or half as much damage on a successful one. A creature also makes that save if it enters the wall’s space or ends it turn there. A creature makes that save only once per turn.</p> </div>', '63019fe2-9bdb-4aad-94bb-62a2fe252254'::uuid),
