                    ('Source', 'source', 'Player’s Handbook (2024)', '', 'abc8a1e9-6cd1-4367-83f9-dbf7a447403a'::uuid),
                    ('Source URL', 'url', 'https://www.dndbeyond.com/spells/2618936-blinding-smite', '', 'abc8a1e9-6cd1-4367-83f9-dbf7a447403a'::uuid),
                    ('Image', 'imageUrl', '', '', 'abc8a1e9-6cd1-4367-83f9-dbf7a447403a'::uuid),
                    ('Level', 'level', '{"levelNumber":"2","label":"2nd"}', '<div> <div> Level </div> <div> 2nd </div> </div>', '6a6e3488-f77a-4901-a4de-b633ecd72bd2'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Action","kind":"action","value":1,"unit":"action","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Action </div> </div>', '6a6e3488-f77a-4901-a4de-b633ecd72bd2'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"120 ft.","kind":"distance","distanceValue":120,"distanceUnit":"ft","area":null}', '<div> <div> Range/Area </div> <div> 120 ft. </div> </div>', '6a6e3488-f77a-4901-a4de-b633ecd72bd2'::uuid),
                    ('Components', 'components', '{"text":"V","verbal":true,"somatic":false,"material":{"required":false,"description":null,"consumed":null,"costGp":null}}', '<div> <div> Components </div> <div> <span>V</span> </div> </div>', '6a6e3488-f77a-4901-a4de-b633ecd72bd2'::uuid),
                    ('Duration', 'duration', '{"text":"1 Minute","kind":"timed","value":1,"unit":"minute","concentration":false,"endCondition":null}', '<div> <div>Duration</div> <div> 1 Minute </div> </div>', '6a6e3488-f77a-4901-a4de-b633ecd72bd2'::uuid),
                    ('School', 'school', 'Transmutation', '<div> <div> School </div> <div> Transmutation </div> </div>', '6a6e3488-f77a-4901-a4de-b633ecd72bd2'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"CON Save","kind":"save","attackType":null,"ability":"CON"}', '<div> <div> Attack/Save </div> <div> <i></i> <span>CON Save</span> </div> </div>', '6a6e3488-f77a-4901-a4de-b633ecd72bd2'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Blinded (...)","damageTypes":[]}', '<div> <div> Damage/Effect </div> <div> <i></i> Blinded (...) </div> </div>', '6a6e3488-f77a-4901-a4de-b633ecd72bd2'::uuid),
                    ('Description', 'description', '["One creature that you can see within range must succeed on a Constitution saving throw, or it has the Blinded or Deafened condition (your choice) for the duration. At the end of each of its turns, the target repeats the save, ending the spell on itself on a success.","Using a Higher-Level Spell Slot. You can target one additional creature for each spell slot level above 2."]', '<div> <p>One creature that you can see within range must succeed on a Constitution saving throw, or it has the <a>Blinded</a> or <a>Deafened</a> condition (your choice) for the duration. At the end of each of its turns, the target repeats the save, ending the spell on itself on a success.</p> <p><strong><em>Using a Higher-Level Spell Slot.</em></strong> You can target one additional creature for each spell slot level above 2.</p> </div>', '6a6e3488-f77a-4901-a4de-b633ecd72bd2'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', '6a6e3488-f77a-4901-a4de-b633ecd72bd2'::uuid),
                    ('Spell Tags', 'spellTags', '["Debuff"]', '', '6a6e3488-f77a-4901-a4de-b633ecd72bd2'::uuid),
                    ('Available For', 'availableFor', '["Bard (Legacy)","Cleric (Legacy)","Sorcerer (Legacy)","Wizard (Legacy)","Bard","Cleric","Sorcerer","Wizard","Cleric - Death Domain (DMG)","Druid - Circle of Spores (TCoE)","Warlock - The Undead (VRGtR)","Warlock - The Undying (SCAG)","Cleric - Shadow Domain (BoET)"]', '', '6a6e3488-f77a-4901-a4de-b633ecd72bd2'::uuid),
                    ('Source', 'source', 'Player’s Handbook, pg. 248', '', '6a6e3488-f77a-4901-a4de-b633ecd72bd2'::uuid),
                    ('Source URL', 'url', 'https://www.dndbeyond.com/spells/2618938-blindness-deafness', '', '6a6e3488-f77a-4901-a4de-b633ecd72bd2'::uuid),
                    ('Image', 'imageUrl', 'https://www.dndbeyond.com/attachments/2/722/transmutation.png', '', '6a6e3488-f77a-4901-a4de-b633ecd72bd2'::uuid),
                    ('Level', 'level', '{"levelNumber":"3","label":"3rd"}', '<div> <div> Level </div> <div> 3rd </div> </div>', 'c1b7bb42-c8ec-4392-8dc7-8e26ccf72d23'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Action","kind":"action","value":1,"unit":"action","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Action </div> </div>', 'c1b7bb42-c8ec-4392-8dc7-8e26ccf72d23'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"Self","kind":"self","distanceValue":null,"distanceUnit":null,"area":null}', '<div> <div> Range/Area </div> <div> Self </div> </div>', 'c1b7bb42-c8ec-4392-8dc7-8e26ccf72d23'::uuid),
                    ('Components', 'components', '{"text":"V, S","verbal":true,"somatic":true,"material":{"required":false,"description":null,"consumed":null,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S</span> </div> </div>', 'c1b7bb42-c8ec-4392-8dc7-8e26ccf72d23'::uuid),
                    ('Duration', 'duration', '{"text":"1 Minute","kind":"timed","value":1,"unit":"minute","concentration":false,"endCondition":null}', '<div> <div>Duration</div> <div> 1 Minute </div> </div>', 'c1b7bb42-c8ec-4392-8dc7-8e26ccf72d23'::uuid);
