                    ('Image', 'imageUrl', 'https://www.dndbeyond.com/attachments/2/722/transmutation.png', '', 'fce3d75a-fec2-4c6e-bcf2-bf9c67b57f5a'::uuid),
                    ('Level', 'level', '{"levelNumber":"2","label":"2nd"}', '<div> <div> Level </div> <div> 2nd </div> </div>', 'ac5f6c40-c9f7-4791-bf0d-a7a4754fb511'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Bonus Action","kind":"bonus_action","value":1,"unit":"action","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Bonus Action </div> </div>', 'ac5f6c40-c9f7-4791-bf0d-a7a4754fb511'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"Self","kind":"self","distanceValue":null,"distanceUnit":null,"area":null}', '<div> <div> Range/Area </div> <div> Self </div> </div>', 'ac5f6c40-c9f7-4791-bf0d-a7a4754fb511'::uuid),
                    ('Components', 'components', '{"text":"V","verbal":true,"somatic":false,"material":{"required":false,"description":null,"consumed":null,"costGp":null}}', '<div> <div> Components </div> <div> <span>V</span> </div> </div>', 'ac5f6c40-c9f7-4791-bf0d-a7a4754fb511'::uuid),
                    ('Duration', 'duration', '{"text":"Concentration 1 Minute","kind":"timed","value":1,"unit":"minute","concentration":true,"endCondition":null}', '<div> <div>Duration</div> <div> <i>Concentration</i> 1 Minute </div> </div>', 'ac5f6c40-c9f7-4791-bf0d-a7a4754fb511'::uuid),
                    ('School', 'school', 'Evocation', '<div> <div> School </div> <div> Evocation </div> </div>', 'ac5f6c40-c9f7-4791-bf0d-a7a4754fb511'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"None","kind":"none","attackType":null,"ability":null}', '<div> <div> Attack/Save </div> <div> <span>None</span> </div> </div>', 'ac5f6c40-c9f7-4791-bf0d-a7a4754fb511'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Radiant","damageTypes":["Radiant"]}', '<div> <div> Damage/Effect </div> <div> <i></i> Radiant </div> </div>', 'ac5f6c40-c9f7-4791-bf0d-a7a4754fb511'::uuid),
                    ('Description', 'description', '["The next time you hit a creature with a weapon attack before this spell ends, the weapon gleams with astral radiance as you strike. The attack deals an extra 2d6 radiant damage to the target, which becomes visible if it is invisible , and the target sheds dim light in a 5-foot radius and can’t become invisible until the spell ends.","At Higher Levels. When you cast this spell using a spell slot of 3rd level or higher, the extra damage increases by 1d6 for each slot level above 2nd."]', '<div> <p>The next time you hit a creature with a weapon attack before this spell ends, the weapon gleams with astral radiance as you strike. The attack deals an extra 2d6 radiant damage to the target, which becomes visible if it is <a>invisible</a>, and the target sheds dim light in a 5-foot radius and can’t become invisible until the spell ends. </p> <p><strong>At Higher Levels. </strong>When you cast this spell using a spell slot of 3rd level or higher, the extra damage increases by 1d6 for each slot level above 2nd.</p> </div>', 'ac5f6c40-c9f7-4791-bf0d-a7a4754fb511'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', 'ac5f6c40-c9f7-4791-bf0d-a7a4754fb511'::uuid),
