                    ('Level', 'level', '{"levelNumber":"1","label":"1st"}', '<div> <div> Level </div> <div> 1st </div> </div>', 'f95765d9-e4e4-47c8-be46-d3c111df1ac5'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Action","kind":"action","value":1,"unit":"action","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Action </div> </div>', 'f95765d9-e4e4-47c8-be46-d3c111df1ac5'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"Self (15 ft.)","kind":"self","distanceValue":null,"distanceUnit":null,"area":{"shape":null,"value":15,"unit":"ft"}}', '<div> <div> Range/Area </div> <div> Self <span>(15 ft. <i></i>)</span> </div> </div>', 'f95765d9-e4e4-47c8-be46-d3c111df1ac5'::uuid),
                    ('Components', 'components', '{"text":"V, S","verbal":true,"somatic":true,"material":{"required":false,"description":null,"consumed":null,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S</span> </div> </div>', 'f95765d9-e4e4-47c8-be46-d3c111df1ac5'::uuid),
                    ('Duration', 'duration', '{"text":"Instantaneous","kind":"instantaneous","value":null,"unit":null,"concentration":false,"endCondition":null}', '<div> <div>Duration</div> <div> Instantaneous </div> </div>', 'f95765d9-e4e4-47c8-be46-d3c111df1ac5'::uuid),
                    ('School', 'school', 'Evocation', '<div> <div> School </div> <div> Evocation </div> </div>', 'f95765d9-e4e4-47c8-be46-d3c111df1ac5'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"DEX Save","kind":"save","attackType":null,"ability":"DEX"}', '<div> <div> Attack/Save </div> <div> <i></i> <span>DEX Save</span> </div> </div>', 'f95765d9-e4e4-47c8-be46-d3c111df1ac5'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Fire","damageTypes":["Fire"]}', '<div> <div> Damage/Effect </div> <div> <i></i> Fire </div> </div>', 'f95765d9-e4e4-47c8-be46-d3c111df1ac5'::uuid),
                    ('Description', 'description', '["A thin sheet of flames shoots forth from you. Each creature in a 15-foot Cone makes a Dexterity saving throw, taking 3d6 Fire damage on a failed save or half as much damage on a successful one.","Flammable objects in the Cone that aren’t being worn or carried start burning .","Using a Higher-Level Spell Slot. The damage increases by 1d6 for each spell slot level above 1."]', '<div> <p>A thin sheet of flames shoots forth from you. Each creature in a 15-foot <a>Cone</a> makes a Dexterity saving throw, taking 3d6 Fire damage on a failed save or half as much damage on a successful one.</p> <p>Flammable objects in the Cone that aren’t being worn or carried start <a>burning</a>.</p> <p><strong><em>Using a Higher-Level Spell Slot.</em></strong> The damage increases by 1d6 for each spell slot level above 1.</p> </div>', 'f95765d9-e4e4-47c8-be46-d3c111df1ac5'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', 'f95765d9-e4e4-47c8-be46-d3c111df1ac5'::uuid),
