                    ('Available For', 'availableFor', '["Druid (Legacy)","Druid","Cleric - Tempest Domain (PHB)","Paladin - Oath of the Open Sea (TCSR)"]', '', 'a7d56ee5-ea37-4a33-88b6-3b078ed00fa1'::uuid),
                    ('Source', 'source', 'Player’s Handbook, pg. 248', '', 'a7d56ee5-ea37-4a33-88b6-3b078ed00fa1'::uuid),
                    ('Source URL', 'url', 'https://www.dndbeyond.com/spells/2618949-call-lightning', '', 'a7d56ee5-ea37-4a33-88b6-3b078ed00fa1'::uuid),
                    ('Image', 'imageUrl', 'https://www.dndbeyond.com/attachments/2/708/conjuration.png', '', 'a7d56ee5-ea37-4a33-88b6-3b078ed00fa1'::uuid),
                    ('Level', 'level', '{"levelNumber":"2","label":"2nd"}', '<div> <div> Level </div> <div> 2nd </div> </div>', '29cc4f3d-39dd-41ca-8380-0f5a601148df'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Action","kind":"action","value":1,"unit":"action","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Action </div> </div>', '29cc4f3d-39dd-41ca-8380-0f5a601148df'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"60 ft. (20 ft.)","kind":"distance","distanceValue":60,"distanceUnit":"ft","area":{"shape":null,"value":20,"unit":"ft"}}', '<div> <div> Range/Area </div> <div> 60 ft. <span>(20 ft. <i></i>)</span> </div> </div>', '29cc4f3d-39dd-41ca-8380-0f5a601148df'::uuid),
                    ('Components', 'components', '{"text":"V, S","verbal":true,"somatic":true,"material":{"required":false,"description":null,"consumed":null,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S</span> </div> </div>', '29cc4f3d-39dd-41ca-8380-0f5a601148df'::uuid),
                    ('Duration', 'duration', '{"text":"Concentration 1 Minute","kind":"timed","value":1,"unit":"minute","concentration":true,"endCondition":null}', '<div> <div>Duration</div> <div> <i>Concentration</i> 1 Minute </div> </div>', '29cc4f3d-39dd-41ca-8380-0f5a601148df'::uuid),
                    ('School', 'school', 'Enchantment', '<div> <div> School </div> <div> Enchantment </div> </div>', '29cc4f3d-39dd-41ca-8380-0f5a601148df'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"CHA Save","kind":"save","attackType":null,"ability":"CHA"}', '<div> <div> Attack/Save </div> <div> <i></i> <span>CHA Save</span> </div> </div>', '29cc4f3d-39dd-41ca-8380-0f5a601148df'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Charmed (...)","damageTypes":[]}', '<div> <div> Damage/Effect </div> <div> <i></i> Charmed (...) </div> </div>', '29cc4f3d-39dd-41ca-8380-0f5a601148df'::uuid),
                    ('Description', 'description', '["Each Humanoid in a 20-foot-radius Sphere centered on a point you choose within range must succeed on a Charisma saving throw or be affected by one of the following effects (choose for each creature):"]', '<div> <p>Each Humanoid in a 20-foot-radius <a>Sphere</a> centered on a point you choose within range must succeed on a Charisma saving throw or be affected by one of the following effects (choose for each creature):</p> <ul> <li>The creature has Immunity to the <a>Charmed</a> and <a>Frightened</a> conditions until the spell ends. If the creature was already Charmed or Frightened, those conditions are suppressed for the duration.</li> <li>The creature becomes <a>Indifferent</a> about creatures of your choice that it’s <a>Hostile</a> toward. This indifference ends if the target takes damage or witnesses its allies taking damage. When the spell ends, the creature’s attitude returns to normal.</li> </ul> </div>', '29cc4f3d-39dd-41ca-8380-0f5a601148df'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', '29cc4f3d-39dd-41ca-8380-0f5a601148df'::uuid),
