                    ('Available For', 'availableFor', '["Sorcerer (Legacy)","Wizard (Legacy)","Sorcerer","Wizard"]', '', '4880880f-4e19-4ec0-b581-bdad92d59929'::uuid),
                    ('Source', 'source', 'Player’s Handbook, pg. 249', '', '4880880f-4e19-4ec0-b581-bdad92d59929'::uuid),
                    ('Source URL', 'url', 'https://www.dndbeyond.com/spells/2618960-chain-lightning', '', '4880880f-4e19-4ec0-b581-bdad92d59929'::uuid),
                    ('Image', 'imageUrl', 'https://www.dndbeyond.com/attachments/2/703/evocation.png', '', '4880880f-4e19-4ec0-b581-bdad92d59929'::uuid),
                    ('Level', 'level', '{"levelNumber":"4","label":"4th"}', '<div> <div> Level </div> <div> 4th </div> </div>', '529c31e4-60ef-4027-b36e-e41ecc3e773d'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Action","kind":"action","value":1,"unit":"action","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Action </div> </div>', '529c31e4-60ef-4027-b36e-e41ecc3e773d'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"30 ft.","kind":"distance","distanceValue":30,"distanceUnit":"ft","area":null}', '<div> <div> Range/Area </div> <div> 30 ft. </div> </div>', '529c31e4-60ef-4027-b36e-e41ecc3e773d'::uuid),
                    ('Components', 'components', '{"text":"V, S","verbal":true,"somatic":true,"material":{"required":false,"description":null,"consumed":null,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S</span> </div> </div>', '529c31e4-60ef-4027-b36e-e41ecc3e773d'::uuid),
                    ('Duration', 'duration', '{"text":"1 Hour","kind":"timed","value":1,"unit":"hour","concentration":false,"endCondition":null}', '<div> <div>Duration</div> <div> 1 Hour </div> </div>', '529c31e4-60ef-4027-b36e-e41ecc3e773d'::uuid),
                    ('School', 'school', 'Enchantment', '<div> <div> School </div> <div> Enchantment </div> </div>', '529c31e4-60ef-4027-b36e-e41ecc3e773d'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"WIS Save","kind":"save","attackType":null,"ability":"WIS"}', '<div> <div> Attack/Save </div> <div> <i></i> <span>WIS Save</span> </div> </div>', '529c31e4-60ef-4027-b36e-e41ecc3e773d'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Charmed","damageTypes":[]}', '<div> <div> Damage/Effect </div> <div> <i></i> Charmed </div> </div>', '529c31e4-60ef-4027-b36e-e41ecc3e773d'::uuid),
                    ('Description', 'description', '["One creature you can see within range makes a Wisdom saving throw. It does so with Advantage if you or your allies are fighting it. On a failed save, the target has the Charmed condition until the spell ends or until you or your allies damage it. The Charmed creature is Friendly to you. When the spell ends, the target knows it was Charmed by you.","Using a Higher-Level Spell Slot. You can target one additional creature for each spell slot level above 4."]', '<div> <p>One creature you can see within range makes a Wisdom saving throw. It does so with Advantage if you or your allies are fighting it. On a failed save, the target has the <a>Charmed</a> condition until the spell ends or until you or your allies damage it. The Charmed creature is <a>Friendly</a> to you. When the spell ends, the target knows it was Charmed by you.</p> <p><strong><em>Using a Higher-Level Spell Slot.</em></strong> You can target one additional creature for each spell slot level above 4.</p> </div>', '529c31e4-60ef-4027-b36e-e41ecc3e773d'::uuid),
