                    ('Components', 'components', '{"text":"V, S","verbal":true,"somatic":true,"material":{"required":false,"description":null,"consumed":null,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S</span> </div> </div>', '9d46f12b-6d20-4ce9-b40e-83de7ddc0262'::uuid),
                    ('Duration', 'duration', '{"text":"1 Hour","kind":"timed","value":1,"unit":"hour","concentration":false,"endCondition":null}', '<div> <div>Duration</div> <div> 1 Hour </div> </div>', '9d46f12b-6d20-4ce9-b40e-83de7ddc0262'::uuid),
                    ('School', 'school', 'Enchantment', '<div> <div> School </div> <div> Enchantment </div> </div>', '9d46f12b-6d20-4ce9-b40e-83de7ddc0262'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"WIS Save","kind":"save","attackType":null,"ability":"WIS"}', '<div> <div> Attack/Save </div> <div> <i></i> <span>WIS Save</span> </div> </div>', '9d46f12b-6d20-4ce9-b40e-83de7ddc0262'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Charmed","damageTypes":[]}', '<div> <div> Damage/Effect </div> <div> <i></i> Charmed </div> </div>', '9d46f12b-6d20-4ce9-b40e-83de7ddc0262'::uuid),
                    ('Description', 'description', '["One Humanoid you can see within range makes a Wisdom saving throw. It does so with Advantage if you or your allies are fighting it. On a failed save, the target has the Charmed condition until the spell ends or until you or your allies damage it. The Charmed creature is Friendly to you. When the spell ends, the target knows it was Charmed by you.","Using a Higher-Level Spell Slot. You can target one additional creature for each spell slot level above 1."]', '<div> <p>One Humanoid you can see within range makes a Wisdom saving throw. It does so with Advantage if you or your allies are fighting it. On a failed save, the target has the <a>Charmed</a> condition until the spell ends or until you or your allies damage it. The Charmed creature is <a>Friendly</a> to you. When the spell ends, the target knows it was Charmed by you.</p> <p><strong><em>Using a Higher-Level Spell Slot.</em></strong> You can target one additional creature for each spell slot level above 1.</p> </div>', '9d46f12b-6d20-4ce9-b40e-83de7ddc0262'::uuid),
