                    ('Image', 'imageUrl', 'https://www.dndbeyond.com/attachments/2/702/enchantment.png', '', '9d46f12b-6d20-4ce9-b40e-83de7ddc0262'::uuid),
                    ('Level', 'level', '{"levelNumber":"Cantrip","label":"Cantrip"}', '<div> <div> Level </div> <div> Cantrip </div> </div>', 'd48c76ad-d04a-4134-9ff9-76740218e2df'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Action","kind":"action","value":1,"unit":"action","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Action </div> </div>', 'd48c76ad-d04a-4134-9ff9-76740218e2df'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"Touch","kind":"touch","distanceValue":null,"distanceUnit":null,"area":null}', '<div> <div> Range/Area </div> <div> Touch </div> </div>', 'd48c76ad-d04a-4134-9ff9-76740218e2df'::uuid),
                    ('Components', 'components', '{"text":"V, S","verbal":true,"somatic":true,"material":{"required":false,"description":null,"consumed":null,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S</span> </div> </div>', 'd48c76ad-d04a-4134-9ff9-76740218e2df'::uuid),
                    ('Duration', 'duration', '{"text":"Instantaneous","kind":"instantaneous","value":null,"unit":null,"concentration":false,"endCondition":null}', '<div> <div>Duration</div> <div> Instantaneous </div> </div>', 'd48c76ad-d04a-4134-9ff9-76740218e2df'::uuid),
                    ('School', 'school', 'Necromancy', '<div> <div> School </div> <div> Necromancy </div> </div>', 'd48c76ad-d04a-4134-9ff9-76740218e2df'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"Melee","kind":"attack","attackType":"melee","ability":null}', '<div> <div> Attack/Save </div> <div> <i></i> <span>Melee</span> </div> </div>', 'd48c76ad-d04a-4134-9ff9-76740218e2df'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Necrotic","damageTypes":["Necrotic"]}', '<div> <div> Damage/Effect </div> <div> <i></i> Necrotic </div> </div>', 'd48c76ad-d04a-4134-9ff9-76740218e2df'::uuid),
                    ('Description', 'description', '["Channeling the chill of the grave, make a melee spell attack against a target within reach. On a hit, the target takes 1d10 Necrotic damage, and it can’t regain Hit Points until the end of your next turn.","Cantrip Upgrade. The damage increases by 1d10 when you reach levels 5 (2d10), 11 (3d10), and 17 (4d10)."]', '<div> <p>Channeling the chill of the grave, make a melee spell attack against a target within reach. On a hit, the target takes 1d10 Necrotic damage, and it can’t regain Hit Points until the end of your next turn.</p> <p><strong><em>Cantrip Upgrade.</em></strong> The damage increases by 1d10 when you reach levels 5 (2d10), 11 (3d10), and 17 (4d10).</p> </div>', 'd48c76ad-d04a-4134-9ff9-76740218e2df'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', 'd48c76ad-d04a-4134-9ff9-76740218e2df'::uuid),
