                    ('Source', 'source', 'Player’s Handbook, pg. 249', '', 'd48c76ad-d04a-4134-9ff9-76740218e2df'::uuid),
                    ('Source URL', 'url', 'https://www.dndbeyond.com/spells/2618965-chill-touch', '', 'd48c76ad-d04a-4134-9ff9-76740218e2df'::uuid),
                    ('Image', 'imageUrl', 'https://www.dndbeyond.com/attachments/2/720/necromancy.png', '', 'd48c76ad-d04a-4134-9ff9-76740218e2df'::uuid),
                    ('Level', 'level', '{"levelNumber":"1","label":"1st"}', '<div> <div> Level </div> <div> 1st </div> </div>', '46885114-ba21-4c40-a9f2-6c5dd748f13d'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Action","kind":"action","value":1,"unit":"action","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Action </div> </div>', '46885114-ba21-4c40-a9f2-6c5dd748f13d'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"90 ft.","kind":"distance","distanceValue":90,"distanceUnit":"ft","area":null}', '<div> <div> Range/Area </div> <div> 90 ft. </div> </div>', '46885114-ba21-4c40-a9f2-6c5dd748f13d'::uuid),
                    ('Components', 'components', '{"text":"V, S, M *","verbal":true,"somatic":true,"material":{"required":true,"description":"a diamond worth 50+ GP","consumed":false,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S, M *</span> </div> </div>', '46885114-ba21-4c40-a9f2-6c5dd748f13d'::uuid),
                    ('Duration', 'duration', '{"text":"Instantaneous","kind":"instantaneous","value":null,"unit":null,"concentration":false,"endCondition":null}', '<div> <div>Duration</div> <div> Instantaneous </div> </div>', '46885114-ba21-4c40-a9f2-6c5dd748f13d'::uuid),
                    ('School', 'school', 'Evocation', '<div> <div> School </div> <div> Evocation </div> </div>', '46885114-ba21-4c40-a9f2-6c5dd748f13d'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"Ranged","kind":"attack","attackType":"ranged","ability":null}', '<div> <div> Attack/Save </div> <div> <i></i> <span>Ranged</span> </div> </div>', '46885114-ba21-4c40-a9f2-6c5dd748f13d'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Acid (...)","damageTypes":["Acid"]}', '<div> <div> Damage/Effect </div> <div> <i></i> Acid (...) </div> </div>', '46885114-ba21-4c40-a9f2-6c5dd748f13d'::uuid),
                    ('Description', 'description', '["You hurl an orb of energy at a target within range. Choose Acid, Cold, Fire, Lightning, Poison, or Thunder for the type of orb you create, and then make a ranged spell attack against the target. On a hit, the target takes 3d8 damage of the chosen type.","If you roll the same number on two or more of the d8s, the orb leaps to a different target of your choice within 30 feet of the target. Make an attack roll against the new target, and make a new damage roll. The orb can’t leap again unless you cast the spell with a level 2+ spell slot.","Using a Higher-Level Spell Slot. The damage increases by 1d8 for each spell slot level above 1. The orb can leap a maximum number of times equal to the level of the slot expended, and a creature can be targeted only once by each casting of this spell."]', '<div> <p>You hurl an orb of energy at a target within range. Choose Acid, Cold, Fire, Lightning, Poison, or Thunder for the type of orb you create, and then make a ranged spell attack against the target. On a hit, the target takes 3d8 damage of the chosen type.</p> <p>If you roll the same number on two or more of the d8s, the orb leaps to a different target of your choice within 30 feet of the target. Make an attack roll against the new target, and make a new damage roll. The orb can’t leap again unless you cast the spell with a level 2+ spell slot.</p> <p><strong><em>Using a Higher-Level Spell Slot.</em></strong> The damage increases by 1d8 for each spell slot level above 1. The orb can leap a maximum number of times equal to the level of the slot expended, and a creature can be targeted only once by each casting of this spell.</p> <span>* - (a diamond worth 50+ GP)</span> </div>', '46885114-ba21-4c40-a9f2-6c5dd748f13d'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', '46885114-ba21-4c40-a9f2-6c5dd748f13d'::uuid),
