                    ('Available For', 'availableFor', '["Sorcerer (Legacy)","Wizard (Legacy)","Sorcerer","Wizard","Sorcerer - Draconic Sorcery"]', '', '46885114-ba21-4c40-a9f2-6c5dd748f13d'::uuid),
                    ('Source', 'source', 'Player’s Handbook, pg. 249', '', '46885114-ba21-4c40-a9f2-6c5dd748f13d'::uuid),
                    ('Source URL', 'url', 'https://www.dndbeyond.com/spells/2618966-chromatic-orb', '', '46885114-ba21-4c40-a9f2-6c5dd748f13d'::uuid),
                    ('Image', 'imageUrl', 'https://www.dndbeyond.com/attachments/2/703/evocation.png', '', '46885114-ba21-4c40-a9f2-6c5dd748f13d'::uuid),
                    ('Level', 'level', '{"levelNumber":"6","label":"6th"}', '<div> <div> Level </div> <div> 6th </div> </div>', '26fcaa7d-186b-4b29-90b8-d225dc6cbcc7'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Action","kind":"action","value":1,"unit":"action","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Action </div> </div>', '26fcaa7d-186b-4b29-90b8-d225dc6cbcc7'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"150 ft. (60 ft.)","kind":"distance","distanceValue":150,"distanceUnit":"ft","area":{"shape":null,"value":60,"unit":"ft"}}', '<div> <div> Range/Area </div> <div> 150 ft. <span>(60 ft. <i></i>)</span> </div> </div>', '26fcaa7d-186b-4b29-90b8-d225dc6cbcc7'::uuid),
                    ('Components', 'components', '{"text":"V, S, M *","verbal":true,"somatic":true,"material":{"required":true,"description":"the powder of a crushed black pearl worth 500+ GP","consumed":false,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S, M *</span> </div> </div>', '26fcaa7d-186b-4b29-90b8-d225dc6cbcc7'::uuid),
                    ('Duration', 'duration', '{"text":"Instantaneous","kind":"instantaneous","value":null,"unit":null,"concentration":false,"endCondition":null}', '<div> <div>Duration</div> <div> Instantaneous </div> </div>', '26fcaa7d-186b-4b29-90b8-d225dc6cbcc7'::uuid),
                    ('School', 'school', 'Necromancy', '<div> <div> School </div> <div> Necromancy </div> </div>', '26fcaa7d-186b-4b29-90b8-d225dc6cbcc7'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"CON Save","kind":"save","attackType":null,"ability":"CON"}', '<div> <div> Attack/Save </div> <div> <i></i> <span>CON Save</span> </div> </div>', '26fcaa7d-186b-4b29-90b8-d225dc6cbcc7'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Necrotic","damageTypes":["Necrotic"]}', '<div> <div> Damage/Effect </div> <div> <i></i> Necrotic </div> </div>', '26fcaa7d-186b-4b29-90b8-d225dc6cbcc7'::uuid),
                    ('Description', 'description', '["Negative energy ripples out in a 60-foot-radius Sphere from a point you choose within range. Each creature in that area makes a Constitution saving throw, taking 8d8 Necrotic damage on a failed save or half as much damage on a successful one.","Using a Higher-Level Spell Slot. The damage increases by 2d8 for each spell slot level above 6."]', '<div> <p>Negative energy ripples out in a 60-foot-radius <a>Sphere</a> from a point you choose within range. Each creature in that area makes a Constitution saving throw, taking 8d8 Necrotic damage on a failed save or half as much damage on a successful one.</p> <p><strong><em>Using a Higher-Level Spell Slot.</em></strong> The damage increases by 2d8 for each spell slot level above 6.</p> <span>* - (the powder of a crushed black pearl worth 500+ GP)</span> </div>', '26fcaa7d-186b-4b29-90b8-d225dc6cbcc7'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', '26fcaa7d-186b-4b29-90b8-d225dc6cbcc7'::uuid);
                """);

            migrationBuilder.Sql("""
                INSERT INTO "SpellComponents" ("Label", "Key", "Value", "Html", "SpellId") VALUES
                    ('Spell Tags', 'spellTags', '["Damage"]', '', '26fcaa7d-186b-4b29-90b8-d225dc6cbcc7'::uuid),
                    ('Available For', 'availableFor', '["Sorcerer (Legacy)","Warlock (Legacy)","Wizard (Legacy)","Sorcerer","Warlock","Wizard"]', '', '26fcaa7d-186b-4b29-90b8-d225dc6cbcc7'::uuid),
                    ('Source', 'source', 'Player’s Handbook, pg. 250', '', '26fcaa7d-186b-4b29-90b8-d225dc6cbcc7'::uuid),
                    ('Source URL', 'url', 'https://www.dndbeyond.com/spells/2618969-circle-of-death', '', '26fcaa7d-186b-4b29-90b8-d225dc6cbcc7'::uuid),
                    ('Image', 'imageUrl', 'https://www.dndbeyond.com/attachments/2/720/necromancy.png', '', '26fcaa7d-186b-4b29-90b8-d225dc6cbcc7'::uuid),
                    ('Level', 'level', '{"levelNumber":"5","label":"5th"}', '', '742bf726-7743-4c5e-8208-2c56841d9ef0'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Action","kind":"action","value":1,"unit":"action","trigger":null,"ritual":false}', '', '742bf726-7743-4c5e-8208-2c56841d9ef0'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"Self (30 ft. )","kind":"self","distanceValue":null,"distanceUnit":null,"area":{"shape":null,"value":30,"unit":"ft"}}', '', '742bf726-7743-4c5e-8208-2c56841d9ef0'::uuid),
                    ('Components', 'components', '{"text":"V","verbal":true,"somatic":false,"material":{"required":false,"description":null,"consumed":null,"costGp":null}}', '', '742bf726-7743-4c5e-8208-2c56841d9ef0'::uuid),
                    ('Duration', 'duration', '{"text":"Concentration 10 Minutes","kind":"timed","value":10,"unit":"minute","concentration":true,"endCondition":null}', '', '742bf726-7743-4c5e-8208-2c56841d9ef0'::uuid),
                    ('School', 'school', 'Abjuration', '', '742bf726-7743-4c5e-8208-2c56841d9ef0'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"None","kind":"none","attackType":null,"ability":null}', '', '742bf726-7743-4c5e-8208-2c56841d9ef0'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Buff (...)","damageTypes":[]}', '', '742bf726-7743-4c5e-8208-2c56841d9ef0'::uuid),
                    ('Description', 'description', '["An aura radiates from you in a 30-foot Emanation for the duration. While in the aura, you and your allies have Advantage on saving throws against spells and other magical effects. When an affected creature makes a saving throw against a spell or magical effect that allows a save to take only half damage, it takes no damage if it succeeds on the save."]', '<p>An aura radiates from you in a 30-foot Emanation for the duration. While in the aura, you and your allies have Advantage on saving throws against spells and other magical effects. When an affected creature makes a saving throw against a spell or magical effect that allows a save to take only half damage, it takes no damage if it succeeds on the save.</p>', '742bf726-7743-4c5e-8208-2c56841d9ef0'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', '742bf726-7743-4c5e-8208-2c56841d9ef0'::uuid),
                    ('Spell Tags', 'spellTags', '[]', '', '742bf726-7743-4c5e-8208-2c56841d9ef0'::uuid),
                    ('Available For', 'availableFor', '["Cleric","Paladin","Wizard"]', '', '742bf726-7743-4c5e-8208-2c56841d9ef0'::uuid),
                    ('Source', 'source', 'Player’s Handbook (2024)', '', '742bf726-7743-4c5e-8208-2c56841d9ef0'::uuid),
                    ('Source URL', 'url', 'https://www.dndbeyond.com/spells/2618970-circle-of-power', '', '742bf726-7743-4c5e-8208-2c56841d9ef0'::uuid),
                    ('Image', 'imageUrl', '', '', '742bf726-7743-4c5e-8208-2c56841d9ef0'::uuid),
                    ('Level', 'level', '{"levelNumber":"3","label":"3rd"}', '<div> <div> Level </div> <div> 3rd </div> </div>', 'fe66f9c8-9ee7-48b6-be0a-9951233d3e8d'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"10 Minutes","kind":"timed","value":10,"unit":"minute","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 10 Minutes </div> </div>', 'fe66f9c8-9ee7-48b6-be0a-9951233d3e8d'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"1 mile","kind":"distance","distanceValue":1,"distanceUnit":"mile","area":null}', '<div> <div> Range/Area </div> <div> 1 mile </div> </div>', 'fe66f9c8-9ee7-48b6-be0a-9951233d3e8d'::uuid),
                    ('Components', 'components', '{"text":"V, S, M *","verbal":true,"somatic":true,"material":{"required":true,"description":"a focus worth 100+ GP, either a jeweled horn for hearing or a glass eye for seeing","consumed":false,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S, M *</span> </div> </div>', 'fe66f9c8-9ee7-48b6-be0a-9951233d3e8d'::uuid),
                    ('Duration', 'duration', '{"text":"Concentration 10 Minutes","kind":"timed","value":10,"unit":"minute","concentration":true,"endCondition":null}', '<div> <div>Duration</div> <div> <i>Concentration</i> 10 Minutes </div> </div>', 'fe66f9c8-9ee7-48b6-be0a-9951233d3e8d'::uuid),
                    ('School', 'school', 'Divination', '<div> <div> School </div> <div> Divination </div> </div>', 'fe66f9c8-9ee7-48b6-be0a-9951233d3e8d'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"None","kind":"none","attackType":null,"ability":null}', '<div> <div> Attack/Save </div> <div> <span>None</span> </div> </div>', 'fe66f9c8-9ee7-48b6-be0a-9951233d3e8d'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Detection (...)","damageTypes":[]}', '<div> <div> Damage/Effect </div> <div> Detection (...) </div> </div>', 'fe66f9c8-9ee7-48b6-be0a-9951233d3e8d'::uuid),
                    ('Description', 'description', '["You create an Invisible sensor within range in a location familiar to you (a place you have visited or seen before) or in an obvious location that is unfamiliar to you (such as behind a door, around a corner, or in a grove of trees). The intangible, invulnerable sensor remains in place for the duration.","When you cast the spell, choose seeing or hearing. You can use the chosen sense through the sensor as if you were in its space. As a Bonus Action, you can switch between seeing and hearing.","A creature that sees the sensor (such as a creature benefiting from See Invisibility or Truesight ) sees a luminous orb about the size of your fist."]', '<div> <p>You create an <a>Invisible</a> sensor within range in a location familiar to you (a place you have visited or seen before) or in an obvious location that is unfamiliar to you (such as behind a door, around a corner, or in a grove of trees). The intangible, invulnerable sensor remains in place for the duration.</p> <p>When you cast the spell, choose seeing or hearing. You can use the chosen sense through the sensor as if you were in its space. As a Bonus Action, you can switch between seeing and hearing.</p> <p>A creature that sees the sensor (such as a creature benefiting from <a>See Invisibility</a> or <a>Truesight</a>) sees a luminous orb about the size of your fist.</p> <span>* - (a focus worth 100+ GP, either a jeweled horn for hearing or a glass eye for seeing)</span> </div>', 'fe66f9c8-9ee7-48b6-be0a-9951233d3e8d'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', 'fe66f9c8-9ee7-48b6-be0a-9951233d3e8d'::uuid),
                    ('Spell Tags', 'spellTags', '["Scrying","Detection","Utility"]', '', 'fe66f9c8-9ee7-48b6-be0a-9951233d3e8d'::uuid),
                    ('Available For', 'availableFor', '["Bard (Legacy)","Cleric (Legacy)","Sorcerer (Legacy)","Wizard (Legacy)","Bard","Cleric","Sorcerer","Wizard","Warlock - Great Old One Patron","Warlock - Great Fool Patron"]', '', 'fe66f9c8-9ee7-48b6-be0a-9951233d3e8d'::uuid),
                    ('Source', 'source', 'Player’s Handbook, pg. 250', '', 'fe66f9c8-9ee7-48b6-be0a-9951233d3e8d'::uuid),
                    ('Source URL', 'url', 'https://www.dndbeyond.com/spells/2618972-clairvoyance', '', 'fe66f9c8-9ee7-48b6-be0a-9951233d3e8d'::uuid),
                    ('Image', 'imageUrl', 'https://www.dndbeyond.com/attachments/2/709/divination.png', '', 'fe66f9c8-9ee7-48b6-be0a-9951233d3e8d'::uuid),
                    ('Level', 'level', '{"levelNumber":"8","label":"8th"}', '<div> <div> Level </div> <div> 8th </div> </div>', 'd53fab58-c543-4461-bcf7-bb26d5b91896'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Hour","kind":"timed","value":1,"unit":"hour","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Hour </div> </div>', 'd53fab58-c543-4461-bcf7-bb26d5b91896'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"Touch","kind":"touch","distanceValue":null,"distanceUnit":null,"area":null}', '<div> <div> Range/Area </div> <div> Touch </div> </div>', 'd53fab58-c543-4461-bcf7-bb26d5b91896'::uuid),
                    ('Components', 'components', '{"text":"V, S, M *","verbal":true,"somatic":true,"material":{"required":true,"description":"a diamond worth 1,000+ GP, which the spell consumes, and a sealable vessel worth 2,000+ GP that is large enough to hold the creature being cloned","consumed":true,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S, M *</span> </div> </div>', 'd53fab58-c543-4461-bcf7-bb26d5b91896'::uuid),
                    ('Duration', 'duration', '{"text":"Instantaneous","kind":"instantaneous","value":null,"unit":null,"concentration":false,"endCondition":null}', '<div> <div>Duration</div> <div> Instantaneous </div> </div>', 'd53fab58-c543-4461-bcf7-bb26d5b91896'::uuid),
                    ('School', 'school', 'Necromancy', '<div> <div> School </div> <div> Necromancy </div> </div>', 'd53fab58-c543-4461-bcf7-bb26d5b91896'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"None","kind":"none","attackType":null,"ability":null}', '<div> <div> Attack/Save </div> <div> <span>None</span> </div> </div>', 'd53fab58-c543-4461-bcf7-bb26d5b91896'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Utility","damageTypes":[]}', '<div> <div> Damage/Effect </div> <div> Utility </div> </div>', 'd53fab58-c543-4461-bcf7-bb26d5b91896'::uuid),
                    ('Description', 'description', '["You touch a creature or at least 1 cubic inch of its flesh. An inert duplicate of that creature forms inside the vessel used in the spell’s casting and finishes growing after 120 days; you choose whether the finished clone is the same age as the creature or younger. The clone remains inert and endures indefinitely while its vessel remains undisturbed.","If the original creature dies after the clone finishes forming, the creature’s soul transfers to the clone if the soul is free and willing to return. The clone is physically identical to the original and has the same personality, memories, and abilities, but none of the original’s equipment. The creature’s original remains, if any, become inert and can’t be revived, since the creature’s soul is elsewhere."]', '<div> <p>You touch a creature or at least 1 cubic inch of its flesh. An inert duplicate of that creature forms inside the vessel used in the spell’s casting and finishes growing after 120 days; you choose whether the finished clone is the same age as the creature or younger. The clone remains inert and endures indefinitely while its vessel remains undisturbed.</p> <p>If the original creature dies after the clone finishes forming, the creature’s soul transfers to the clone if the soul is free and willing to return. The clone is physically identical to the original and has the same personality, memories, and abilities, but none of the original’s equipment. The creature’s original remains, if any, become inert and can’t be revived, since the creature’s soul is elsewhere.</p> <span>* - (a diamond worth 1,000+ GP, which the spell consumes, and a sealable vessel worth 2,000+ GP that is large enough to hold the creature being cloned)</span> </div>', 'd53fab58-c543-4461-bcf7-bb26d5b91896'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', 'd53fab58-c543-4461-bcf7-bb26d5b91896'::uuid),
                    ('Spell Tags', 'spellTags', '["Utility"]', '', 'd53fab58-c543-4461-bcf7-bb26d5b91896'::uuid),
                    ('Available For', 'availableFor', '["Wizard (Legacy)","Wizard"]', '', 'd53fab58-c543-4461-bcf7-bb26d5b91896'::uuid),
                    ('Source', 'source', 'Player’s Handbook, pg. 251', '', 'd53fab58-c543-4461-bcf7-bb26d5b91896'::uuid),
                    ('Source URL', 'url', 'https://www.dndbeyond.com/spells/2618973-clone', '', 'd53fab58-c543-4461-bcf7-bb26d5b91896'::uuid),
                    ('Image', 'imageUrl', 'https://www.dndbeyond.com/attachments/2/720/necromancy.png', '', 'd53fab58-c543-4461-bcf7-bb26d5b91896'::uuid),
                    ('Level', 'level', '{"levelNumber":"2","label":"2nd"}', '', '85a973d4-f94a-4b17-875d-0c355dfbb60f'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Action","kind":"action","value":1,"unit":"action","trigger":null,"ritual":false}', '', '85a973d4-f94a-4b17-875d-0c355dfbb60f'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"60 ft. (5 ft. )","kind":"distance","distanceValue":60,"distanceUnit":"ft","area":{"shape":null,"value":5,"unit":"ft"}}', '', '85a973d4-f94a-4b17-875d-0c355dfbb60f'::uuid),
                    ('Components', 'components', '{"text":"V, S, M *","verbal":true,"somatic":true,"material":{"required":true,"description":null,"consumed":null,"costGp":null}}', '', '85a973d4-f94a-4b17-875d-0c355dfbb60f'::uuid),
                    ('Duration', 'duration', '{"text":"Concentration 1 Minute","kind":"timed","value":1,"unit":"minute","concentration":true,"endCondition":null}', '', '85a973d4-f94a-4b17-875d-0c355dfbb60f'::uuid),
                    ('School', 'school', 'Conjuration', '', '85a973d4-f94a-4b17-875d-0c355dfbb60f'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"None","kind":"none","attackType":null,"ability":null}', '', '85a973d4-f94a-4b17-875d-0c355dfbb60f'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Slashing","damageTypes":["Slashing"]}', '', '85a973d4-f94a-4b17-875d-0c355dfbb60f'::uuid),
                    ('Description', 'description', '["You conjure spinning daggers in a 5-foot Cube centered on a point within range. Each creature in that area takes 4d4 Slashing damage. A creature also takes this damage if it enters the Cube or ends its turn there or if the Cube moves into its space. A creature takes this damage only once per turn.","On your later turns, you can take a Magic action to teleport the Cube up to 30 feet.","Using a Higher-Level Spell Slot. The damage increases by 2d4 for each spell slot level above 2."]', '<p>You conjure spinning daggers in a 5-foot Cube centered on a point within range. Each creature in that area takes 4d4 Slashing damage. A creature also takes this damage if it enters the Cube or ends its turn there or if the Cube moves into its space. A creature takes this damage only once per turn.</p> <p>On your later turns, you can take a Magic action to teleport the Cube up to 30 feet.</p> <p>Using a Higher-Level Spell Slot. The damage increases by 2d4 for each spell slot level above 2.</p>', '85a973d4-f94a-4b17-875d-0c355dfbb60f'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', '85a973d4-f94a-4b17-875d-0c355dfbb60f'::uuid),
                    ('Spell Tags', 'spellTags', '[]', '', '85a973d4-f94a-4b17-875d-0c355dfbb60f'::uuid),
                    ('Available For', 'availableFor', '["Bard","Sorcerer","Warlock","Wizard"]', '', '85a973d4-f94a-4b17-875d-0c355dfbb60f'::uuid),
                    ('Source', 'source', 'Player’s Handbook (2024)', '', '85a973d4-f94a-4b17-875d-0c355dfbb60f'::uuid),
                    ('Source URL', 'url', 'https://www.dndbeyond.com/spells/2618974-cloud-of-daggers', '', '85a973d4-f94a-4b17-875d-0c355dfbb60f'::uuid),
                    ('Image', 'imageUrl', '', '', '85a973d4-f94a-4b17-875d-0c355dfbb60f'::uuid),
                    ('Level', 'level', '{"levelNumber":"5","label":"5th"}', '<div> <div> Level </div> <div> 5th </div> </div>', 'f4f6010f-667a-455c-90fa-20fd6a90ef6f'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Action","kind":"action","value":1,"unit":"action","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Action </div> </div>', 'f4f6010f-667a-455c-90fa-20fd6a90ef6f'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"120 ft. (20 ft.)","kind":"distance","distanceValue":120,"distanceUnit":"ft","area":{"shape":null,"value":20,"unit":"ft"}}', '<div> <div> Range/Area </div> <div> 120 ft. <span>(20 ft. <i></i>)</span> </div> </div>', 'f4f6010f-667a-455c-90fa-20fd6a90ef6f'::uuid),
                    ('Components', 'components', '{"text":"V, S","verbal":true,"somatic":true,"material":{"required":false,"description":null,"consumed":null,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S</span> </div> </div>', 'f4f6010f-667a-455c-90fa-20fd6a90ef6f'::uuid),
                    ('Duration', 'duration', '{"text":"Concentration 10 Minutes","kind":"timed","value":10,"unit":"minute","concentration":true,"endCondition":null}', '<div> <div>Duration</div> <div> <i>Concentration</i> 10 Minutes </div> </div>', 'f4f6010f-667a-455c-90fa-20fd6a90ef6f'::uuid),
                    ('School', 'school', 'Conjuration', '<div> <div> School </div> <div> Conjuration </div> </div>', 'f4f6010f-667a-455c-90fa-20fd6a90ef6f'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"CON Save","kind":"save","attackType":null,"ability":"CON"}', '<div> <div> Attack/Save </div> <div> <i></i> <span>CON Save</span> </div> </div>', 'f4f6010f-667a-455c-90fa-20fd6a90ef6f'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Poison","damageTypes":["Poison"]}', '<div> <div> Damage/Effect </div> <div> <i></i> Poison </div> </div>', 'f4f6010f-667a-455c-90fa-20fd6a90ef6f'::uuid),
                    ('Description', 'description', '["You create a 20-foot-radius Sphere of yellow-green fog centered on a point within range. The fog lasts for the duration or until strong wind (such as the one created by Gust of Wind ) disperses it, ending the spell. Its area is Heavily Obscured .","Each creature in the Sphere makes a Constitution saving throw, taking 5d8 Poison damage on a failed save or half as much damage on a successful one. A creature must also make this save when the Sphere moves into its space and when it enters the Sphere or ends its turn there. A creature makes this save only once per turn.","The Sphere moves 10 feet away from you at the start of each of your turns.","Using a Higher-Level Spell Slot. The damage increases by 1d8 for each spell slot level above 5."]', '<div> <p>You create a 20-foot-radius <a>Sphere</a> of yellow-green fog centered on a point within range. The fog lasts for the duration or until strong wind (such as the one created by <a>Gust of Wind</a>) disperses it, ending the spell. Its area is <a>Heavily Obscured</a>.</p> <p>Each creature in the Sphere makes a Constitution saving throw, taking 5d8 Poison damage on a failed save or half as much damage on a successful one. A creature must also make this save when the Sphere moves into its space and when it enters the Sphere or ends its turn there. A creature makes this save only once per turn.</p> <p>The Sphere moves 10 feet away from you at the start of each of your turns.</p> <p><strong><em>Using a Higher-Level Spell Slot.</em></strong> The damage increases by 1d8 for each spell slot level above 5.</p> </div>', 'f4f6010f-667a-455c-90fa-20fd6a90ef6f'::uuid),
