                    ('Attack/Save', 'attackSave', '{"text":"CON Save","kind":"save","attackType":null,"ability":"CON"}', '<div> <div> Attack/Save </div> <div> <i></i> <span>CON Save</span> </div> </div>', '42208213-c721-424f-8a9f-8185b3a753d2'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Blinded","damageTypes":[]}', '<div> <div> Damage/Effect </div> <div> <i></i> Blinded </div> </div>', '42208213-c721-424f-8a9f-8185b3a753d2'::uuid),
                    ('Description', 'description', '["You launch a dazzling array of flashing, colorful light. Each creature in a 15-foot Cone originating from you must succeed on a Constitution saving throw or have the Blinded condition until the end of your next turn."]', '<div> <p>You launch a dazzling array of flashing, colorful light. Each creature in a 15-foot <a>Cone</a> originating from you must succeed on a Constitution saving throw or have the <a>Blinded</a> condition until the end of your next turn.</p> <span>* - (a pinch of colorful sand)</span> </div>', '42208213-c721-424f-8a9f-8185b3a753d2'::uuid),
