                    ('Source URL', 'url', 'https://www.dndbeyond.com/spells/2618989-commune-with-nature', '', '212b68dd-320a-4e3b-bde3-bd8d5af78921'::uuid),
                    ('Image', 'imageUrl', 'https://www.dndbeyond.com/attachments/2/709/divination.png', '', '212b68dd-320a-4e3b-bde3-bd8d5af78921'::uuid),
                    ('Level', 'level', '{"levelNumber":"5","label":"5th"}', '<div> <div> Level </div> <div> 5th </div> </div>', 'ad743808-eecb-4312-b3cf-99e635374fe0'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Minute Ritual","kind":"timed","value":1,"unit":"minute","trigger":null,"ritual":true}', '<div> <div> Casting Time </div> <div> 1 Minute <i>Ritual</i> </div> </div>', 'ad743808-eecb-4312-b3cf-99e635374fe0'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"Self","kind":"self","distanceValue":null,"distanceUnit":null,"area":null}', '<div> <div> Range/Area </div> <div> Self </div> </div>', 'ad743808-eecb-4312-b3cf-99e635374fe0'::uuid),
                    ('Components', 'components', '{"text":"V, S, M *","verbal":true,"somatic":true,"material":{"required":true,"description":"incense","consumed":false,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S, M *</span> </div> </div>', 'ad743808-eecb-4312-b3cf-99e635374fe0'::uuid),
                    ('Duration', 'duration', '{"text":"1 Minute","kind":"timed","value":1,"unit":"minute","concentration":false,"endCondition":null}', '<div> <div>Duration</div> <div> 1 Minute </div> </div>', 'ad743808-eecb-4312-b3cf-99e635374fe0'::uuid),
                    ('School', 'school', 'Divination', '<div> <div> School </div> <div> Divination </div> </div>', 'ad743808-eecb-4312-b3cf-99e635374fe0'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"None","kind":"none","attackType":null,"ability":null}', '<div> <div> Attack/Save </div> <div> <span>None</span> </div> </div>', 'ad743808-eecb-4312-b3cf-99e635374fe0'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Foreknowledge","damageTypes":[]}', '<div> <div> Damage/Effect </div> <div> Foreknowledge </div> </div>', 'ad743808-eecb-4312-b3cf-99e635374fe0'::uuid),
                    ('Description', 'description', '["You contact a deity or a divine proxy and ask up to three questions that can be answered with yes or no. You must ask your questions before the spell ends. You receive a correct answer for each question.","Divine beings aren’t necessarily omniscient, so you might receive “unclear” as an answer if a question pertains to information that lies beyond the deity’s knowledge. In a case where a one-word answer could be misleading or contrary to the deity’s interests, the DM might offer a short phrase as an answer instead.","If you cast the spell more than once before finishing a Long Rest, there is a cumulative 25 percent chance for each casting after the first that you get no answer."]', '<div> <p>You contact a deity or a divine proxy and ask up to three questions that can be answered with yes or no. You must ask your questions before the spell ends. You receive a correct answer for each question.</p> <p>Divine beings aren’t necessarily omniscient, so you might receive “unclear” as an answer if a question pertains to information that lies beyond the deity’s knowledge. In a case where a one-word answer could be misleading or contrary to the deity’s interests, the DM might offer a short phrase as an answer instead.</p> <p>If you cast the spell more than once before finishing a Long Rest, there is a cumulative 25 percent chance for each casting after the first that you get no answer.</p> <span>* - (incense)</span> </div>', 'ad743808-eecb-4312-b3cf-99e635374fe0'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', 'ad743808-eecb-4312-b3cf-99e635374fe0'::uuid),
