                    ('Source', 'source', 'Player’s Handbook, pg. 254', '', 'bfb3a241-0a51-4505-ab1c-55c2a857ffbd'::uuid),
                    ('Source URL', 'url', 'https://www.dndbeyond.com/spells/2619047-conjure-elemental', '', 'bfb3a241-0a51-4505-ab1c-55c2a857ffbd'::uuid),
