                    ('Image', 'imageUrl', 'https://www.dndbeyond.com/attachments/2/708/conjuration.png', '', 'aebc3b38-01d7-4aa6-9948-2a523c82cc0a'::uuid),
                    ('Level', 'level', '{"levelNumber":"4","label":"4th"}', '<div> <div> Level </div> <div> 4th </div> </div>', '3945910a-0827-4f7d-9f52-7f18ec877c72'::uuid),
