                    ('Level', 'level', '{"levelNumber":"Cantrip","label":"Cantrip"}', '<div> <div> Level </div> <div> Cantrip </div> </div>', '9d634f36-2083-4170-abba-834a7696eedc'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Action","kind":"action","value":1,"unit":"action","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Action </div> </div>', '9d634f36-2083-4170-abba-834a7696eedc'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"60 ft. (5 ft.)","kind":"distance","distanceValue":60,"distanceUnit":"ft","area":{"shape":null,"value":5,"unit":"ft"}}', '<div> <div> Range/Area </div> <div> 60 ft. <span>(5 ft. <i></i>)</span> </div> </div>', '9d634f36-2083-4170-abba-834a7696eedc'::uuid),
                    ('Components', 'components', '{"text":"V, S","verbal":true,"somatic":true,"material":{"required":false,"description":null,"consumed":null,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S</span> </div> </div>', '9d634f36-2083-4170-abba-834a7696eedc'::uuid),
                    ('Duration', 'duration', '{"text":"Concentration 1 Minute","kind":"timed","value":1,"unit":"minute","concentration":true,"endCondition":null}', '<div> <div>Duration</div> <div> <i>Concentration</i> 1 Minute </div> </div>', '9d634f36-2083-4170-abba-834a7696eedc'::uuid),
                    ('School', 'school', 'Conjuration', '<div> <div> School </div> <div> Conjuration </div> </div>', '9d634f36-2083-4170-abba-834a7696eedc'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"DEX Save","kind":"save","attackType":null,"ability":"DEX"}', '<div> <div> Attack/Save </div> <div> <i></i> <span>DEX Save</span> </div> </div>', '9d634f36-2083-4170-abba-834a7696eedc'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Fire","damageTypes":["Fire"]}', '<div> <div> Damage/Effect </div> <div> <i></i> Fire </div> </div>', '9d634f36-2083-4170-abba-834a7696eedc'::uuid),
                    ('Description', 'description', '["You create a bonfire on ground that you can see within range. Until the spell ends, the magic bonfire fills a 5-foot cube. Any creature in the bonfire’s space when you cast the spell must succeed on a Dexterity saving throw or take 1d8 fire damage. A creature must also make the saving throw when it moves into the bonfire’s space for the first time on a turn or ends its turn there.","The bonfire ignites flammable objects in its area that aren’t being worn or carried.","The spell’s damage increases by 1d8 when you reach 5th level (2d8), 11th level (3d8), and 17th level (4d8)."]', '<div> <p>You create a bonfire on ground that you can see within range. Until the spell ends, the magic bonfire fills a 5-foot cube. Any creature in the bonfire’s space when you cast the spell must succeed on a Dexterity saving throw or take 1d8 fire damage. A creature must also make the saving throw when it moves into the bonfire’s space for the first time on a turn or ends its turn there.</p> <p>The bonfire ignites flammable objects in its area that aren’t being worn or carried.</p> <p>The spell’s damage increases by 1d8 when you reach 5th level (2d8), 11th level (3d8), and 17th level (4d8).</p> </div>', '9d634f36-2083-4170-abba-834a7696eedc'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', '9d634f36-2083-4170-abba-834a7696eedc'::uuid),
