                    ('Casting Time', 'castingTime', '{"text":"1 Action","kind":"action","value":1,"unit":"action","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Action </div> </div>', 'b37ea4ab-3c44-4d12-bdcc-df373215b449'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"30 ft.","kind":"distance","distanceValue":30,"distanceUnit":"ft","area":null}', '<div> <div> Range/Area </div> <div> 30 ft. </div> </div>', 'b37ea4ab-3c44-4d12-bdcc-df373215b449'::uuid),
                    ('Components', 'components', '{"text":"V, S","verbal":true,"somatic":true,"material":{"required":false,"description":null,"consumed":null,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S</span> </div> </div>', 'b37ea4ab-3c44-4d12-bdcc-df373215b449'::uuid),
                    ('Duration', 'duration', '{"text":"Instantaneous","kind":"instantaneous","value":null,"unit":null,"concentration":false,"endCondition":null}', '<div> <div>Duration</div> <div> Instantaneous </div> </div>', 'b37ea4ab-3c44-4d12-bdcc-df373215b449'::uuid),
                    ('School', 'school', 'Conjuration', '<div> <div> School </div> <div> Conjuration </div> </div>', 'b37ea4ab-3c44-4d12-bdcc-df373215b449'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"None","kind":"none","attackType":null,"ability":null}', '<div> <div> Attack/Save </div> <div> <span>None</span> </div> </div>', 'b37ea4ab-3c44-4d12-bdcc-df373215b449'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Creation","damageTypes":[]}', '<div> <div> Damage/Effect </div> <div> Creation </div> </div>', 'b37ea4ab-3c44-4d12-bdcc-df373215b449'::uuid),
                    ('Description', 'description', '["You create 45 pounds of food and 30 gallons of fresh water on the ground or in containers within range—both useful in fending off the hazards of malnutrition and dehydration . The food is bland but nourishing and looks like a food of your choice, and the water is clean. The food spoils after 24 hours if uneaten."]', '<div> <p>You create 45 pounds of food and 30 gallons of fresh water on the ground or in containers within range—both useful in fending off the hazards of <a>malnutrition</a> and <a>dehydration</a>. The food is bland but nourishing and looks like a food of your choice, and the water is clean. The food spoils after 24 hours if uneaten.</p> </div>', 'b37ea4ab-3c44-4d12-bdcc-df373215b449'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', 'b37ea4ab-3c44-4d12-bdcc-df373215b449'::uuid),
                    ('Spell Tags', 'spellTags', '["Creation"]', '', 'b37ea4ab-3c44-4d12-bdcc-df373215b449'::uuid),
                    ('Available For', 'availableFor', '["Cleric (Legacy)","Paladin (Legacy)","Artificer (Legacy)","Cleric","Paladin","Artificer","Paladin - Oath of the Harvest (HGtMH1)","Paladin - Oath of Revelry","Warlock - The Genie (TCoE)","Cleric - Festus Domain"]', '', 'b37ea4ab-3c44-4d12-bdcc-df373215b449'::uuid),
                    ('Source', 'source', 'Player’s Handbook, pg. 258', '', 'b37ea4ab-3c44-4d12-bdcc-df373215b449'::uuid),
                    ('Source URL', 'url', 'https://www.dndbeyond.com/spells/2619073-create-food-and-water', '', 'b37ea4ab-3c44-4d12-bdcc-df373215b449'::uuid),
                    ('Image', 'imageUrl', 'https://www.dndbeyond.com/attachments/2/708/conjuration.png', '', 'b37ea4ab-3c44-4d12-bdcc-df373215b449'::uuid),
                    ('Level', 'level', '{"levelNumber":"1","label":"1st"}', '<div> <div> Level </div> <div> 1st </div> </div>', 'c18fd4c9-569e-4244-a605-79801c5ed96f'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Action","kind":"action","value":1,"unit":"action","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Action </div> </div>', 'c18fd4c9-569e-4244-a605-79801c5ed96f'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"30 ft. (30 ft.)","kind":"distance","distanceValue":30,"distanceUnit":"ft","area":{"shape":null,"value":30,"unit":"ft"}}', '<div> <div> Range/Area </div> <div> 30 ft. <span>(30 ft. <i></i>)</span> </div> </div>', 'c18fd4c9-569e-4244-a605-79801c5ed96f'::uuid),
                    ('Components', 'components', '{"text":"V, S, M *","verbal":true,"somatic":true,"material":{"required":true,"description":"a mix of water and sand","consumed":false,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S, M *</span> </div> </div>', 'c18fd4c9-569e-4244-a605-79801c5ed96f'::uuid),
                    ('Duration', 'duration', '{"text":"Instantaneous","kind":"instantaneous","value":null,"unit":null,"concentration":false,"endCondition":null}', '<div> <div>Duration</div> <div> Instantaneous </div> </div>', 'c18fd4c9-569e-4244-a605-79801c5ed96f'::uuid),
                    ('School', 'school', 'Transmutation', '<div> <div> School </div> <div> Transmutation </div> </div>', 'c18fd4c9-569e-4244-a605-79801c5ed96f'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"None","kind":"none","attackType":null,"ability":null}', '<div> <div> Attack/Save </div> <div> <span>None</span> </div> </div>', 'c18fd4c9-569e-4244-a605-79801c5ed96f'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Creation","damageTypes":[]}', '<div> <div> Damage/Effect </div> <div> Creation </div> </div>', 'c18fd4c9-569e-4244-a605-79801c5ed96f'::uuid),
                    ('Description', 'description', '["You do one of the following:","Create Water. You create up to 10 gallons of clean water within range in an open container. Alternatively, the water falls as rain in a 30-foot Cube within range, extinguishing exposed flames there.","Destroy Water. You destroy up to 10 gallons of water in an open container within range. Alternatively, you destroy fog in a 30-foot Cube within range.","Using a Higher-Level Spell Slot. You create or destroy 10 additional gallons of water, or the size of the Cube increases by 5 feet, for each spell slot level above 1."]', '<div> <p>You do one of the following:</p> <p><strong>Create Water.</strong> You create up to 10 gallons of clean water within range in an open container. Alternatively, the water falls as rain in a 30-foot <a>Cube</a> within range, extinguishing exposed flames there.</p> <p><strong>Destroy Water.</strong> You destroy up to 10 gallons of water in an open container within range. Alternatively, you destroy fog in a 30-foot Cube within range.</p> <p><strong><em>Using a Higher-Level Spell Slot.</em></strong> You create or destroy 10 additional gallons of water, or the size of the Cube increases by 5 feet, for each spell slot level above 1.</p> <span>* - (a mix of water and sand)</span> </div>', 'c18fd4c9-569e-4244-a605-79801c5ed96f'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', 'c18fd4c9-569e-4244-a605-79801c5ed96f'::uuid),
