                    ('Source', 'source', 'Player’s Handbook, pg. 259', '', '1c1e1e8c-040f-4dae-b1f4-55430076be92'::uuid),
                    ('Source URL', 'url', 'https://www.dndbeyond.com/spells/2619077-creation', '', '1c1e1e8c-040f-4dae-b1f4-55430076be92'::uuid),
