                    ('Damage/Effect', 'damageEffect', '{"text":"Healing","damageTypes":[]}', '<div> <div> Damage/Effect </div> <div> Healing </div> </div>', '2244fe4f-3704-46f6-b92f-2d16b65b3e55'::uuid),
                    ('Description', 'description', '["A creature you touch regains a number of Hit Points equal to 2d8 plus your spellcasting ability modifier.","Using a Higher-Level Spell Slot. The healing increases by 2d8 for each spell slot level above 1."]', '<div> <p>A creature you touch regains a number of Hit Points equal to 2d8 plus your spellcasting ability modifier.</p> <p><strong><em>Using a Higher-Level Spell Slot.</em></strong> The healing increases by 2d8 for each spell slot level above 1.</p> </div>', '2244fe4f-3704-46f6-b92f-2d16b65b3e55'::uuid),
