                    ('Available For', 'availableFor', '["Bard (Legacy)","Cleric (Legacy)","Druid (Legacy)","Paladin (Legacy)","Ranger (Legacy)","Artificer (Legacy)","Bard","Cleric","Druid","Paladin","Ranger","Artificer","Warlock (Legacy) - The Celestial (Legacy)","Cleric - Life Domain","Druid - Circle of Wildfire (TCoE)","Sorcerer - Crimson Sorcery","Warlock - Celestial Patron"]', '', '2244fe4f-3704-46f6-b92f-2d16b65b3e55'::uuid),
                    ('Source', 'source', 'Player’s Handbook, pg. 259', '', '2244fe4f-3704-46f6-b92f-2d16b65b3e55'::uuid),
                    ('Source URL', 'url', 'https://www.dndbeyond.com/spells/2619079-cure-wounds', '', '2244fe4f-3704-46f6-b92f-2d16b65b3e55'::uuid),
                    ('Image', 'imageUrl', 'https://www.dndbeyond.com/attachments/2/707/abjuration.png', '', '2244fe4f-3704-46f6-b92f-2d16b65b3e55'::uuid),
                    ('Level', 'level', '{"levelNumber":"Cantrip","label":"Cantrip"}', '<div> <div> Level </div> <div> Cantrip </div> </div>', '85a3670b-55d4-41ae-9d63-5ae32fcc121a'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Action","kind":"action","value":1,"unit":"action","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Action </div> </div>', '85a3670b-55d4-41ae-9d63-5ae32fcc121a'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"120 ft.","kind":"distance","distanceValue":120,"distanceUnit":"ft","area":null}', '<div> <div> Range/Area </div> <div> 120 ft. </div> </div>', '85a3670b-55d4-41ae-9d63-5ae32fcc121a'::uuid),
                    ('Components', 'components', '{"text":"V, S, M *","verbal":true,"somatic":true,"material":{"required":true,"description":"a bit of phosphorus","consumed":false,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S, M *</span> </div> </div>', '85a3670b-55d4-41ae-9d63-5ae32fcc121a'::uuid),
                    ('Duration', 'duration', '{"text":"Concentration 1 Minute","kind":"timed","value":1,"unit":"minute","concentration":true,"endCondition":null}', '<div> <div>Duration</div> <div> <i>Concentration</i> 1 Minute </div> </div>', '85a3670b-55d4-41ae-9d63-5ae32fcc121a'::uuid),
                    ('School', 'school', 'Illusion', '<div> <div> School </div> <div> Illusion </div> </div>', '85a3670b-55d4-41ae-9d63-5ae32fcc121a'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"None","kind":"none","attackType":null,"ability":null}', '<div> <div> Attack/Save </div> <div> <span>None</span> </div> </div>', '85a3670b-55d4-41ae-9d63-5ae32fcc121a'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Utility","damageTypes":[]}', '<div> <div> Damage/Effect </div> <div> Utility </div> </div>', '85a3670b-55d4-41ae-9d63-5ae32fcc121a'::uuid),
                    ('Description', 'description', '["You create up to four torch-size lights within range, making them appear as torches, lanterns, or glowing orbs that hover for the duration. Alternatively, you combine the four lights into one glowing Medium form that is vaguely humanlike. Whichever form you choose, each light sheds Dim Light in a 10-foot radius.","As a Bonus Action, you can move the lights up to 60 feet to a space within range. A light must be within 20 feet of another light created by this spell, and a light vanishes if it exceeds the spell’s range."]', '<div> <p>You create up to four torch-size lights within range, making them appear as torches, lanterns, or glowing orbs that hover for the duration. Alternatively, you combine the four lights into one glowing Medium form that is vaguely humanlike. Whichever form you choose, each light sheds <a>Dim Light</a> in a 10-foot radius.</p> <p>As a Bonus Action, you can move the lights up to 60 feet to a space within range. A light must be within 20 feet of another light created by this spell, and a light vanishes if it exceeds the spell’s range.</p> <span>* - (a bit of phosphorus)</span> </div>', '85a3670b-55d4-41ae-9d63-5ae32fcc121a'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', '85a3670b-55d4-41ae-9d63-5ae32fcc121a'::uuid),
