                    ('Source', 'source', 'Player’s Handbook, pg. 259', '', '85a3670b-55d4-41ae-9d63-5ae32fcc121a'::uuid),
                    ('Source URL', 'url', 'https://www.dndbeyond.com/spells/2619058-dancing-lights', '', '85a3670b-55d4-41ae-9d63-5ae32fcc121a'::uuid),
                    ('Image', 'imageUrl', 'https://www.dndbeyond.com/attachments/2/704/illusion.png', '', '85a3670b-55d4-41ae-9d63-5ae32fcc121a'::uuid),
