                    ('Range/Area', 'rangeArea', '{"text":"120 ft. (125 ft. *)","kind":"distance","distanceValue":120,"distanceUnit":"ft","area":{"shape":null,"value":125,"unit":"ft"}}', '', 'eea3fd49-69cd-4f8f-9433-e0e026b4b3ec'::uuid),
                    ('Components', 'components', '{"text":"V, S","verbal":true,"somatic":true,"material":{"required":false,"description":null,"consumed":null,"costGp":null}}', '', 'eea3fd49-69cd-4f8f-9433-e0e026b4b3ec'::uuid),
                    ('Duration', 'duration', '{"text":"Instantaneous","kind":"instantaneous","value":null,"unit":null,"concentration":false,"endCondition":null}', '', 'eea3fd49-69cd-4f8f-9433-e0e026b4b3ec'::uuid),
                    ('School', 'school', 'Conjuration', '', 'eea3fd49-69cd-4f8f-9433-e0e026b4b3ec'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"DEX Save","kind":"save","attackType":null,"ability":"DEX"}', '', 'eea3fd49-69cd-4f8f-9433-e0e026b4b3ec'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Force (...)","damageTypes":["Force"]}', '', 'eea3fd49-69cd-4f8f-9433-e0e026b4b3ec'::uuid),
                    ('Description', 'description', '["Once per short rest, you swing a slash that cuts space itself.","Create a 120-foot line, 5 feet wide:","Each creature in the line takes 12d10 force damage","Magical barriers, walls, and constructs are automatically cut apart","Teleportation and extradimensional effects in the line instantly fail","This slash can hit creatures behind walls — the slash literally the 3rd dimension."]', '<p>Once per short rest, you swing a slash that cuts space itself.</p> <p>Create a 120-foot line, 5 feet wide:</p> <p>Each creature in the line takes 12d10 force damage</p> <p>Magical barriers, walls, and constructs are automatically cut apart</p> <p>Teleportation and extradimensional effects in the line instantly fail</p> <p>This slash can hit creatures behind walls — the slash literally the 3rd dimension.</p>', 'eea3fd49-69cd-4f8f-9433-e0e026b4b3ec'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', 'eea3fd49-69cd-4f8f-9433-e0e026b4b3ec'::uuid),
