                    ('School', 'school', 'Transmutation', '<div> <div> School </div> <div> Transmutation </div> </div>', '14da7dcf-ac43-4e36-b1e0-ae1ae0c74e4c'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"None","kind":"none","attackType":null,"ability":null}', '<div> <div> Attack/Save </div> <div> <span>None</span> </div> </div>', '14da7dcf-ac43-4e36-b1e0-ae1ae0c74e4c'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Buff","damageTypes":[]}', '<div> <div> Damage/Effect </div> <div> Buff </div> </div>', '14da7dcf-ac43-4e36-b1e0-ae1ae0c74e4c'::uuid),
                    ('Description', 'description', '["For the duration, a willing creature you touch has Darkvision with a range of 150 feet."]', '<div> <p>For the duration, a willing creature you touch has <a>Darkvision</a> with a range of 150 feet.</p> <span>* - (a dried carrot)</span> </div>', '14da7dcf-ac43-4e36-b1e0-ae1ae0c74e4c'::uuid),
