                    ('Level', 'level', '{"levelNumber":"3","label":"3rd"}', '<div> <div> Level </div> <div> 3rd </div> </div>', '115e4e84-a4d6-436b-9648-4b07c4a81aac'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Action","kind":"action","value":1,"unit":"action","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Action </div> </div>', '115e4e84-a4d6-436b-9648-4b07c4a81aac'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"60 ft. (60 ft.)","kind":"distance","distanceValue":60,"distanceUnit":"ft","area":{"shape":null,"value":60,"unit":"ft"}}', '<div> <div> Range/Area </div> <div> 60 ft. <span>(60 ft. <i></i>)</span> </div> </div>', '115e4e84-a4d6-436b-9648-4b07c4a81aac'::uuid),
                    ('Components', 'components', '{"text":"V, S","verbal":true,"somatic":true,"material":{"required":false,"description":null,"consumed":null,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S</span> </div> </div>', '115e4e84-a4d6-436b-9648-4b07c4a81aac'::uuid),
                    ('Duration', 'duration', '{"text":"1 Hour","kind":"timed","value":1,"unit":"hour","concentration":false,"endCondition":null}', '<div> <div>Duration</div> <div> 1 Hour </div> </div>', '115e4e84-a4d6-436b-9648-4b07c4a81aac'::uuid),
                    ('School', 'school', 'Evocation', '<div> <div> School </div> <div> Evocation </div> </div>', '115e4e84-a4d6-436b-9648-4b07c4a81aac'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"None","kind":"none","attackType":null,"ability":null}', '<div> <div> Attack/Save </div> <div> <span>None</span> </div> </div>', '115e4e84-a4d6-436b-9648-4b07c4a81aac'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Control","damageTypes":[]}', '<div> <div> Damage/Effect </div> <div> Control </div> </div>', '115e4e84-a4d6-436b-9648-4b07c4a81aac'::uuid),
                    ('Description', 'description', '["For the duration, sunlight spreads from a point within range and fills a 60-foot-radius Sphere . The sunlight’s area is Bright Light and sheds Dim Light for an additional 60 feet.","Alternatively, you cast the spell on an object that isn’t being worn or carried, causing the sunlight to fill a 60-foot Emanation originating from that object. Covering that object with something opaque, such as a bowl or helm, blocks the sunlight.","If any of this spell’s area overlaps with an area of Darkness created by a spell of level 3 or lower, that other spell is dispelled."]', '<div> <p>For the duration, sunlight spreads from a point within range and fills a 60-foot-radius <a>Sphere</a>. The sunlight’s area is <a>Bright Light</a> and sheds <a>Dim Light</a> for an additional 60 feet.</p> <p>Alternatively, you cast the spell on an object that isn’t being worn or carried, causing the sunlight to fill a 60-foot <a>Emanation</a> originating from that object. Covering that object with something opaque, such as a bowl or helm, blocks the sunlight.</p> <p>If any of this spell’s area overlaps with an area of <a>Darkness</a> created by a spell of level 3 or lower, that other spell is dispelled.</p> </div>', '115e4e84-a4d6-436b-9648-4b07c4a81aac'::uuid),
