                    ('Level', 'level', '{"levelNumber":"4","label":"4th"}', '<div> <div> Level </div> <div> 4th </div> </div>', '7ce6bfda-3877-43ae-95e4-ede93bc85c72'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Action","kind":"action","value":1,"unit":"action","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Action </div> </div>', '7ce6bfda-3877-43ae-95e4-ede93bc85c72'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"Touch","kind":"touch","distanceValue":null,"distanceUnit":null,"area":null}', '<div> <div> Range/Area </div> <div> Touch </div> </div>', '7ce6bfda-3877-43ae-95e4-ede93bc85c72'::uuid),
                    ('Components', 'components', '{"text":"V, S","verbal":true,"somatic":true,"material":{"required":false,"description":null,"consumed":null,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S</span> </div> </div>', '7ce6bfda-3877-43ae-95e4-ede93bc85c72'::uuid),
                    ('Duration', 'duration', '{"text":"8 Hours","kind":"timed","value":8,"unit":"hour","concentration":false,"endCondition":null}', '<div> <div>Duration</div> <div> 8 Hours </div> </div>', '7ce6bfda-3877-43ae-95e4-ede93bc85c72'::uuid),
                    ('School', 'school', 'Abjuration', '<div> <div> School </div> <div> Abjuration </div> </div>', '7ce6bfda-3877-43ae-95e4-ede93bc85c72'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"None","kind":"none","attackType":null,"ability":null}', '<div> <div> Attack/Save </div> <div> <span>None</span> </div> </div>', '7ce6bfda-3877-43ae-95e4-ede93bc85c72'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Buff (...)","damageTypes":[]}', '<div> <div> Damage/Effect </div> <div> Buff (...) </div> </div>', '7ce6bfda-3877-43ae-95e4-ede93bc85c72'::uuid),
                    ('Description', 'description', '["You touch a creature and grant it a measure of protection from death. The first time the target would drop to 0 Hit Points before the spell ends, the target instead drops to 1 Hit Point, and the spell ends.","If the spell is still in effect when the target is subjected to an effect that would kill it instantly without dealing damage, that effect is negated against the target, and the spell ends."]', '<div> <p>You touch a creature and grant it a measure of protection from death. The first time the target would drop to 0 Hit Points before the spell ends, the target instead drops to 1 Hit Point, and the spell ends.</p> <p>If the spell is still in effect when the target is subjected to an effect that would kill it instantly without dealing damage, that effect is negated against the target, and the spell ends.</p> </div>', '7ce6bfda-3877-43ae-95e4-ede93bc85c72'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', '7ce6bfda-3877-43ae-95e4-ede93bc85c72'::uuid),
                    ('Spell Tags', 'spellTags', '["Buff","Warding"]', '', '7ce6bfda-3877-43ae-95e4-ede93bc85c72'::uuid),
                    ('Available For', 'availableFor', '["Cleric (Legacy)","Paladin (Legacy)","Cleric","Paladin","Cleric - Life Domain","Cleric - Grave Domain (XGtE)","Cleric - Death Domain (DMG)","Paladin - Oath of the Harvest (HGtMH1)","Sorcerer - Crimson Sorcery","Warlock - The Undead (VRGtR)","Warlock - The Undying (SCAG)","Warlock - Future You Patron","Illrigger - Architect of Ruin","Cleric - Keeper Domain (BoET)"]', '', '7ce6bfda-3877-43ae-95e4-ede93bc85c72'::uuid),
                    ('Source', 'source', 'Player’s Handbook, pg. 261', '', '7ce6bfda-3877-43ae-95e4-ede93bc85c72'::uuid),
