                    ('Image', 'imageUrl', 'https://www.dndbeyond.com/attachments/2/707/abjuration.png', '', '7ce6bfda-3877-43ae-95e4-ede93bc85c72'::uuid),
                    ('Level', 'level', '{"levelNumber":"7","label":"7th"}', '<div> <div> Level </div> <div> 7th </div> </div>', '57f9c3b0-dfef-4d1a-b963-3e03f6b3612f'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Action","kind":"action","value":1,"unit":"action","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Action </div> </div>', '57f9c3b0-dfef-4d1a-b963-3e03f6b3612f'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"150 ft. (20 ft.)","kind":"distance","distanceValue":150,"distanceUnit":"ft","area":{"shape":null,"value":20,"unit":"ft"}}', '<div> <div> Range/Area </div> <div> 150 ft. <span>(20 ft. <i></i>)</span> </div> </div>', '57f9c3b0-dfef-4d1a-b963-3e03f6b3612f'::uuid),
                    ('Components', 'components', '{"text":"V, S, M *","verbal":true,"somatic":true,"material":{"required":true,"description":"a ball of bat guano and sulfur","consumed":false,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S, M *</span> </div> </div>', '57f9c3b0-dfef-4d1a-b963-3e03f6b3612f'::uuid),
                    ('Duration', 'duration', '{"text":"Concentration 1 Minute","kind":"timed","value":1,"unit":"minute","concentration":true,"endCondition":null}', '<div> <div>Duration</div> <div> <i>Concentration</i> 1 Minute </div> </div>', '57f9c3b0-dfef-4d1a-b963-3e03f6b3612f'::uuid),
                    ('School', 'school', 'Evocation', '<div> <div> School </div> <div> Evocation </div> </div>', '57f9c3b0-dfef-4d1a-b963-3e03f6b3612f'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"DEX Save","kind":"save","attackType":null,"ability":"DEX"}', '<div> <div> Attack/Save </div> <div> <i></i> <span>DEX Save</span> </div> </div>', '57f9c3b0-dfef-4d1a-b963-3e03f6b3612f'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Fire (...)","damageTypes":["Fire"]}', '<div> <div> Damage/Effect </div> <div> <i></i> Fire (...) </div> </div>', '57f9c3b0-dfef-4d1a-b963-3e03f6b3612f'::uuid),
                    ('Description', 'description', '["A beam of yellow light flashes from you, then condenses at a chosen point within range as a glowing bead for the duration. When the spell ends, the bead explodes, and each creature in a 20-foot-radius Sphere centered on that point makes a Dexterity saving throw. A creature takes Fire damage equal to the total accumulated damage on a failed save or half as much damage on a successful one.","The spell’s base damage is 12d6, and the damage increases by 1d6 whenever your turn ends and the spell hasn’t ended.","If a creature touches the glowing bead before the spell ends, that creature makes a Dexterity saving throw. On a failed save, the spell ends, causing the bead to explode. On a successful save, the creature can throw the bead up to 40 feet. If the thrown bead enters a creature’s space or collides with a solid object, the spell ends, and the bead explodes.","When the bead explodes, flammable objects in the explosion that aren’t being worn or carried start burning .","Using a Higher-Level Spell Slot. The base damage increases by 1d6 for each spell slot level above 7."]', '<div> <p>A beam of yellow light flashes from you, then condenses at a chosen point within range as a glowing bead for the duration. When the spell ends, the bead explodes, and each creature in a 20-foot-radius <a>Sphere</a> centered on that point makes a Dexterity saving throw. A creature takes Fire damage equal to the total accumulated damage on a failed save or half as much damage on a successful one.</p> <p>The spell’s base damage is 12d6, and the damage increases by 1d6 whenever your turn ends and the spell hasn’t ended.</p> <p>If a creature touches the glowing bead before the spell ends, that creature makes a Dexterity saving throw. On a failed save, the spell ends, causing the bead to explode. On a successful save, the creature can throw the bead up to 40 feet. If the thrown bead enters a creature’s space or collides with a solid object, the spell ends, and the bead explodes.</p> <p>When the bead explodes, flammable objects in the explosion that aren’t being worn or carried start <a>burning</a>.</p> <p><strong><em>Using a Higher-Level Spell Slot.</em></strong> The base damage increases by 1d6 for each spell slot level above 7.</p> <span>* - (a ball of bat guano and sulfur)</span> </div>', '57f9c3b0-dfef-4d1a-b963-3e03f6b3612f'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', '57f9c3b0-dfef-4d1a-b963-3e03f6b3612f'::uuid),
