                    ('Range/Area', 'rangeArea', '{"text":"Self (30 ft.)","kind":"self","distanceValue":null,"distanceUnit":null,"area":{"shape":null,"value":30,"unit":"ft"}}', '<div> <div> Range/Area </div> <div> Self <span>(30 ft. <i></i>)</span> </div> </div>', '323a063d-dbb6-4af9-bdb1-5116efff4cc7'::uuid),
                    ('Components', 'components', '{"text":"V, S","verbal":true,"somatic":true,"material":{"required":false,"description":null,"consumed":null,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S</span> </div> </div>', '323a063d-dbb6-4af9-bdb1-5116efff4cc7'::uuid),
                    ('Duration', 'duration', '{"text":"Concentration 10 Minutes","kind":"timed","value":10,"unit":"minute","concentration":true,"endCondition":null}', '<div> <div>Duration</div> <div> <i>Concentration</i> 10 Minutes </div> </div>', '323a063d-dbb6-4af9-bdb1-5116efff4cc7'::uuid),
                    ('School', 'school', 'Divination', '<div> <div> School </div> <div> Divination </div> </div>', '323a063d-dbb6-4af9-bdb1-5116efff4cc7'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"None","kind":"none","attackType":null,"ability":null}', '<div> <div> Attack/Save </div> <div> <span>None</span> </div> </div>', '323a063d-dbb6-4af9-bdb1-5116efff4cc7'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Detection","damageTypes":[]}', '<div> <div> Damage/Effect </div> <div> Detection </div> </div>', '323a063d-dbb6-4af9-bdb1-5116efff4cc7'::uuid),
                    ('Description', 'description', '["For the duration, you sense the location of any Aberration, Celestial, Elemental, Fey, Fiend, or Undead within 30 feet of yourself. You also sense whether the Hallow spell is active there and, if so, where.","The spell is blocked by 1 foot of stone, dirt, or wood; 1 inch of metal; or a thin sheet of lead."]', '<div> <p>For the duration, you sense the location of any Aberration, Celestial, Elemental, Fey, Fiend, or Undead within 30 feet of yourself. You also sense whether the <a>Hallow</a> spell is active there and, if so, where.</p> <p>The spell is blocked by 1 foot of stone, dirt, or wood; 1 inch of metal; or a thin sheet of lead.</p> </div>', '323a063d-dbb6-4af9-bdb1-5116efff4cc7'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', '323a063d-dbb6-4af9-bdb1-5116efff4cc7'::uuid),
