                    ('Casting Time', 'castingTime', '{"text":"1 Action Ritual","kind":"action","value":1,"unit":"action","trigger":null,"ritual":true}', '<div> <div> Casting Time </div> <div> 1 Action <i>Ritual</i> </div> </div>', '9d75d577-4ff3-4f19-87ba-8b756350045b'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"Self (30 ft.)","kind":"self","distanceValue":null,"distanceUnit":null,"area":{"shape":null,"value":30,"unit":"ft"}}', '<div> <div> Range/Area </div> <div> Self <span>(30 ft. <i></i>)</span> </div> </div>', '9d75d577-4ff3-4f19-87ba-8b756350045b'::uuid),
                    ('Components', 'components', '{"text":"V, S","verbal":true,"somatic":true,"material":{"required":false,"description":null,"consumed":null,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S</span> </div> </div>', '9d75d577-4ff3-4f19-87ba-8b756350045b'::uuid),
                    ('Duration', 'duration', '{"text":"Concentration 10 Minutes","kind":"timed","value":10,"unit":"minute","concentration":true,"endCondition":null}', '<div> <div>Duration</div> <div> <i>Concentration</i> 10 Minutes </div> </div>', '9d75d577-4ff3-4f19-87ba-8b756350045b'::uuid),
                    ('School', 'school', 'Divination', '<div> <div> School </div> <div> Divination </div> </div>', '9d75d577-4ff3-4f19-87ba-8b756350045b'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"None","kind":"none","attackType":null,"ability":null}', '<div> <div> Attack/Save </div> <div> <span>None</span> </div> </div>', '9d75d577-4ff3-4f19-87ba-8b756350045b'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Detection","damageTypes":[]}', '<div> <div> Damage/Effect </div> <div> Detection </div> </div>', '9d75d577-4ff3-4f19-87ba-8b756350045b'::uuid),
                    ('Description', 'description', '["For the duration, you sense the presence of magical effects within 30 feet of yourself. If you sense such effects, you can take the Magic action to see a faint aura around any visible creature or object in the area that bears the magic, and if an effect was created by a spell, you learn the spell’s school of magic.","The spell is blocked by 1 foot of stone, dirt, or wood; 1 inch of metal; or a thin sheet of lead."]', '<div> <p>For the duration, you sense the presence of magical effects within 30 feet of yourself. If you sense such effects, you can take the <a>Magic</a> action to see a faint aura around any visible creature or object in the area that bears the magic, and if an effect was created by a spell, you learn the spell’s school of magic.</p> <p>The spell is blocked by 1 foot of stone, dirt, or wood; 1 inch of metal; or a thin sheet of lead.</p> </div>', '9d75d577-4ff3-4f19-87ba-8b756350045b'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', '9d75d577-4ff3-4f19-87ba-8b756350045b'::uuid),
                    ('Spell Tags', 'spellTags', '["Detection"]', '', '9d75d577-4ff3-4f19-87ba-8b756350045b'::uuid),
