            migrationBuilder.Sql("""
                INSERT INTO "SpellComponents" ("Label", "Key", "Value", "Html", "SpellId") VALUES
                    ('Level', 'level', '{"levelNumber":"2","label":"2nd"}', '<div> <div> Level </div> <div> 2nd </div> </div>', '431a3523-3a69-4dd7-85a6-4b92e05e9b46'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Action","kind":"action","value":1,"unit":"action","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Action </div> </div>', '431a3523-3a69-4dd7-85a6-4b92e05e9b46'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"Self","kind":"self","distanceValue":null,"distanceUnit":null,"area":null}', '<div> <div> Range/Area </div> <div> Self </div> </div>', '431a3523-3a69-4dd7-85a6-4b92e05e9b46'::uuid),
                    ('Components', 'components', '{"text":"V, S, M *","verbal":true,"somatic":true,"material":{"required":true,"description":"1 Copper Piece","consumed":false,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S, M *</span> </div> </div>', '431a3523-3a69-4dd7-85a6-4b92e05e9b46'::uuid),
                    ('Duration', 'duration', '{"text":"Concentration 1 Minute","kind":"timed","value":1,"unit":"minute","concentration":true,"endCondition":null}', '<div> <div>Duration</div> <div> <i>Concentration</i> 1 Minute </div> </div>', '431a3523-3a69-4dd7-85a6-4b92e05e9b46'::uuid),
                    ('School', 'school', 'Divination', '<div> <div> School </div> <div> Divination </div> </div>', '431a3523-3a69-4dd7-85a6-4b92e05e9b46'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"WIS Save","kind":"save","attackType":null,"ability":"WIS"}', '<div> <div> Attack/Save </div> <div> <i></i> <span>WIS Save</span> </div> </div>', '431a3523-3a69-4dd7-85a6-4b92e05e9b46'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Detection (...)","damageTypes":[]}', '<div> <div> Damage/Effect </div> <div> Detection (...) </div> </div>', '431a3523-3a69-4dd7-85a6-4b92e05e9b46'::uuid),
                    ('Description', 'description', '["You activate one of the effects below. Until the spell ends, you can activate either effect as a Magic action on your later turns.","Sense Thoughts. You sense the presence of thoughts within 30 feet of yourself that belong to creatures that know languages or are telepathic. You don’t read the thoughts, but you know that a thinking creature is present.","The spell is blocked by 1 foot of stone, dirt, or wood; 1 inch of metal; or a thin sheet of lead.","Read Thoughts. Target one creature you can see within 30 feet of yourself or one creature within 30 feet of yourself that you detected with the Sense Thoughts option. You learn what is most on the target’s mind right now. If the target doesn’t know any languages and isn’t telepathic, you learn nothing.","As a Magic action on your next turn, you can try to probe deeper into the target’s mind. If you probe deeper, the target makes a Wisdom saving throw. On a failed save, you discern the target’s reasoning, emotions, and something that looms large in its mind (such as a worry, love, or hate). On a successful save, the spell ends. Either way, the target knows that you are probing into its mind, and until you shift your attention away from the target’s mind, the target can take an action on its turn to make an Intelligence ( Arcana ) check against your spell save DC, ending the spell on a success."]', '<div> <p>You activate one of the effects below. Until the spell ends, you can activate either effect as a <a>Magic</a> action on your later turns.</p> <p><strong><em>Sense Thoughts.</em></strong> You sense the presence of thoughts within 30 feet of yourself that belong to creatures that know languages or are telepathic. You don’t read the thoughts, but you know that a thinking creature is present.</p> <p>The spell is blocked by 1 foot of stone, dirt, or wood; 1 inch of metal; or a thin sheet of lead.</p> <p><strong><em>Read Thoughts.</em></strong> Target one creature you can see within 30 feet of yourself or one creature within 30 feet of yourself that you detected with the Sense Thoughts option. You learn what is most on the target’s mind right now. If the target doesn’t know any languages and isn’t telepathic, you learn nothing.</p> <p>As a <a>Magic</a> action on your next turn, you can try to probe deeper into the target’s mind. If you probe deeper, the target makes a Wisdom saving throw. On a failed save, you discern the target’s reasoning, emotions, and something that looms large in its mind (such as a worry, love, or hate). On a successful save, the spell ends. Either way, the target knows that you are probing into its mind, and until you shift your attention away from the target’s mind, the target can take an action on its turn to make an Intelligence (<a>Arcana</a>) check against your spell save DC, ending the spell on a success.</p> <span>* - (1 Copper Piece)</span> </div>', '431a3523-3a69-4dd7-85a6-4b92e05e9b46'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', '431a3523-3a69-4dd7-85a6-4b92e05e9b46'::uuid),
                    ('Spell Tags', 'spellTags', '["Social","Detection"]', '', '431a3523-3a69-4dd7-85a6-4b92e05e9b46'::uuid),
                    ('Available For', 'availableFor', '["Bard (Legacy)","Sorcerer (Legacy)","Wizard (Legacy)","Bard","Sorcerer","Wizard","Sorcerer - Aberrant Sorcery","Warlock - Great Old One Patron","Warlock - Great Fool Patron","Illrigger - Architect of Ruin"]', '', '431a3523-3a69-4dd7-85a6-4b92e05e9b46'::uuid),
                    ('Source', 'source', 'Player’s Handbook, pg. 262', '', '431a3523-3a69-4dd7-85a6-4b92e05e9b46'::uuid),
                    ('Source URL', 'url', 'https://www.dndbeyond.com/spells/2619099-detect-thoughts', '', '431a3523-3a69-4dd7-85a6-4b92e05e9b46'::uuid),
                    ('Image', 'imageUrl', 'https://www.dndbeyond.com/attachments/2/709/divination.png', '', '431a3523-3a69-4dd7-85a6-4b92e05e9b46'::uuid),
                    ('Level', 'level', '{"levelNumber":"Cantrip","label":"Cantrip"}', '', 'b0b03c52-abcf-4dc6-a340-fc64c2367d01'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Action","kind":"action","value":1,"unit":"action","trigger":null,"ritual":false}', '', 'b0b03c52-abcf-4dc6-a340-fc64c2367d01'::uuid),
