                    ('Duration', 'duration', '{"text":"Instantaneous","kind":"instantaneous","value":null,"unit":null,"concentration":false,"endCondition":null}', '', 'b0b03c52-abcf-4dc6-a340-fc64c2367d01'::uuid),
                    ('School', 'school', 'Evocation', '', 'b0b03c52-abcf-4dc6-a340-fc64c2367d01'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"DEX Save","kind":"save","attackType":null,"ability":"DEX"}', '', 'b0b03c52-abcf-4dc6-a340-fc64c2367d01'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Piercing (...)","damageTypes":["Piercing"]}', '', 'b0b03c52-abcf-4dc6-a340-fc64c2367d01'::uuid),
                    ('Description', 'description', '["Close-range burst damage.","Cost: 10 bullets","Range: 15 ft cone","Targets make a Dexterity save","On fail: 3d10 damage for 0-5 feet, 2d10 damage for 5-10 feet and 1d10 for 10-15 feet","On success: half damage","Strong in tight spaces."]', '<p>Close-range burst damage.</p> <p>Cost: 10 bullets</p> <p>Range: 15 ft cone</p> <p>Targets make a Dexterity save</p> <p>On fail: 3d10 damage for 0-5 feet, 2d10 damage for 5-10 feet and 1d10 for 10-15 feet</p> <p>On success: half damage</p> <p>Strong in tight spaces.</p>', 'b0b03c52-abcf-4dc6-a340-fc64c2367d01'::uuid),
