                    ('Level', 'level', '{"levelNumber":"4","label":"4th"}', '<div> <div> Level </div> <div> 4th </div> </div>', '97b6bf18-67b5-4550-aacd-3e0f745c84e4'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Action","kind":"action","value":1,"unit":"action","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Action </div> </div>', '97b6bf18-67b5-4550-aacd-3e0f745c84e4'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"500 ft.","kind":"distance","distanceValue":500,"distanceUnit":"ft","area":null}', '<div> <div> Range/Area </div> <div> 500 ft. </div> </div>', '97b6bf18-67b5-4550-aacd-3e0f745c84e4'::uuid),
                    ('Components', 'components', '{"text":"V","verbal":true,"somatic":false,"material":{"required":false,"description":null,"consumed":null,"costGp":null}}', '<div> <div> Components </div> <div> <span>V</span> </div> </div>', '97b6bf18-67b5-4550-aacd-3e0f745c84e4'::uuid),
                    ('Duration', 'duration', '{"text":"Instantaneous","kind":"instantaneous","value":null,"unit":null,"concentration":false,"endCondition":null}', '<div> <div>Duration</div> <div> Instantaneous </div> </div>', '97b6bf18-67b5-4550-aacd-3e0f745c84e4'::uuid),
                    ('School', 'school', 'Conjuration', '<div> <div> School </div> <div> Conjuration </div> </div>', '97b6bf18-67b5-4550-aacd-3e0f745c84e4'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"None","kind":"none","attackType":null,"ability":null}', '<div> <div> Attack/Save </div> <div> <span>None</span> </div> </div>', '97b6bf18-67b5-4550-aacd-3e0f745c84e4'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Teleportation","damageTypes":[]}', '<div> <div> Damage/Effect </div> <div> Teleportation </div> </div>', '97b6bf18-67b5-4550-aacd-3e0f745c84e4'::uuid),
                    ('Description', 'description', '["You teleport to a location within range. You arrive at exactly the spot desired. It can be a place you can see, one you can visualize, or one you can describe by stating distance and direction, such as “200 feet straight downward” or “300 feet upward to the northwest at a 45-degree angle.”","You can also teleport one willing creature. The creature must be within 5 feet of you when you teleport, and it teleports to a space within 5 feet of your destination space.","If you, the other creature, or both would arrive in a space occupied by a creature or completely filled by one or more objects, you and any creature traveling with you each take 4d6 Force damage, and the teleportation fails."]', '<div> <p>You teleport to a location within range. You arrive at exactly the spot desired. It can be a place you can see, one you can visualize, or one you can describe by stating distance and direction, such as “200 feet straight downward” or “300 feet upward to the northwest at a 45-degree angle.”</p> <p>You can also teleport one willing creature. The creature must be within 5 feet of you when you teleport, and it teleports to a space within 5 feet of your destination space.</p> <p>If you, the other creature, or both would arrive in a space occupied by a creature or completely filled by one or more objects, you and any creature traveling with you each take 4d6 Force damage, and the teleportation fails.</p> </div>', '97b6bf18-67b5-4550-aacd-3e0f745c84e4'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', '97b6bf18-67b5-4550-aacd-3e0f745c84e4'::uuid),
                    ('Spell Tags', 'spellTags', '["Teleportation"]', '', '97b6bf18-67b5-4550-aacd-3e0f745c84e4'::uuid),
                    ('Available For', 'availableFor', '["Bard (Legacy)","Sorcerer (Legacy)","Warlock (Legacy)","Wizard (Legacy)","Bard","Sorcerer","Warlock","Wizard","Cleric - Trickery Domain","Paladin - Oath of Vengeance","Ranger - Fey Wanderer","Illrigger - Architect of Ruin","Paladin - Oath of the Spelldrinker"]', '', '97b6bf18-67b5-4550-aacd-3e0f745c84e4'::uuid),
                    ('Source', 'source', 'Player’s Handbook, pg. 262', '', '97b6bf18-67b5-4550-aacd-3e0f745c84e4'::uuid),
