                    ('Level', 'level', '{"levelNumber":"1","label":"1st"}', '<div> <div> Level </div> <div> 1st </div> </div>', 'af8f7b78-abbd-4b23-b1c0-3e6b447b4744'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Action","kind":"action","value":1,"unit":"action","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Action </div> </div>', 'af8f7b78-abbd-4b23-b1c0-3e6b447b4744'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"Self","kind":"self","distanceValue":null,"distanceUnit":null,"area":null}', '<div> <div> Range/Area </div> <div> Self </div> </div>', 'af8f7b78-abbd-4b23-b1c0-3e6b447b4744'::uuid),
                    ('Components', 'components', '{"text":"V, S","verbal":true,"somatic":true,"material":{"required":false,"description":null,"consumed":null,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S</span> </div> </div>', 'af8f7b78-abbd-4b23-b1c0-3e6b447b4744'::uuid),
                    ('Duration', 'duration', '{"text":"1 Hour","kind":"timed","value":1,"unit":"hour","concentration":false,"endCondition":null}', '<div> <div>Duration</div> <div> 1 Hour </div> </div>', 'af8f7b78-abbd-4b23-b1c0-3e6b447b4744'::uuid),
                    ('School', 'school', 'Illusion', '<div> <div> School </div> <div> Illusion </div> </div>', 'af8f7b78-abbd-4b23-b1c0-3e6b447b4744'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"None","kind":"none","attackType":null,"ability":null}', '<div> <div> Attack/Save </div> <div> <span>None</span> </div> </div>', 'af8f7b78-abbd-4b23-b1c0-3e6b447b4744'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Shapechanging","damageTypes":[]}', '<div> <div> Damage/Effect </div> <div> Shapechanging </div> </div>', 'af8f7b78-abbd-4b23-b1c0-3e6b447b4744'::uuid),
                    ('Description', 'description', '["You make yourself—including your clothing, armor, weapons, and other belongings on your person—look different until the spell ends. You can seem 1 foot shorter or taller and can appear heavier or lighter. You must adopt a form that has the same basic arrangement of limbs as you have. Otherwise, the extent of the illusion is up to you.","The changes wrought by this spell fail to hold up to physical inspection. For example, if you use this spell to add a hat to your outfit, objects pass through the hat, and anyone who touches it would feel nothing.","To discern that you are disguised, a creature must take the Study action to inspect your appearance and succeed on an Intelligence ( Investigation ) check against your spell save DC."]', '<div> <p>You make yourself—including your clothing, armor, weapons, and other belongings on your person—look different until the spell ends. You can seem 1 foot shorter or taller and can appear heavier or lighter. You must adopt a form that has the same basic arrangement of limbs as you have. Otherwise, the extent of the illusion is up to you.</p> <p>The changes wrought by this spell fail to hold up to physical inspection. For example, if you use this spell to add a hat to your outfit, objects pass through the hat, and anyone who touches it would feel nothing.</p> <p>To discern that you are disguised, a creature must take the <a>Study</a> action to inspect your appearance and succeed on an Intelligence (<a>Investigation</a>) check against your spell save DC.</p> </div>', 'af8f7b78-abbd-4b23-b1c0-3e6b447b4744'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', 'af8f7b78-abbd-4b23-b1c0-3e6b447b4744'::uuid),
                    ('Spell Tags', 'spellTags', '["Shapechanging"]', '', 'af8f7b78-abbd-4b23-b1c0-3e6b447b4744'::uuid),
                    ('Available For', 'availableFor', '["Bard (Legacy)","Sorcerer (Legacy)","Wizard (Legacy)","Artificer (Legacy)","Bard","Sorcerer","Wizard","Artificer","Cleric - Trickery Domain","Ranger - Gloom Stalker","Illrigger - Architect of Ruin"]', '', 'af8f7b78-abbd-4b23-b1c0-3e6b447b4744'::uuid),
