                    ('Image', 'imageUrl', 'https://www.dndbeyond.com/attachments/2/707/abjuration.png', '', '93a93e7b-db0f-4d33-9803-c5a8c505f42e'::uuid),
                    ('Level', 'level', '{"levelNumber":"1","label":"1st"}', '<div> <div> Level </div> <div> 1st </div> </div>', '5e98e609-924a-4ed9-ac3f-56992031ba0a'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Action","kind":"action","value":1,"unit":"action","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Action </div> </div>', '5e98e609-924a-4ed9-ac3f-56992031ba0a'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"60 ft.","kind":"distance","distanceValue":60,"distanceUnit":"ft","area":null}', '<div> <div> Range/Area </div> <div> 60 ft. </div> </div>', '5e98e609-924a-4ed9-ac3f-56992031ba0a'::uuid),
                    ('Components', 'components', '{"text":"V","verbal":true,"somatic":false,"material":{"required":false,"description":null,"consumed":null,"costGp":null}}', '<div> <div> Components </div> <div> <span>V</span> </div> </div>', '5e98e609-924a-4ed9-ac3f-56992031ba0a'::uuid),
                    ('Duration', 'duration', '{"text":"Instantaneous","kind":"instantaneous","value":null,"unit":null,"concentration":false,"endCondition":null}', '<div> <div>Duration</div> <div> Instantaneous </div> </div>', '5e98e609-924a-4ed9-ac3f-56992031ba0a'::uuid),
                    ('School', 'school', 'Enchantment', '<div> <div> School </div> <div> Enchantment </div> </div>', '5e98e609-924a-4ed9-ac3f-56992031ba0a'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"WIS Save","kind":"save","attackType":null,"ability":"WIS"}', '<div> <div> Attack/Save </div> <div> <i></i> <span>WIS Save</span> </div> </div>', '5e98e609-924a-4ed9-ac3f-56992031ba0a'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Psychic","damageTypes":["Psychic"]}', '<div> <div> Damage/Effect </div> <div> <i></i> Psychic </div> </div>', '5e98e609-924a-4ed9-ac3f-56992031ba0a'::uuid),
                    ('Description', 'description', '["One creature of your choice that you can see within range hears a discordant melody in its mind. The target makes a Wisdom saving throw. On a failed save, it takes 3d6 Psychic damage and must immediately use its Reaction, if available, to move as far away from you as it can, using the safest route. On a successful save, the target takes half as much damage only.","Using a Higher-Level Spell Slot. The damage increases by 1d6 for each spell slot level above 1."]', '<div> <p>One creature of your choice that you can see within range hears a discordant melody in its mind. The target makes a Wisdom saving throw. On a failed save, it takes 3d6 Psychic damage and must immediately use its Reaction, if available, to move as far away from you as it can, using the safest route. On a successful save, the target takes half as much damage only.</p> <p><strong><em>Using a Higher-Level Spell Slot.</em></strong> The damage increases by 1d6 for each spell slot level above 1.</p> </div>', '5e98e609-924a-4ed9-ac3f-56992031ba0a'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', '5e98e609-924a-4ed9-ac3f-56992031ba0a'::uuid),
                    ('Spell Tags', 'spellTags', '["Damage","Control"]', '', '5e98e609-924a-4ed9-ac3f-56992031ba0a'::uuid),
                    ('Available For', 'availableFor', '["Bard (Legacy)","Bard","Sorcerer - Aberrant Sorcery","Warlock - Great Old One Patron","Warlock - Great Fool Patron"]', '', '5e98e609-924a-4ed9-ac3f-56992031ba0a'::uuid),
                    ('Source', 'source', 'Player’s Handbook, pg. 264', '', '5e98e609-924a-4ed9-ac3f-56992031ba0a'::uuid),
                    ('Source URL', 'url', 'https://www.dndbeyond.com/spells/2619104-dissonant-whispers', '', '5e98e609-924a-4ed9-ac3f-56992031ba0a'::uuid),
