                    ('Casting Time', 'castingTime', '{"text":"1 Action Ritual","kind":"action","value":1,"unit":"action","trigger":null,"ritual":true}', '<div> <div> Casting Time </div> <div> 1 Action <i>Ritual</i> </div> </div>', 'c4e9674e-b671-4299-8e13-a2285692c258'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"Self","kind":"self","distanceValue":null,"distanceUnit":null,"area":null}', '<div> <div> Range/Area </div> <div> Self </div> </div>', 'c4e9674e-b671-4299-8e13-a2285692c258'::uuid),
                    ('Components', 'components', '{"text":"V, S, M *","verbal":true,"somatic":true,"material":{"required":true,"description":"incense worth 25+ GP, which the spell consumes","consumed":true,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S, M *</span> </div> </div>', 'c4e9674e-b671-4299-8e13-a2285692c258'::uuid),
                    ('Duration', 'duration', '{"text":"Instantaneous","kind":"instantaneous","value":null,"unit":null,"concentration":false,"endCondition":null}', '<div> <div>Duration</div> <div> Instantaneous </div> </div>', 'c4e9674e-b671-4299-8e13-a2285692c258'::uuid),
                    ('School', 'school', 'Divination', '<div> <div> School </div> <div> Divination </div> </div>', 'c4e9674e-b671-4299-8e13-a2285692c258'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"None","kind":"none","attackType":null,"ability":null}', '<div> <div> Attack/Save </div> <div> <span>None</span> </div> </div>', 'c4e9674e-b671-4299-8e13-a2285692c258'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Foreknowledge","damageTypes":[]}', '<div> <div> Damage/Effect </div> <div> Foreknowledge </div> </div>', 'c4e9674e-b671-4299-8e13-a2285692c258'::uuid),
                    ('Description', 'description', '["This spell puts you in contact with a god or a god’s servants. You ask one question about a specific goal, event, or activity to occur within 7 days. The DM offers a truthful reply, which might be a short phrase or cryptic rhyme. The spell doesn’t account for circumstances that might change the answer, such as the casting of other spells.","If you cast the spell more than once before finishing a Long Rest, there is a cumulative 25 percent chance for each casting after the first that you get no answer."]', '<div> <p>This spell puts you in contact with a god or a god’s servants. You ask one question about a specific goal, event, or activity to occur within 7 days. The DM offers a truthful reply, which might be a short phrase or cryptic rhyme. The spell doesn’t account for circumstances that might change the answer, such as the casting of other spells.</p> <p>If you cast the spell more than once before finishing a Long Rest, there is a cumulative 25 percent chance for each casting after the first that you get no answer.</p> <span>* - (incense worth 25+ GP, which the spell consumes)</span> </div>', 'c4e9674e-b671-4299-8e13-a2285692c258'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', 'c4e9674e-b671-4299-8e13-a2285692c258'::uuid),
