            migrationBuilder.Sql("""
                INSERT INTO "SpellComponents" ("Label", "Key", "Value", "Html", "SpellId") VALUES
                    ('Level', 'level', '{"levelNumber":"4","label":"4th"}', '<div> <div> Level </div> <div> 4th </div> </div>', 'eeec0043-390d-4204-a79b-d1e7fc88189d'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Action","kind":"action","value":1,"unit":"action","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Action </div> </div>', 'eeec0043-390d-4204-a79b-d1e7fc88189d'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"60 ft.","kind":"distance","distanceValue":60,"distanceUnit":"ft","area":null}', '<div> <div> Range/Area </div> <div> 60 ft. </div> </div>', 'eeec0043-390d-4204-a79b-d1e7fc88189d'::uuid),
                    ('Components', 'components', '{"text":"V, S","verbal":true,"somatic":true,"material":{"required":false,"description":null,"consumed":null,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S</span> </div> </div>', 'eeec0043-390d-4204-a79b-d1e7fc88189d'::uuid),
                    ('Duration', 'duration', '{"text":"Concentration 1 Minute","kind":"timed","value":1,"unit":"minute","concentration":true,"endCondition":null}', '<div> <div>Duration</div> <div> <i>Concentration</i> 1 Minute </div> </div>', 'eeec0043-390d-4204-a79b-d1e7fc88189d'::uuid),
                    ('School', 'school', 'Enchantment', '<div> <div> School </div> <div> Enchantment </div> </div>', 'eeec0043-390d-4204-a79b-d1e7fc88189d'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"WIS Save","kind":"save","attackType":null,"ability":"WIS"}', '<div> <div> Attack/Save </div> <div> <i></i> <span>WIS Save</span> </div> </div>', 'eeec0043-390d-4204-a79b-d1e7fc88189d'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Charmed","damageTypes":[]}', '<div> <div> Damage/Effect </div> <div> <i></i> Charmed </div> </div>', 'eeec0043-390d-4204-a79b-d1e7fc88189d'::uuid),
                    ('Description', 'description', '["One Beast you can see within range must succeed on a Wisdom saving throw or have the Charmed condition for the duration. The target has Advantage on the save if you or your allies are fighting it. Whenever the target takes damage, it repeats the save, ending the spell on itself on a success.","You have a telepathic link with the Charmed target while the two of you are on the same plane of existence. On your turn, you can use this link to issue commands to the target (no action required), such as “Attack that creature,” “Move over there,” or “Fetch that object.” The target does its best to obey on its turn. If it completes an order and doesn’t receive further direction from you, it acts and moves as it likes, focusing on protecting itself.","You can command the target to take a Reaction but must take your own Reaction to do so.","Using a Higher-Level Spell Slot. Your Concentration can last longer with a spell slot of level 5 (up to 10 minutes), 6 (up to 1 hour), or 7+ (up to 8 hours)."]', '<div> <p>One Beast you can see within range must succeed on a Wisdom saving throw or have the <a>Charmed</a> condition for the duration. The target has Advantage on the save if you or your allies are fighting it. Whenever the target takes damage, it repeats the save, ending the spell on itself on a success.</p> <p>You have a telepathic link with the Charmed target while the two of you are on the same plane of existence. On your turn, you can use this link to issue commands to the target (no action required), such as “Attack that creature,” “Move over there,” or “Fetch that object.” The target does its best to obey on its turn. If it completes an order and doesn’t receive further direction from you, it acts and moves as it likes, focusing on protecting itself.</p> <p>You can command the target to take a Reaction but must take your own Reaction to do so.</p> <p><strong><em>Using a Higher-Level Spell Slot.</em></strong> Your <a>Concentration</a> can last longer with a spell slot of level 5 (up to 10 minutes), 6 (up to 1 hour), or 7+ (up to 8 hours).</p> </div>', 'eeec0043-390d-4204-a79b-d1e7fc88189d'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', 'eeec0043-390d-4204-a79b-d1e7fc88189d'::uuid),
                    ('Spell Tags', 'spellTags', '["Control"]', '', 'eeec0043-390d-4204-a79b-d1e7fc88189d'::uuid),
                    ('Available For', 'availableFor', '["Druid (Legacy)","Ranger (Legacy)","Sorcerer (Legacy)","Druid","Ranger","Sorcerer","Cleric - Nature Domain (PHB)","Paladin - Oath of Conquest (XGtE)","Warlock - Archfey Patron","Warlock - The Predator (HWT)","Illrigger - Architect of Ruin"]', '', 'eeec0043-390d-4204-a79b-d1e7fc88189d'::uuid),
