                    ('Level', 'level', '{"levelNumber":"2","label":"2nd"}', '<div> <div> Level </div> <div> 2nd </div> </div>', 'ec0d3f97-1d6d-4e25-8c41-567eac8108ef'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Bonus Action","kind":"bonus_action","value":1,"unit":"action","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Bonus Action </div> </div>', 'ec0d3f97-1d6d-4e25-8c41-567eac8108ef'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"Touch (15 ft.)","kind":"touch","distanceValue":null,"distanceUnit":null,"area":{"shape":null,"value":15,"unit":"ft"}}', '<div> <div> Range/Area </div> <div> Touch <span>(15 ft. <i></i>)</span> </div> </div>', 'ec0d3f97-1d6d-4e25-8c41-567eac8108ef'::uuid),
                    ('Components', 'components', '{"text":"V, S, M *","verbal":true,"somatic":true,"material":{"required":true,"description":"a hot pepper","consumed":false,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S, M *</span> </div> </div>', 'ec0d3f97-1d6d-4e25-8c41-567eac8108ef'::uuid),
                    ('Duration', 'duration', '{"text":"Concentration 1 Minute","kind":"timed","value":1,"unit":"minute","concentration":true,"endCondition":null}', '<div> <div>Duration</div> <div> <i>Concentration</i> 1 Minute </div> </div>', 'ec0d3f97-1d6d-4e25-8c41-567eac8108ef'::uuid),
                    ('School', 'school', 'Transmutation', '<div> <div> School </div> <div> Transmutation </div> </div>', 'ec0d3f97-1d6d-4e25-8c41-567eac8108ef'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"DEX Save","kind":"save","attackType":null,"ability":"DEX"}', '<div> <div> Attack/Save </div> <div> <i></i> <span>DEX Save</span> </div> </div>', 'ec0d3f97-1d6d-4e25-8c41-567eac8108ef'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Acid (...)","damageTypes":["Acid"]}', '<div> <div> Damage/Effect </div> <div> <i></i> Acid (...) </div> </div>', 'ec0d3f97-1d6d-4e25-8c41-567eac8108ef'::uuid),
                    ('Description', 'description', '["You touch one willing creature, and choose Acid, Cold, Fire, Lightning, or Poison. Until the spell ends, the target can take a Magic action to exhale a 15-foot Cone . Each creature in that area makes a Dexterity saving throw, taking 3d6 damage of the chosen type on a failed save or half as much damage on a successful one.","Using a Higher-Level Spell Slot. The damage increases by 1d6 for each spell slot level above 2."]', '<div> <p>You touch one willing creature, and choose Acid, Cold, Fire, Lightning, or Poison. Until the spell ends, the target can take a <a>Magic</a> action to exhale a 15-foot <a>Cone</a>. Each creature in that area makes a Dexterity saving throw, taking 3d6 damage of the chosen type on a failed save or half as much damage on a successful one.</p> <p><strong><em>Using a Higher-Level Spell Slot.</em></strong> The damage increases by 1d6 for each spell slot level above 2.</p> <span>* - (a hot pepper)</span> </div>', 'ec0d3f97-1d6d-4e25-8c41-567eac8108ef'::uuid),
