                    ('Source URL', 'url', 'https://www.dndbeyond.com/spells/2619158-druidcraft', '', '7c63bb8a-23ba-42ec-b480-9d1d26e8f9f2'::uuid),
                    ('Image', 'imageUrl', 'https://www.dndbeyond.com/attachments/2/722/transmutation.png', '', '7c63bb8a-23ba-42ec-b480-9d1d26e8f9f2'::uuid),
                    ('Level', 'level', '{"levelNumber":"2","label":"2nd"}', '<div> <div> Level </div> <div> 2nd </div> </div>', 'a9b9094d-ca90-4a5b-b27d-f4132ddfb19c'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Action","kind":"action","value":1,"unit":"action","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Action </div> </div>', 'a9b9094d-ca90-4a5b-b27d-f4132ddfb19c'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"60 ft. (5 ft. *)","kind":"distance","distanceValue":60,"distanceUnit":"ft","area":{"shape":null,"value":5,"unit":"ft"}}', '<div> <div> Range/Area </div> <div> 60 ft. <span>(5 ft. <i></i> *)</span> </div> </div>', 'a9b9094d-ca90-4a5b-b27d-f4132ddfb19c'::uuid),
                    ('Components', 'components', '{"text":"V, S, M *","verbal":true,"somatic":true,"material":{"required":true,"description":"a pinch of dust","consumed":false,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S, M *</span> </div> </div>', 'a9b9094d-ca90-4a5b-b27d-f4132ddfb19c'::uuid),
                    ('Duration', 'duration', '{"text":"Concentration 1 Minute","kind":"timed","value":1,"unit":"minute","concentration":true,"endCondition":null}', '<div> <div>Duration</div> <div> <i>Concentration</i> 1 Minute </div> </div>', 'a9b9094d-ca90-4a5b-b27d-f4132ddfb19c'::uuid),
                    ('School', 'school', 'Conjuration', '<div> <div> School </div> <div> Conjuration </div> </div>', 'a9b9094d-ca90-4a5b-b27d-f4132ddfb19c'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"STR Save","kind":"save","attackType":null,"ability":"STR"}', '<div> <div> Attack/Save </div> <div> <i></i> <span>STR Save</span> </div> </div>', 'a9b9094d-ca90-4a5b-b27d-f4132ddfb19c'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Bludgeoning","damageTypes":["Bludgeoning"]}', '<div> <div> Damage/Effect </div> <div> <i></i> Bludgeoning </div> </div>', 'a9b9094d-ca90-4a5b-b27d-f4132ddfb19c'::uuid),
                    ('Description', 'description', '["Choose an unoccupied 5-foot cube of air that you can see within range. An elemental force that resembles a dust devil appears in the cube and lasts for the spell’s duration.","Any creature that ends its turn within 5 feet of the dust devil must make a Strength saving throw. On a failed save, the creature takes 1d8 bludgeoning damage and is pushed 10 feet away. On a successful save, the creature takes half as much damage and isn’t pushed.","As a bonus action, you can move the dust devil up to 30 feet in any direction. If the dust devil moves over sand, dust, loose dirt, or small gravel, it sucks up the material and forms a 10-foot-radius cloud of debris around itself that lasts until the start of your next turn. The cloud heavily obscures its area.","At Higher Levels. When you cast this spell using a spell slot of 3rd level or higher, the damage increases by 1d8 for each slot level above 2nd."]', '<div> <p>Choose an unoccupied 5-foot cube of air that you can see within range. An elemental force that resembles a dust devil appears in the cube and lasts for the spell’s duration.</p> <p>Any creature that ends its turn within 5 feet of the dust devil must make a Strength saving throw. On a failed save, the creature takes 1d8 bludgeoning damage and is pushed 10 feet away. On a successful save, the creature takes half as much damage and isn’t pushed.</p> <p>As a bonus action, you can move the dust devil up to 30 feet in any direction. If the dust devil moves over sand, dust, loose dirt, or small gravel, it sucks up the material and forms a 10-foot-radius cloud of debris around itself that lasts until the start of your next turn. The cloud heavily obscures its area.</p> <p><em><strong>At Higher Levels.</strong></em> When you cast this spell using a spell slot of 3rd level or higher, the damage increases by 1d8 for each slot level above 2nd.</p> <span>* - (a pinch of dust)</span> </div>', 'a9b9094d-ca90-4a5b-b27d-f4132ddfb19c'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', 'a9b9094d-ca90-4a5b-b27d-f4132ddfb19c'::uuid),
                    ('Spell Tags', 'spellTags', '["Damage","Control"]', '', 'a9b9094d-ca90-4a5b-b27d-f4132ddfb19c'::uuid),
                    ('Available For', 'availableFor', '["Druid (Legacy)","Sorcerer (Legacy)","Wizard (Legacy)","Druid","Sorcerer","Wizard"]', '', 'a9b9094d-ca90-4a5b-b27d-f4132ddfb19c'::uuid),
                    ('Source', 'source', 'Elemental Evil Player''s Companion, pg. 154', '', 'a9b9094d-ca90-4a5b-b27d-f4132ddfb19c'::uuid),
