                    ('Level', 'level', '{"levelNumber":"1","label":"1st"}', '<div> <div> Level </div> <div> 1st </div> </div>', '445b7b7e-050a-4f16-8543-32ee99d137d1'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Action","kind":"action","value":1,"unit":"action","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Action </div> </div>', '445b7b7e-050a-4f16-8543-32ee99d137d1'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"10 ft.","kind":"distance","distanceValue":10,"distanceUnit":"ft","area":null}', '<div> <div> Range/Area </div> <div> 10 ft. </div> </div>', '445b7b7e-050a-4f16-8543-32ee99d137d1'::uuid),
                    ('Components', 'components', '{"text":"V, S","verbal":true,"somatic":true,"material":{"required":false,"description":null,"consumed":null,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S</span> </div> </div>', '445b7b7e-050a-4f16-8543-32ee99d137d1'::uuid),
                    ('Duration', 'duration', '{"text":"Instantaneous","kind":"instantaneous","value":null,"unit":null,"concentration":false,"endCondition":null}', '<div> <div>Duration</div> <div> Instantaneous </div> </div>', '445b7b7e-050a-4f16-8543-32ee99d137d1'::uuid),
                    ('School', 'school', 'Evocation', '<div> <div> School </div> <div> Evocation </div> </div>', '445b7b7e-050a-4f16-8543-32ee99d137d1'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"DEX Save","kind":"save","attackType":null,"ability":"DEX"}', '<div> <div> Attack/Save </div> <div> <i></i> <span>DEX Save</span> </div> </div>', '445b7b7e-050a-4f16-8543-32ee99d137d1'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Bludgeoning","damageTypes":["Bludgeoning"]}', '<div> <div> Damage/Effect </div> <div> <i></i> Bludgeoning </div> </div>', '445b7b7e-050a-4f16-8543-32ee99d137d1'::uuid),
                    ('Description', 'description', '["You cause a tremor in the ground within range. Each creature other than you in that area must make a Dexterity saving throw. On a failed save, a creature takes 1d6 bludgeoning damage and is knocked prone . If the ground in that area is loose earth or stone, it becomes difficult terrain until cleared, with each 5-foot-diameter portion requiring at least 1 minute to clear by hand.","At Higher Levels. When you cast this spell using a spell slot of 2nd level or higher, the damage increases by 1d6 for each slot level above 1st."]', '<div> <p>You cause a tremor in the ground within range. Each creature other than you in that area must make a Dexterity saving throw. On a failed save, a creature takes 1d6 bludgeoning damage and is knocked <a>prone</a>. If the ground in that area is loose earth or stone, it becomes difficult terrain until cleared, with each 5-foot-diameter portion requiring at least 1 minute to clear by hand.</p> <p><span><strong>At Higher Levels.</strong> </span>When you cast this spell using a spell slot of 2nd level or higher, the damage increases by 1d6 for each slot level above 1st.</p> <p><span> </span></p> </div>', '445b7b7e-050a-4f16-8543-32ee99d137d1'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', '445b7b7e-050a-4f16-8543-32ee99d137d1'::uuid),
