                    ('Available For', 'availableFor', '["Wizard (Legacy)","Wizard","Warlock (Legacy) - The Many","Warlock (Legacy) - The Parasite","Sorcerer - Aberrant Sorcery","Warlock - The Parasite","Cleric - Shadow Domain (BoET)","Druid - Circle of Shadows (BoET)","Warlock - The Many"]', '', 'd6356b88-2757-4d76-b9ef-c38c935d9721'::uuid),
                    ('Source', 'source', 'Player’s Handbook, pg. 270', '', 'd6356b88-2757-4d76-b9ef-c38c935d9721'::uuid),
                    ('Source URL', 'url', 'https://www.dndbeyond.com/spells/2619187-evards-black-tentacles', '', 'd6356b88-2757-4d76-b9ef-c38c935d9721'::uuid),
                    ('Image', 'imageUrl', 'https://www.dndbeyond.com/attachments/2/708/conjuration.png', '', 'd6356b88-2757-4d76-b9ef-c38c935d9721'::uuid),
                    ('Level', 'level', '{"levelNumber":"1","label":"1st"}', '<div> <div> Level </div> <div> 1st </div> </div>', 'a34cc51a-d856-4a21-adc9-888003330077'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Bonus Action","kind":"bonus_action","value":1,"unit":"action","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Bonus Action </div> </div>', 'a34cc51a-d856-4a21-adc9-888003330077'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"Self","kind":"self","distanceValue":null,"distanceUnit":null,"area":null}', '<div> <div> Range/Area </div> <div> Self </div> </div>', 'a34cc51a-d856-4a21-adc9-888003330077'::uuid),
                    ('Components', 'components', '{"text":"V, S","verbal":true,"somatic":true,"material":{"required":false,"description":null,"consumed":null,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S</span> </div> </div>', 'a34cc51a-d856-4a21-adc9-888003330077'::uuid),
                    ('Duration', 'duration', '{"text":"Concentration 10 Minutes","kind":"timed","value":10,"unit":"minute","concentration":true,"endCondition":null}', '<div> <div>Duration</div> <div> <i>Concentration</i> 10 Minutes </div> </div>', 'a34cc51a-d856-4a21-adc9-888003330077'::uuid),
                    ('School', 'school', 'Transmutation', '<div> <div> School </div> <div> Transmutation </div> </div>', 'a34cc51a-d856-4a21-adc9-888003330077'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"None","kind":"none","attackType":null,"ability":null}', '<div> <div> Attack/Save </div> <div> <span>None</span> </div> </div>', 'a34cc51a-d856-4a21-adc9-888003330077'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Movement","damageTypes":[]}', '<div> <div> Damage/Effect </div> <div> Movement </div> </div>', 'a34cc51a-d856-4a21-adc9-888003330077'::uuid),
                    ('Description', 'description', '["You take the Dash action, and until the spell ends, you can take that action again as a Bonus Action."]', '<div> <p>You take the <a>Dash</a> action, and until the spell ends, you can take that action again as a Bonus Action.</p> </div>', 'a34cc51a-d856-4a21-adc9-888003330077'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', 'a34cc51a-d856-4a21-adc9-888003330077'::uuid),
                    ('Spell Tags', 'spellTags', '["Movement"]', '', 'a34cc51a-d856-4a21-adc9-888003330077'::uuid),
                    ('Available For', 'availableFor', '["Sorcerer (Legacy)","Warlock (Legacy)","Wizard (Legacy)","Artificer (Legacy)","Sorcerer","Warlock","Wizard","Artificer","Paladin - Oath of the Open Sea (TCSR)"]', '', 'a34cc51a-d856-4a21-adc9-888003330077'::uuid),
                    ('Source', 'source', 'Player’s Handbook, pg. 270', '', 'a34cc51a-d856-4a21-adc9-888003330077'::uuid),
                    ('Source URL', 'url', 'https://www.dndbeyond.com/spells/2619189-expeditious-retreat', '', 'a34cc51a-d856-4a21-adc9-888003330077'::uuid),
