                    ('Available For', 'availableFor', '["Wizard (Legacy)","Artificer (Legacy)","Wizard","Artificer","Cleric - Forge Domain (XGtE)"]', '', 'c3131ad7-51d4-427a-9dbc-79392fd7357c'::uuid),
                    ('Source', 'source', 'Player’s Handbook, pg. 271', '', 'c3131ad7-51d4-427a-9dbc-79392fd7357c'::uuid),
