                    ('Level', 'level', '{"levelNumber":"1","label":"1st"}', '<div> <div> Level </div> <div> 1st </div> </div>', '00757d3c-b1f7-4651-9b0e-9db3139c0f1d'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Action","kind":"action","value":1,"unit":"action","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Action </div> </div>', '00757d3c-b1f7-4651-9b0e-9db3139c0f1d'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"60 ft. (20 ft.)","kind":"distance","distanceValue":60,"distanceUnit":"ft","area":{"shape":null,"value":20,"unit":"ft"}}', '<div> <div> Range/Area </div> <div> 60 ft. <span>(20 ft. <i></i>)</span> </div> </div>', '00757d3c-b1f7-4651-9b0e-9db3139c0f1d'::uuid),
                    ('Components', 'components', '{"text":"V","verbal":true,"somatic":false,"material":{"required":false,"description":null,"consumed":null,"costGp":null}}', '<div> <div> Components </div> <div> <span>V</span> </div> </div>', '00757d3c-b1f7-4651-9b0e-9db3139c0f1d'::uuid),
                    ('Duration', 'duration', '{"text":"Concentration 1 Minute","kind":"timed","value":1,"unit":"minute","concentration":true,"endCondition":null}', '<div> <div>Duration</div> <div> <i>Concentration</i> 1 Minute </div> </div>', '00757d3c-b1f7-4651-9b0e-9db3139c0f1d'::uuid),
                    ('School', 'school', 'Evocation', '<div> <div> School </div> <div> Evocation </div> </div>', '00757d3c-b1f7-4651-9b0e-9db3139c0f1d'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"DEX Save","kind":"save","attackType":null,"ability":"DEX"}', '<div> <div> Attack/Save </div> <div> <i></i> <span>DEX Save</span> </div> </div>', '00757d3c-b1f7-4651-9b0e-9db3139c0f1d'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Debuff","damageTypes":[]}', '<div> <div> Damage/Effect </div> <div> Debuff </div> </div>', '00757d3c-b1f7-4651-9b0e-9db3139c0f1d'::uuid),
                    ('Description', 'description', '["Objects in a 20-foot Cube within range are outlined in blue, green, or violet light (your choice). Each creature in the Cube is also outlined if it fails a Dexterity saving throw. For the duration, objects and affected creatures shed Dim Light in a 10-foot radius and can’t benefit from the Invisible condition.","Attack rolls against an affected creature or object have Advantage if the attacker can see it."]', '<div> <p>Objects in a 20-foot <a>Cube</a> within range are outlined in blue, green, or violet light (your choice). Each creature in the Cube is also outlined if it fails a Dexterity saving throw. For the duration, objects and affected creatures shed <a>Dim Light</a> in a 10-foot radius and can’t benefit from the <a>Invisible</a> condition.</p> <p>Attack rolls against an affected creature or object have Advantage if the attacker can see it.</p> </div>', '00757d3c-b1f7-4651-9b0e-9db3139c0f1d'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', '00757d3c-b1f7-4651-9b0e-9db3139c0f1d'::uuid),
                    ('Spell Tags', 'spellTags', '["Debuff"]', '', '00757d3c-b1f7-4651-9b0e-9db3139c0f1d'::uuid),
                    ('Available For', 'availableFor', '["Bard (Legacy)","Druid (Legacy)","Artificer (Legacy)","Bard","Druid","Artificer","Cleric - Light Domain","Cleric - Twilight Domain (TCoE)","Warlock - Archfey Patron","Cleric - Moon Domain (TCSR)","Warlock - Lantern Patron (OTTG)"]', '', '00757d3c-b1f7-4651-9b0e-9db3139c0f1d'::uuid),
                    ('Source', 'source', 'Player’s Handbook, pg. 271', '', '00757d3c-b1f7-4651-9b0e-9db3139c0f1d'::uuid),
