                    ('Image', 'imageUrl', 'https://www.dndbeyond.com/attachments/2/703/evocation.png', '', '00757d3c-b1f7-4651-9b0e-9db3139c0f1d'::uuid),
                    ('Level', 'level', '{"levelNumber":"4","label":"4th"}', '<div> <div> Level </div> <div> 4th </div> </div>', '43818389-b08b-4680-a2f6-ced45136375c'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Action","kind":"action","value":1,"unit":"action","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Action </div> </div>', '43818389-b08b-4680-a2f6-ced45136375c'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"30 ft.","kind":"distance","distanceValue":30,"distanceUnit":"ft","area":null}', '<div> <div> Range/Area </div> <div> 30 ft. </div> </div>', '43818389-b08b-4680-a2f6-ced45136375c'::uuid),
                    ('Components', 'components', '{"text":"V, S, M *","verbal":true,"somatic":true,"material":{"required":true,"description":"a tiny silver whistle, a piece of bone, and a thread","consumed":false,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S, M *</span> </div> </div>', '43818389-b08b-4680-a2f6-ced45136375c'::uuid),
                    ('Duration', 'duration', '{"text":"8 Hours","kind":"timed","value":8,"unit":"hour","concentration":false,"endCondition":null}', '<div> <div>Duration</div> <div> 8 Hours </div> </div>', '43818389-b08b-4680-a2f6-ced45136375c'::uuid),
                    ('School', 'school', 'Conjuration', '<div> <div> School </div> <div> Conjuration </div> </div>', '43818389-b08b-4680-a2f6-ced45136375c'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"Melee","kind":"attack","attackType":"melee","ability":null}', '<div> <div> Attack/Save </div> <div> <i></i> <span>Melee</span> </div> </div>', '43818389-b08b-4680-a2f6-ced45136375c'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Piercing","damageTypes":["Piercing"]}', '<div> <div> Damage/Effect </div> <div> <i></i> Piercing </div> </div>', '43818389-b08b-4680-a2f6-ced45136375c'::uuid),
                    ('Description', 'description', '["You conjure a phantom watchdog in an unoccupied space that you can see within range, where it remains for the duration, until you dismiss it as an action, or until you move more than 100 feet away from it.","The hound is invisible to all creatures except you and can''t be harmed. When a Small or larger creature comes within 30 feet of it without first speaking the password that you specify when you cast this spell, the hound starts barking loudly. The hound sees invisible creatures and can see into the Ethereal Plane. It ignores illusions.","At the start of each of your turns, the hound attempts to bite one creature within 5 feet of it that is hostile to you. The hound''s attack bonus is equal to your spellcasting ability modifier + your proficiency bonus. On a hit, it deals 4d8 piercing damage."]', '<div> <p>You conjure a phantom watchdog in an unoccupied space that you can see within range, where it remains for the duration, until you dismiss it as an action, or until you move more than 100 feet away from it.</p> <p>The hound is <a>invisible</a> to all creatures except you and can''t be harmed. When a Small or larger creature comes within 30 feet of it without first speaking the password that you specify when you cast this spell, the hound starts barking loudly. The hound sees <a>invisible</a> creatures and can see into the Ethereal Plane. It ignores illusions.</p> <p>At the start of each of your turns, the hound attempts to bite one creature within 5 feet of it that is hostile to you. The hound''s attack bonus is equal to your spellcasting ability modifier + your proficiency bonus. On a hit, it deals 4d8 piercing damage.</p> <span>* - (a tiny silver whistle, a piece of bone, and a thread)</span> </div>', '43818389-b08b-4680-a2f6-ced45136375c'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', '43818389-b08b-4680-a2f6-ced45136375c'::uuid),
