                    ('School', 'school', 'Necromancy', '<div> <div> School </div> <div> Necromancy </div> </div>', '85223f71-eb71-486a-aae7-868d80cc40c4'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"None","kind":"none","attackType":null,"ability":null}', '<div> <div> Attack/Save </div> <div> <span>None</span> </div> </div>', '85223f71-eb71-486a-aae7-868d80cc40c4'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Buff","damageTypes":[]}', '<div> <div> Damage/Effect </div> <div> Buff </div> </div>', '85223f71-eb71-486a-aae7-868d80cc40c4'::uuid),
                    ('Description', 'description', '["You gain 2d4 + 4 Temporary Hit Points .","Using a Higher-Level Spell Slot. You gain 5 additional Temporary Hit Points for each spell slot level above 1."]', '<div> <p>You gain 2d4 + 4 <a>Temporary Hit Points</a>.</p> <p><strong><em>Using a Higher-Level Spell Slot.</em></strong> You gain 5 additional Temporary Hit Points for each spell slot level above 1.</p> <span>* - (a drop of alcohol)</span> </div>', '85223f71-eb71-486a-aae7-868d80cc40c4'::uuid),
