                    ('Casting Time', 'castingTime', '{"text":"1 Action","kind":"action","value":1,"unit":"action","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Action </div> </div>', 'afc80f92-174c-4d4c-85f5-39c9b87ca616'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"Self (30 ft.)","kind":"self","distanceValue":null,"distanceUnit":null,"area":{"shape":null,"value":30,"unit":"ft"}}', '<div> <div> Range/Area </div> <div> Self <span>(30 ft. <i></i>)</span> </div> </div>', 'afc80f92-174c-4d4c-85f5-39c9b87ca616'::uuid),
                    ('Components', 'components', '{"text":"V, S, M *","verbal":true,"somatic":true,"material":{"required":true,"description":"a white feather","consumed":false,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S, M *</span> </div> </div>', 'afc80f92-174c-4d4c-85f5-39c9b87ca616'::uuid),
                    ('Duration', 'duration', '{"text":"Concentration 1 Minute","kind":"timed","value":1,"unit":"minute","concentration":true,"endCondition":null}', '<div> <div>Duration</div> <div> <i>Concentration</i> 1 Minute </div> </div>', 'afc80f92-174c-4d4c-85f5-39c9b87ca616'::uuid),
                    ('School', 'school', 'Illusion', '<div> <div> School </div> <div> Illusion </div> </div>', 'afc80f92-174c-4d4c-85f5-39c9b87ca616'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"WIS Save","kind":"save","attackType":null,"ability":"WIS"}', '<div> <div> Attack/Save </div> <div> <i></i> <span>WIS Save</span> </div> </div>', 'afc80f92-174c-4d4c-85f5-39c9b87ca616'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Frightened","damageTypes":[]}', '<div> <div> Damage/Effect </div> <div> <i></i> Frightened </div> </div>', 'afc80f92-174c-4d4c-85f5-39c9b87ca616'::uuid),
                    ('Description', 'description', '["Each creature in a 30-foot Cone must succeed on a Wisdom saving throw or drop whatever it is holding and have the Frightened condition for the duration.","A Frightened creature takes the Dash action and moves away from you by the safest route on each of its turns unless there is nowhere to move. If the creature ends its turn in a space where it doesn’t have line of sight to you, the creature makes a Wisdom saving throw. On a successful save, the spell ends on that creature."]', '<div> <p>Each creature in a 30-foot <a>Cone</a> must succeed on a Wisdom saving throw or drop whatever it is holding and have the <a>Frightened</a> condition for the duration.</p> <p>A Frightened creature takes the <a>Dash</a> action and moves away from you by the safest route on each of its turns unless there is nowhere to move. If the creature ends its turn in a space where it doesn’t have line of sight to you, the creature makes a Wisdom saving throw. On a successful save, the spell ends on that creature.</p> <span>* - (a white feather)</span> </div>', 'afc80f92-174c-4d4c-85f5-39c9b87ca616'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', 'afc80f92-174c-4d4c-85f5-39c9b87ca616'::uuid),
