                    ('Level', 'level', '{"levelNumber":"1","label":"1st"}', '<div> <div> Level </div> <div> 1st </div> </div>', '98840ab5-f707-410f-9cb8-ea9c5ea8cc12'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Reaction *","kind":"reaction","value":1,"unit":"action","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Reaction * </div> </div>', '98840ab5-f707-410f-9cb8-ea9c5ea8cc12'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"60 ft.","kind":"distance","distanceValue":60,"distanceUnit":"ft","area":null}', '<div> <div> Range/Area </div> <div> 60 ft. </div> </div>', '98840ab5-f707-410f-9cb8-ea9c5ea8cc12'::uuid),
                    ('Components', 'components', '{"text":"V, M **","verbal":true,"somatic":false,"material":{"required":true,"description":"** - (a small feather or piece of down)","consumed":false,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, M **</span> </div> </div>', '98840ab5-f707-410f-9cb8-ea9c5ea8cc12'::uuid),
                    ('Duration', 'duration', '{"text":"1 Minute","kind":"timed","value":1,"unit":"minute","concentration":false,"endCondition":null}', '<div> <div>Duration</div> <div> 1 Minute </div> </div>', '98840ab5-f707-410f-9cb8-ea9c5ea8cc12'::uuid),
                    ('School', 'school', 'Transmutation', '<div> <div> School </div> <div> Transmutation </div> </div>', '98840ab5-f707-410f-9cb8-ea9c5ea8cc12'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"None","kind":"none","attackType":null,"ability":null}', '<div> <div> Attack/Save </div> <div> <span>None</span> </div> </div>', '98840ab5-f707-410f-9cb8-ea9c5ea8cc12'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Exploration (...)","damageTypes":[]}', '<div> <div> Damage/Effect </div> <div> Exploration (...) </div> </div>', '98840ab5-f707-410f-9cb8-ea9c5ea8cc12'::uuid),
                    ('Description', 'description', '["Choose up to five falling creatures within range. A falling creature’s rate of descent slows to 60 feet per round until the spell ends. If a creature lands before the spell ends, the creature takes no damage from the fall, and the spell ends for that creature."]', '<div> <p>Choose up to five falling creatures within range. A falling creature’s rate of descent slows to 60 feet per round until the spell ends. If a creature lands before the spell ends, the creature takes no damage from the fall, and the spell ends for that creature.</p> <span>* - which you take when you or a creature you can see within 60 feet of you falls</span> <span>** - (a small feather or piece of down)</span> </div>', '98840ab5-f707-410f-9cb8-ea9c5ea8cc12'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '* - which you take when you or a creature you can see within 60 feet of you falls', '', '98840ab5-f707-410f-9cb8-ea9c5ea8cc12'::uuid),
                    ('Spell Tags', 'spellTags', '["Utility","Exploration"]', '', '98840ab5-f707-410f-9cb8-ea9c5ea8cc12'::uuid),
