                    ('Range/Area', 'rangeArea', '{"text":"Sight","kind":"sight","distanceValue":null,"distanceUnit":null,"area":null}', '', '8b8e19a4-a3ec-4332-999e-dc95f9f2134b'::uuid),
                    ('Components', 'components', '{"text":"None","verbal":false,"somatic":false,"material":{"required":false,"description":null,"consumed":null,"costGp":null}}', '', '8b8e19a4-a3ec-4332-999e-dc95f9f2134b'::uuid),
                    ('Duration', 'duration', '{"text":"Instantaneous","kind":"instantaneous","value":null,"unit":null,"concentration":false,"endCondition":null}', '', '8b8e19a4-a3ec-4332-999e-dc95f9f2134b'::uuid),
                    ('School', 'school', 'Evocation', '', '8b8e19a4-a3ec-4332-999e-dc95f9f2134b'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"None","kind":"none","attackType":null,"ability":null}', '', '8b8e19a4-a3ec-4332-999e-dc95f9f2134b'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"","damageTypes":[]}', '', '8b8e19a4-a3ec-4332-999e-dc95f9f2134b'::uuid),
                    ('Description', 'description', '["You put your hand into a menacing finger gun and pretend to load and cock it before aiming it at one creature you can see. If that creature''s hit point maximum is under 350 points, it must make a constitution saving throw with disadvantage or drop to their knees and fall to 0 hit points as a hole is blown through them with a finger gun of all things.","\"You messed with the wrong gunslinger, boy.\" *Insta kills red dragons with finger gun*"]', '<p>You put your hand into a menacing finger gun and pretend to load and cock it before aiming it at one creature you can see. If that creature''s hit point maximum is under 350 points, it must make a constitution saving throw with disadvantage or drop to their knees and fall to 0 hit points as a hole is blown through them with a finger gun of all things.</p> <p>"You messed with the wrong gunslinger, boy." *Insta kills red dragons with finger gun*</p>', '8b8e19a4-a3ec-4332-999e-dc95f9f2134b'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', '8b8e19a4-a3ec-4332-999e-dc95f9f2134b'::uuid),
                    ('Spell Tags', 'spellTags', '[]', '', '8b8e19a4-a3ec-4332-999e-dc95f9f2134b'::uuid),
                    ('Available For', 'availableFor', '[]', '', '8b8e19a4-a3ec-4332-999e-dc95f9f2134b'::uuid),
                    ('Source', 'source', 'Homebrew (D&D Beyond)', '', '8b8e19a4-a3ec-4332-999e-dc95f9f2134b'::uuid),
                    ('Source URL', 'url', 'https://www.dndbeyond.com/spells/3220917-finger-gun-pow', '', '8b8e19a4-a3ec-4332-999e-dc95f9f2134b'::uuid),
                    ('Image', 'imageUrl', '', '', '8b8e19a4-a3ec-4332-999e-dc95f9f2134b'::uuid),
                    ('Level', 'level', '{"levelNumber":"7","label":"7th"}', '<div> <div> Level </div> <div> 7th </div> </div>', '450e4634-7def-4433-bed3-6ac8b1dabcf3'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Action","kind":"action","value":1,"unit":"action","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Action </div> </div>', '450e4634-7def-4433-bed3-6ac8b1dabcf3'::uuid),
