            migrationBuilder.Sql("""
                INSERT INTO "SpellComponents" ("Label", "Key", "Value", "Html", "SpellId") VALUES
                    ('School', 'school', 'Necromancy', '<div> <div> School </div> <div> Necromancy </div> </div>', '450e4634-7def-4433-bed3-6ac8b1dabcf3'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"CON Save","kind":"save","attackType":null,"ability":"CON"}', '<div> <div> Attack/Save </div> <div> <i></i> <span>CON Save</span> </div> </div>', '450e4634-7def-4433-bed3-6ac8b1dabcf3'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Necrotic","damageTypes":["Necrotic"]}', '<div> <div> Damage/Effect </div> <div> <i></i> Necrotic </div> </div>', '450e4634-7def-4433-bed3-6ac8b1dabcf3'::uuid),
                    ('Description', 'description', '["You unleash negative energy toward a creature you can see within range. The target makes a Constitution saving throw, taking 7d8 + 30 Necrotic damage on a failed save or half as much damage on a successful one.","A Humanoid killed by this spell rises at the start of your next turn as a Zombie (see appendix B) that follows your verbal orders."]', '<div> <p>You unleash negative energy toward a creature you can see within range. The target makes a Constitution saving throw, taking 7d8 + 30 Necrotic damage on a failed save or half as much damage on a successful one.</p> <p>A Humanoid killed by this spell rises at the start of your next turn as a <a>Zombie</a> (see appendix B) that follows your verbal orders.</p> </div>', '450e4634-7def-4433-bed3-6ac8b1dabcf3'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', '450e4634-7def-4433-bed3-6ac8b1dabcf3'::uuid),
                    ('Spell Tags', 'spellTags', '["Creation","Damage","Control"]', '', '450e4634-7def-4433-bed3-6ac8b1dabcf3'::uuid),
                    ('Available For', 'availableFor', '["Sorcerer (Legacy)","Warlock (Legacy)","Wizard (Legacy)","Sorcerer","Warlock","Wizard"]', '', '450e4634-7def-4433-bed3-6ac8b1dabcf3'::uuid),
                    ('Source', 'source', 'Player’s Handbook, pg. 273', '', '450e4634-7def-4433-bed3-6ac8b1dabcf3'::uuid),
                    ('Source URL', 'url', 'https://www.dndbeyond.com/spells/2618885-finger-of-death', '', '450e4634-7def-4433-bed3-6ac8b1dabcf3'::uuid),
                    ('Image', 'imageUrl', 'https://www.dndbeyond.com/attachments/2/720/necromancy.png', '', '450e4634-7def-4433-bed3-6ac8b1dabcf3'::uuid),
                    ('Level', 'level', '{"levelNumber":"Cantrip","label":"Cantrip"}', '<div> <div> Level </div> <div> Cantrip </div> </div>', 'b2c02b56-752c-46ec-b275-c202fa19361c'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Action","kind":"action","value":1,"unit":"action","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Action </div> </div>', 'b2c02b56-752c-46ec-b275-c202fa19361c'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"120 ft.","kind":"distance","distanceValue":120,"distanceUnit":"ft","area":null}', '<div> <div> Range/Area </div> <div> 120 ft. </div> </div>', 'b2c02b56-752c-46ec-b275-c202fa19361c'::uuid),
                    ('Components', 'components', '{"text":"V, S","verbal":true,"somatic":true,"material":{"required":false,"description":null,"consumed":null,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S</span> </div> </div>', 'b2c02b56-752c-46ec-b275-c202fa19361c'::uuid),
                    ('Duration', 'duration', '{"text":"Instantaneous","kind":"instantaneous","value":null,"unit":null,"concentration":false,"endCondition":null}', '<div> <div>Duration</div> <div> Instantaneous </div> </div>', 'b2c02b56-752c-46ec-b275-c202fa19361c'::uuid),
                    ('School', 'school', 'Evocation', '<div> <div> School </div> <div> Evocation </div> </div>', 'b2c02b56-752c-46ec-b275-c202fa19361c'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"Ranged","kind":"attack","attackType":"ranged","ability":null}', '<div> <div> Attack/Save </div> <div> <i></i> <span>Ranged</span> </div> </div>', 'b2c02b56-752c-46ec-b275-c202fa19361c'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Fire","damageTypes":["Fire"]}', '<div> <div> Damage/Effect </div> <div> <i></i> Fire </div> </div>', 'b2c02b56-752c-46ec-b275-c202fa19361c'::uuid),
                    ('Description', 'description', '["You hurl a mote of fire at a creature or an object within range. Make a ranged spell attack against the target. On a hit, the target takes 1d10 Fire damage. A flammable object hit by this spell starts burning if it isn’t being worn or carried.","Cantrip Upgrade. The damage increases by 1d10 when you reach levels 5 (2d10), 11 (3d10), and 17 (4d10)."]', '<div> <p>You hurl a mote of fire at a creature or an object within range. Make a ranged spell attack against the target. On a hit, the target takes 1d10 Fire damage. A flammable object hit by this spell starts <a>burning</a> if it isn’t being worn or carried.</p> <p><strong><em>Cantrip Upgrade.</em></strong> The damage increases by 1d10 when you reach levels 5 (2d10), 11 (3d10), and 17 (4d10).</p> </div>', 'b2c02b56-752c-46ec-b275-c202fa19361c'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', 'b2c02b56-752c-46ec-b275-c202fa19361c'::uuid),
                    ('Spell Tags', 'spellTags', '["Damage"]', '', 'b2c02b56-752c-46ec-b275-c202fa19361c'::uuid),
                    ('Available For', 'availableFor', '["Sorcerer (Legacy)","Wizard (Legacy)","Artificer (Legacy)","Sorcerer","Wizard","Artificer","Illrigger - Architect of Ruin"]', '', 'b2c02b56-752c-46ec-b275-c202fa19361c'::uuid),
                    ('Source', 'source', 'Player’s Handbook, pg. 274', '', 'b2c02b56-752c-46ec-b275-c202fa19361c'::uuid),
                    ('Source URL', 'url', 'https://www.dndbeyond.com/spells/2618890-fire-bolt', '', 'b2c02b56-752c-46ec-b275-c202fa19361c'::uuid),
                    ('Image', 'imageUrl', 'https://www.dndbeyond.com/attachments/2/703/evocation.png', '', 'b2c02b56-752c-46ec-b275-c202fa19361c'::uuid),
                    ('Level', 'level', '{"levelNumber":"4","label":"4th"}', '<div> <div> Level </div> <div> 4th </div> </div>', '11e685f8-a49d-4a7a-9279-11a9f0f71233'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Action","kind":"action","value":1,"unit":"action","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Action </div> </div>', '11e685f8-a49d-4a7a-9279-11a9f0f71233'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"Self","kind":"self","distanceValue":null,"distanceUnit":null,"area":null}', '<div> <div> Range/Area </div> <div> Self </div> </div>', '11e685f8-a49d-4a7a-9279-11a9f0f71233'::uuid),
                    ('Components', 'components', '{"text":"V, S, M *","verbal":true,"somatic":true,"material":{"required":true,"description":"a bit of phosphorus or a firefly","consumed":false,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S, M *</span> </div> </div>', '11e685f8-a49d-4a7a-9279-11a9f0f71233'::uuid),
                    ('Duration', 'duration', '{"text":"10 Minutes","kind":"timed","value":10,"unit":"minute","concentration":false,"endCondition":null}', '<div> <div>Duration</div> <div> 10 Minutes </div> </div>', '11e685f8-a49d-4a7a-9279-11a9f0f71233'::uuid),
                    ('School', 'school', 'Evocation', '<div> <div> School </div> <div> Evocation </div> </div>', '11e685f8-a49d-4a7a-9279-11a9f0f71233'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"None","kind":"none","attackType":null,"ability":null}', '<div> <div> Attack/Save </div> <div> <span>None</span> </div> </div>', '11e685f8-a49d-4a7a-9279-11a9f0f71233'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Fire (...)","damageTypes":["Fire"]}', '<div> <div> Damage/Effect </div> <div> <i></i> Fire (...) </div> </div>', '11e685f8-a49d-4a7a-9279-11a9f0f71233'::uuid),
                    ('Description', 'description', '["Wispy flames wreathe your body for the duration, shedding Bright Light in a 10-foot radius and Dim Light for an additional 10 feet.","The flames provide you with a warm shield or a chill shield, as you choose. The warm shield grants you Resistance to Cold damage, and the chill shield grants you Resistance to Fire damage.","In addition, whenever a creature within 5 feet of you hits you with a melee attack roll, the shield erupts with flame. The attacker takes 2d8 Fire damage from a warm shield or 2d8 Cold damage from a chill shield."]', '<div> <p>Wispy flames wreathe your body for the duration, shedding <a>Bright Light</a> in a 10-foot radius and <a>Dim Light</a> for an additional 10 feet.</p> <p>The flames provide you with a warm shield or a chill shield, as you choose. The warm shield grants you Resistance to Cold damage, and the chill shield grants you Resistance to Fire damage.</p> <p>In addition, whenever a creature within 5 feet of you hits you with a melee attack roll, the shield erupts with flame. The attacker takes 2d8 Fire damage from a warm shield or 2d8 Cold damage from a chill shield.</p> <span>* - (a bit of phosphorus or a firefly)</span> </div>', '11e685f8-a49d-4a7a-9279-11a9f0f71233'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', '11e685f8-a49d-4a7a-9279-11a9f0f71233'::uuid),
                    ('Spell Tags', 'spellTags', '["Damage","Buff"]', '', '11e685f8-a49d-4a7a-9279-11a9f0f71233'::uuid),
                    ('Available For', 'availableFor', '["Druid (Legacy)","Sorcerer (Legacy)","Wizard (Legacy)","Druid","Sorcerer","Wizard","Cleric - War Domain","Druid - Circle of Wildfire (TCoE)","Warlock - The Genie (TCoE)","Warlock - Fiend Patron"]', '', '11e685f8-a49d-4a7a-9279-11a9f0f71233'::uuid),
                    ('Source', 'source', 'Player’s Handbook, pg. 274', '', '11e685f8-a49d-4a7a-9279-11a9f0f71233'::uuid),
