                    ('Available For', 'availableFor', '["Sorcerer (Legacy)","Wizard (Legacy)","Sorcerer","Wizard","Cleric - Light Domain","Warlock - The Genie (TCoE)","Warlock - Fiend Patron"]', '', 'f98810fa-d23c-4382-b8a3-73eb7eeaa222'::uuid),
                    ('Source', 'source', 'Player’s Handbook, pg. 274', '', 'f98810fa-d23c-4382-b8a3-73eb7eeaa222'::uuid),
                    ('Source URL', 'url', 'https://www.dndbeyond.com/spells/2618887-fireball', '', 'f98810fa-d23c-4382-b8a3-73eb7eeaa222'::uuid),
                    ('Image', 'imageUrl', 'https://www.dndbeyond.com/attachments/2/703/evocation.png', '', 'f98810fa-d23c-4382-b8a3-73eb7eeaa222'::uuid),
                    ('Level', 'level', '{"levelNumber":"3","label":"3rd"}', '<div> <div> Level </div> <div> 3rd </div> </div>', 'b1ff482d-281c-4746-8dc3-53fab6015d05'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Action","kind":"action","value":1,"unit":"action","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Action </div> </div>', 'b1ff482d-281c-4746-8dc3-53fab6015d05'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"Touch","kind":"touch","distanceValue":null,"distanceUnit":null,"area":null}', '<div> <div> Range/Area </div> <div> Touch </div> </div>', 'b1ff482d-281c-4746-8dc3-53fab6015d05'::uuid),
                    ('Components', 'components', '{"text":"V, S","verbal":true,"somatic":true,"material":{"required":false,"description":null,"consumed":null,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S</span> </div> </div>', 'b1ff482d-281c-4746-8dc3-53fab6015d05'::uuid),
                    ('Duration', 'duration', '{"text":"Concentration 1 Hour","kind":"timed","value":1,"unit":"hour","concentration":true,"endCondition":null}', '<div> <div>Duration</div> <div> <i>Concentration</i> 1 Hour </div> </div>', 'b1ff482d-281c-4746-8dc3-53fab6015d05'::uuid),
                    ('School', 'school', 'Transmutation', '<div> <div> School </div> <div> Transmutation </div> </div>', 'b1ff482d-281c-4746-8dc3-53fab6015d05'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"None","kind":"none","attackType":null,"ability":null}', '<div> <div> Attack/Save </div> <div> <span>None</span> </div> </div>', 'b1ff482d-281c-4746-8dc3-53fab6015d05'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Fire","damageTypes":["Fire"]}', '<div> <div> Damage/Effect </div> <div> <i></i> Fire </div> </div>', 'b1ff482d-281c-4746-8dc3-53fab6015d05'::uuid),
                    ('Description', 'description', '["You touch a quiver containing arrows or bolts. When a target is hit by a ranged weapon attack using a piece of ammunition drawn from the quiver, the target takes an extra 1d6 fire damage. The spell’s magic ends on the piece of ammunition when it hits or misses, and the spell ends when twelve pieces of ammunition have been drawn from the quiver.","At Higher Levels. When you cast this spell using a spell slot of 4th level or higher, the number of pieces of ammunition you can affect with this spell increases by two for each slot level above 3rd."]', '<div> <p>You touch a quiver containing arrows or bolts. When a target is hit by a ranged weapon attack using a piece of ammunition drawn from the quiver, the target takes an extra 1d6 fire damage. The spell’s magic ends on the piece of ammunition when it hits or misses, and the spell ends when twelve pieces of ammunition have been drawn from the quiver.</p> <p><em><strong>At Higher Levels.</strong></em> When you cast this spell using a spell slot of 4th level or higher, the number of pieces of ammunition you can affect with this spell increases by two for each slot level above 3rd.</p> </div>', 'b1ff482d-281c-4746-8dc3-53fab6015d05'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', 'b1ff482d-281c-4746-8dc3-53fab6015d05'::uuid),
                    ('Spell Tags', 'spellTags', '["Damage","Buff"]', '', 'b1ff482d-281c-4746-8dc3-53fab6015d05'::uuid),
                    ('Available For', 'availableFor', '["Druid (Legacy)","Ranger (Legacy)","Sorcerer (Legacy)","Wizard (Legacy)","Artificer (Legacy)","Druid","Ranger","Sorcerer","Wizard","Artificer"]', '', 'b1ff482d-281c-4746-8dc3-53fab6015d05'::uuid),
                    ('Source', 'source', 'Elemental Evil Player''s Companion, pg. 156', '', 'b1ff482d-281c-4746-8dc3-53fab6015d05'::uuid),
