                    ('Image', 'imageUrl', 'https://www.dndbeyond.com/attachments/2/722/transmutation.png', '', 'b1ff482d-281c-4746-8dc3-53fab6015d05'::uuid),
                    ('Level', 'level', '{"levelNumber":"2","label":"2nd"}', '<div> <div> Level </div> <div> 2nd </div> </div>', 'c3931b5d-7b01-4e21-a2df-646d06f47c19'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Bonus Action","kind":"bonus_action","value":1,"unit":"action","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Bonus Action </div> </div>', 'c3931b5d-7b01-4e21-a2df-646d06f47c19'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"Self","kind":"self","distanceValue":null,"distanceUnit":null,"area":null}', '<div> <div> Range/Area </div> <div> Self </div> </div>', 'c3931b5d-7b01-4e21-a2df-646d06f47c19'::uuid),
                    ('Components', 'components', '{"text":"V, S, M *","verbal":true,"somatic":true,"material":{"required":true,"description":"a sumac leaf","consumed":false,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S, M *</span> </div> </div>', 'c3931b5d-7b01-4e21-a2df-646d06f47c19'::uuid),
                    ('Duration', 'duration', '{"text":"Concentration 10 Minutes","kind":"timed","value":10,"unit":"minute","concentration":true,"endCondition":null}', '<div> <div>Duration</div> <div> <i>Concentration</i> 10 Minutes </div> </div>', 'c3931b5d-7b01-4e21-a2df-646d06f47c19'::uuid),
                    ('School', 'school', 'Evocation', '<div> <div> School </div> <div> Evocation </div> </div>', 'c3931b5d-7b01-4e21-a2df-646d06f47c19'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"Melee","kind":"attack","attackType":"melee","ability":null}', '<div> <div> Attack/Save </div> <div> <i></i> <span>Melee</span> </div> </div>', 'c3931b5d-7b01-4e21-a2df-646d06f47c19'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Fire","damageTypes":["Fire"]}', '<div> <div> Damage/Effect </div> <div> <i></i> Fire </div> </div>', 'c3931b5d-7b01-4e21-a2df-646d06f47c19'::uuid),
                    ('Description', 'description', '["You evoke a fiery blade in your free hand. The blade is similar in size and shape to a scimitar, and it lasts for the duration. If you let go of the blade, it disappears, but you can evoke it again as a Bonus Action.","As a Magic action, you can make a melee spell attack with the fiery blade. On a hit, the target takes Fire damage equal to 3d6 plus your spellcasting ability modifier.","The flaming blade sheds Bright Light in a 10-foot radius and Dim Light for an additional 10 feet.","Using a Higher-Level Spell Slot. The damage increases by 1d6 for each spell slot level above 2."]', '<div> <p>You evoke a fiery blade in your free hand. The blade is similar in size and shape to a scimitar, and it lasts for the duration. If you let go of the blade, it disappears, but you can evoke it again as a Bonus Action.</p> <p>As a <a>Magic</a> action, you can make a melee spell attack with the fiery blade. On a hit, the target takes Fire damage equal to 3d6 plus your spellcasting ability modifier.</p> <p>The flaming blade sheds <a>Bright Light</a> in a 10-foot radius and <a>Dim Light</a> for an additional 10 feet.</p> <p><strong><em>Using a Higher-Level Spell Slot.</em></strong> The damage increases by 1d6 for each spell slot level above 2.</p> <span>* - (a sumac leaf)</span> </div>', 'c3931b5d-7b01-4e21-a2df-646d06f47c19'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', 'c3931b5d-7b01-4e21-a2df-646d06f47c19'::uuid),
