                    ('Source URL', 'url', 'https://www.dndbeyond.com/spells/2618899-flame-blade', '', 'c3931b5d-7b01-4e21-a2df-646d06f47c19'::uuid),
                    ('Image', 'imageUrl', 'https://www.dndbeyond.com/attachments/2/703/evocation.png', '', 'c3931b5d-7b01-4e21-a2df-646d06f47c19'::uuid),
                    ('Level', 'level', '{"levelNumber":"5","label":"5th"}', '<div> <div> Level </div> <div> 5th </div> </div>', 'db4c6e58-a5ce-49d1-ae08-cd9be84784c1'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Action","kind":"action","value":1,"unit":"action","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Action </div> </div>', 'db4c6e58-a5ce-49d1-ae08-cd9be84784c1'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"60 ft. (10 ft. *)","kind":"distance","distanceValue":60,"distanceUnit":"ft","area":{"shape":null,"value":10,"unit":"ft"}}', '<div> <div> Range/Area </div> <div> 60 ft. <span>(10 ft. <i></i> *)</span> </div> </div>', 'db4c6e58-a5ce-49d1-ae08-cd9be84784c1'::uuid),
                    ('Components', 'components', '{"text":"V, S, M *","verbal":true,"somatic":true,"material":{"required":true,"description":"a pinch of sulfur","consumed":false,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S, M *</span> </div> </div>', 'db4c6e58-a5ce-49d1-ae08-cd9be84784c1'::uuid),
                    ('Duration', 'duration', '{"text":"Instantaneous","kind":"instantaneous","value":null,"unit":null,"concentration":false,"endCondition":null}', '<div> <div>Duration</div> <div> Instantaneous </div> </div>', 'db4c6e58-a5ce-49d1-ae08-cd9be84784c1'::uuid),
                    ('School', 'school', 'Evocation', '<div> <div> School </div> <div> Evocation </div> </div>', 'db4c6e58-a5ce-49d1-ae08-cd9be84784c1'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"DEX Save","kind":"save","attackType":null,"ability":"DEX"}', '<div> <div> Attack/Save </div> <div> <i></i> <span>DEX Save</span> </div> </div>', 'db4c6e58-a5ce-49d1-ae08-cd9be84784c1'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Fire (...)","damageTypes":["Fire"]}', '<div> <div> Damage/Effect </div> <div> <i></i> Fire (...) </div> </div>', 'db4c6e58-a5ce-49d1-ae08-cd9be84784c1'::uuid),
                    ('Description', 'description', '["A vertical column of brilliant fire roars down from above. Each creature in a 10-foot-radius, 40-foot-high Cylinder centered on a point within range makes a Dexterity saving throw, taking 5d6 Fire damage and 5d6 Radiant damage on a failed save or half as much damage on a successful one.","Using a Higher-Level Spell Slot. The Fire damage and the Radiant damage increase by 1d6 for each spell slot level above 5."]', '<div> <p>A vertical column of brilliant fire roars down from above. Each creature in a 10-foot-radius, 40-foot-high <a>Cylinder</a> centered on a point within range makes a Dexterity saving throw, taking 5d6 Fire damage and 5d6 Radiant damage on a failed save or half as much damage on a successful one.</p> <p><strong><em>Using a Higher-Level Spell Slot.</em></strong> The Fire damage and the Radiant damage increase by 1d6 for each spell slot level above 5.</p> <span>* - (a pinch of sulfur)</span> </div>', 'db4c6e58-a5ce-49d1-ae08-cd9be84784c1'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', 'db4c6e58-a5ce-49d1-ae08-cd9be84784c1'::uuid),
