                    ('Image', 'imageUrl', 'https://www.dndbeyond.com/attachments/2/708/conjuration.png', '', '287b1520-1bc1-4367-b8f4-89e31b5b7dbc'::uuid),
                    ('Level', 'level', '{"levelNumber":"3","label":"3rd"}', '<div> <div> Level </div> <div> 3rd </div> </div>', '4d581084-074d-4833-94f3-e336c7220cee'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Action","kind":"action","value":1,"unit":"action","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Action </div> </div>', '4d581084-074d-4833-94f3-e336c7220cee'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"Touch","kind":"touch","distanceValue":null,"distanceUnit":null,"area":null}', '<div> <div> Range/Area </div> <div> Touch </div> </div>', '4d581084-074d-4833-94f3-e336c7220cee'::uuid),
                    ('Components', 'components', '{"text":"V, S, M *","verbal":true,"somatic":true,"material":{"required":true,"description":"a feather","consumed":false,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S, M *</span> </div> </div>', '4d581084-074d-4833-94f3-e336c7220cee'::uuid),
                    ('Duration', 'duration', '{"text":"Concentration 10 Minutes","kind":"timed","value":10,"unit":"minute","concentration":true,"endCondition":null}', '<div> <div>Duration</div> <div> <i>Concentration</i> 10 Minutes </div> </div>', '4d581084-074d-4833-94f3-e336c7220cee'::uuid),
                    ('School', 'school', 'Transmutation', '<div> <div> School </div> <div> Transmutation </div> </div>', '4d581084-074d-4833-94f3-e336c7220cee'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"None","kind":"none","attackType":null,"ability":null}', '<div> <div> Attack/Save </div> <div> <span>None</span> </div> </div>', '4d581084-074d-4833-94f3-e336c7220cee'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Movement","damageTypes":[]}', '<div> <div> Damage/Effect </div> <div> Movement </div> </div>', '4d581084-074d-4833-94f3-e336c7220cee'::uuid),
                    ('Description', 'description', '["You touch a willing creature. For the duration, the target gains a Fly Speed of 60 feet and can hover. When the spell ends, the target falls if it is still aloft unless it can stop the fall.","Using a Higher-Level Spell Slot. You can target one additional creature for each spell slot level above 3."]', '<div> <p>You touch a willing creature. For the duration, the target gains a Fly Speed of 60 feet and can hover. When the spell ends, the target falls if it is still aloft unless it can stop the fall.</p> <p><strong><em>Using a Higher-Level Spell Slot.</em></strong> You can target one additional creature for each spell slot level above 3.</p> <span>* - (a feather)</span> </div>', '4d581084-074d-4833-94f3-e336c7220cee'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', '4d581084-074d-4833-94f3-e336c7220cee'::uuid),
                    ('Spell Tags', 'spellTags', '["Movement"]', '', '4d581084-074d-4833-94f3-e336c7220cee'::uuid),
                    ('Available For', 'availableFor', '["Sorcerer (Legacy)","Warlock (Legacy)","Wizard (Legacy)","Artificer (Legacy)","Sorcerer","Warlock","Wizard","Artificer","Druid - Circle of the Hive (HGtMH1)","Sorcerer - Draconic Sorcery","Warlock - Horned King Patron","Illrigger - Architect of Ruin"]', '', '4d581084-074d-4833-94f3-e336c7220cee'::uuid),
                    ('Source', 'source', 'Player’s Handbook, pg. 276', '', '4d581084-074d-4833-94f3-e336c7220cee'::uuid),
