                    ('Level', 'level', '{"levelNumber":"Cantrip","label":"Cantrip"}', '<div> <div> Level </div> <div> Cantrip </div> </div>', 'de0beea8-9fd1-461b-a3df-1f59811a4eb2'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Action","kind":"action","value":1,"unit":"action","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Action </div> </div>', 'de0beea8-9fd1-461b-a3df-1f59811a4eb2'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"60 ft.","kind":"distance","distanceValue":60,"distanceUnit":"ft","area":null}', '<div> <div> Range/Area </div> <div> 60 ft. </div> </div>', 'de0beea8-9fd1-461b-a3df-1f59811a4eb2'::uuid),
                    ('Components', 'components', '{"text":"V, S","verbal":true,"somatic":true,"material":{"required":false,"description":null,"consumed":null,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S</span> </div> </div>', 'de0beea8-9fd1-461b-a3df-1f59811a4eb2'::uuid),
                    ('Duration', 'duration', '{"text":"Instantaneous","kind":"instantaneous","value":null,"unit":null,"concentration":false,"endCondition":null}', '<div> <div>Duration</div> <div> Instantaneous </div> </div>', 'de0beea8-9fd1-461b-a3df-1f59811a4eb2'::uuid),
                    ('School', 'school', 'Evocation', '<div> <div> School </div> <div> Evocation </div> </div>', 'de0beea8-9fd1-461b-a3df-1f59811a4eb2'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"CON Save","kind":"save","attackType":null,"ability":"CON"}', '<div> <div> Attack/Save </div> <div> <i></i> <span>CON Save</span> </div> </div>', 'de0beea8-9fd1-461b-a3df-1f59811a4eb2'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Cold","damageTypes":["Cold"]}', '<div> <div> Damage/Effect </div> <div> <i></i> Cold </div> </div>', 'de0beea8-9fd1-461b-a3df-1f59811a4eb2'::uuid),
                    ('Description', 'description', '["You cause numbing frost to form on one creature that you can see within range. The target must make a Constitution saving throw. On a failed save, the target takes 1d6 cold damage, and it has disadvantage on the next weapon attack roll it makes before the end of its next turn.","The spell’s damage increases by 1d6 when you reach 5th level (2d6), 11th level (3d6), and 17th level (4d6)."]', '<div> <p>You cause numbing frost to form on one creature that you can see within range. The target must make a Constitution saving throw. On a failed save, the target takes 1d6 cold damage, and it has disadvantage on the next weapon attack roll it makes before the end of its next turn.</p> <p>The spell’s damage increases by 1d6 when you reach 5th level (2d6), 11th level (3d6), and 17th level (4d6).</p> </div>', 'de0beea8-9fd1-461b-a3df-1f59811a4eb2'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', 'de0beea8-9fd1-461b-a3df-1f59811a4eb2'::uuid),
                    ('Spell Tags', 'spellTags', '["Damage","Debuff"]', '', 'de0beea8-9fd1-461b-a3df-1f59811a4eb2'::uuid),
                    ('Available For', 'availableFor', '["Druid (Legacy)","Sorcerer (Legacy)","Warlock (Legacy)","Wizard (Legacy)","Artificer (Legacy)","Druid","Sorcerer","Warlock","Wizard","Artificer"]', '', 'de0beea8-9fd1-461b-a3df-1f59811a4eb2'::uuid),
                    ('Source', 'source', 'Elemental Evil Player''s Companion, pg. 156', '', 'de0beea8-9fd1-461b-a3df-1f59811a4eb2'::uuid),
                    ('Source URL', 'url', 'https://www.dndbeyond.com/spells/2382-frostbite', '', 'de0beea8-9fd1-461b-a3df-1f59811a4eb2'::uuid),
