                    ('Level', 'level', '{"levelNumber":"8","label":"8th"}', '<div> <div> Level </div> <div> 8th </div> </div>', '876c4ecb-7898-4192-9322-c16d7701d679'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Action","kind":"action","value":1,"unit":"action","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Action </div> </div>', '876c4ecb-7898-4192-9322-c16d7701d679'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"Self","kind":"self","distanceValue":null,"distanceUnit":null,"area":null}', '<div> <div> Range/Area </div> <div> Self </div> </div>', '876c4ecb-7898-4192-9322-c16d7701d679'::uuid),
                    ('Components', 'components', '{"text":"V","verbal":true,"somatic":false,"material":{"required":false,"description":null,"consumed":null,"costGp":null}}', '<div> <div> Components </div> <div> <span>V</span> </div> </div>', '876c4ecb-7898-4192-9322-c16d7701d679'::uuid),
                    ('Duration', 'duration', '{"text":"1 Hour","kind":"timed","value":1,"unit":"hour","concentration":false,"endCondition":null}', '<div> <div>Duration</div> <div> 1 Hour </div> </div>', '876c4ecb-7898-4192-9322-c16d7701d679'::uuid),
                    ('School', 'school', 'Enchantment', '<div> <div> School </div> <div> Enchantment </div> </div>', '876c4ecb-7898-4192-9322-c16d7701d679'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"None","kind":"none","attackType":null,"ability":null}', '<div> <div> Attack/Save </div> <div> <span>None</span> </div> </div>', '876c4ecb-7898-4192-9322-c16d7701d679'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Social","damageTypes":[]}', '<div> <div> Damage/Effect </div> <div> Social </div> </div>', '876c4ecb-7898-4192-9322-c16d7701d679'::uuid),
                    ('Description', 'description', '["Until the spell ends, when you make a Charisma check, you can replace the number you roll with a 15. Additionally, no matter what you say, magic that would determine if you are telling the truth indicates that you are being truthful."]', '<div> <p>Until the spell ends, when you make a Charisma check, you can replace the number you roll with a 15. Additionally, no matter what you say, magic that would determine if you are telling the truth indicates that you are being truthful.</p> </div>', '876c4ecb-7898-4192-9322-c16d7701d679'::uuid),
