                    ('Duration', 'duration', '{"text":"24 Hours","kind":"timed","value":24,"unit":"hour","concentration":false,"endCondition":null}', '<div> <div>Duration</div> <div> 24 Hours </div> </div>', '858e8463-4cee-4195-b8b7-dcf3e2677b7c'::uuid),
                    ('School', 'school', 'Conjuration', '<div> <div> School </div> <div> Conjuration </div> </div>', '858e8463-4cee-4195-b8b7-dcf3e2677b7c'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"None","kind":"none","attackType":null,"ability":null}', '<div> <div> Attack/Save </div> <div> <span>None</span> </div> </div>', '858e8463-4cee-4195-b8b7-dcf3e2677b7c'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Healing","damageTypes":[]}', '<div> <div> Damage/Effect </div> <div> Healing </div> </div>', '858e8463-4cee-4195-b8b7-dcf3e2677b7c'::uuid),
                    ('Description', 'description', '["Ten berries appear in your hand and are infused with magic for the duration. A creature can take a Bonus Action to eat one berry. Eating a berry restores 1 Hit Point, and the berry provides enough nourishment to sustain a creature for one day.","Uneaten berries disappear when the spell ends."]', '<div> <p>Ten berries appear in your hand and are infused with magic for the duration. A creature can take a Bonus Action to eat one berry. Eating a berry restores 1 Hit Point, and the berry provides enough nourishment to sustain a creature for one day.</p> <p>Uneaten berries disappear when the spell ends.</p> <span>* - (a sprig of mistletoe)</span> </div>', '858e8463-4cee-4195-b8b7-dcf3e2677b7c'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', '858e8463-4cee-4195-b8b7-dcf3e2677b7c'::uuid),
                    ('Spell Tags', 'spellTags', '["Healing"]', '', '858e8463-4cee-4195-b8b7-dcf3e2677b7c'::uuid),
                    ('Available For', 'availableFor', '["Druid (Legacy)","Ranger (Legacy)","Druid","Ranger","Cleric - Festus Domain","Cleric - Community Domain (HCS)"]', '', '858e8463-4cee-4195-b8b7-dcf3e2677b7c'::uuid),
                    ('Source', 'source', 'Player’s Handbook, pg. 280', '', '858e8463-4cee-4195-b8b7-dcf3e2677b7c'::uuid),
                    ('Source URL', 'url', 'https://www.dndbeyond.com/spells/2618952-goodberry', '', '858e8463-4cee-4195-b8b7-dcf3e2677b7c'::uuid),
                    ('Image', 'imageUrl', 'https://www.dndbeyond.com/attachments/2/708/conjuration.png', '', '858e8463-4cee-4195-b8b7-dcf3e2677b7c'::uuid),
                    ('Level', 'level', '{"levelNumber":"4","label":"4th"}', '', 'fbd19988-d2e9-46fd-b500-910729dc556b'::uuid),
