                    ('Duration', 'duration', '{"text":"1 Minute","kind":"timed","value":1,"unit":"minute","concentration":false,"endCondition":null}', '<div> <div>Duration</div> <div> 1 Minute </div> </div>', '3a94ce8e-df61-47aa-b2a9-708599d98d95'::uuid),
                    ('School', 'school', 'Conjuration', '<div> <div> School </div> <div> Conjuration </div> </div>', '3a94ce8e-df61-47aa-b2a9-708599d98d95'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"DEX Save","kind":"save","attackType":null,"ability":"DEX"}', '<div> <div> Attack/Save </div> <div> <i></i> <span>DEX Save</span> </div> </div>', '3a94ce8e-df61-47aa-b2a9-708599d98d95'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Prone","damageTypes":[]}', '<div> <div> Damage/Effect </div> <div> <i></i> Prone </div> </div>', '3a94ce8e-df61-47aa-b2a9-708599d98d95'::uuid),
                    ('Description', 'description', '["Nonflammable grease covers the ground in a 10-foot square centered on a point within range and turns it into Difficult Terrain for the duration.","When the grease appears, each creature standing in its area must succeed on a Dexterity saving throw or have the Prone condition. A creature that enters the area or ends its turn there must also succeed on that save or fall Prone."]', '<div> <p>Nonflammable grease covers the ground in a 10-foot square centered on a point within range and turns it into <a>Difficult Terrain</a> for the duration.</p> <p>When the grease appears, each creature standing in its area must succeed on a Dexterity saving throw or have the <a>Prone</a> condition. A creature that enters the area or ends its turn there must also succeed on that save or fall Prone.</p> <span>* - (a bit of pork rind or butter)</span> </div>', '3a94ce8e-df61-47aa-b2a9-708599d98d95'::uuid),
