                    ('Level', 'level', '{"levelNumber":"4","label":"4th"}', '<div> <div> Level </div> <div> 4th </div> </div>', 'b6a22563-f88f-4d66-a44e-67344d5099ba'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Action","kind":"action","value":1,"unit":"action","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Action </div> </div>', 'b6a22563-f88f-4d66-a44e-67344d5099ba'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"30 ft.","kind":"distance","distanceValue":30,"distanceUnit":"ft","area":null}', '<div> <div> Range/Area </div> <div> 30 ft. </div> </div>', 'b6a22563-f88f-4d66-a44e-67344d5099ba'::uuid),
                    ('Components', 'components', '{"text":"V","verbal":true,"somatic":false,"material":{"required":false,"description":null,"consumed":null,"costGp":null}}', '<div> <div> Components </div> <div> <span>V</span> </div> </div>', 'b6a22563-f88f-4d66-a44e-67344d5099ba'::uuid),
                    ('Duration', 'duration', '{"text":"8 Hours","kind":"timed","value":8,"unit":"hour","concentration":false,"endCondition":null}', '<div> <div>Duration</div> <div> 8 Hours </div> </div>', 'b6a22563-f88f-4d66-a44e-67344d5099ba'::uuid),
                    ('School', 'school', 'Conjuration', '<div> <div> School </div> <div> Conjuration </div> </div>', 'b6a22563-f88f-4d66-a44e-67344d5099ba'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"DEX Save","kind":"save","attackType":null,"ability":"DEX"}', '<div> <div> Attack/Save </div> <div> <i></i> <span>DEX Save</span> </div> </div>', 'b6a22563-f88f-4d66-a44e-67344d5099ba'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Radiant","damageTypes":["Radiant"]}', '<div> <div> Damage/Effect </div> <div> <i></i> Radiant </div> </div>', 'b6a22563-f88f-4d66-a44e-67344d5099ba'::uuid),
                    ('Description', 'description', '["A Large spectral guardian appears and hovers for the duration in an unoccupied space that you can see within range. The guardian occupies that space and is invulnerable, and it appears in a form appropriate for your deity or pantheon.","Any enemy that moves to a space within 10 feet of the guardian for the first time on a turn or starts its turn there makes a Dexterity saving throw, taking 20 Radiant damage on a failed save or half as much damage on a successful one. The guardian vanishes when it has dealt a total of 60 damage."]', '<div> <p>A Large spectral guardian appears and hovers for the duration in an unoccupied space that you can see within range. The guardian occupies that space and is invulnerable, and it appears in a form appropriate for your deity or pantheon.</p> <p>Any enemy that moves to a space within 10 feet of the guardian for the first time on a turn or starts its turn there makes a Dexterity saving throw, taking 20 Radiant damage on a failed save or half as much damage on a successful one. The guardian vanishes when it has dealt a total of 60 damage.</p> </div>', 'b6a22563-f88f-4d66-a44e-67344d5099ba'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', 'b6a22563-f88f-4d66-a44e-67344d5099ba'::uuid),
                    ('Spell Tags', 'spellTags', '["Summoning","Damage","Control"]', '', 'b6a22563-f88f-4d66-a44e-67344d5099ba'::uuid),
                    ('Available For', 'availableFor', '["Cleric (Legacy)","Cleric","Warlock (Legacy) - The Celestial (Legacy)","Paladin - Oath of the Crown (SCAG)","Paladin - Oath of Devotion","Warlock - Celestial Patron","Cleric - Keeper Domain (BoET)","Warlock - Lantern Patron (OTTG)"]', '', 'b6a22563-f88f-4d66-a44e-67344d5099ba'::uuid),
                    ('Source', 'source', 'Player’s Handbook, pg. 281', '', 'b6a22563-f88f-4d66-a44e-67344d5099ba'::uuid),
                    ('Source URL', 'url', 'https://www.dndbeyond.com/spells/2619135-guardian-of-faith', '', 'b6a22563-f88f-4d66-a44e-67344d5099ba'::uuid),
                    ('Image', 'imageUrl', 'https://www.dndbeyond.com/attachments/2/708/conjuration.png', '', 'b6a22563-f88f-4d66-a44e-67344d5099ba'::uuid),
                    ('Level', 'level', '{"levelNumber":"6","label":"6th"}', '<div> <div> Level </div> <div> 6th </div> </div>', '411e7da8-819c-4c2a-a3dd-1ffc8b551ba8'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Hour","kind":"timed","value":1,"unit":"hour","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Hour </div> </div>', '411e7da8-819c-4c2a-a3dd-1ffc8b551ba8'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"Touch (2,500 ft. 2)","kind":"touch","distanceValue":null,"distanceUnit":null,"area":{"shape":null,"value":2500,"unit":"ft2"}}', '<div> <div> Range/Area </div> <div> Touch <span>(2,500 ft.<sup>2</sup>)</span> </div> </div>', '411e7da8-819c-4c2a-a3dd-1ffc8b551ba8'::uuid),
                    ('Components', 'components', '{"text":"V, S, M *","verbal":true,"somatic":true,"material":{"required":true,"description":"a silver rod worth 10+ GP","consumed":false,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S, M *</span> </div> </div>', '411e7da8-819c-4c2a-a3dd-1ffc8b551ba8'::uuid),
                    ('Duration', 'duration', '{"text":"24 Hours","kind":"timed","value":24,"unit":"hour","concentration":false,"endCondition":null}', '<div> <div>Duration</div> <div> 24 Hours </div> </div>', '411e7da8-819c-4c2a-a3dd-1ffc8b551ba8'::uuid),
                    ('School', 'school', 'Abjuration', '<div> <div> School </div> <div> Abjuration </div> </div>', '411e7da8-819c-4c2a-a3dd-1ffc8b551ba8'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"None","kind":"none","attackType":null,"ability":null}', '<div> <div> Attack/Save </div> <div> <span>None</span> </div> </div>', '411e7da8-819c-4c2a-a3dd-1ffc8b551ba8'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Control (...)","damageTypes":[]}', '<div> <div> Damage/Effect </div> <div> Control (...) </div> </div>', '411e7da8-819c-4c2a-a3dd-1ffc8b551ba8'::uuid),
                    ('Description', 'description', '["You create a ward that protects up to 2,500 square feet of floor space. The warded area can be up to 20 feet tall, and you shape it as one 50-foot square, one hundred 5-foot squares that are contiguous, or twenty-five 10-foot squares that are contiguous.","When you cast this spell, you can specify individuals that are unaffected by the spell’s effects. You can also specify a password that, when spoken aloud within 5 feet of the warded area, makes the speaker immune to its effects.","The spell creates the effects below within the warded area. Dispel Magic has no effect on Guards and Wards itself, but each of the following effects can be dispelled. If all four are dispelled, Guards and Wards ends. If you cast the spell every day for 365 days on the same area, the spell thereafter lasts until all its effects are dispelled.","Corridors. Fog fills all the warded corridors, making them Heavily Obscured . In addition, at each intersection or branching passage offering a choice of direction, there is a 50 percent chance that a creature other than you believes it is going in the opposite direction from the one it chooses.","Doors. All doors in the warded area are magically locked, as if sealed by the Arcane Lock spell. In addition, you can cover up to ten doors with an illusion to make them appear as plain sections of wall.","Stairs. Webs fill all stairs in the warded area from top to bottom, as in the Web spell. These strands regrow in 10 minutes if they are destroyed while Guards and Wards lasts.","Other Spell Effect. Place one of the following magical effects within the warded area:"]', '<div> <p>You create a ward that protects up to 2,500 square feet of floor space. The warded area can be up to 20 feet tall, and you shape it as one 50-foot square, one hundred 5-foot squares that are contiguous, or twenty-five 10-foot squares that are contiguous.</p> <p>When you cast this spell, you can specify individuals that are unaffected by the spell’s effects. You can also specify a password that, when spoken aloud within 5 feet of the warded area, makes the speaker immune to its effects.</p> <p>The spell creates the effects below within the warded area. <a>Dispel Magic</a> has no effect on <em>Guards and Wards</em> itself, but each of the following effects can be dispelled. If all four are dispelled, <em>Guards and Wards</em> ends. If you cast the spell every day for 365 days on the same area, the spell thereafter lasts until all its effects are dispelled.</p> <p><strong><em>Corridors.</em></strong> Fog fills all the warded corridors, making them <a>Heavily Obscured</a>. In addition, at each intersection or branching passage offering a choice of direction, there is a 50 percent chance that a creature other than you believes it is going in the opposite direction from the one it chooses.</p> <p><strong><em>Doors.</em></strong> All doors in the warded area are magically locked, as if sealed by the <a>Arcane Lock</a> spell. In addition, you can cover up to ten doors with an illusion to make them appear as plain sections of wall.</p> <p><strong><em>Stairs.</em></strong> Webs fill all stairs in the warded area from top to bottom, as in the <a>Web</a> spell. These strands regrow in 10 minutes if they are destroyed while <em>Guards and Wards</em> lasts.</p> <p><strong><em>Other Spell Effect.</em></strong> Place one of the following magical effects within the warded area:</p> <ul> <li><a>Dancing Lights</a> in four corridors, with a simple program that the lights repeat as long as <em>Guards and Wards</em> lasts</li> <li><a>Magic Mouth</a> in two locations</li> <li><a>Stinking Cloud</a> in two locations (the vapors return within 10 minutes if dispersed while <em>Guards and Wards</em> lasts)</li> <li><a>Gust of Wind</a> in one corridor or room (the wind blows continuously while the spell lasts)</li> <li><a>Suggestion</a> in one 5-foot square; any creature that enters that square receives the suggestion mentally</li> </ul> <span>* - (a silver rod worth 10+ GP)</span> </div>', '411e7da8-819c-4c2a-a3dd-1ffc8b551ba8'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', '411e7da8-819c-4c2a-a3dd-1ffc8b551ba8'::uuid),
                    ('Spell Tags', 'spellTags', '["Control","Warding"]', '', '411e7da8-819c-4c2a-a3dd-1ffc8b551ba8'::uuid),
                    ('Available For', 'availableFor', '["Bard (Legacy)","Wizard (Legacy)","Bard","Wizard"]', '', '411e7da8-819c-4c2a-a3dd-1ffc8b551ba8'::uuid),
                    ('Source', 'source', 'Player’s Handbook, pg. 282', '', '411e7da8-819c-4c2a-a3dd-1ffc8b551ba8'::uuid),
                    ('Source URL', 'url', 'https://www.dndbeyond.com/spells/2618968-guards-and-wards', '', '411e7da8-819c-4c2a-a3dd-1ffc8b551ba8'::uuid),
                    ('Image', 'imageUrl', 'https://www.dndbeyond.com/attachments/2/707/abjuration.png', '', '411e7da8-819c-4c2a-a3dd-1ffc8b551ba8'::uuid),
                    ('Level', 'level', '{"levelNumber":"Cantrip","label":"Cantrip"}', '<div> <div> Level </div> <div> Cantrip </div> </div>', '9faba2d1-7da9-41bd-b9d7-bfe1b55ce05d'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Action","kind":"action","value":1,"unit":"action","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Action </div> </div>', '9faba2d1-7da9-41bd-b9d7-bfe1b55ce05d'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"Touch","kind":"touch","distanceValue":null,"distanceUnit":null,"area":null}', '<div> <div> Range/Area </div> <div> Touch </div> </div>', '9faba2d1-7da9-41bd-b9d7-bfe1b55ce05d'::uuid),
                    ('Components', 'components', '{"text":"V, S","verbal":true,"somatic":true,"material":{"required":false,"description":null,"consumed":null,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S</span> </div> </div>', '9faba2d1-7da9-41bd-b9d7-bfe1b55ce05d'::uuid),
                    ('Duration', 'duration', '{"text":"Concentration 1 Minute","kind":"timed","value":1,"unit":"minute","concentration":true,"endCondition":null}', '<div> <div>Duration</div> <div> <i>Concentration</i> 1 Minute </div> </div>', '9faba2d1-7da9-41bd-b9d7-bfe1b55ce05d'::uuid);
                """);

