                    ('Range/Area', 'rangeArea', '{"text":"120 ft.","kind":"distance","distanceValue":120,"distanceUnit":"ft","area":null}', '<div> <div> Range/Area </div> <div> 120 ft. </div> </div>', '7721d1a2-d9da-40d3-8d3a-dc9ff0b13d69'::uuid),
                    ('Components', 'components', '{"text":"V, S","verbal":true,"somatic":true,"material":{"required":false,"description":null,"consumed":null,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S</span> </div> </div>', '7721d1a2-d9da-40d3-8d3a-dc9ff0b13d69'::uuid),
                    ('Duration', 'duration', '{"text":"1 Round","kind":"timed","value":1,"unit":"round","concentration":false,"endCondition":null}', '<div> <div>Duration</div> <div> 1 Round </div> </div>', '7721d1a2-d9da-40d3-8d3a-dc9ff0b13d69'::uuid),
                    ('School', 'school', 'Evocation', '<div> <div> School </div> <div> Evocation </div> </div>', '7721d1a2-d9da-40d3-8d3a-dc9ff0b13d69'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"Ranged","kind":"attack","attackType":"ranged","ability":null}', '<div> <div> Attack/Save </div> <div> <i></i> <span>Ranged</span> </div> </div>', '7721d1a2-d9da-40d3-8d3a-dc9ff0b13d69'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Radiant","damageTypes":["Radiant"]}', '<div> <div> Damage/Effect </div> <div> <i></i> Radiant </div> </div>', '7721d1a2-d9da-40d3-8d3a-dc9ff0b13d69'::uuid),
                    ('Description', 'description', '["You hurl a bolt of light toward a creature within range. Make a ranged spell attack against the target. On a hit, it takes 4d6 Radiant damage, and the next attack roll made against it before the end of your next turn has Advantage.","Using a Higher-Level Spell Slot. The damage increases by 1d6 for each spell slot level above 1."]', '<div> <p>You hurl a bolt of light toward a creature within range. Make a ranged spell attack against the target. On a hit, it takes 4d6 Radiant damage, and the next attack roll made against it before the end of your next turn has Advantage.</p> <p><strong><em>Using a Higher-Level Spell Slot.</em></strong> The damage increases by 1d6 for each spell slot level above 1.</p> </div>', '7721d1a2-d9da-40d3-8d3a-dc9ff0b13d69'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', '7721d1a2-d9da-40d3-8d3a-dc9ff0b13d69'::uuid),
