                    ('Available For', 'availableFor', '["Cleric (Legacy)","Cleric","Warlock (Legacy) - The Celestial (Legacy)","Cleric - War Domain","Paladin - Oath of Glory","Warlock - Celestial Patron"]', '', '7721d1a2-d9da-40d3-8d3a-dc9ff0b13d69'::uuid),
                    ('Source', 'source', 'Player’s Handbook, pg. 282', '', '7721d1a2-d9da-40d3-8d3a-dc9ff0b13d69'::uuid),
                    ('Source URL', 'url', 'https://www.dndbeyond.com/spells/2619136-guiding-bolt', '', '7721d1a2-d9da-40d3-8d3a-dc9ff0b13d69'::uuid),
                    ('Image', 'imageUrl', 'https://www.dndbeyond.com/attachments/2/703/evocation.png', '', '7721d1a2-d9da-40d3-8d3a-dc9ff0b13d69'::uuid),
                    ('Level', 'level', '{"levelNumber":"2","label":"2nd"}', '<div> <div> Level </div> <div> 2nd </div> </div>', 'd40f0ac7-4f68-46eb-a503-199982c0263b'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Action","kind":"action","value":1,"unit":"action","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Action </div> </div>', 'd40f0ac7-4f68-46eb-a503-199982c0263b'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"Self","kind":"self","distanceValue":null,"distanceUnit":null,"area":null}', '<div> <div> Range/Area </div> <div> Self </div> </div>', 'd40f0ac7-4f68-46eb-a503-199982c0263b'::uuid),
                    ('Components', 'components', '{"text":"V, S, M *","verbal":true,"somatic":true,"material":{"required":true,"description":"a legume seed","consumed":false,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S, M *</span> </div> </div>', 'd40f0ac7-4f68-46eb-a503-199982c0263b'::uuid),
                    ('Duration', 'duration', '{"text":"Concentration 1 Minute","kind":"timed","value":1,"unit":"minute","concentration":true,"endCondition":null}', '<div> <div>Duration</div> <div> <i>Concentration</i> 1 Minute </div> </div>', 'd40f0ac7-4f68-46eb-a503-199982c0263b'::uuid),
                    ('School', 'school', 'Evocation', '<div> <div> School </div> <div> Evocation </div> </div>', 'd40f0ac7-4f68-46eb-a503-199982c0263b'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"STR Save","kind":"save","attackType":null,"ability":"STR"}', '<div> <div> Attack/Save </div> <div> <i></i> <span>STR Save</span> </div> </div>', 'd40f0ac7-4f68-46eb-a503-199982c0263b'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Control","damageTypes":[]}', '<div> <div> Damage/Effect </div> <div> Control </div> </div>', 'd40f0ac7-4f68-46eb-a503-199982c0263b'::uuid),
                    ('Description', 'description', '["A Line of strong wind 60 feet long and 10 feet wide blasts from you in a direction you choose for the duration. Each creature in the Line must succeed on a Strength saving throw or be pushed 15 feet away from you in a direction following the Line. A creature that ends its turn in the Line must make the same save.","Any creature in the Line must spend 2 feet of movement for every 1 foot it moves when moving closer to you.","The gust disperses gas or vapor, and it extinguishes candles and similar unprotected flames in the area. It causes protected flames, such as those of lanterns, to dance wildly and has a 50 percent chance to extinguish them.","As a Bonus Action on your later turns, you can change the direction in which the Line blasts from you."]', '<div> <p>A <a>Line</a> of strong wind 60 feet long and 10 feet wide blasts from you in a direction you choose for the duration. Each creature in the Line must succeed on a Strength saving throw or be pushed 15 feet away from you in a direction following the Line. A creature that ends its turn in the Line must make the same save.</p> <p>Any creature in the Line must spend 2 feet of movement for every 1 foot it moves when moving closer to you.</p> <p>The gust disperses gas or vapor, and it extinguishes candles and similar unprotected flames in the area. It causes protected flames, such as those of lanterns, to dance wildly and has a 50 percent chance to extinguish them.</p> <p>As a Bonus Action on your later turns, you can change the direction in which the Line blasts from you.</p> <span>* - (a legume seed)</span> </div>', 'd40f0ac7-4f68-46eb-a503-199982c0263b'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', 'd40f0ac7-4f68-46eb-a503-199982c0263b'::uuid),
                    ('Spell Tags', 'spellTags', '["Control"]', '', 'd40f0ac7-4f68-46eb-a503-199982c0263b'::uuid),
                    ('Available For', 'availableFor', '["Druid (Legacy)","Ranger (Legacy)","Sorcerer (Legacy)","Wizard (Legacy)","Druid","Ranger","Sorcerer","Wizard","Cleric - Tempest Domain (PHB)","Druid - Circle of the Sea","Warlock - The Fathomless (TCoE)","Warlock - The Genie (TCoE)"]', '', 'd40f0ac7-4f68-46eb-a503-199982c0263b'::uuid),
                    ('Source', 'source', 'Player’s Handbook, pg. 282', '', 'd40f0ac7-4f68-46eb-a503-199982c0263b'::uuid),
