                    ('Level', 'level', '{"levelNumber":"Cantrip","label":"Cantrip"}', '<div> <div> Level </div> <div> Cantrip </div> </div>', '6ae55a9b-ba8e-437a-87c3-9aaed7d3f3ca'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Action","kind":"action","value":1,"unit":"action","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Action </div> </div>', '6ae55a9b-ba8e-437a-87c3-9aaed7d3f3ca'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"30 ft.","kind":"distance","distanceValue":30,"distanceUnit":"ft","area":null}', '<div> <div> Range/Area </div> <div> 30 ft. </div> </div>', '6ae55a9b-ba8e-437a-87c3-9aaed7d3f3ca'::uuid),
                    ('Components', 'components', '{"text":"V, S","verbal":true,"somatic":true,"material":{"required":false,"description":null,"consumed":null,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S</span> </div> </div>', '6ae55a9b-ba8e-437a-87c3-9aaed7d3f3ca'::uuid),
                    ('Duration', 'duration', '{"text":"Instantaneous","kind":"instantaneous","value":null,"unit":null,"concentration":false,"endCondition":null}', '<div> <div>Duration</div> <div> Instantaneous </div> </div>', '6ae55a9b-ba8e-437a-87c3-9aaed7d3f3ca'::uuid),
                    ('School', 'school', 'Transmutation', '<div> <div> School </div> <div> Transmutation </div> </div>', '6ae55a9b-ba8e-437a-87c3-9aaed7d3f3ca'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"STR Save","kind":"save","attackType":null,"ability":"STR"}', '<div> <div> Attack/Save </div> <div> <i></i> <span>STR Save</span> </div> </div>', '6ae55a9b-ba8e-437a-87c3-9aaed7d3f3ca'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Control","damageTypes":[]}', '<div> <div> Damage/Effect </div> <div> Control </div> </div>', '6ae55a9b-ba8e-437a-87c3-9aaed7d3f3ca'::uuid),
                    ('Description', 'description', '["You seize the air and compel it to create one of the following effects at a point you can see within range:","One Medium or smaller creature that you choose must succeed on a Strength saving throw or be pushed up to 5 feet away from you.","You create a small blast of air capable of moving one object that is neither held nor carried and that weighs no more than 5 pounds. The object is pushed up to 10 feet away from you. It isn’t pushed with enough force to cause damage.","You create a harmless sensory effect using air, such as causing leaves to rustle, wind to slam shutters shut, or your clothing to ripple in a breeze."]', '<div> <p>You seize the air and compel it to create one of the following effects at a point you can see within range:</p> <ul> <li> <p>One Medium or smaller creature that you choose must succeed on a Strength saving throw or be pushed up to 5 feet away from you.</p> </li> <li> <p>You create a small blast of air capable of moving one object that is neither held nor carried and that weighs no more than 5 pounds. The object is pushed up to 10 feet away from you. It isn’t pushed with enough force to cause damage.</p> </li> <li> <p>You create a harmless sensory effect using air, such as causing leaves to rustle, wind to slam shutters shut, or your clothing to ripple in a breeze.</p> </li> </ul> </div>', '6ae55a9b-ba8e-437a-87c3-9aaed7d3f3ca'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', '6ae55a9b-ba8e-437a-87c3-9aaed7d3f3ca'::uuid),
                    ('Spell Tags', 'spellTags', '["Control"]', '', '6ae55a9b-ba8e-437a-87c3-9aaed7d3f3ca'::uuid),
                    ('Available For', 'availableFor', '["Druid (Legacy)","Sorcerer (Legacy)","Wizard (Legacy)","Druid","Sorcerer","Wizard"]', '', '6ae55a9b-ba8e-437a-87c3-9aaed7d3f3ca'::uuid),
