                    ('Casting Time', 'castingTime', '{"text":"1 Bonus Action *","kind":"bonus_action","value":1,"unit":"action","trigger":null,"ritual":false}', '', 'cf61b1f9-beba-401e-b74b-ea096fed3a76'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"Self","kind":"self","distanceValue":null,"distanceUnit":null,"area":null}', '', 'cf61b1f9-beba-401e-b74b-ea096fed3a76'::uuid),
                    ('Components', 'components', '{"text":"V","verbal":true,"somatic":false,"material":{"required":false,"description":null,"consumed":null,"costGp":null}}', '', 'cf61b1f9-beba-401e-b74b-ea096fed3a76'::uuid),
                    ('Duration', 'duration', '{"text":"Instantaneous","kind":"instantaneous","value":null,"unit":null,"concentration":false,"endCondition":null}', '', 'cf61b1f9-beba-401e-b74b-ea096fed3a76'::uuid),
                    ('School', 'school', 'Conjuration', '', 'cf61b1f9-beba-401e-b74b-ea096fed3a76'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"DEX Save","kind":"save","attackType":null,"ability":"DEX"}', '', 'cf61b1f9-beba-401e-b74b-ea096fed3a76'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Piercing","damageTypes":["Piercing"]}', '', 'cf61b1f9-beba-401e-b74b-ea096fed3a76'::uuid),
                    ('Description', 'description', '["As you hit the creature, this spell creates a rain of thorns that sprouts from your Ranged weapon or ammunition. The target of the attack and each creature within 5 feet of it make a Dexterity saving throw, taking 1d10 Piercing damage on a failed save or half as much damage on a successful one.","Using a Higher-Level Spell Slot. The damage increases by 1d10 for each spell slot level above 1."]', '<p>As you hit the creature, this spell creates a rain of thorns that sprouts from your Ranged weapon or ammunition. The target of the attack and each creature within 5 feet of it make a Dexterity saving throw, taking 1d10 Piercing damage on a failed save or half as much damage on a successful one.</p> <p>Using a Higher-Level Spell Slot. The damage increases by 1d10 for each spell slot level above 1.</p>', 'cf61b1f9-beba-401e-b74b-ea096fed3a76'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', 'cf61b1f9-beba-401e-b74b-ea096fed3a76'::uuid),
