                    ('Available For', 'availableFor', '["Ranger"]', '', 'cf61b1f9-beba-401e-b74b-ea096fed3a76'::uuid),
                    ('Source', 'source', 'Player’s Handbook (2024)', '', 'cf61b1f9-beba-401e-b74b-ea096fed3a76'::uuid),
                    ('Source URL', 'url', 'https://www.dndbeyond.com/spells/2618975-hail-of-thorns', '', 'cf61b1f9-beba-401e-b74b-ea096fed3a76'::uuid),
                    ('Image', 'imageUrl', '', '', 'cf61b1f9-beba-401e-b74b-ea096fed3a76'::uuid),
                    ('Level', 'level', '{"levelNumber":"5","label":"5th"}', '<div> <div> Level </div> <div> 5th </div> </div>', '33ce1d7a-11c1-42c5-a14e-7f53e729654e'::uuid),
