                    ('Casting Time', 'castingTime', '{"text":"1 Action","kind":"action","value":1,"unit":"action","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Action </div> </div>', '89c21917-6c2d-4b14-a258-34f294d290ba'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"60 ft.","kind":"distance","distanceValue":60,"distanceUnit":"ft","area":null}', '<div> <div> Range/Area </div> <div> 60 ft. </div> </div>', '89c21917-6c2d-4b14-a258-34f294d290ba'::uuid),
                    ('Components', 'components', '{"text":"V, S","verbal":true,"somatic":true,"material":{"required":false,"description":null,"consumed":null,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S</span> </div> </div>', '89c21917-6c2d-4b14-a258-34f294d290ba'::uuid),
                    ('Duration', 'duration', '{"text":"Instantaneous","kind":"instantaneous","value":null,"unit":null,"concentration":false,"endCondition":null}', '<div> <div>Duration</div> <div> Instantaneous </div> </div>', '89c21917-6c2d-4b14-a258-34f294d290ba'::uuid),
                    ('School', 'school', 'Necromancy', '<div> <div> School </div> <div> Necromancy </div> </div>', '89c21917-6c2d-4b14-a258-34f294d290ba'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"CON Save","kind":"save","attackType":null,"ability":"CON"}', '<div> <div> Attack/Save </div> <div> <i></i> <span>CON Save</span> </div> </div>', '89c21917-6c2d-4b14-a258-34f294d290ba'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Necrotic","damageTypes":["Necrotic"]}', '<div> <div> Damage/Effect </div> <div> <i></i> Necrotic </div> </div>', '89c21917-6c2d-4b14-a258-34f294d290ba'::uuid),
                    ('Description', 'description', '["You unleash virulent magic on a creature you can see within range. The target makes a Constitution saving throw. On a failed save, it takes 14d6 Necrotic damage, and its Hit Point maximum is reduced by an amount equal to the Necrotic damage it took. On a successful save, it takes half as much damage only. This spell can’t reduce a target’s Hit Point maximum below 1."]', '<div> <p>You unleash virulent magic on a creature you can see within range. The target makes a Constitution saving throw. On a failed save, it takes 14d6 Necrotic damage, and its Hit Point maximum is reduced by an amount equal to the Necrotic damage it took. On a successful save, it takes half as much damage only. This spell can’t reduce a target’s Hit Point maximum below 1.</p> </div>', '89c21917-6c2d-4b14-a258-34f294d290ba'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', '89c21917-6c2d-4b14-a258-34f294d290ba'::uuid),
