                    ('Available For', 'availableFor', '["Cleric (Legacy)","Cleric"]', '', '89c21917-6c2d-4b14-a258-34f294d290ba'::uuid),
                    ('Source', 'source', 'Player’s Handbook, pg. 283', '', '89c21917-6c2d-4b14-a258-34f294d290ba'::uuid),
                    ('Source URL', 'url', 'https://www.dndbeyond.com/spells/2618977-harm', '', '89c21917-6c2d-4b14-a258-34f294d290ba'::uuid),
                    ('Image', 'imageUrl', 'https://www.dndbeyond.com/attachments/2/720/necromancy.png', '', '89c21917-6c2d-4b14-a258-34f294d290ba'::uuid),
