                    ('Components', 'components', '{"text":"V, S","verbal":true,"somatic":true,"material":{"required":false,"description":null,"consumed":null,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S</span> </div> </div>', '9694b953-1a90-4f58-97f1-60023b7978fe'::uuid),
                    ('Duration', 'duration', '{"text":"Instantaneous","kind":"instantaneous","value":null,"unit":null,"concentration":false,"endCondition":null}', '<div> <div>Duration</div> <div> Instantaneous </div> </div>', '9694b953-1a90-4f58-97f1-60023b7978fe'::uuid),
                    ('School', 'school', 'Abjuration', '<div> <div> School </div> <div> Abjuration </div> </div>', '9694b953-1a90-4f58-97f1-60023b7978fe'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"None","kind":"none","attackType":null,"ability":null}', '<div> <div> Attack/Save </div> <div> <span>None</span> </div> </div>', '9694b953-1a90-4f58-97f1-60023b7978fe'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Blinded (...)","damageTypes":[]}', '<div> <div> Damage/Effect </div> <div> <i></i> Blinded (...) </div> </div>', '9694b953-1a90-4f58-97f1-60023b7978fe'::uuid),
                    ('Description', 'description', '["Choose a creature that you can see within range. Positive energy washes through the target, restoring 70 Hit Points. This spell also ends the Blinded , Deafened , and Poisoned conditions on the target.","Using a Higher-Level Spell Slot. The healing increases by 10 for each spell slot level above 6."]', '<div> <p>Choose a creature that you can see within range. Positive energy washes through the target, restoring 70 Hit Points. This spell also ends the <a>Blinded</a>, <a>Deafened</a>, and <a>Poisoned</a> conditions on the target.</p> <p><strong><em>Using a Higher-Level Spell Slot.</em></strong> The healing increases by 10 for each spell slot level above 6.</p> </div>', '9694b953-1a90-4f58-97f1-60023b7978fe'::uuid),
