                    ('Casting Time', 'castingTime', '{"text":"1 Bonus Action","kind":"bonus_action","value":1,"unit":"action","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Bonus Action </div> </div>', '9be59d72-580b-476f-a240-d488111d1142'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"60 ft.","kind":"distance","distanceValue":60,"distanceUnit":"ft","area":null}', '<div> <div> Range/Area </div> <div> 60 ft. </div> </div>', '9be59d72-580b-476f-a240-d488111d1142'::uuid),
                    ('Components', 'components', '{"text":"V","verbal":true,"somatic":false,"material":{"required":false,"description":null,"consumed":null,"costGp":null}}', '<div> <div> Components </div> <div> <span>V</span> </div> </div>', '9be59d72-580b-476f-a240-d488111d1142'::uuid),
                    ('Duration', 'duration', '{"text":"Instantaneous","kind":"instantaneous","value":null,"unit":null,"concentration":false,"endCondition":null}', '<div> <div>Duration</div> <div> Instantaneous </div> </div>', '9be59d72-580b-476f-a240-d488111d1142'::uuid),
                    ('School', 'school', 'Abjuration', '<div> <div> School </div> <div> Abjuration </div> </div>', '9be59d72-580b-476f-a240-d488111d1142'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"None","kind":"none","attackType":null,"ability":null}', '<div> <div> Attack/Save </div> <div> <span>None</span> </div> </div>', '9be59d72-580b-476f-a240-d488111d1142'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Healing","damageTypes":[]}', '<div> <div> Damage/Effect </div> <div> Healing </div> </div>', '9be59d72-580b-476f-a240-d488111d1142'::uuid),
                    ('Description', 'description', '["A creature of your choice that you can see within range regains Hit Points equal to 2d4 plus your spellcasting ability modifier.","Using a Higher-Level Spell Slot. The healing increases by 2d4 for each spell slot level above 1."]', '<div> <p>A creature of your choice that you can see within range regains Hit Points equal to 2d4 plus your spellcasting ability modifier.</p> <p><strong><em>Using a Higher-Level Spell Slot.</em></strong> The healing increases by 2d4 for each spell slot level above 1.</p> </div>', '9be59d72-580b-476f-a240-d488111d1142'::uuid),
