                    ('Level', 'level', '{"levelNumber":"2","label":"2nd"}', '<div> <div> Level </div> <div> 2nd </div> </div>', '30ad57b9-8c8a-44e2-b31d-c0578ca12b2d'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Action","kind":"action","value":1,"unit":"action","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Action </div> </div>', '30ad57b9-8c8a-44e2-b31d-c0578ca12b2d'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"60 ft.","kind":"distance","distanceValue":60,"distanceUnit":"ft","area":null}', '<div> <div> Range/Area </div> <div> 60 ft. </div> </div>', '30ad57b9-8c8a-44e2-b31d-c0578ca12b2d'::uuid),
                    ('Components', 'components', '{"text":"V, S, M *","verbal":true,"somatic":true,"material":{"required":true,"description":"a piece of iron and a flame","consumed":false,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S, M *</span> </div> </div>', '30ad57b9-8c8a-44e2-b31d-c0578ca12b2d'::uuid),
                    ('Duration', 'duration', '{"text":"Concentration 1 Minute","kind":"timed","value":1,"unit":"minute","concentration":true,"endCondition":null}', '<div> <div>Duration</div> <div> <i>Concentration</i> 1 Minute </div> </div>', '30ad57b9-8c8a-44e2-b31d-c0578ca12b2d'::uuid),
                    ('School', 'school', 'Transmutation', '<div> <div> School </div> <div> Transmutation </div> </div>', '30ad57b9-8c8a-44e2-b31d-c0578ca12b2d'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"CON Save","kind":"save","attackType":null,"ability":"CON"}', '<div> <div> Attack/Save </div> <div> <i></i> <span>CON Save</span> </div> </div>', '30ad57b9-8c8a-44e2-b31d-c0578ca12b2d'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Fire","damageTypes":["Fire"]}', '<div> <div> Damage/Effect </div> <div> <i></i> Fire </div> </div>', '30ad57b9-8c8a-44e2-b31d-c0578ca12b2d'::uuid),
                    ('Description', 'description', '["Choose a manufactured metal object, such as a metal weapon or a suit of Heavy or Medium metal armor, that you can see within range. You cause the object to glow red-hot. Any creature in physical contact with the object takes 2d8 Fire damage when you cast the spell. Until the spell ends, you can take a Bonus Action on each of your later turns to deal this damage again if the object is within range.","If a creature is holding or wearing the object and takes the damage from it, the creature must succeed on a Constitution saving throw or drop the object if it can. If it doesn’t drop the object, it has Disadvantage on attack rolls and ability checks until the start of your next turn.","Using a Higher-Level Spell Slot. The damage increases by 1d8 for each spell slot level above 2."]', '<div> <p>Choose a manufactured metal object, such as a metal weapon or a suit of Heavy or Medium metal armor, that you can see within range. You cause the object to glow red-hot. Any creature in physical contact with the object takes 2d8 Fire damage when you cast the spell. Until the spell ends, you can take a Bonus Action on each of your later turns to deal this damage again if the object is within range.</p> <p>If a creature is holding or wearing the object and takes the damage from it, the creature must succeed on a Constitution saving throw or drop the object if it can. If it doesn’t drop the object, it has Disadvantage on attack rolls and ability checks until the start of your next turn.</p> <p><strong><em>Using a Higher-Level Spell Slot.</em></strong> The damage increases by 1d8 for each spell slot level above 2.</p> <span>* - (a piece of iron and a flame)</span> </div>', '30ad57b9-8c8a-44e2-b31d-c0578ca12b2d'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', '30ad57b9-8c8a-44e2-b31d-c0578ca12b2d'::uuid),
