                    ('Casting Time', 'castingTime', '{"text":"1 Reaction *","kind":"reaction","value":1,"unit":"action","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Reaction * </div> </div>', 'a0b88b99-cb6c-4f75-bab7-d56fdf587eea'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"60 ft.","kind":"distance","distanceValue":60,"distanceUnit":"ft","area":null}', '<div> <div> Range/Area </div> <div> 60 ft. </div> </div>', 'a0b88b99-cb6c-4f75-bab7-d56fdf587eea'::uuid),
                    ('Components', 'components', '{"text":"V, S","verbal":true,"somatic":true,"material":{"required":false,"description":null,"consumed":null,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S</span> </div> </div>', 'a0b88b99-cb6c-4f75-bab7-d56fdf587eea'::uuid),
                    ('Duration', 'duration', '{"text":"Instantaneous","kind":"instantaneous","value":null,"unit":null,"concentration":false,"endCondition":null}', '<div> <div>Duration</div> <div> Instantaneous </div> </div>', 'a0b88b99-cb6c-4f75-bab7-d56fdf587eea'::uuid),
                    ('School', 'school', 'Evocation', '<div> <div> School </div> <div> Evocation </div> </div>', 'a0b88b99-cb6c-4f75-bab7-d56fdf587eea'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"DEX Save","kind":"save","attackType":null,"ability":"DEX"}', '<div> <div> Attack/Save </div> <div> <i></i> <span>DEX Save</span> </div> </div>', 'a0b88b99-cb6c-4f75-bab7-d56fdf587eea'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Fire","damageTypes":["Fire"]}', '<div> <div> Damage/Effect </div> <div> <i></i> Fire </div> </div>', 'a0b88b99-cb6c-4f75-bab7-d56fdf587eea'::uuid),
                    ('Description', 'description', '["The creature that damaged you is momentarily surrounded by green flames. It makes a Dexterity saving throw, taking 2d10 Fire damage on a failed save or half as much damage on a successful one.","Using a Higher-Level Spell Slot. The damage increases by 1d10 for each spell slot level above 1."]', '<div> <p>The creature that damaged you is momentarily surrounded by green flames. It makes a Dexterity saving throw, taking 2d10 Fire damage on a failed save or half as much damage on a successful one.</p> <p><strong><em>Using a Higher-Level Spell Slot.</em></strong> The damage increases by 1d10 for each spell slot level above 1.</p> <span>* - which you take in response to taking damage from a creature that you can see within 60 feet of yourself</span> </div>', 'a0b88b99-cb6c-4f75-bab7-d56fdf587eea'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '* - which you take in response to taking damage from a creature that you can see within 60 feet of yourself', '', 'a0b88b99-cb6c-4f75-bab7-d56fdf587eea'::uuid);
                """);

            migrationBuilder.Sql("""
                INSERT INTO "SpellComponents" ("Label", "Key", "Value", "Html", "SpellId") VALUES
                    ('Spell Tags', 'spellTags', '["Damage"]', '', 'a0b88b99-cb6c-4f75-bab7-d56fdf587eea'::uuid),
                    ('Available For', 'availableFor', '["Warlock (Legacy)","Warlock","Paladin - Oathbreaker (DMG)","Illrigger - Architect of Ruin"]', '', 'a0b88b99-cb6c-4f75-bab7-d56fdf587eea'::uuid),
                    ('Source', 'source', 'Player’s Handbook, pg. 284', '', 'a0b88b99-cb6c-4f75-bab7-d56fdf587eea'::uuid),
                    ('Source URL', 'url', 'https://www.dndbeyond.com/spells/2619149-hellish-rebuke', '', 'a0b88b99-cb6c-4f75-bab7-d56fdf587eea'::uuid),
                    ('Image', 'imageUrl', 'https://www.dndbeyond.com/attachments/2/703/evocation.png', '', 'a0b88b99-cb6c-4f75-bab7-d56fdf587eea'::uuid),
                    ('Level', 'level', '{"levelNumber":"6","label":"6th"}', '<div> <div> Level </div> <div> 6th </div> </div>', 'd7ad6308-045b-4dcc-bfed-d2ef570eb8d3'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"10 Minutes","kind":"timed","value":10,"unit":"minute","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 10 Minutes </div> </div>', 'd7ad6308-045b-4dcc-bfed-d2ef570eb8d3'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"Self (10 ft.)","kind":"self","distanceValue":null,"distanceUnit":null,"area":{"shape":null,"value":10,"unit":"ft"}}', '<div> <div> Range/Area </div> <div> Self <span>(10 ft. <i></i>)</span> </div> </div>', 'd7ad6308-045b-4dcc-bfed-d2ef570eb8d3'::uuid),
                    ('Components', 'components', '{"text":"V, S, M *","verbal":true,"somatic":true,"material":{"required":true,"description":"a gem-encrusted bowl worth 1,000+ GP, which the spell consumes","consumed":true,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S, M *</span> </div> </div>', 'd7ad6308-045b-4dcc-bfed-d2ef570eb8d3'::uuid),
                    ('Duration', 'duration', '{"text":"Instantaneous","kind":"instantaneous","value":null,"unit":null,"concentration":false,"endCondition":null}', '<div> <div>Duration</div> <div> Instantaneous </div> </div>', 'd7ad6308-045b-4dcc-bfed-d2ef570eb8d3'::uuid),
                    ('School', 'school', 'Conjuration', '<div> <div> School </div> <div> Conjuration </div> </div>', 'd7ad6308-045b-4dcc-bfed-d2ef570eb8d3'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"None","kind":"none","attackType":null,"ability":null}', '<div> <div> Attack/Save </div> <div> <span>None</span> </div> </div>', 'd7ad6308-045b-4dcc-bfed-d2ef570eb8d3'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Poisoned (...)","damageTypes":[]}', '<div> <div> Damage/Effect </div> <div> <i></i> Poisoned (...) </div> </div>', 'd7ad6308-045b-4dcc-bfed-d2ef570eb8d3'::uuid),
                    ('Description', 'description', '["You conjure a feast that appears on a surface in an unoccupied 10-foot Cube next to you. The feast takes 1 hour to consume and disappears at the end of that time, and the beneficial effects don’t set in until this hour is over. Up to twelve creatures can partake of the feast.","A creature that partakes gains several benefits, which last for 24 hours. The creature has Resistance to Poison damage, and it has Immunity to the Frightened and Poisoned conditions. Its Hit Point maximum also increases by 2d10, and it gains the same number of Hit Points."]', '<div> <p>You conjure a feast that appears on a surface in an unoccupied 10-foot <a>Cube</a> next to you. The feast takes 1 hour to consume and disappears at the end of that time, and the beneficial effects don’t set in until this hour is over. Up to twelve creatures can partake of the feast.</p> <p>A creature that partakes gains several benefits, which last for 24 hours. The creature has Resistance to Poison damage, and it has Immunity to the <a>Frightened</a> and <a>Poisoned</a> conditions. Its Hit Point maximum also increases by 2d10, and it gains the same number of Hit Points.</p> <span>* - (a gem-encrusted bowl worth 1,000+ GP, which the spell consumes)</span> </div>', 'd7ad6308-045b-4dcc-bfed-d2ef570eb8d3'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', 'd7ad6308-045b-4dcc-bfed-d2ef570eb8d3'::uuid),
                    ('Spell Tags', 'spellTags', '["Buff","Social"]', '', 'd7ad6308-045b-4dcc-bfed-d2ef570eb8d3'::uuid),
                    ('Available For', 'availableFor', '["Bard (Legacy)","Cleric (Legacy)","Druid (Legacy)","Bard","Cleric","Druid"]', '', 'd7ad6308-045b-4dcc-bfed-d2ef570eb8d3'::uuid),
                    ('Source', 'source', 'Player’s Handbook, pg. 284', '', 'd7ad6308-045b-4dcc-bfed-d2ef570eb8d3'::uuid),
                    ('Source URL', 'url', 'https://www.dndbeyond.com/spells/2618983-heroes-feast', '', 'd7ad6308-045b-4dcc-bfed-d2ef570eb8d3'::uuid),
                    ('Image', 'imageUrl', 'https://www.dndbeyond.com/attachments/2/708/conjuration.png', '', 'd7ad6308-045b-4dcc-bfed-d2ef570eb8d3'::uuid),
                    ('Level', 'level', '{"levelNumber":"1","label":"1st"}', '<div> <div> Level </div> <div> 1st </div> </div>', '992e032c-b810-49d1-8f3a-5e0d81e45582'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Action","kind":"action","value":1,"unit":"action","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Action </div> </div>', '992e032c-b810-49d1-8f3a-5e0d81e45582'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"Touch","kind":"touch","distanceValue":null,"distanceUnit":null,"area":null}', '<div> <div> Range/Area </div> <div> Touch </div> </div>', '992e032c-b810-49d1-8f3a-5e0d81e45582'::uuid),
                    ('Components', 'components', '{"text":"V, S","verbal":true,"somatic":true,"material":{"required":false,"description":null,"consumed":null,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S</span> </div> </div>', '992e032c-b810-49d1-8f3a-5e0d81e45582'::uuid),
                    ('Duration', 'duration', '{"text":"Concentration 1 Minute","kind":"timed","value":1,"unit":"minute","concentration":true,"endCondition":null}', '<div> <div>Duration</div> <div> <i>Concentration</i> 1 Minute </div> </div>', '992e032c-b810-49d1-8f3a-5e0d81e45582'::uuid),
                    ('School', 'school', 'Enchantment', '<div> <div> School </div> <div> Enchantment </div> </div>', '992e032c-b810-49d1-8f3a-5e0d81e45582'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"None","kind":"none","attackType":null,"ability":null}', '<div> <div> Attack/Save </div> <div> <span>None</span> </div> </div>', '992e032c-b810-49d1-8f3a-5e0d81e45582'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Frightened","damageTypes":[]}', '<div> <div> Damage/Effect </div> <div> <i></i> Frightened </div> </div>', '992e032c-b810-49d1-8f3a-5e0d81e45582'::uuid),
                    ('Description', 'description', '["A willing creature you touch is imbued with bravery. Until the spell ends, the creature is immune to the Frightened condition and gains Temporary Hit Points equal to your spellcasting ability modifier at the start of each of its turns.","Using a Higher-Level Spell Slot. You can target one additional creature for each spell slot level above 1."]', '<div> <p>A willing creature you touch is imbued with bravery. Until the spell ends, the creature is immune to the <a>Frightened</a> condition and gains <a>Temporary Hit Points</a> equal to your spellcasting ability modifier at the start of each of its turns.</p> <p><strong><em>Using a Higher-Level Spell Slot.</em></strong> You can target one additional creature for each spell slot level above 1.</p> </div>', '992e032c-b810-49d1-8f3a-5e0d81e45582'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', '992e032c-b810-49d1-8f3a-5e0d81e45582'::uuid),
                    ('Spell Tags', 'spellTags', '["Buff"]', '', '992e032c-b810-49d1-8f3a-5e0d81e45582'::uuid),
                    ('Available For', 'availableFor', '["Bard (Legacy)","Paladin (Legacy)","Bard","Paladin","Warlock (Legacy) - The Parasite","Cleric - Order Domain (TCoE)","Cleric - Peace Domain (TCoE)","Paladin - Oath of Glory","Paladin - Oath of the Harvest (HGtMH1)","Warlock - The Parasite","Cleric - Community Domain (HCS)"]', '', '992e032c-b810-49d1-8f3a-5e0d81e45582'::uuid),
                    ('Source', 'source', 'Player’s Handbook, pg. 285', '', '992e032c-b810-49d1-8f3a-5e0d81e45582'::uuid),
                    ('Source URL', 'url', 'https://www.dndbeyond.com/spells/2619151-heroism', '', '992e032c-b810-49d1-8f3a-5e0d81e45582'::uuid),
                    ('Image', 'imageUrl', 'https://www.dndbeyond.com/attachments/2/702/enchantment.png', '', '992e032c-b810-49d1-8f3a-5e0d81e45582'::uuid),
                    ('Level', 'level', '{"levelNumber":"1","label":"1st"}', '<div> <div> Level </div> <div> 1st </div> </div>', '5e781b58-40d3-40fb-afe6-7a8186283651'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Bonus Action","kind":"bonus_action","value":1,"unit":"action","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Bonus Action </div> </div>', '5e781b58-40d3-40fb-afe6-7a8186283651'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"90 ft.","kind":"distance","distanceValue":90,"distanceUnit":"ft","area":null}', '<div> <div> Range/Area </div> <div> 90 ft. </div> </div>', '5e781b58-40d3-40fb-afe6-7a8186283651'::uuid),
                    ('Components', 'components', '{"text":"V, S, M *","verbal":true,"somatic":true,"material":{"required":true,"description":"the petrified eye of a newt","consumed":false,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S, M *</span> </div> </div>', '5e781b58-40d3-40fb-afe6-7a8186283651'::uuid),
                    ('Duration', 'duration', '{"text":"Concentration 1 Hour","kind":"timed","value":1,"unit":"hour","concentration":true,"endCondition":null}', '<div> <div>Duration</div> <div> <i>Concentration</i> 1 Hour </div> </div>', '5e781b58-40d3-40fb-afe6-7a8186283651'::uuid),
                    ('School', 'school', 'Enchantment', '<div> <div> School </div> <div> Enchantment </div> </div>', '5e781b58-40d3-40fb-afe6-7a8186283651'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"None","kind":"none","attackType":null,"ability":null}', '<div> <div> Attack/Save </div> <div> <span>None</span> </div> </div>', '5e781b58-40d3-40fb-afe6-7a8186283651'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Necrotic","damageTypes":["Necrotic"]}', '<div> <div> Damage/Effect </div> <div> <i></i> Necrotic </div> </div>', '5e781b58-40d3-40fb-afe6-7a8186283651'::uuid),
                    ('Description', 'description', '["You place a curse on a creature that you can see within range. Until the spell ends, you deal an extra 1d6 Necrotic damage to the target whenever you hit it with an attack roll. Also, choose one ability when you cast the spell. The target has Disadvantage on ability checks made with the chosen ability.","If the target drops to 0 Hit Points before this spell ends, you can take a Bonus Action on a later turn to curse a new creature.","Using a Higher-Level Spell Slot. Your Concentration can last longer with a spell slot of level 2 (up to 4 hours), 3–4 (up to 8 hours), or 5+ (24 hours)."]', '<div> <p>You place a <a>curse</a> on a creature that you can see within range. Until the spell ends, you deal an extra 1d6 Necrotic damage to the target whenever you hit it with an attack roll. Also, choose one ability when you cast the spell. The target has Disadvantage on ability checks made with the chosen ability.</p> <p>If the target drops to 0 Hit Points before this spell ends, you can take a Bonus Action on a later turn to curse a new creature.</p> <p><strong><em>Using a Higher-Level Spell Slot.</em></strong> Your <a>Concentration</a> can last longer with a spell slot of level 2 (up to 4 hours), 3–4 (up to 8 hours), or 5+ (24 hours).</p> <span>* - (the petrified eye of a newt)</span> </div>', '5e781b58-40d3-40fb-afe6-7a8186283651'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', '5e781b58-40d3-40fb-afe6-7a8186283651'::uuid),
                    ('Spell Tags', 'spellTags', '["Damage","Debuff"]', '', '5e781b58-40d3-40fb-afe6-7a8186283651'::uuid),
                    ('Available For', 'availableFor', '["Warlock (Legacy)","Warlock"]', '', '5e781b58-40d3-40fb-afe6-7a8186283651'::uuid),
                    ('Source', 'source', 'Player’s Handbook, pg. 285', '', '5e781b58-40d3-40fb-afe6-7a8186283651'::uuid),
                    ('Source URL', 'url', 'https://www.dndbeyond.com/spells/2618988-hex', '', '5e781b58-40d3-40fb-afe6-7a8186283651'::uuid),
                    ('Image', 'imageUrl', 'https://www.dndbeyond.com/attachments/2/702/enchantment.png', '', '5e781b58-40d3-40fb-afe6-7a8186283651'::uuid),
                    ('Level', 'level', '{"levelNumber":"1","label":"1st"}', '<div> <div> Level </div> <div> 1st </div> </div>', '8b365e70-31e9-4d2e-8e18-1d1fe3767cc8'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Action","kind":"action","value":1,"unit":"action","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Action </div> </div>', '8b365e70-31e9-4d2e-8e18-1d1fe3767cc8'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"30 ft.","kind":"distance","distanceValue":30,"distanceUnit":"ft","area":null}', '<div> <div> Range/Area </div> <div> 30 ft. </div> </div>', '8b365e70-31e9-4d2e-8e18-1d1fe3767cc8'::uuid),
                    ('Components', 'components', '{"text":"V, S, M *","verbal":true,"somatic":true,"material":{"required":true,"description":"tiny tarts and a feather that is waved in the air","consumed":false,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S, M *</span> </div> </div>', '8b365e70-31e9-4d2e-8e18-1d1fe3767cc8'::uuid),
                    ('Duration', 'duration', '{"text":"Concentration 1 Minute","kind":"timed","value":1,"unit":"minute","concentration":true,"endCondition":null}', '<div> <div>Duration</div> <div> <i>Concentration</i> 1 Minute </div> </div>', '8b365e70-31e9-4d2e-8e18-1d1fe3767cc8'::uuid),
                    ('School', 'school', 'Enchantment', '<div> <div> School </div> <div> Enchantment </div> </div>', '8b365e70-31e9-4d2e-8e18-1d1fe3767cc8'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"WIS Save","kind":"save","attackType":null,"ability":"WIS"}', '<div> <div> Attack/Save </div> <div> <i></i> <span>WIS Save</span> </div> </div>', '8b365e70-31e9-4d2e-8e18-1d1fe3767cc8'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Prone (...)","damageTypes":[]}', '<div> <div> Damage/Effect </div> <div> <i></i> Prone (...) </div> </div>', '8b365e70-31e9-4d2e-8e18-1d1fe3767cc8'::uuid),
                    ('Description', 'description', '["A creature of your choice that you can see within range perceives everything as hilariously funny and falls into fits of laughter if this spell affects it. The target must succeed on a Wisdom saving throw or fall prone , becoming incapacitated and unable to stand up for the duration. A creature with an Intelligence score of 4 or less isn''t affected.","At the end of each of its turns, and each time it takes damage, the target can make another Wisdom saving throw. The target has advantage on the saving throw if it''s triggered by damage. On a success, the spell ends."]', '<div> <p>A creature of your choice that you can see within range perceives everything as hilariously funny and falls into fits of laughter if this spell affects it. The target must succeed on a Wisdom saving throw or fall <a>prone</a>, becoming <a>incapacitated</a> and unable to stand up for the duration. A creature with an Intelligence score of 4 or less isn''t affected.</p> <p>At the end of each of its turns, and each time it takes damage, the target can make another Wisdom saving throw. The target has advantage on the saving throw if it''s triggered by damage. On a success, the spell ends.</p> <span>* - (tiny tarts and a feather that is waved in the air)</span> </div>', '8b365e70-31e9-4d2e-8e18-1d1fe3767cc8'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', '8b365e70-31e9-4d2e-8e18-1d1fe3767cc8'::uuid),
                    ('Spell Tags', 'spellTags', '["Control","Debuff"]', '', '8b365e70-31e9-4d2e-8e18-1d1fe3767cc8'::uuid),
                    ('Available For', 'availableFor', '["Bard (Legacy)","Wizard (Legacy)","Warlock (Legacy) - The Great Old One (Legacy)","Warlock (Legacy) - The Great Fool (2014)"]', '', '8b365e70-31e9-4d2e-8e18-1d1fe3767cc8'::uuid),
                    ('Source', 'source', 'Basic Rules (2014)', '', '8b365e70-31e9-4d2e-8e18-1d1fe3767cc8'::uuid),
                    ('Source URL', 'url', 'https://www.dndbeyond.com/spells/2145-hideous-laughter', '', '8b365e70-31e9-4d2e-8e18-1d1fe3767cc8'::uuid),
                    ('Image', 'imageUrl', 'https://www.dndbeyond.com/attachments/2/702/enchantment.png', '', '8b365e70-31e9-4d2e-8e18-1d1fe3767cc8'::uuid),
                    ('Level', 'level', '{"levelNumber":"5","label":"5th"}', '<div> <div> Level </div> <div> 5th </div> </div>', '53e038a9-f8e6-436e-8eef-91c3f1bf4032'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Action","kind":"action","value":1,"unit":"action","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Action </div> </div>', '53e038a9-f8e6-436e-8eef-91c3f1bf4032'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"90 ft.","kind":"distance","distanceValue":90,"distanceUnit":"ft","area":null}', '<div> <div> Range/Area </div> <div> 90 ft. </div> </div>', '53e038a9-f8e6-436e-8eef-91c3f1bf4032'::uuid),
                    ('Components', 'components', '{"text":"V, S, M *","verbal":true,"somatic":true,"material":{"required":true,"description":"a straight piece of iron","consumed":false,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S, M *</span> </div> </div>', '53e038a9-f8e6-436e-8eef-91c3f1bf4032'::uuid),
                    ('Duration', 'duration', '{"text":"Concentration 1 Minute","kind":"timed","value":1,"unit":"minute","concentration":true,"endCondition":null}', '<div> <div>Duration</div> <div> <i>Concentration</i> 1 Minute </div> </div>', '53e038a9-f8e6-436e-8eef-91c3f1bf4032'::uuid),
                    ('School', 'school', 'Enchantment', '<div> <div> School </div> <div> Enchantment </div> </div>', '53e038a9-f8e6-436e-8eef-91c3f1bf4032'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"WIS Save","kind":"save","attackType":null,"ability":"WIS"}', '<div> <div> Attack/Save </div> <div> <i></i> <span>WIS Save</span> </div> </div>', '53e038a9-f8e6-436e-8eef-91c3f1bf4032'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Paralyzed","damageTypes":[]}', '<div> <div> Damage/Effect </div> <div> <i></i> Paralyzed </div> </div>', '53e038a9-f8e6-436e-8eef-91c3f1bf4032'::uuid),
                    ('Description', 'description', '["Choose a creature that you can see within range. The target must succeed on a Wisdom saving throw or have the Paralyzed condition for the duration. At the end of each of its turns, the target repeats the save, ending the spell on itself on a success.","Using a Higher-Level Spell Slot. You can target one additional creature for each spell slot level above 5."]', '<div> <p>Choose a creature that you can see within range. The target must succeed on a Wisdom saving throw or have the <a>Paralyzed</a> condition for the duration. At the end of each of its turns, the target repeats the save, ending the spell on itself on a success.</p> <p><strong><em>Using a Higher-Level Spell Slot.</em></strong> You can target one additional creature for each spell slot level above 5.</p> <span>* - (a straight piece of iron)</span> </div>', '53e038a9-f8e6-436e-8eef-91c3f1bf4032'::uuid),
