                    ('Range/Area', 'rangeArea', '{"text":"60 ft.","kind":"distance","distanceValue":60,"distanceUnit":"ft","area":null}', '<div> <div> Range/Area </div> <div> 60 ft. </div> </div>', '5765c5b8-5222-4460-b12b-4380fff0e38f'::uuid),
                    ('Components', 'components', '{"text":"V, S, M *","verbal":true,"somatic":true,"material":{"required":true,"description":"a straight piece of iron","consumed":false,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S, M *</span> </div> </div>', '5765c5b8-5222-4460-b12b-4380fff0e38f'::uuid),
                    ('Duration', 'duration', '{"text":"Concentration 1 Minute","kind":"timed","value":1,"unit":"minute","concentration":true,"endCondition":null}', '<div> <div>Duration</div> <div> <i>Concentration</i> 1 Minute </div> </div>', '5765c5b8-5222-4460-b12b-4380fff0e38f'::uuid),
                    ('School', 'school', 'Enchantment', '<div> <div> School </div> <div> Enchantment </div> </div>', '5765c5b8-5222-4460-b12b-4380fff0e38f'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"WIS Save","kind":"save","attackType":null,"ability":"WIS"}', '<div> <div> Attack/Save </div> <div> <i></i> <span>WIS Save</span> </div> </div>', '5765c5b8-5222-4460-b12b-4380fff0e38f'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Paralyzed","damageTypes":[]}', '<div> <div> Damage/Effect </div> <div> <i></i> Paralyzed </div> </div>', '5765c5b8-5222-4460-b12b-4380fff0e38f'::uuid),
                    ('Description', 'description', '["Choose a Humanoid that you can see within range. The target must succeed on a Wisdom saving throw or have the Paralyzed condition for the duration. At the end of each of its turns, the target repeats the save, ending the spell on itself on a success.","Using a Higher-Level Spell Slot. You can target one additional Humanoid for each spell slot level above 2."]', '<div> <p>Choose a Humanoid that you can see within range. The target must succeed on a Wisdom saving throw or have the <a>Paralyzed</a> condition for the duration. At the end of each of its turns, the target repeats the save, ending the spell on itself on a success.</p> <p><strong><em>Using a Higher-Level Spell Slot.</em></strong> You can target one additional Humanoid for each spell slot level above 2.</p> <span>* - (a straight piece of iron)</span> </div>', '5765c5b8-5222-4460-b12b-4380fff0e38f'::uuid),
