                    ('Casting Time', 'castingTime', '{"text":"1 Action","kind":"action","value":1,"unit":"action","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Action </div> </div>', '204bdcbd-03e2-4909-ab65-c78fa4ed77f5'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"Self (30 ft.)","kind":"self","distanceValue":null,"distanceUnit":null,"area":{"shape":null,"value":30,"unit":"ft"}}', '<div> <div> Range/Area </div> <div> Self <span>(30 ft. <i></i>)</span> </div> </div>', '204bdcbd-03e2-4909-ab65-c78fa4ed77f5'::uuid),
                    ('Components', 'components', '{"text":"V, S, M *","verbal":true,"somatic":true,"material":{"required":true,"description":"a reliquary worth 1,000+ GP","consumed":false,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S, M *</span> </div> </div>', '204bdcbd-03e2-4909-ab65-c78fa4ed77f5'::uuid),
                    ('Duration', 'duration', '{"text":"Concentration 1 Minute","kind":"timed","value":1,"unit":"minute","concentration":true,"endCondition":null}', '<div> <div>Duration</div> <div> <i>Concentration</i> 1 Minute </div> </div>', '204bdcbd-03e2-4909-ab65-c78fa4ed77f5'::uuid),
                    ('School', 'school', 'Abjuration', '<div> <div> School </div> <div> Abjuration </div> </div>', '204bdcbd-03e2-4909-ab65-c78fa4ed77f5'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"CON Save","kind":"save","attackType":null,"ability":"CON"}', '<div> <div> Attack/Save </div> <div> <i></i> <span>CON Save</span> </div> </div>', '204bdcbd-03e2-4909-ab65-c78fa4ed77f5'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Blinded","damageTypes":[]}', '<div> <div> Damage/Effect </div> <div> <i></i> Blinded </div> </div>', '204bdcbd-03e2-4909-ab65-c78fa4ed77f5'::uuid),
                    ('Description', 'description', '["For the duration, you emit an aura in a 30-foot Emanation . While in the aura, creatures of your choice have Advantage on all saving throws, and other creatures have Disadvantage on attack rolls against them. In addition, when a Fiend or an Undead hits an affected creature with a melee attack roll, the attacker must succeed on a Constitution saving throw or have the Blinded condition until the end of its next turn."]', '<div> <p>For the duration, you emit an aura in a 30-foot <a>Emanation</a>. While in the aura, creatures of your choice have Advantage on all saving throws, and other creatures have Disadvantage on attack rolls against them. In addition, when a Fiend or an Undead hits an affected creature with a melee attack roll, the attacker must succeed on a Constitution saving throw or have the <a>Blinded</a> condition until the end of its next turn.</p> <span>* - (a reliquary worth 1,000+ GP)</span> </div>', '204bdcbd-03e2-4909-ab65-c78fa4ed77f5'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', '204bdcbd-03e2-4909-ab65-c78fa4ed77f5'::uuid),
                    ('Spell Tags', 'spellTags', '["Buff","Debuff"]', '', '204bdcbd-03e2-4909-ab65-c78fa4ed77f5'::uuid),
