                    ('Image', 'imageUrl', '', '', 'd4c0e92b-8085-40c1-99ac-d16181f49306'::uuid),
                    ('Level', 'level', '{"levelNumber":"1","label":"1st"}', '<div> <div> Level </div> <div> 1st </div> </div>', '8f979696-9f93-44d3-bc4d-e87b2b2590e7'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Bonus Action","kind":"bonus_action","value":1,"unit":"action","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Bonus Action </div> </div>', '8f979696-9f93-44d3-bc4d-e87b2b2590e7'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"90 ft.","kind":"distance","distanceValue":90,"distanceUnit":"ft","area":null}', '<div> <div> Range/Area </div> <div> 90 ft. </div> </div>', '8f979696-9f93-44d3-bc4d-e87b2b2590e7'::uuid),
                    ('Components', 'components', '{"text":"V","verbal":true,"somatic":false,"material":{"required":false,"description":null,"consumed":null,"costGp":null}}', '<div> <div> Components </div> <div> <span>V</span> </div> </div>', '8f979696-9f93-44d3-bc4d-e87b2b2590e7'::uuid),
                    ('Duration', 'duration', '{"text":"Concentration 1 Hour","kind":"timed","value":1,"unit":"hour","concentration":true,"endCondition":null}', '<div> <div>Duration</div> <div> <i>Concentration</i> 1 Hour </div> </div>', '8f979696-9f93-44d3-bc4d-e87b2b2590e7'::uuid),
                    ('School', 'school', 'Divination', '<div> <div> School </div> <div> Divination </div> </div>', '8f979696-9f93-44d3-bc4d-e87b2b2590e7'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"None","kind":"none","attackType":null,"ability":null}', '<div> <div> Attack/Save </div> <div> <span>None</span> </div> </div>', '8f979696-9f93-44d3-bc4d-e87b2b2590e7'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Force","damageTypes":["Force"]}', '<div> <div> Damage/Effect </div> <div> <i></i> Force </div> </div>', '8f979696-9f93-44d3-bc4d-e87b2b2590e7'::uuid),
                    ('Description', 'description', '["You magically mark one creature you can see within range as your quarry. Until the spell ends, you deal an extra 1d6 Force damage to the target whenever you hit it with an attack roll. You also have Advantage on any Wisdom ( Perception or Survival ) check you make to find it.","If the target drops to 0 Hit Points before this spell ends, you can take a Bonus Action to move the mark to a new creature you can see within range.","Using a Higher-Level Spell Slot. Your Concentration can last longer with a spell slot of level 3–4 (up to 8 hours) or 5+ (up to 24 hours)."]', '<div> <p>You magically mark one creature you can see within range as your quarry. Until the spell ends, you deal an extra 1d6 Force damage to the target whenever you hit it with an attack roll. You also have Advantage on any Wisdom (<a>Perception</a> or <a>Survival</a>) check you make to find it.</p> <p>If the target drops to 0 Hit Points before this spell ends, you can take a Bonus Action to move the mark to a new creature you can see within range.</p> <p><strong><em>Using a Higher-Level Spell Slot.</em></strong> Your Concentration can last longer with a spell slot of level 3–4 (up to 8 hours) or 5+ (up to 24 hours).</p> </div>', '8f979696-9f93-44d3-bc4d-e87b2b2590e7'::uuid),
