                    ('Level', 'level', '{"levelNumber":"3","label":"3rd"}', '<div> <div> Level </div> <div> 3rd </div> </div>', '3aeca2a2-861e-4818-a5ca-c00624bce2b1'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Action","kind":"action","value":1,"unit":"action","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Action </div> </div>', '3aeca2a2-861e-4818-a5ca-c00624bce2b1'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"120 ft. (30 ft.)","kind":"distance","distanceValue":120,"distanceUnit":"ft","area":{"shape":null,"value":30,"unit":"ft"}}', '<div> <div> Range/Area </div> <div> 120 ft. <span>(30 ft. <i></i>)</span> </div> </div>', '3aeca2a2-861e-4818-a5ca-c00624bce2b1'::uuid),
                    ('Components', 'components', '{"text":"S, M *","verbal":false,"somatic":true,"material":{"required":true,"description":"a pinch of confetti","consumed":false,"costGp":null}}', '<div> <div> Components </div> <div> <span>S, M *</span> </div> </div>', '3aeca2a2-861e-4818-a5ca-c00624bce2b1'::uuid),
                    ('Duration', 'duration', '{"text":"Concentration 1 Minute","kind":"timed","value":1,"unit":"minute","concentration":true,"endCondition":null}', '<div> <div>Duration</div> <div> <i>Concentration</i> 1 Minute </div> </div>', '3aeca2a2-861e-4818-a5ca-c00624bce2b1'::uuid),
                    ('School', 'school', 'Illusion', '<div> <div> School </div> <div> Illusion </div> </div>', '3aeca2a2-861e-4818-a5ca-c00624bce2b1'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"WIS Save","kind":"save","attackType":null,"ability":"WIS"}', '<div> <div> Attack/Save </div> <div> <i></i> <span>WIS Save</span> </div> </div>', '3aeca2a2-861e-4818-a5ca-c00624bce2b1'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Charmed (...)","damageTypes":[]}', '<div> <div> Damage/Effect </div> <div> <i></i> Charmed (...) </div> </div>', '3aeca2a2-861e-4818-a5ca-c00624bce2b1'::uuid),
                    ('Description', 'description', '["You create a twisting pattern of colors in a 30-foot Cube within range. The pattern appears for a moment and vanishes. Each creature in the area who can see the pattern must succeed on a Wisdom saving throw or have the Charmed condition for the duration. While Charmed, the creature has the Incapacitated condition and a Speed of 0.","The spell ends for an affected creature if it takes any damage or if someone else uses an action to shake the creature out of its stupor."]', '<div> <p>You create a twisting pattern of colors in a 30-foot <a>Cube</a> within range. The pattern appears for a moment and vanishes. Each creature in the area who can see the pattern must succeed on a Wisdom saving throw or have the <a>Charmed</a> condition for the duration. While Charmed, the creature has the <a>Incapacitated</a> condition and a Speed of 0.</p> <p>The spell ends for an affected creature if it takes any damage or if someone else uses an action to shake the creature out of its stupor.</p> <span>* - (a pinch of confetti)</span> </div>', '3aeca2a2-861e-4818-a5ca-c00624bce2b1'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', '3aeca2a2-861e-4818-a5ca-c00624bce2b1'::uuid),
