                    ('Level', 'level', '{"levelNumber":"8","label":"8th"}', '<div> <div> Level </div> <div> 8th </div> </div>', 'eec06d74-dd14-4b28-b69b-192bbf2174e8'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Action","kind":"action","value":1,"unit":"action","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Action </div> </div>', 'eec06d74-dd14-4b28-b69b-192bbf2174e8'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"150 ft. (20 ft.)","kind":"distance","distanceValue":150,"distanceUnit":"ft","area":{"shape":null,"value":20,"unit":"ft"}}', '<div> <div> Range/Area </div> <div> 150 ft. <span>(20 ft. <i></i>)</span> </div> </div>', 'eec06d74-dd14-4b28-b69b-192bbf2174e8'::uuid),
                    ('Components', 'components', '{"text":"V, S","verbal":true,"somatic":true,"material":{"required":false,"description":null,"consumed":null,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S</span> </div> </div>', 'eec06d74-dd14-4b28-b69b-192bbf2174e8'::uuid),
                    ('Duration', 'duration', '{"text":"Concentration 1 Minute","kind":"timed","value":1,"unit":"minute","concentration":true,"endCondition":null}', '<div> <div>Duration</div> <div> <i>Concentration</i> 1 Minute </div> </div>', 'eec06d74-dd14-4b28-b69b-192bbf2174e8'::uuid),
                    ('School', 'school', 'Conjuration', '<div> <div> School </div> <div> Conjuration </div> </div>', 'eec06d74-dd14-4b28-b69b-192bbf2174e8'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"DEX Save","kind":"save","attackType":null,"ability":"DEX"}', '<div> <div> Attack/Save </div> <div> <i></i> <span>DEX Save</span> </div> </div>', 'eec06d74-dd14-4b28-b69b-192bbf2174e8'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Fire","damageTypes":["Fire"]}', '<div> <div> Damage/Effect </div> <div> <i></i> Fire </div> </div>', 'eec06d74-dd14-4b28-b69b-192bbf2174e8'::uuid),
                    ('Description', 'description', '["A swirling cloud of embers and smoke fills a 20-foot-radius Sphere centered on a point within range. The cloud’s area is Heavily Obscured . It lasts for the duration or until a strong wind (like that created by Gust of Wind ) disperses it.","When the cloud appears, each creature in it makes a Dexterity saving throw, taking 10d8 Fire damage on a failed save or half as much damage on a successful one. A creature must also make this save when the Sphere moves into its space and when it enters the Sphere or ends its turn there. A creature makes this save only once per turn.","The cloud moves 10 feet away from you in a direction you choose at the start of each of your turns."]', '<div> <p>A swirling cloud of embers and smoke fills a 20-foot-radius <a>Sphere</a> centered on a point within range. The cloud’s area is <a>Heavily Obscured</a>. It lasts for the duration or until a strong wind (like that created by <a>Gust of Wind</a>) disperses it.</p> <p>When the cloud appears, each creature in it makes a Dexterity saving throw, taking 10d8 Fire damage on a failed save or half as much damage on a successful one. A creature must also make this save when the Sphere moves into its space and when it enters the Sphere or ends its turn there. A creature makes this save only once per turn.</p> <p>The cloud moves 10 feet away from you in a direction you choose at the start of each of your turns.</p> </div>', 'eec06d74-dd14-4b28-b69b-192bbf2174e8'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', 'eec06d74-dd14-4b28-b69b-192bbf2174e8'::uuid),
