                    ('School', 'school', 'Necromancy', '<div> <div> School </div> <div> Necromancy </div> </div>', '841e41aa-dfb3-48ab-9551-349cd62e88b2'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"CON Save","kind":"save","attackType":null,"ability":"CON"}', '<div> <div> Attack/Save </div> <div> <i></i> <span>CON Save</span> </div> </div>', '841e41aa-dfb3-48ab-9551-349cd62e88b2'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Necrotic","damageTypes":["Necrotic"]}', '<div> <div> Damage/Effect </div> <div> <i></i> Necrotic </div> </div>', '841e41aa-dfb3-48ab-9551-349cd62e88b2'::uuid),
                    ('Description', 'description', '["A creature you touch makes a Constitution saving throw, taking 2d10 Necrotic damage on a failed save or half as much damage on a successful one.","Using a Higher-Level Spell Slot. The damage increases by 1d10 for each spell slot level above 1."]', '<div> <p>A creature you touch makes a Constitution saving throw, taking 2d10 Necrotic damage on a failed save or half as much damage on a successful one.</p> <p><strong><em>Using a Higher-Level Spell Slot.</em></strong> The damage increases by 1d10 for each spell slot level above 1.</p> </div>', '841e41aa-dfb3-48ab-9551-349cd62e88b2'::uuid),
