                    ('Range/Area', 'rangeArea', '{"text":"300 ft. (20 ft.)","kind":"distance","distanceValue":300,"distanceUnit":"ft","area":{"shape":null,"value":20,"unit":"ft"}}', '<div> <div> Range/Area </div> <div> 300 ft. <span>(20 ft. <i></i>)</span> </div> </div>', 'dab32b67-00a8-4f6c-bc97-544d113ee63c'::uuid),
                    ('Components', 'components', '{"text":"V, S, M *","verbal":true,"somatic":true,"material":{"required":true,"description":"a locust","consumed":false,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S, M *</span> </div> </div>', 'dab32b67-00a8-4f6c-bc97-544d113ee63c'::uuid),
                    ('Duration', 'duration', '{"text":"Concentration 10 Minutes","kind":"timed","value":10,"unit":"minute","concentration":true,"endCondition":null}', '<div> <div>Duration</div> <div> <i>Concentration</i> 10 Minutes </div> </div>', 'dab32b67-00a8-4f6c-bc97-544d113ee63c'::uuid),
                    ('School', 'school', 'Conjuration', '<div> <div> School </div> <div> Conjuration </div> </div>', 'dab32b67-00a8-4f6c-bc97-544d113ee63c'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"CON Save","kind":"save","attackType":null,"ability":"CON"}', '<div> <div> Attack/Save </div> <div> <i></i> <span>CON Save</span> </div> </div>', 'dab32b67-00a8-4f6c-bc97-544d113ee63c'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Piercing","damageTypes":["Piercing"]}', '<div> <div> Damage/Effect </div> <div> <i></i> Piercing </div> </div>', 'dab32b67-00a8-4f6c-bc97-544d113ee63c'::uuid),
                    ('Description', 'description', '["Swarming locusts fill a 20-foot-radius Sphere centered on a point you choose within range. The Sphere remains for the duration, and its area is Lightly Obscured and Difficult Terrain .","When the swarm appears, each creature in it makes a Constitution saving throw, taking 4d10 Piercing damage on a failed save or half as much damage on a successful one. A creature also makes this save when it enters the spell’s area for the first time on a turn or ends its turn there. A creature makes this save only once per turn.","Using a Higher-Level Spell Slot. The damage increases by 1d10 for each spell slot level above 5."]', '<div> <p>Swarming locusts fill a 20-foot-radius <a>Sphere</a> centered on a point you choose within range. The Sphere remains for the duration, and its area is <a>Lightly Obscured</a> and <a>Difficult Terrain</a>.</p> <p>When the swarm appears, each creature in it makes a Constitution saving throw, taking 4d10 Piercing damage on a failed save or half as much damage on a successful one. A creature also makes this save when it enters the spell’s area for the first time on a turn or ends its turn there. A creature makes this save only once per turn.</p> <p><strong><em>Using a Higher-Level Spell Slot.</em></strong> The damage increases by 1d10 for each spell slot level above 5.</p> <span>* - (a locust)</span> </div>', 'dab32b67-00a8-4f6c-bc97-544d113ee63c'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', 'dab32b67-00a8-4f6c-bc97-544d113ee63c'::uuid),
                    ('Spell Tags', 'spellTags', '["Damage","Control"]', '', 'dab32b67-00a8-4f6c-bc97-544d113ee63c'::uuid),
                    ('Available For', 'availableFor', '["Cleric (Legacy)","Druid (Legacy)","Sorcerer (Legacy)","Cleric","Druid","Sorcerer","Cleric - Tempest Domain (PHB)","Cleric - Nature Domain (PHB)","Druid - Circle of the Hive (HGtMH1)","Warlock - Fiend Patron"]', '', 'dab32b67-00a8-4f6c-bc97-544d113ee63c'::uuid),
