                    ('Components', 'components', '{"text":"V, S","verbal":true,"somatic":true,"material":{"required":false,"description":null,"consumed":null,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S</span> </div> </div>', '23c2acf6-ca89-4d36-a5e6-e75e34cefd85'::uuid),
                    ('Duration', 'duration', '{"text":"Concentration 10 Minutes","kind":"timed","value":10,"unit":"minute","concentration":true,"endCondition":null}', '<div> <div>Duration</div> <div> <i>Concentration</i> 10 Minutes </div> </div>', '23c2acf6-ca89-4d36-a5e6-e75e34cefd85'::uuid),
