                    ('Level', 'level', '{"levelNumber":"6","label":"6th"}', '<div> <div> Level </div> <div> 6th </div> </div>', '4111b662-0946-4f73-a54a-d8b6be06cb5e'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Action","kind":"action","value":1,"unit":"action","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Action </div> </div>', '4111b662-0946-4f73-a54a-d8b6be06cb5e'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"Self","kind":"self","distanceValue":null,"distanceUnit":null,"area":null}', '<div> <div> Range/Area </div> <div> Self </div> </div>', '4111b662-0946-4f73-a54a-d8b6be06cb5e'::uuid),
                    ('Components', 'components', '{"text":"V, S","verbal":true,"somatic":true,"material":{"required":false,"description":null,"consumed":null,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S</span> </div> </div>', '4111b662-0946-4f73-a54a-d8b6be06cb5e'::uuid),
                    ('Duration', 'duration', '{"text":"Concentration 10 Minutes","kind":"timed","value":10,"unit":"minute","concentration":true,"endCondition":null}', '<div> <div>Duration</div> <div> <i>Concentration</i> 10 Minutes </div> </div>', '4111b662-0946-4f73-a54a-d8b6be06cb5e'::uuid),
                    ('School', 'school', 'Transmutation', '<div> <div> School </div> <div> Transmutation </div> </div>', '4111b662-0946-4f73-a54a-d8b6be06cb5e'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"DEX Save","kind":"save","attackType":null,"ability":"DEX"}', '<div> <div> Attack/Save </div> <div> <i></i> <span>DEX Save</span> </div> </div>', '4111b662-0946-4f73-a54a-d8b6be06cb5e'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Prone","damageTypes":[]}', '<div> <div> Damage/Effect </div> <div> <i></i> Prone </div> </div>', '4111b662-0946-4f73-a54a-d8b6be06cb5e'::uuid),
                    ('Description', 'description', '["Until the spell ends, bits of rock spread across your body, and you gain the following benefits:","You have resistance to bludgeoning, piercing, and slashing damage from nonmagical attacks.","You can use your action to create a small earthquake on the ground in a 15-foot radius centered on you. Other creatures on that ground must succeed on a Dexterity saving throw or be knocked prone .","You can move across difficult terrain made of earth or stone without spending extra movement. You can move through solid earth or stone as if it was air and without destabilizing it, but you can’t end your movement there. If you do so, you are ejected to the nearest unoccupied space, this spell ends, and you are stunned until the end of your next turn."]', '<div> <p>Until the spell ends, bits of rock spread across your body, and you gain the following benefits:</p> <ul> <li> <p>You have resistance to bludgeoning, piercing, and slashing damage from nonmagical attacks.</p> </li> <li> <p>You can use your action to create a small earthquake on the ground in a 15-foot radius centered on you. Other creatures on that ground must succeed on a Dexterity saving throw or be knocked <a>prone</a>.</p> </li> <li> <p>You can move across difficult terrain made of earth or stone without spending extra movement. You can move through solid earth or stone as if it was air and without destabilizing it, but you can’t end your movement there. If you do so, you are ejected to the nearest unoccupied space, this spell ends, and you are <a>stunned</a> until the end of your next turn.</p> </li> </ul> </div>', '4111b662-0946-4f73-a54a-d8b6be06cb5e'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', '4111b662-0946-4f73-a54a-d8b6be06cb5e'::uuid),
