                    ('Casting Time', 'castingTime', '{"text":"1 Bonus Action","kind":"bonus_action","value":1,"unit":"action","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Bonus Action </div> </div>', 'bfc6b92f-6b7e-4813-b2eb-c1ee4e68888a'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"Touch","kind":"touch","distanceValue":null,"distanceUnit":null,"area":null}', '<div> <div> Range/Area </div> <div> Touch </div> </div>', 'bfc6b92f-6b7e-4813-b2eb-c1ee4e68888a'::uuid),
                    ('Components', 'components', '{"text":"V, S, M *","verbal":true,"somatic":true,"material":{"required":true,"description":"a grasshopper’s hind leg","consumed":false,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S, M *</span> </div> </div>', 'bfc6b92f-6b7e-4813-b2eb-c1ee4e68888a'::uuid),
                    ('Duration', 'duration', '{"text":"1 Minute","kind":"timed","value":1,"unit":"minute","concentration":false,"endCondition":null}', '<div> <div>Duration</div> <div> 1 Minute </div> </div>', 'bfc6b92f-6b7e-4813-b2eb-c1ee4e68888a'::uuid),
                    ('School', 'school', 'Transmutation', '<div> <div> School </div> <div> Transmutation </div> </div>', 'bfc6b92f-6b7e-4813-b2eb-c1ee4e68888a'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"None","kind":"none","attackType":null,"ability":null}', '<div> <div> Attack/Save </div> <div> <span>None</span> </div> </div>', 'bfc6b92f-6b7e-4813-b2eb-c1ee4e68888a'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Movement","damageTypes":[]}', '<div> <div> Damage/Effect </div> <div> Movement </div> </div>', 'bfc6b92f-6b7e-4813-b2eb-c1ee4e68888a'::uuid),
                    ('Description', 'description', '["You touch a willing creature. Once on each of its turns until the spell ends, that creature can jump up to 30 feet by spending 10 feet of movement.","Using a Higher-Level Spell Slot. You can target one additional creature for each spell slot level above 1."]', '<div> <p>You touch a willing creature. Once on each of its turns until the spell ends, that creature can jump up to 30 feet by spending 10 feet of movement.</p> <p><strong><em>Using a Higher-Level Spell Slot.</em></strong> You can target one additional creature for each spell slot level above 1.</p> <span>* - (a grasshopper’s hind leg)</span> </div>', 'bfc6b92f-6b7e-4813-b2eb-c1ee4e68888a'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', 'bfc6b92f-6b7e-4813-b2eb-c1ee4e68888a'::uuid),
