                    ('Level', 'level', '{"levelNumber":"2","label":"2nd"}', '<div> <div> Level </div> <div> 2nd </div> </div>', '6224fda1-5869-4fdf-a015-8f997f69c325'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Action","kind":"action","value":1,"unit":"action","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Action </div> </div>', '6224fda1-5869-4fdf-a015-8f997f69c325'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"60 ft.","kind":"distance","distanceValue":60,"distanceUnit":"ft","area":null}', '<div> <div> Range/Area </div> <div> 60 ft. </div> </div>', '6224fda1-5869-4fdf-a015-8f997f69c325'::uuid),
                    ('Components', 'components', '{"text":"V","verbal":true,"somatic":false,"material":{"required":false,"description":null,"consumed":null,"costGp":null}}', '<div> <div> Components </div> <div> <span>V</span> </div> </div>', '6224fda1-5869-4fdf-a015-8f997f69c325'::uuid),
                    ('Duration', 'duration', '{"text":"Instantaneous","kind":"instantaneous","value":null,"unit":null,"concentration":false,"endCondition":null}', '<div> <div>Duration</div> <div> Instantaneous </div> </div>', '6224fda1-5869-4fdf-a015-8f997f69c325'::uuid),
                    ('School', 'school', 'Transmutation', '<div> <div> School </div> <div> Transmutation </div> </div>', '6224fda1-5869-4fdf-a015-8f997f69c325'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"None","kind":"none","attackType":null,"ability":null}', '<div> <div> Attack/Save </div> <div> <span>None</span> </div> </div>', '6224fda1-5869-4fdf-a015-8f997f69c325'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Utility","damageTypes":[]}', '<div> <div> Damage/Effect </div> <div> Utility </div> </div>', '6224fda1-5869-4fdf-a015-8f997f69c325'::uuid),
                    ('Description', 'description', '["Choose an object that you can see within range. The object can be a door, a box, a chest, a set of manacles, a padlock, or another object that contains a mundane or magical means that prevents access.","A target that is held shut by a mundane lock or that is stuck or barred becomes unlocked, unstuck, or unbarred. If the object has multiple locks, only one of them is unlocked.","If the target is held shut by Arcane Lock , that spell is suppressed for 10 minutes, during which time the target can be opened and closed.","When you cast the spell, a loud knock, audible up to 300 feet away, emanates from the target."]', '<div> <p>Choose an object that you can see within range. The object can be a door, a box, a chest, a set of manacles, a padlock, or another object that contains a mundane or magical means that prevents access.</p> <p>A target that is held shut by a mundane lock or that is stuck or barred becomes unlocked, unstuck, or unbarred. If the object has multiple locks, only one of them is unlocked.</p> <p>If the target is held shut by <a>Arcane Lock</a>, that spell is suppressed for 10 minutes, during which time the target can be opened and closed.</p> <p>When you cast the spell, a loud knock, audible up to 300 feet away, emanates from the target.</p> </div>', '6224fda1-5869-4fdf-a015-8f997f69c325'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', '6224fda1-5869-4fdf-a015-8f997f69c325'::uuid),
