                    ('School', 'school', 'Evocation', '', 'baa73d9d-dc2b-4391-8be9-aa9dd83d600b'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"DEX Save","kind":"save","attackType":null,"ability":"DEX"}', '', 'baa73d9d-dc2b-4391-8be9-aa9dd83d600b'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Piercing","damageTypes":["Piercing"]}', '', 'baa73d9d-dc2b-4391-8be9-aa9dd83d600b'::uuid),
                    ('Description', 'description', '["Flexible combat form.","Cost: 24 bullets per attack sequence","Range: 50 ft","I choose up to 3 targets or the same target multiple times.","Each hit deals 1d10 + Dexterity modifier to the target.","Reliable mid-range damage."]', '<p>Flexible combat form.</p> <p>Cost: 24 bullets per attack sequence</p> <p>Range: 50 ft</p> <p>I choose up to 3 targets or the same target multiple times.</p> <p>Each hit deals 1d10 + Dexterity modifier to the target.</p> <p>Reliable mid-range damage.</p>', 'baa73d9d-dc2b-4391-8be9-aa9dd83d600b'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', 'baa73d9d-dc2b-4391-8be9-aa9dd83d600b'::uuid),
