                    ('Damage/Effect', 'damageEffect', '{"text":"Healing","damageTypes":[]}', '<div> <div> Damage/Effect </div> <div> Healing </div> </div>', '491cf9d5-e008-4652-bda8-46f4696174ac'::uuid),
                    ('Description', 'description', '["You touch a creature and end one condition on it: Blinded , Deafened , Paralyzed , or Poisoned ."]', '<div> <p>You touch a creature and end one condition on it: <a>Blinded</a>, <a>Deafened</a>, <a>Paralyzed</a>, or <a>Poisoned</a>.</p> </div>', '491cf9d5-e008-4652-bda8-46f4696174ac'::uuid),
