                    ('Components', 'components', '{"text":"V, M *","verbal":true,"somatic":false,"material":{"required":true,"description":"a firefly or phosphorescent moss","consumed":false,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, M *</span> </div> </div>', 'f1f0b6b0-d845-48b4-95a3-287a75d57799'::uuid),
