                    ('School', 'school', 'Evocation', '<div> <div> School </div> <div> Evocation </div> </div>', 'f1f0b6b0-d845-48b4-95a3-287a75d57799'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"None","kind":"none","attackType":null,"ability":null}', '<div> <div> Attack/Save </div> <div> <span>None</span> </div> </div>', 'f1f0b6b0-d845-48b4-95a3-287a75d57799'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Creation (...)","damageTypes":[]}', '<div> <div> Damage/Effect </div> <div> Creation (...) </div> </div>', 'f1f0b6b0-d845-48b4-95a3-287a75d57799'::uuid),
                    ('Description', 'description', '["You touch one Large or smaller object that isn’t being worn or carried by someone else. Until the spell ends, the object sheds Bright Light in a 20-foot radius and Dim Light for an additional 20 feet. The light can be colored as you like.","Covering the object with something opaque blocks the light. The spell ends if you cast it again."]', '<div> <p>You touch one Large or smaller object that isn’t being worn or carried by someone else. Until the spell ends, the object sheds <a>Bright Light</a> in a 20-foot radius and <a>Dim Light</a> for an additional 20 feet. The light can be colored as you like.</p> <p>Covering the object with something opaque blocks the light. The spell ends if you cast it again.</p> <span>* - (a firefly or phosphorescent moss)</span> </div>', 'f1f0b6b0-d845-48b4-95a3-287a75d57799'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', 'f1f0b6b0-d845-48b4-95a3-287a75d57799'::uuid),
