                    ('Source URL', 'url', 'https://www.dndbeyond.com/spells/2618996-light', '', 'f1f0b6b0-d845-48b4-95a3-287a75d57799'::uuid),
                    ('Image', 'imageUrl', 'https://www.dndbeyond.com/attachments/2/703/evocation.png', '', 'f1f0b6b0-d845-48b4-95a3-287a75d57799'::uuid),
                    ('Level', 'level', '{"levelNumber":"3","label":"3rd"}', '', '1b1f53cb-5565-40e0-a120-9241b203e6dd'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Bonus Action *","kind":"bonus_action","value":1,"unit":"action","trigger":null,"ritual":false}', '', '1b1f53cb-5565-40e0-a120-9241b203e6dd'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"Self","kind":"self","distanceValue":null,"distanceUnit":null,"area":null}', '', '1b1f53cb-5565-40e0-a120-9241b203e6dd'::uuid),
                    ('Components', 'components', '{"text":"V, S","verbal":true,"somatic":true,"material":{"required":false,"description":null,"consumed":null,"costGp":null}}', '', '1b1f53cb-5565-40e0-a120-9241b203e6dd'::uuid),
                    ('Duration', 'duration', '{"text":"Instantaneous","kind":"instantaneous","value":null,"unit":null,"concentration":false,"endCondition":null}', '', '1b1f53cb-5565-40e0-a120-9241b203e6dd'::uuid),
                    ('School', 'school', 'Transmutation', '', '1b1f53cb-5565-40e0-a120-9241b203e6dd'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"DEX Save","kind":"save","attackType":null,"ability":"DEX"}', '', '1b1f53cb-5565-40e0-a120-9241b203e6dd'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Lightning (...)","damageTypes":["Lightning"]}', '', '1b1f53cb-5565-40e0-a120-9241b203e6dd'::uuid),
                    ('Description', 'description', '["As your attack hits or misses the target, the weapon or ammunition you’re using transforms into a lightning bolt. Instead of taking any damage or other effects from the attack, the target takes 4d8 Lightning damage on a hit or half as much damage on a miss. Each creature within 10 feet of the target then makes a Dexterity saving throw, taking 2d8 Lightning damage on a failed save or half as much damage on a successful one.","The weapon or ammunition then returns to its normal form.","Using a Higher-Level Spell Slot. The damage for both effects of the spell increases by 1d8 for each spell slot level above 3."]', '<p>As your attack hits or misses the target, the weapon or ammunition you’re using transforms into a lightning bolt. Instead of taking any damage or other effects from the attack, the target takes 4d8 Lightning damage on a hit or half as much damage on a miss. Each creature within 10 feet of the target then makes a Dexterity saving throw, taking 2d8 Lightning damage on a failed save or half as much damage on a successful one.</p> <p>The weapon or ammunition then returns to its normal form.</p> <p>Using a Higher-Level Spell Slot. The damage for both effects of the spell increases by 1d8 for each spell slot level above 3.</p>', '1b1f53cb-5565-40e0-a120-9241b203e6dd'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', '1b1f53cb-5565-40e0-a120-9241b203e6dd'::uuid),
