                    ('Range/Area', 'rangeArea', '{"text":"Self (100 ft.)","kind":"self","distanceValue":null,"distanceUnit":null,"area":{"shape":null,"value":100,"unit":"ft"}}', '<div> <div> Range/Area </div> <div> Self <span>(100 ft. <i></i>)</span> </div> </div>', '411a305c-152f-465e-b61e-43470548f71c'::uuid),
                    ('Components', 'components', '{"text":"V, S, M *","verbal":true,"somatic":true,"material":{"required":true,"description":"a bit of fur and a crystal rod","consumed":false,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S, M *</span> </div> </div>', '411a305c-152f-465e-b61e-43470548f71c'::uuid),
                    ('Duration', 'duration', '{"text":"Instantaneous","kind":"instantaneous","value":null,"unit":null,"concentration":false,"endCondition":null}', '<div> <div>Duration</div> <div> Instantaneous </div> </div>', '411a305c-152f-465e-b61e-43470548f71c'::uuid),
                    ('School', 'school', 'Evocation', '<div> <div> School </div> <div> Evocation </div> </div>', '411a305c-152f-465e-b61e-43470548f71c'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"DEX Save","kind":"save","attackType":null,"ability":"DEX"}', '<div> <div> Attack/Save </div> <div> <i></i> <span>DEX Save</span> </div> </div>', '411a305c-152f-465e-b61e-43470548f71c'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Lightning","damageTypes":["Lightning"]}', '<div> <div> Damage/Effect </div> <div> <i></i> Lightning </div> </div>', '411a305c-152f-465e-b61e-43470548f71c'::uuid),
                    ('Description', 'description', '["A stroke of lightning forming a 100-foot-long, 5-foot-wide Line blasts out from you in a direction you choose. Each creature in the Line makes a Dexterity saving throw, taking 8d6 Lightning damage on a failed save or half as much damage on a successful one.","Using a Higher-Level Spell Slot. The damage increases by 1d6 for each spell slot level above 3."]', '<div> <p>A stroke of lightning forming a 100-foot-long, 5-foot-wide <a>Line</a> blasts out from you in a direction you choose. Each creature in the Line makes a Dexterity saving throw, taking 8d6 Lightning damage on a failed save or half as much damage on a successful one.</p> <p><strong><em>Using a Higher-Level Spell Slot.</em></strong> The damage increases by 1d6 for each spell slot level above 3.</p> <span>* - (a bit of fur and a crystal rod)</span> </div>', '411a305c-152f-465e-b61e-43470548f71c'::uuid),
