                    ('Attack/Save', 'attackSave', '{"text":"None","kind":"none","attackType":null,"ability":null}', '<div> <div> Attack/Save </div> <div> <span>None</span> </div> </div>', '907d0120-57cb-4352-ad54-2395b4354cee'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Detection","damageTypes":[]}', '<div> <div> Damage/Effect </div> <div> Detection </div> </div>', '907d0120-57cb-4352-ad54-2395b4354cee'::uuid),
                    ('Description', 'description', '["Describe or name a specific kind of Beast, Plant creature, or nonmagical plant. You learn the direction and distance to the closest creature or plant of that kind within 5 miles, if any are present."]', '<div> <p>Describe or name a specific kind of Beast, Plant creature, or nonmagical plant. You learn the direction and distance to the closest creature or plant of that kind within 5 miles, if any are present.</p> <span>* - (fur from a bloodhound)</span> </div>', '907d0120-57cb-4352-ad54-2395b4354cee'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', '907d0120-57cb-4352-ad54-2395b4354cee'::uuid);
                """);

