                    ('Source URL', 'url', 'https://www.dndbeyond.com/spells/2619001-locate-creature', '', '88606e8d-bc9a-473e-a4e6-126b6a96c64c'::uuid),
                    ('Image', 'imageUrl', 'https://www.dndbeyond.com/attachments/2/709/divination.png', '', '88606e8d-bc9a-473e-a4e6-126b6a96c64c'::uuid),
                    ('Level', 'level', '{"levelNumber":"2","label":"2nd"}', '<div> <div> Level </div> <div> 2nd </div> </div>', '99091f0d-fbf7-4a55-b1d9-be9d7d8e3521'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Action","kind":"action","value":1,"unit":"action","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Action </div> </div>', '99091f0d-fbf7-4a55-b1d9-be9d7d8e3521'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"Self","kind":"self","distanceValue":null,"distanceUnit":null,"area":null}', '<div> <div> Range/Area </div> <div> Self </div> </div>', '99091f0d-fbf7-4a55-b1d9-be9d7d8e3521'::uuid),
                    ('Components', 'components', '{"text":"V, S, M *","verbal":true,"somatic":true,"material":{"required":true,"description":"a forked twig","consumed":false,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S, M *</span> </div> </div>', '99091f0d-fbf7-4a55-b1d9-be9d7d8e3521'::uuid),
                    ('Duration', 'duration', '{"text":"Concentration 10 Minutes","kind":"timed","value":10,"unit":"minute","concentration":true,"endCondition":null}', '<div> <div>Duration</div> <div> <i>Concentration</i> 10 Minutes </div> </div>', '99091f0d-fbf7-4a55-b1d9-be9d7d8e3521'::uuid),
                    ('School', 'school', 'Divination', '<div> <div> School </div> <div> Divination </div> </div>', '99091f0d-fbf7-4a55-b1d9-be9d7d8e3521'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"None","kind":"none","attackType":null,"ability":null}', '<div> <div> Attack/Save </div> <div> <span>None</span> </div> </div>', '99091f0d-fbf7-4a55-b1d9-be9d7d8e3521'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Detection","damageTypes":[]}', '<div> <div> Damage/Effect </div> <div> Detection </div> </div>', '99091f0d-fbf7-4a55-b1d9-be9d7d8e3521'::uuid),
                    ('Description', 'description', '["Describe or name an object that is familiar to you. You sense the direction to the object’s location if that object is within 1,000 feet of you. If the object is in motion, you know the direction of its movement.","The spell can locate a specific object known to you if you have seen it up close—within 30 feet—at least once. Alternatively, the spell can locate the nearest object of a particular kind, such as a certain kind of apparel, jewelry, furniture, tool, or weapon.","This spell can’t locate an object if any thickness of lead blocks a direct path between you and the object."]', '<div> <p>Describe or name an object that is familiar to you. You sense the direction to the object’s location if that object is within 1,000 feet of you. If the object is in motion, you know the direction of its movement.</p> <p>The spell can locate a specific object known to you if you have seen it up close—within 30 feet—at least once. Alternatively, the spell can locate the nearest object of a particular kind, such as a certain kind of apparel, jewelry, furniture, tool, or weapon.</p> <p>This spell can’t locate an object if any thickness of lead blocks a direct path between you and the object.</p> <span>* - (a forked twig)</span> </div>', '99091f0d-fbf7-4a55-b1d9-be9d7d8e3521'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', '99091f0d-fbf7-4a55-b1d9-be9d7d8e3521'::uuid),
