                    ('Range/Area', 'rangeArea', '{"text":"Touch","kind":"touch","distanceValue":null,"distanceUnit":null,"area":null}', '<div> <div> Range/Area </div> <div> Touch </div> </div>', 'aa49f6d2-4e2e-48d3-b00a-e70a4f0dbe71'::uuid),
                    ('Components', 'components', '{"text":"V, S, M *","verbal":true,"somatic":true,"material":{"required":true,"description":"a pinch of dirt","consumed":false,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S, M *</span> </div> </div>', 'aa49f6d2-4e2e-48d3-b00a-e70a4f0dbe71'::uuid),
                    ('Duration', 'duration', '{"text":"1 Hour","kind":"timed","value":1,"unit":"hour","concentration":false,"endCondition":null}', '<div> <div>Duration</div> <div> 1 Hour </div> </div>', 'aa49f6d2-4e2e-48d3-b00a-e70a4f0dbe71'::uuid),
                    ('School', 'school', 'Transmutation', '<div> <div> School </div> <div> Transmutation </div> </div>', 'aa49f6d2-4e2e-48d3-b00a-e70a4f0dbe71'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"None","kind":"none","attackType":null,"ability":null}', '<div> <div> Attack/Save </div> <div> <span>None</span> </div> </div>', 'aa49f6d2-4e2e-48d3-b00a-e70a4f0dbe71'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Buff (...)","damageTypes":[]}', '<div> <div> Damage/Effect </div> <div> Buff (...) </div> </div>', 'aa49f6d2-4e2e-48d3-b00a-e70a4f0dbe71'::uuid),
                    ('Description', 'description', '["You touch a creature. The target’s Speed increases by 10 feet until the spell ends.","Using a Higher-Level Spell Slot. You can target one additional creature for each spell slot level above 1."]', '<div> <p>You touch a creature. The target’s Speed increases by 10 feet until the spell ends.</p> <p><strong><em>Using a Higher-Level Spell Slot.</em></strong> You can target one additional creature for each spell slot level above 1.</p> <span>* - (a pinch of dirt)</span> </div>', 'aa49f6d2-4e2e-48d3-b00a-e70a4f0dbe71'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', 'aa49f6d2-4e2e-48d3-b00a-e70a4f0dbe71'::uuid),
