                    ('Level', 'level', '{"levelNumber":"5","label":"5th"}', '<div> <div> Level </div> <div> 5th </div> </div>', 'fc9aa13b-4387-45f5-aa88-66156024c813'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Action","kind":"action","value":1,"unit":"action","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Action </div> </div>', 'fc9aa13b-4387-45f5-aa88-66156024c813'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"120 ft.","kind":"distance","distanceValue":120,"distanceUnit":"ft","area":null}', '<div> <div> Range/Area </div> <div> 120 ft. </div> </div>', 'fc9aa13b-4387-45f5-aa88-66156024c813'::uuid),
                    ('Components', 'components', '{"text":"V, S, M *","verbal":true,"somatic":true,"material":{"required":true,"description":"paper or leaf in the shape of a funnel","consumed":false,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S, M *</span> </div> </div>', 'fc9aa13b-4387-45f5-aa88-66156024c813'::uuid),
                    ('Duration', 'duration', '{"text":"Concentration 1 Minute","kind":"timed","value":1,"unit":"minute","concentration":true,"endCondition":null}', '<div> <div>Duration</div> <div> <i>Concentration</i> 1 Minute </div> </div>', 'fc9aa13b-4387-45f5-aa88-66156024c813'::uuid),
                    ('School', 'school', 'Evocation', '<div> <div> School </div> <div> Evocation </div> </div>', 'fc9aa13b-4387-45f5-aa88-66156024c813'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"STR Save","kind":"save","attackType":null,"ability":"STR"}', '<div> <div> Attack/Save </div> <div> <i></i> <span>STR Save</span> </div> </div>', 'fc9aa13b-4387-45f5-aa88-66156024c813'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Bludgeoning","damageTypes":["Bludgeoning"]}', '<div> <div> Damage/Effect </div> <div> <i></i> Bludgeoning </div> </div>', 'fc9aa13b-4387-45f5-aa88-66156024c813'::uuid),
                    ('Description', 'description', '["A swirling mass of 5-foot-deep water appears in a 30-foot radius centered on a point you can see within range. The point must be on the ground or in a body of water. Until the spell ends, that area is difficult terrain, and any creature that starts its turn there must succeed on a Strength saving throw or take 6d6 bludgeoning damage and be pulled 10 feet toward the center."]', '<div> <p>A swirling mass of 5-foot-deep water appears in a 30-foot radius centered on a point you can see within range. The point must be on the ground or in a body of water. Until the spell ends, that area is difficult terrain, and any creature that starts its turn there must succeed on a Strength saving throw or take 6d6 bludgeoning damage and be pulled 10 feet toward the center.</p> <span>* - (paper or leaf in the shape of a funnel)</span> </div>', 'fc9aa13b-4387-45f5-aa88-66156024c813'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', 'fc9aa13b-4387-45f5-aa88-66156024c813'::uuid),
                    ('Spell Tags', 'spellTags', '["Damage","Control"]', '', 'fc9aa13b-4387-45f5-aa88-66156024c813'::uuid),
                    ('Available For', 'availableFor', '["Druid (Legacy)","Druid"]', '', 'fc9aa13b-4387-45f5-aa88-66156024c813'::uuid),
