                    ('Source URL', 'url', 'https://www.dndbeyond.com/spells/2390-maelstrom', '', 'fc9aa13b-4387-45f5-aa88-66156024c813'::uuid),
                    ('Image', 'imageUrl', 'https://www.dndbeyond.com/attachments/2/703/evocation.png', '', 'fc9aa13b-4387-45f5-aa88-66156024c813'::uuid),
                    ('Level', 'level', '{"levelNumber":"1","label":"1st"}', '<div> <div> Level </div> <div> 1st </div> </div>', '1e9e1e6e-420f-43fd-ae4d-d93cd5ffcdcd'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Action","kind":"action","value":1,"unit":"action","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Action </div> </div>', '1e9e1e6e-420f-43fd-ae4d-d93cd5ffcdcd'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"Touch","kind":"touch","distanceValue":null,"distanceUnit":null,"area":null}', '<div> <div> Range/Area </div> <div> Touch </div> </div>', '1e9e1e6e-420f-43fd-ae4d-d93cd5ffcdcd'::uuid),
                    ('Components', 'components', '{"text":"V, S, M *","verbal":true,"somatic":true,"material":{"required":true,"description":"a piece of cured leather","consumed":false,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S, M *</span> </div> </div>', '1e9e1e6e-420f-43fd-ae4d-d93cd5ffcdcd'::uuid),
                    ('Duration', 'duration', '{"text":"8 Hours","kind":"timed","value":8,"unit":"hour","concentration":false,"endCondition":null}', '<div> <div>Duration</div> <div> 8 Hours </div> </div>', '1e9e1e6e-420f-43fd-ae4d-d93cd5ffcdcd'::uuid),
                    ('School', 'school', 'Abjuration', '<div> <div> School </div> <div> Abjuration </div> </div>', '1e9e1e6e-420f-43fd-ae4d-d93cd5ffcdcd'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"None","kind":"none","attackType":null,"ability":null}', '<div> <div> Attack/Save </div> <div> <span>None</span> </div> </div>', '1e9e1e6e-420f-43fd-ae4d-d93cd5ffcdcd'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Buff (...)","damageTypes":[]}', '<div> <div> Damage/Effect </div> <div> Buff (...) </div> </div>', '1e9e1e6e-420f-43fd-ae4d-d93cd5ffcdcd'::uuid),
                    ('Description', 'description', '["You touch a willing creature who isn’t wearing armor. Until the spell ends, the target’s base AC becomes 13 plus its Dexterity modifier. The spell ends early if the target dons armor."]', '<div> <p>You touch a willing creature who isn’t wearing armor. Until the spell ends, the target’s base AC becomes 13 plus its Dexterity modifier. The spell ends early if the target dons armor.</p> <span>* - (a piece of cured leather)</span> </div>', '1e9e1e6e-420f-43fd-ae4d-d93cd5ffcdcd'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', '1e9e1e6e-420f-43fd-ae4d-d93cd5ffcdcd'::uuid),
                    ('Spell Tags', 'spellTags', '["Buff","Warding"]', '', '1e9e1e6e-420f-43fd-ae4d-d93cd5ffcdcd'::uuid),
                    ('Available For', 'availableFor', '["Sorcerer (Legacy)","Wizard (Legacy)","Sorcerer","Wizard"]', '', '1e9e1e6e-420f-43fd-ae4d-d93cd5ffcdcd'::uuid),
