                    ('Level', 'level', '{"levelNumber":"Cantrip","label":"Cantrip"}', '<div> <div> Level </div> <div> Cantrip </div> </div>', '9d41719b-fa51-425f-8616-cbd2a8b8d38b'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Action","kind":"action","value":1,"unit":"action","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Action </div> </div>', '9d41719b-fa51-425f-8616-cbd2a8b8d38b'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"30 ft.","kind":"distance","distanceValue":30,"distanceUnit":"ft","area":null}', '<div> <div> Range/Area </div> <div> 30 ft. </div> </div>', '9d41719b-fa51-425f-8616-cbd2a8b8d38b'::uuid),
                    ('Components', 'components', '{"text":"V, S","verbal":true,"somatic":true,"material":{"required":false,"description":null,"consumed":null,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S</span> </div> </div>', '9d41719b-fa51-425f-8616-cbd2a8b8d38b'::uuid),
                    ('Duration', 'duration', '{"text":"1 Minute","kind":"timed","value":1,"unit":"minute","concentration":false,"endCondition":null}', '<div> <div>Duration</div> <div> 1 Minute </div> </div>', '9d41719b-fa51-425f-8616-cbd2a8b8d38b'::uuid),
                    ('School', 'school', 'Conjuration', '<div> <div> School </div> <div> Conjuration </div> </div>', '9d41719b-fa51-425f-8616-cbd2a8b8d38b'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"None","kind":"none","attackType":null,"ability":null}', '<div> <div> Attack/Save </div> <div> <span>None</span> </div> </div>', '9d41719b-fa51-425f-8616-cbd2a8b8d38b'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Utility","damageTypes":[]}', '<div> <div> Damage/Effect </div> <div> Utility </div> </div>', '9d41719b-fa51-425f-8616-cbd2a8b8d38b'::uuid),
                    ('Description', 'description', '["A spectral, floating hand appears at a point you choose within range. The hand lasts for the duration. The hand vanishes if it is ever more than 30 feet away from you or if you cast this spell again.","When you cast the spell, you can use the hand to manipulate an object, open an unlocked door or container, stow or retrieve an item from an open container, or pour the contents out of a vial.","As a Magic action on your later turns, you can control the hand thus again. As part of that action, you can move the hand up to 30 feet.","The hand can’t attack, activate magic items, or carry more than 10 pounds."]', '<div> <p>A spectral, floating hand appears at a point you choose within range. The hand lasts for the duration. The hand vanishes if it is ever more than 30 feet away from you or if you cast this spell again.</p> <p>When you cast the spell, you can use the hand to manipulate an object, open an unlocked door or container, stow or retrieve an item from an open container, or pour the contents out of a vial.</p> <p>As a <a>Magic</a> action on your later turns, you can control the hand thus again. As part of that action, you can move the hand up to 30 feet.</p> <p>The hand can’t attack, activate magic items, or carry more than 10 pounds.</p> </div>', '9d41719b-fa51-425f-8616-cbd2a8b8d38b'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', '9d41719b-fa51-425f-8616-cbd2a8b8d38b'::uuid),
