                    ('Casting Time', 'castingTime', '{"text":"1 Action","kind":"action","value":1,"unit":"action","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Action </div> </div>', 'b87a1031-9288-4cd6-8474-20c0314c551e'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"120 ft.","kind":"distance","distanceValue":120,"distanceUnit":"ft","area":null}', '<div> <div> Range/Area </div> <div> 120 ft. </div> </div>', 'b87a1031-9288-4cd6-8474-20c0314c551e'::uuid),
                    ('Components', 'components', '{"text":"V, S","verbal":true,"somatic":true,"material":{"required":false,"description":null,"consumed":null,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S</span> </div> </div>', 'b87a1031-9288-4cd6-8474-20c0314c551e'::uuid),
                    ('Duration', 'duration', '{"text":"Instantaneous","kind":"instantaneous","value":null,"unit":null,"concentration":false,"endCondition":null}', '<div> <div>Duration</div> <div> Instantaneous </div> </div>', 'b87a1031-9288-4cd6-8474-20c0314c551e'::uuid),
                    ('School', 'school', 'Evocation', '<div> <div> School </div> <div> Evocation </div> </div>', 'b87a1031-9288-4cd6-8474-20c0314c551e'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"None","kind":"none","attackType":null,"ability":null}', '<div> <div> Attack/Save </div> <div> <span>None</span> </div> </div>', 'b87a1031-9288-4cd6-8474-20c0314c551e'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Force","damageTypes":["Force"]}', '<div> <div> Damage/Effect </div> <div> <i></i> Force </div> </div>', 'b87a1031-9288-4cd6-8474-20c0314c551e'::uuid),
                    ('Description', 'description', '["You create three glowing darts of magical force. Each dart strikes a creature of your choice that you can see within range. A dart deals 1d4 + 1 Force damage to its target. The darts all strike simultaneously, and you can direct them to hit one creature or several.","Using a Higher-Level Spell Slot. The spell creates one more dart for each spell slot level above 1."]', '<div> <p>You create three glowing darts of magical force. Each dart strikes a creature of your choice that you can see within range. A dart deals 1d4 + 1 Force damage to its target. The darts all strike simultaneously, and you can direct them to hit one creature or several.</p> <p><strong><em>Using a Higher-Level Spell Slot.</em></strong> The spell creates one more dart for each spell slot level above 1.</p> </div>', 'b87a1031-9288-4cd6-8474-20c0314c551e'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', 'b87a1031-9288-4cd6-8474-20c0314c551e'::uuid),
