                    ('Available For', 'availableFor', '["Bard (Legacy)","Wizard (Legacy)","Artificer (Legacy)","Bard","Wizard","Artificer"]', '', '473bf3bf-7b3f-42cc-be70-3184032dc81c'::uuid),
                    ('Source', 'source', 'Player’s Handbook, pg. 295', '', '473bf3bf-7b3f-42cc-be70-3184032dc81c'::uuid),
                    ('Source URL', 'url', 'https://www.dndbeyond.com/spells/2619023-magic-mouth', '', '473bf3bf-7b3f-42cc-be70-3184032dc81c'::uuid),
                    ('Image', 'imageUrl', 'https://www.dndbeyond.com/attachments/2/704/illusion.png', '', '473bf3bf-7b3f-42cc-be70-3184032dc81c'::uuid),
                    ('Level', 'level', '{"levelNumber":"Cantrip","label":"Cantrip"}', '<div> <div> Level </div> <div> Cantrip </div> </div>', '06f6ccb2-7fd5-4d1d-a534-90f111fc81eb'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Bonus Action","kind":"bonus_action","value":1,"unit":"action","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Bonus Action </div> </div>', '06f6ccb2-7fd5-4d1d-a534-90f111fc81eb'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"Touch","kind":"touch","distanceValue":null,"distanceUnit":null,"area":null}', '<div> <div> Range/Area </div> <div> Touch </div> </div>', '06f6ccb2-7fd5-4d1d-a534-90f111fc81eb'::uuid),
                    ('Components', 'components', '{"text":"V, S","verbal":true,"somatic":true,"material":{"required":false,"description":null,"consumed":null,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S</span> </div> </div>', '06f6ccb2-7fd5-4d1d-a534-90f111fc81eb'::uuid),
                    ('Duration', 'duration', '{"text":"1 Minute","kind":"timed","value":1,"unit":"minute","concentration":false,"endCondition":null}', '<div> <div>Duration</div> <div> 1 Minute </div> </div>', '06f6ccb2-7fd5-4d1d-a534-90f111fc81eb'::uuid),
                    ('School', 'school', 'Transmutation', '<div> <div> School </div> <div> Transmutation </div> </div>', '06f6ccb2-7fd5-4d1d-a534-90f111fc81eb'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"Ranged","kind":"attack","attackType":"ranged","ability":null}', '<div> <div> Attack/Save </div> <div> <i></i> <span>Ranged</span> </div> </div>', '06f6ccb2-7fd5-4d1d-a534-90f111fc81eb'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Bludgeoning","damageTypes":["Bludgeoning"]}', '<div> <div> Damage/Effect </div> <div> <i></i> Bludgeoning </div> </div>', '06f6ccb2-7fd5-4d1d-a534-90f111fc81eb'::uuid),
                    ('Description', 'description', '["You touch one to three pebbles and imbue them with magic. You or someone else can make a ranged spell attack with one of the pebbles by throwing it or hurling it with a sling. If thrown, it has a range of 60 feet. If someone else attacks with the pebble, that attacker adds your spellcasting ability modifier, not the attacker’s, to the attack roll. On a hit, the target takes bludgeoning damage equal to 1d6 + your spellcasting ability modifier. Hit or miss, the spell then ends on the stone.","If you cast this spell again, the spell ends early on any pebbles still affected by it."]', '<div> <p>You touch one to three pebbles and imbue them with magic. You or someone else can make a ranged spell attack with one of the pebbles by throwing it or hurling it with a sling. If thrown, it has a range of 60 feet. If someone else attacks with the pebble, that attacker adds your spellcasting ability modifier, not the attacker’s, to the attack roll. On a hit, the target takes bludgeoning damage equal to 1d6 + your spellcasting ability modifier. Hit or miss, the spell then ends on the stone.</p> <p>If you cast this spell again, the spell ends early on any pebbles still affected by it.</p> </div>', '06f6ccb2-7fd5-4d1d-a534-90f111fc81eb'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', '06f6ccb2-7fd5-4d1d-a534-90f111fc81eb'::uuid),
                    ('Spell Tags', 'spellTags', '["Damage"]', '', '06f6ccb2-7fd5-4d1d-a534-90f111fc81eb'::uuid),
                    ('Available For', 'availableFor', '["Druid (Legacy)","Warlock (Legacy)","Artificer (Legacy)","Druid","Warlock","Artificer"]', '', '06f6ccb2-7fd5-4d1d-a534-90f111fc81eb'::uuid),
                    ('Source', 'source', 'Elemental Evil Player''s Companion, pg. 160', '', '06f6ccb2-7fd5-4d1d-a534-90f111fc81eb'::uuid),
                    ('Source URL', 'url', 'https://www.dndbeyond.com/spells/2391-magic-stone', '', '06f6ccb2-7fd5-4d1d-a534-90f111fc81eb'::uuid),
                    ('Image', 'imageUrl', 'https://www.dndbeyond.com/attachments/2/722/transmutation.png', '', '06f6ccb2-7fd5-4d1d-a534-90f111fc81eb'::uuid),
                    ('Level', 'level', '{"levelNumber":"2","label":"2nd"}', '<div> <div> Level </div> <div> 2nd </div> </div>', 'ddaa3cc2-91be-4837-bbf2-0a61bce9b49f'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Bonus Action","kind":"bonus_action","value":1,"unit":"action","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Bonus Action </div> </div>', 'ddaa3cc2-91be-4837-bbf2-0a61bce9b49f'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"Touch","kind":"touch","distanceValue":null,"distanceUnit":null,"area":null}', '<div> <div> Range/Area </div> <div> Touch </div> </div>', 'ddaa3cc2-91be-4837-bbf2-0a61bce9b49f'::uuid),
                    ('Components', 'components', '{"text":"V, S","verbal":true,"somatic":true,"material":{"required":false,"description":null,"consumed":null,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S</span> </div> </div>', 'ddaa3cc2-91be-4837-bbf2-0a61bce9b49f'::uuid),
                    ('Duration', 'duration', '{"text":"1 Hour","kind":"timed","value":1,"unit":"hour","concentration":false,"endCondition":null}', '<div> <div>Duration</div> <div> 1 Hour </div> </div>', 'ddaa3cc2-91be-4837-bbf2-0a61bce9b49f'::uuid),
                    ('School', 'school', 'Transmutation', '<div> <div> School </div> <div> Transmutation </div> </div>', 'ddaa3cc2-91be-4837-bbf2-0a61bce9b49f'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"None","kind":"none","attackType":null,"ability":null}', '<div> <div> Attack/Save </div> <div> <span>None</span> </div> </div>', 'ddaa3cc2-91be-4837-bbf2-0a61bce9b49f'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Buff","damageTypes":[]}', '<div> <div> Damage/Effect </div> <div> Buff </div> </div>', 'ddaa3cc2-91be-4837-bbf2-0a61bce9b49f'::uuid),
                    ('Description', 'description', '["You touch a nonmagical weapon. Until the spell ends, that weapon becomes a magic weapon with a +1 bonus to attack rolls and damage rolls. The spell ends early if you cast it again.","Using a Higher-Level Spell Slot. The bonus increases to +2 with a level 3–5 spell slot. The bonus increases to +3 with a level 6+ spell slot."]', '<div> <p>You touch a nonmagical weapon. Until the spell ends, that weapon becomes a magic weapon with a +1 bonus to attack rolls and damage rolls. The spell ends early if you cast it again.</p> <p><strong><em>Using a Higher-Level Spell Slot.</em></strong> The bonus increases to +2 with a level 3–5 spell slot. The bonus increases to +3 with a level 6+ spell slot.</p> </div>', 'ddaa3cc2-91be-4837-bbf2-0a61bce9b49f'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', 'ddaa3cc2-91be-4837-bbf2-0a61bce9b49f'::uuid),
                    ('Spell Tags', 'spellTags', '["Buff"]', '', 'ddaa3cc2-91be-4837-bbf2-0a61bce9b49f'::uuid),
                    ('Available For', 'availableFor', '["Paladin (Legacy)","Ranger (Legacy)","Sorcerer (Legacy)","Wizard (Legacy)","Artificer (Legacy)","Paladin","Ranger","Sorcerer","Wizard","Artificer","Cleric - War Domain","Cleric - Arcana Domain (SCAG)","Cleric - Forge Domain (XGtE)","Paladin - Oath of Glory"]', '', 'ddaa3cc2-91be-4837-bbf2-0a61bce9b49f'::uuid),
                    ('Source', 'source', 'Player’s Handbook, pg. 295', '', 'ddaa3cc2-91be-4837-bbf2-0a61bce9b49f'::uuid),
                    ('Source URL', 'url', 'https://www.dndbeyond.com/spells/2619024-magic-weapon', '', 'ddaa3cc2-91be-4837-bbf2-0a61bce9b49f'::uuid),
                    ('Image', 'imageUrl', 'https://www.dndbeyond.com/attachments/2/722/transmutation.png', '', 'ddaa3cc2-91be-4837-bbf2-0a61bce9b49f'::uuid),
                    ('Level', 'level', '{"levelNumber":"7","label":"7th"}', '<div> <div> Level </div> <div> 7th </div> </div>', 'c1b87752-7d89-4cad-82e6-b683299cfdcd'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Minute","kind":"timed","value":1,"unit":"minute","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Minute </div> </div>', 'c1b87752-7d89-4cad-82e6-b683299cfdcd'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"300 ft. (*)","kind":"distance","distanceValue":300,"distanceUnit":"ft","area":null}', '<div> <div> Range/Area </div> <div> 300 ft. <span>(<i></i>*)</span> </div> </div>', 'c1b87752-7d89-4cad-82e6-b683299cfdcd'::uuid),
                    ('Components', 'components', '{"text":"V, S, M *","verbal":true,"somatic":true,"material":{"required":true,"description":"a miniature portal carved from ivory, a small piece of polished marble, and a tiny silver spoon, each item worth at least 5 gp","consumed":false,"costGp":5}}', '<div> <div> Components </div> <div> <span>V, S, M *</span> </div> </div>', 'c1b87752-7d89-4cad-82e6-b683299cfdcd'::uuid),
                    ('Duration', 'duration', '{"text":"24 Hours","kind":"timed","value":24,"unit":"hour","concentration":false,"endCondition":null}', '<div> <div>Duration</div> <div> 24 Hours </div> </div>', 'c1b87752-7d89-4cad-82e6-b683299cfdcd'::uuid),
                    ('School', 'school', 'Conjuration', '<div> <div> School </div> <div> Conjuration </div> </div>', 'c1b87752-7d89-4cad-82e6-b683299cfdcd'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"None","kind":"none","attackType":null,"ability":null}', '<div> <div> Attack/Save </div> <div> <span>None</span> </div> </div>', 'c1b87752-7d89-4cad-82e6-b683299cfdcd'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Exploration (...)","damageTypes":[]}', '<div> <div> Damage/Effect </div> <div> Exploration (...) </div> </div>', 'c1b87752-7d89-4cad-82e6-b683299cfdcd'::uuid),
                    ('Description', 'description', '["You conjure an extradimensional dwelling in range that lasts for the duration. You choose where its one entrance is located. The entrance shimmers faintly and is 5 feet wide and 10 feet tall. You and any creature you designate when you cast the spell can enter the extradimensional dwelling as long as the portal remains open. You can open or close the portal if you are within 30 feet of it. While closed, the portal is invisible.","Beyond the portal is a magnificent foyer with numerous chambers beyond. The atmosphere is clean, fresh, and warm.","You can create any floor plan you like, but the space can’t exceed 50 cubes, each cube being 10 feet on each side. The place is furnished and decorated as you choose. It contains sufficient food to serve a nine-course banquet for up to 100 people. A staff of 100 near-transparent servants attends all who enter. You decide the visual appearance of these servants and their attire. They are completely obedient to your orders. Each servant can perform any task a normal human servant could perform, but they can’t attack or take any action that would directly harm another creature. Thus the servants can fetch things, clean, mend, fold clothes, light fires, serve food, pour wine, and so on. The servants can go anywhere in the mansion but can’t leave it. Furnishings and other objects created by this spell dissipate into smoke if removed from the mansion. When the spell ends, any creatures or objects left inside the extradimensional space are expelled into the open spaces nearest to the entrance."]', '<div> <p>You conjure an extradimensional dwelling in range that lasts for the duration. You choose where its one entrance is located. The entrance shimmers faintly and is 5 feet wide and 10 feet tall. You and any creature you designate when you cast the spell can enter the extradimensional dwelling as long as the portal remains open. You can open or close the portal if you are within 30 feet of it. While closed, the portal is invisible.</p> <p>Beyond the portal is a magnificent foyer with numerous chambers beyond. The atmosphere is clean, fresh, and warm.</p> <p>You can create any floor plan you like, but the space can’t exceed 50 cubes, each cube being 10 feet on each side. The place is furnished and decorated as you choose. It contains sufficient food to serve a nine-course banquet for up to 100 people. A staff of 100 near-transparent servants attends all who enter. You decide the visual appearance of these servants and their attire. They are completely obedient to your orders. Each servant can perform any task a normal human servant could perform, but they can’t attack or take any action that would directly harm another creature. Thus the servants can fetch things, clean, mend, fold clothes, light fires, serve food, pour wine, and so on. The servants can go anywhere in the mansion but can’t leave it. Furnishings and other objects created by this spell dissipate into smoke if removed from the mansion. When the spell ends, any creatures or objects left inside the extradimensional space are expelled into the open spaces nearest to the entrance.</p> <span>* - (a miniature portal carved from ivory, a small piece of polished marble, and a tiny silver spoon, each item worth at least 5 gp)</span> </div>', 'c1b87752-7d89-4cad-82e6-b683299cfdcd'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', 'c1b87752-7d89-4cad-82e6-b683299cfdcd'::uuid),
                    ('Spell Tags', 'spellTags', '["Utility","Exploration"]', '', 'c1b87752-7d89-4cad-82e6-b683299cfdcd'::uuid),
                    ('Available For', 'availableFor', '["Bard (Legacy)","Wizard (Legacy)"]', '', 'c1b87752-7d89-4cad-82e6-b683299cfdcd'::uuid),
                    ('Source', 'source', 'Basic Rules (2014)', '', 'c1b87752-7d89-4cad-82e6-b683299cfdcd'::uuid),
                    ('Source URL', 'url', 'https://www.dndbeyond.com/spells/2179-magnificent-mansion', '', 'c1b87752-7d89-4cad-82e6-b683299cfdcd'::uuid),
                    ('Image', 'imageUrl', 'https://www.dndbeyond.com/attachments/2/708/conjuration.png', '', 'c1b87752-7d89-4cad-82e6-b683299cfdcd'::uuid);
                """);

            migrationBuilder.Sql("""
                INSERT INTO "SpellComponents" ("Label", "Key", "Value", "Html", "SpellId") VALUES
                    ('Level', 'level', '{"levelNumber":"3","label":"3rd"}', '<div> <div> Level </div> <div> 3rd </div> </div>', 'cce81863-815e-406c-bfc8-edf780c4de8c'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Action","kind":"action","value":1,"unit":"action","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Action </div> </div>', 'cce81863-815e-406c-bfc8-edf780c4de8c'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"120 ft. (20 ft. *)","kind":"distance","distanceValue":120,"distanceUnit":"ft","area":{"shape":null,"value":20,"unit":"ft"}}', '<div> <div> Range/Area </div> <div> 120 ft. <span>(20 ft. <i></i> *)</span> </div> </div>', 'cce81863-815e-406c-bfc8-edf780c4de8c'::uuid),
                    ('Components', 'components', '{"text":"V, S, M *","verbal":true,"somatic":true,"material":{"required":true,"description":"a bit of fleece","consumed":false,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S, M *</span> </div> </div>', 'cce81863-815e-406c-bfc8-edf780c4de8c'::uuid),
                    ('Duration', 'duration', '{"text":"Concentration 10 Minutes","kind":"timed","value":10,"unit":"minute","concentration":true,"endCondition":null}', '<div> <div>Duration</div> <div> <i>Concentration</i> 10 Minutes </div> </div>', 'cce81863-815e-406c-bfc8-edf780c4de8c'::uuid),
                    ('School', 'school', 'Illusion', '<div> <div> School </div> <div> Illusion </div> </div>', 'cce81863-815e-406c-bfc8-edf780c4de8c'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"None","kind":"none","attackType":null,"ability":null}', '<div> <div> Attack/Save </div> <div> <span>None</span> </div> </div>', 'cce81863-815e-406c-bfc8-edf780c4de8c'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Control","damageTypes":[]}', '<div> <div> Damage/Effect </div> <div> Control </div> </div>', 'cce81863-815e-406c-bfc8-edf780c4de8c'::uuid),
                    ('Description', 'description', '["You create the image of an object, a creature, or some other visible phenomenon that is no larger than a 20-foot Cube . The image appears at a spot that you can see within range and lasts for the duration. It seems real, including sounds, smells, and temperature appropriate to the thing depicted, but it can’t deal damage or cause conditions.","If you are within range of the illusion, you can take a Magic action to cause the image to move to any other spot within range. As the image changes location, you can alter its appearance so that its movements appear natural for the image. For example, if you create an image of a creature and move it, you can alter the image so that it appears to be walking. Similarly, you can cause the illusion to make different sounds at different times, even making it carry on a conversation, for example.","Physical interaction with the image reveals it to be an illusion, for things can pass through it. A creature that takes a Study action to examine the image can determine that it is an illusion with a successful Intelligence ( Investigation ) check against your spell save DC. If a creature discerns the illusion for what it is, the creature can see through the image, and its other sensory qualities become faint to the creature.","Using a Higher-Level Spell Slot. The spell lasts until dispelled, without requiring Concentration , if cast with a level 4+ spell slot."]', '<div> <p>You create the image of an object, a creature, or some other visible phenomenon that is no larger than a 20-foot <a>Cube</a>. The image appears at a spot that you can see within range and lasts for the duration. It seems real, including sounds, smells, and temperature appropriate to the thing depicted, but it can’t deal damage or cause conditions.</p> <p>If you are within range of the illusion, you can take a <a>Magic</a> action to cause the image to move to any other spot within range. As the image changes location, you can alter its appearance so that its movements appear natural for the image. For example, if you create an image of a creature and move it, you can alter the image so that it appears to be walking. Similarly, you can cause the illusion to make different sounds at different times, even making it carry on a conversation, for example.</p> <p>Physical interaction with the image reveals it to be an illusion, for things can pass through it. A creature that takes a <a>Study</a> action to examine the image can determine that it is an illusion with a successful Intelligence (<a>Investigation</a>) check against your spell save DC. If a creature discerns the illusion for what it is, the creature can see through the image, and its other sensory qualities become faint to the creature.</p> <p><strong><em>Using a Higher-Level Spell Slot.</em></strong> The spell lasts until dispelled, without requiring <a>Concentration</a>, if cast with a level 4+ spell slot.</p> <span>* - (a bit of fleece)</span> </div>', 'cce81863-815e-406c-bfc8-edf780c4de8c'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', 'cce81863-815e-406c-bfc8-edf780c4de8c'::uuid),
                    ('Spell Tags', 'spellTags', '["Control"]', '', 'cce81863-815e-406c-bfc8-edf780c4de8c'::uuid),
                    ('Available For', 'availableFor', '["Bard (Legacy)","Sorcerer (Legacy)","Warlock (Legacy)","Wizard (Legacy)","Bard","Sorcerer","Warlock","Wizard","Illrigger - Architect of Ruin","Cleric - Moon Domain (TCSR)"]', '', 'cce81863-815e-406c-bfc8-edf780c4de8c'::uuid),
                    ('Source', 'source', 'Player’s Handbook, pg. 295', '', 'cce81863-815e-406c-bfc8-edf780c4de8c'::uuid),
                    ('Source URL', 'url', 'https://www.dndbeyond.com/spells/2619025-major-image', '', 'cce81863-815e-406c-bfc8-edf780c4de8c'::uuid),
                    ('Image', 'imageUrl', 'https://www.dndbeyond.com/attachments/2/704/illusion.png', '', 'cce81863-815e-406c-bfc8-edf780c4de8c'::uuid),
                    ('Level', 'level', '{"levelNumber":"5","label":"5th"}', '<div> <div> Level </div> <div> 5th </div> </div>', '0ba20d16-60a9-4f9e-812b-ec41f1ca7601'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Action","kind":"action","value":1,"unit":"action","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Action </div> </div>', '0ba20d16-60a9-4f9e-812b-ec41f1ca7601'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"60 ft. (30 ft.)","kind":"distance","distanceValue":60,"distanceUnit":"ft","area":{"shape":null,"value":30,"unit":"ft"}}', '<div> <div> Range/Area </div> <div> 60 ft. <span>(30 ft. <i></i>)</span> </div> </div>', '0ba20d16-60a9-4f9e-812b-ec41f1ca7601'::uuid),
                    ('Components', 'components', '{"text":"V, S","verbal":true,"somatic":true,"material":{"required":false,"description":null,"consumed":null,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S</span> </div> </div>', '0ba20d16-60a9-4f9e-812b-ec41f1ca7601'::uuid),
                    ('Duration', 'duration', '{"text":"Instantaneous","kind":"instantaneous","value":null,"unit":null,"concentration":false,"endCondition":null}', '<div> <div>Duration</div> <div> Instantaneous </div> </div>', '0ba20d16-60a9-4f9e-812b-ec41f1ca7601'::uuid),
                    ('School', 'school', 'Abjuration', '<div> <div> School </div> <div> Abjuration </div> </div>', '0ba20d16-60a9-4f9e-812b-ec41f1ca7601'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"None","kind":"none","attackType":null,"ability":null}', '<div> <div> Attack/Save </div> <div> <span>None</span> </div> </div>', '0ba20d16-60a9-4f9e-812b-ec41f1ca7601'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Healing","damageTypes":[]}', '<div> <div> Damage/Effect </div> <div> Healing </div> </div>', '0ba20d16-60a9-4f9e-812b-ec41f1ca7601'::uuid),
                    ('Description', 'description', '["A wave of healing energy washes out from a point you can see within range. Choose up to six creatures in a 30-foot-radius Sphere centered on that point. Each target regains Hit Points equal to 5d8 plus your spellcasting ability modifier.","Using a Higher-Level Spell Slot. The healing increases by 1d8 for each spell slot level above 5."]', '<div> <p>A wave of healing energy washes out from a point you can see within range. Choose up to six creatures in a 30-foot-radius <a>Sphere</a> centered on that point. Each target regains Hit Points equal to 5d8 plus your spellcasting ability modifier.</p> <p><strong><em>Using a Higher-Level Spell Slot.</em></strong> The healing increases by 1d8 for each spell slot level above 5.</p> </div>', '0ba20d16-60a9-4f9e-812b-ec41f1ca7601'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', '0ba20d16-60a9-4f9e-812b-ec41f1ca7601'::uuid),
                    ('Spell Tags', 'spellTags', '["Healing"]', '', '0ba20d16-60a9-4f9e-812b-ec41f1ca7601'::uuid),
                    ('Available For', 'availableFor', '["Bard (Legacy)","Cleric (Legacy)","Druid (Legacy)","Bard","Cleric","Druid","Cleric - Life Domain","Druid - Circle of Wildfire (TCoE)","Paladin - Oath of the Harvest (HGtMH1)","Sorcerer - Crimson Sorcery","Cleric - Community Domain (HCS)","Paladin - Oath of the River (OTTG)"]', '', '0ba20d16-60a9-4f9e-812b-ec41f1ca7601'::uuid),
                    ('Source', 'source', 'Player’s Handbook, pg. 296', '', '0ba20d16-60a9-4f9e-812b-ec41f1ca7601'::uuid),
                    ('Source URL', 'url', 'https://www.dndbeyond.com/spells/2619026-mass-cure-wounds', '', '0ba20d16-60a9-4f9e-812b-ec41f1ca7601'::uuid),
                    ('Image', 'imageUrl', 'https://www.dndbeyond.com/attachments/2/707/abjuration.png', '', '0ba20d16-60a9-4f9e-812b-ec41f1ca7601'::uuid),
                    ('Level', 'level', '{"levelNumber":"9","label":"9th"}', '<div> <div> Level </div> <div> 9th </div> </div>', '423938a8-bc96-4e7c-a187-3f66dd96ea2d'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Action","kind":"action","value":1,"unit":"action","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Action </div> </div>', '423938a8-bc96-4e7c-a187-3f66dd96ea2d'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"60 ft.","kind":"distance","distanceValue":60,"distanceUnit":"ft","area":null}', '<div> <div> Range/Area </div> <div> 60 ft. </div> </div>', '423938a8-bc96-4e7c-a187-3f66dd96ea2d'::uuid),
                    ('Components', 'components', '{"text":"V, S","verbal":true,"somatic":true,"material":{"required":false,"description":null,"consumed":null,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S</span> </div> </div>', '423938a8-bc96-4e7c-a187-3f66dd96ea2d'::uuid),
                    ('Duration', 'duration', '{"text":"Instantaneous","kind":"instantaneous","value":null,"unit":null,"concentration":false,"endCondition":null}', '<div> <div>Duration</div> <div> Instantaneous </div> </div>', '423938a8-bc96-4e7c-a187-3f66dd96ea2d'::uuid),
                    ('School', 'school', 'Abjuration', '<div> <div> School </div> <div> Abjuration </div> </div>', '423938a8-bc96-4e7c-a187-3f66dd96ea2d'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"None","kind":"none","attackType":null,"ability":null}', '<div> <div> Attack/Save </div> <div> <span>None</span> </div> </div>', '423938a8-bc96-4e7c-a187-3f66dd96ea2d'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Blinded (...)","damageTypes":[]}', '<div> <div> Damage/Effect </div> <div> <i></i> Blinded (...) </div> </div>', '423938a8-bc96-4e7c-a187-3f66dd96ea2d'::uuid),
                    ('Description', 'description', '["A flood of healing energy flows from you into creatures around you. You restore up to 700 Hit Points, divided as you choose among any number of creatures that you can see within range. Creatures healed by this spell also have the Blinded , Deafened , and Poisoned conditions removed from them."]', '<div> <p>A flood of healing energy flows from you into creatures around you. You restore up to 700 Hit Points, divided as you choose among any number of creatures that you can see within range. Creatures healed by this spell also have the <a>Blinded</a>, <a>Deafened</a>, and <a>Poisoned</a> conditions removed from them.</p> </div>', '423938a8-bc96-4e7c-a187-3f66dd96ea2d'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', '423938a8-bc96-4e7c-a187-3f66dd96ea2d'::uuid),
