                    ('Available For', 'availableFor', '["Cleric (Legacy)","Cleric"]', '', '423938a8-bc96-4e7c-a187-3f66dd96ea2d'::uuid),
                    ('Source', 'source', 'Player’s Handbook, pg. 296', '', '423938a8-bc96-4e7c-a187-3f66dd96ea2d'::uuid),
                    ('Source URL', 'url', 'https://www.dndbeyond.com/spells/2619027-mass-heal', '', '423938a8-bc96-4e7c-a187-3f66dd96ea2d'::uuid),
                    ('Image', 'imageUrl', 'https://www.dndbeyond.com/attachments/2/707/abjuration.png', '', '423938a8-bc96-4e7c-a187-3f66dd96ea2d'::uuid),
                    ('Level', 'level', '{"levelNumber":"3","label":"3rd"}', '<div> <div> Level </div> <div> 3rd </div> </div>', '67730373-33d8-4fe7-9273-93c8d9fd6562'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Bonus Action","kind":"bonus_action","value":1,"unit":"action","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Bonus Action </div> </div>', '67730373-33d8-4fe7-9273-93c8d9fd6562'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"60 ft.","kind":"distance","distanceValue":60,"distanceUnit":"ft","area":null}', '<div> <div> Range/Area </div> <div> 60 ft. </div> </div>', '67730373-33d8-4fe7-9273-93c8d9fd6562'::uuid),
                    ('Components', 'components', '{"text":"V","verbal":true,"somatic":false,"material":{"required":false,"description":null,"consumed":null,"costGp":null}}', '<div> <div> Components </div> <div> <span>V</span> </div> </div>', '67730373-33d8-4fe7-9273-93c8d9fd6562'::uuid),
                    ('Duration', 'duration', '{"text":"Instantaneous","kind":"instantaneous","value":null,"unit":null,"concentration":false,"endCondition":null}', '<div> <div>Duration</div> <div> Instantaneous </div> </div>', '67730373-33d8-4fe7-9273-93c8d9fd6562'::uuid),
                    ('School', 'school', 'Abjuration', '<div> <div> School </div> <div> Abjuration </div> </div>', '67730373-33d8-4fe7-9273-93c8d9fd6562'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"None","kind":"none","attackType":null,"ability":null}', '<div> <div> Attack/Save </div> <div> <span>None</span> </div> </div>', '67730373-33d8-4fe7-9273-93c8d9fd6562'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Healing","damageTypes":[]}', '<div> <div> Damage/Effect </div> <div> Healing </div> </div>', '67730373-33d8-4fe7-9273-93c8d9fd6562'::uuid),
                    ('Description', 'description', '["Up to six creatures of your choice that you can see within range regain Hit Points equal to 2d4 plus your spellcasting ability modifier.","Using a Higher-Level Spell Slot. The healing increases by 1d4 for each spell slot level above 3."]', '<div> <p>Up to six creatures of your choice that you can see within range regain Hit Points equal to 2d4 plus your spellcasting ability modifier.</p> <p><strong><em>Using a Higher-Level Spell Slot.</em></strong> The healing increases by 1d4 for each spell slot level above 3.</p> </div>', '67730373-33d8-4fe7-9273-93c8d9fd6562'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', '67730373-33d8-4fe7-9273-93c8d9fd6562'::uuid),
                    ('Spell Tags', 'spellTags', '["Healing"]', '', '67730373-33d8-4fe7-9273-93c8d9fd6562'::uuid),
                    ('Available For', 'availableFor', '["Bard (Legacy)","Cleric (Legacy)","Bard","Cleric","Cleric - Life Domain","Cleric - Order Domain (TCoE)"]', '', '67730373-33d8-4fe7-9273-93c8d9fd6562'::uuid),
                    ('Source', 'source', 'Player’s Handbook, pg. 296', '', '67730373-33d8-4fe7-9273-93c8d9fd6562'::uuid),
                    ('Source URL', 'url', 'https://www.dndbeyond.com/spells/2619028-mass-healing-word', '', '67730373-33d8-4fe7-9273-93c8d9fd6562'::uuid),
