                    ('Level', 'level', '{"levelNumber":"2","label":"2nd"}', '<div> <div> Level </div> <div> 2nd </div> </div>', '6a28f1a5-e4f0-4b9a-a641-631c856133f4'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Action","kind":"action","value":1,"unit":"action","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Action </div> </div>', '6a28f1a5-e4f0-4b9a-a641-631c856133f4'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"90 ft.","kind":"distance","distanceValue":90,"distanceUnit":"ft","area":null}', '<div> <div> Range/Area </div> <div> 90 ft. </div> </div>', '6a28f1a5-e4f0-4b9a-a641-631c856133f4'::uuid),
                    ('Components', 'components', '{"text":"V, S, M *","verbal":true,"somatic":true,"material":{"required":true,"description":"powdered rhubarb leaf","consumed":false,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S, M *</span> </div> </div>', '6a28f1a5-e4f0-4b9a-a641-631c856133f4'::uuid),
                    ('Duration', 'duration', '{"text":"Instantaneous","kind":"instantaneous","value":null,"unit":null,"concentration":false,"endCondition":null}', '<div> <div>Duration</div> <div> Instantaneous </div> </div>', '6a28f1a5-e4f0-4b9a-a641-631c856133f4'::uuid),
                    ('School', 'school', 'Evocation', '<div> <div> School </div> <div> Evocation </div> </div>', '6a28f1a5-e4f0-4b9a-a641-631c856133f4'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"Ranged","kind":"attack","attackType":"ranged","ability":null}', '<div> <div> Attack/Save </div> <div> <i></i> <span>Ranged</span> </div> </div>', '6a28f1a5-e4f0-4b9a-a641-631c856133f4'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Acid (...)","damageTypes":["Acid"]}', '<div> <div> Damage/Effect </div> <div> <i></i> Acid (...) </div> </div>', '6a28f1a5-e4f0-4b9a-a641-631c856133f4'::uuid),
                    ('Description', 'description', '["A shimmering green arrow streaks toward a target within range and bursts in a spray of acid. Make a ranged spell attack against the target. On a hit, the target takes 4d4 Acid damage and 2d4 Acid damage at the end of its next turn. On a miss, the arrow splashes the target with acid for half as much of the initial damage only.","Using a Higher-Level Spell Slot. The damage (both initial and later) increases by 1d4 for each spell slot level above 2."]', '<div> <p>A shimmering green arrow streaks toward a target within range and bursts in a spray of acid. Make a ranged spell attack against the target. On a hit, the target takes 4d4 Acid damage and 2d4 Acid damage at the end of its next turn. On a miss, the arrow splashes the target with acid for half as much of the initial damage only.</p> <p><strong><em>Using a Higher-Level Spell Slot.</em></strong> The damage (both initial and later) increases by 1d4 for each spell slot level above 2.</p> <span>* - (powdered rhubarb leaf)</span> </div>', '6a28f1a5-e4f0-4b9a-a641-631c856133f4'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', '6a28f1a5-e4f0-4b9a-a641-631c856133f4'::uuid),
