                    ('Available For', 'availableFor', '["Wizard (Legacy)","Wizard"]', '', '6a28f1a5-e4f0-4b9a-a641-631c856133f4'::uuid),
                    ('Source', 'source', 'Player’s Handbook, pg. 297', '', '6a28f1a5-e4f0-4b9a-a641-631c856133f4'::uuid),
                    ('Source URL', 'url', 'https://www.dndbeyond.com/spells/2619032-melfs-acid-arrow', '', '6a28f1a5-e4f0-4b9a-a641-631c856133f4'::uuid),
                    ('Image', 'imageUrl', 'https://www.dndbeyond.com/attachments/2/703/evocation.png', '', '6a28f1a5-e4f0-4b9a-a641-631c856133f4'::uuid),
                    ('Level', 'level', '{"levelNumber":"3","label":"3rd"}', '<div> <div> Level </div> <div> 3rd </div> </div>', '712c6720-329e-4d13-b572-6660758540e6'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Action","kind":"action","value":1,"unit":"action","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Action </div> </div>', '712c6720-329e-4d13-b572-6660758540e6'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"Self","kind":"self","distanceValue":null,"distanceUnit":null,"area":null}', '<div> <div> Range/Area </div> <div> Self </div> </div>', '712c6720-329e-4d13-b572-6660758540e6'::uuid),
                    ('Components', 'components', '{"text":"V, S, M *","verbal":true,"somatic":true,"material":{"required":true,"description":"niter, sulfur, and pine tar formed into a bead","consumed":false,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S, M *</span> </div> </div>', '712c6720-329e-4d13-b572-6660758540e6'::uuid),
                    ('Duration', 'duration', '{"text":"Concentration 10 Minutes","kind":"timed","value":10,"unit":"minute","concentration":true,"endCondition":null}', '<div> <div>Duration</div> <div> <i>Concentration</i> 10 Minutes </div> </div>', '712c6720-329e-4d13-b572-6660758540e6'::uuid),
                    ('School', 'school', 'Evocation', '<div> <div> School </div> <div> Evocation </div> </div>', '712c6720-329e-4d13-b572-6660758540e6'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"DEX Save","kind":"save","attackType":null,"ability":"DEX"}', '<div> <div> Attack/Save </div> <div> <i></i> <span>DEX Save</span> </div> </div>', '712c6720-329e-4d13-b572-6660758540e6'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Fire","damageTypes":["Fire"]}', '<div> <div> Damage/Effect </div> <div> <i></i> Fire </div> </div>', '712c6720-329e-4d13-b572-6660758540e6'::uuid),
                    ('Description', 'description', '["You create six tiny meteors in your space. They float in the air and orbit you for the spell’s duration. When you cast the spell — and as a bonus action on each of your turns thereafter — you can expend one or two of the meteors, sending them streaking toward a point or points you choose within 120 feet of you. Once a meteor reaches its destination or impacts against a solid surface, the meteor explodes. Each creature within 5 feet of the point where the meteor explodes must make a Dexterity saving throw. A creature takes 2d6 fire damage on a failed save, or half as much damage on a successful one.","At Higher Levels. When you cast this spell using a spell slot of 4th level or higher, the number of meteors created increases by two for each slot level above 3rd."]', '<div> <p>You create six tiny meteors in your space. They float in the air and orbit you for the spell’s duration. When you cast the spell — and as a bonus action on each of your turns thereafter — you can expend one or two of the meteors, sending them streaking toward a point or points you choose within 120 feet of you. Once a meteor reaches its destination or impacts against a solid surface, the meteor explodes. Each creature within 5 feet of the point where the meteor explodes must make a Dexterity saving throw. A creature takes 2d6 fire damage on a failed save, or half as much damage on a successful one.</p> <p><strong>At Higher Levels.</strong> <span>When you cast this spell using a spell slot of 4th level or higher, the number of meteors created increases by two for each slot level above 3rd.</span></p> <span>* - (niter, sulfur, and pine tar formed into a bead)</span> </div>', '712c6720-329e-4d13-b572-6660758540e6'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', '712c6720-329e-4d13-b572-6660758540e6'::uuid),
