                    ('Image', 'imageUrl', 'https://www.dndbeyond.com/attachments/2/703/evocation.png', '', '712c6720-329e-4d13-b572-6660758540e6'::uuid),
                    ('Level', 'level', '{"levelNumber":"Cantrip","label":"Cantrip"}', '<div> <div> Level </div> <div> Cantrip </div> </div>', '29fd18ea-089a-4c1b-adce-f6b79e6e9830'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Minute","kind":"timed","value":1,"unit":"minute","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Minute </div> </div>', '29fd18ea-089a-4c1b-adce-f6b79e6e9830'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"Touch","kind":"touch","distanceValue":null,"distanceUnit":null,"area":null}', '<div> <div> Range/Area </div> <div> Touch </div> </div>', '29fd18ea-089a-4c1b-adce-f6b79e6e9830'::uuid),
                    ('Components', 'components', '{"text":"V, S, M *","verbal":true,"somatic":true,"material":{"required":true,"description":"two lodestones","consumed":false,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S, M *</span> </div> </div>', '29fd18ea-089a-4c1b-adce-f6b79e6e9830'::uuid),
                    ('Duration', 'duration', '{"text":"Instantaneous","kind":"instantaneous","value":null,"unit":null,"concentration":false,"endCondition":null}', '<div> <div>Duration</div> <div> Instantaneous </div> </div>', '29fd18ea-089a-4c1b-adce-f6b79e6e9830'::uuid),
                    ('School', 'school', 'Transmutation', '<div> <div> School </div> <div> Transmutation </div> </div>', '29fd18ea-089a-4c1b-adce-f6b79e6e9830'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"None","kind":"none","attackType":null,"ability":null}', '<div> <div> Attack/Save </div> <div> <span>None</span> </div> </div>', '29fd18ea-089a-4c1b-adce-f6b79e6e9830'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Utility","damageTypes":[]}', '<div> <div> Damage/Effect </div> <div> Utility </div> </div>', '29fd18ea-089a-4c1b-adce-f6b79e6e9830'::uuid),
                    ('Description', 'description', '["This spell repairs a single break or tear in an object you touch, such as a broken chain link, two halves of a broken key, a torn cloak, or a leaking wineskin. As long as the break or tear is no larger than 1 foot in any dimension, you mend it, leaving no trace of the former damage.","This spell can physically repair a magic item, but it can’t restore magic to such an object."]', '<div> <p>This spell repairs a single break or tear in an object you touch, such as a broken chain link, two halves of a broken key, a torn cloak, or a leaking wineskin. As long as the break or tear is no larger than 1 foot in any dimension, you mend it, leaving no trace of the former damage.</p> <p>This spell can physically repair a magic item, but it can’t restore magic to such an object.</p> <span>* - (two lodestones)</span> </div>', '29fd18ea-089a-4c1b-adce-f6b79e6e9830'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', '29fd18ea-089a-4c1b-adce-f6b79e6e9830'::uuid),
                    ('Spell Tags', 'spellTags', '["Utility"]', '', '29fd18ea-089a-4c1b-adce-f6b79e6e9830'::uuid),
                    ('Available For', 'availableFor', '["Bard (Legacy)","Cleric (Legacy)","Druid (Legacy)","Sorcerer (Legacy)","Wizard (Legacy)","Artificer (Legacy)","Bard","Cleric","Druid","Sorcerer","Wizard","Fighter - Bonesmith"]', '', '29fd18ea-089a-4c1b-adce-f6b79e6e9830'::uuid),
                    ('Source', 'source', 'Player’s Handbook, pg. 297', '', '29fd18ea-089a-4c1b-adce-f6b79e6e9830'::uuid),
                    ('Source URL', 'url', 'https://www.dndbeyond.com/spells/2619033-mending', '', '29fd18ea-089a-4c1b-adce-f6b79e6e9830'::uuid),
                    ('Image', 'imageUrl', 'https://www.dndbeyond.com/attachments/2/722/transmutation.png', '', '29fd18ea-089a-4c1b-adce-f6b79e6e9830'::uuid),
                    ('Level', 'level', '{"levelNumber":"Cantrip","label":"Cantrip"}', '<div> <div> Level </div> <div> Cantrip </div> </div>', 'c3b322d5-191d-429f-8ac1-0a6c2779b903'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Action","kind":"action","value":1,"unit":"action","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Action </div> </div>', 'c3b322d5-191d-429f-8ac1-0a6c2779b903'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"120 ft.","kind":"distance","distanceValue":120,"distanceUnit":"ft","area":null}', '<div> <div> Range/Area </div> <div> 120 ft. </div> </div>', 'c3b322d5-191d-429f-8ac1-0a6c2779b903'::uuid),
                    ('Components', 'components', '{"text":"S, M *","verbal":false,"somatic":true,"material":{"required":true,"description":"a copper wire","consumed":false,"costGp":null}}', '<div> <div> Components </div> <div> <span>S, M *</span> </div> </div>', 'c3b322d5-191d-429f-8ac1-0a6c2779b903'::uuid),
                    ('Duration', 'duration', '{"text":"1 Round","kind":"timed","value":1,"unit":"round","concentration":false,"endCondition":null}', '<div> <div>Duration</div> <div> 1 Round </div> </div>', 'c3b322d5-191d-429f-8ac1-0a6c2779b903'::uuid),
                    ('School', 'school', 'Transmutation', '<div> <div> School </div> <div> Transmutation </div> </div>', 'c3b322d5-191d-429f-8ac1-0a6c2779b903'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"None","kind":"none","attackType":null,"ability":null}', '<div> <div> Attack/Save </div> <div> <span>None</span> </div> </div>', 'c3b322d5-191d-429f-8ac1-0a6c2779b903'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Communication (...)","damageTypes":[]}', '<div> <div> Damage/Effect </div> <div> Communication (...) </div> </div>', 'c3b322d5-191d-429f-8ac1-0a6c2779b903'::uuid),
                    ('Description', 'description', '["You point toward a creature within range and whisper a message. The target (and only the target) hears the message and can reply in a whisper that only you can hear.","You can cast this spell through solid objects if you are familiar with the target and know it is beyond the barrier. Magical silence; 1 foot of stone, metal, or wood; or a thin sheet of lead blocks the spell."]', '<div> <p>You point toward a creature within range and whisper a message. The target (and only the target) hears the message and can reply in a whisper that only you can hear.</p> <p>You can cast this spell through solid objects if you are familiar with the target and know it is beyond the barrier. Magical silence; 1 foot of stone, metal, or wood; or a thin sheet of lead blocks the spell.</p> <span>* - (a copper wire)</span> </div>', 'c3b322d5-191d-429f-8ac1-0a6c2779b903'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', 'c3b322d5-191d-429f-8ac1-0a6c2779b903'::uuid),
                    ('Spell Tags', 'spellTags', '["Communication","Social"]', '', 'c3b322d5-191d-429f-8ac1-0a6c2779b903'::uuid),
