                    ('Level', 'level', '{"levelNumber":"9","label":"9th"}', '<div> <div> Level </div> <div> 9th </div> </div>', '00ac1d22-f104-4b4c-a774-3da7ec895e58'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Action","kind":"action","value":1,"unit":"action","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Action </div> </div>', '00ac1d22-f104-4b4c-a774-3da7ec895e58'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"1 mile (40 ft. *)","kind":"distance","distanceValue":1,"distanceUnit":"mile","area":{"shape":null,"value":40,"unit":"ft"}}', '<div> <div> Range/Area </div> <div> 1 mile <span>(40 ft. <i></i> *)</span> </div> </div>', '00ac1d22-f104-4b4c-a774-3da7ec895e58'::uuid),
                    ('Components', 'components', '{"text":"V, S","verbal":true,"somatic":true,"material":{"required":false,"description":null,"consumed":null,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S</span> </div> </div>', '00ac1d22-f104-4b4c-a774-3da7ec895e58'::uuid),
                    ('Duration', 'duration', '{"text":"Instantaneous","kind":"instantaneous","value":null,"unit":null,"concentration":false,"endCondition":null}', '<div> <div>Duration</div> <div> Instantaneous </div> </div>', '00ac1d22-f104-4b4c-a774-3da7ec895e58'::uuid),
                    ('School', 'school', 'Evocation', '<div> <div> School </div> <div> Evocation </div> </div>', '00ac1d22-f104-4b4c-a774-3da7ec895e58'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"DEX Save","kind":"save","attackType":null,"ability":"DEX"}', '<div> <div> Attack/Save </div> <div> <i></i> <span>DEX Save</span> </div> </div>', '00ac1d22-f104-4b4c-a774-3da7ec895e58'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Fire (...)","damageTypes":["Fire"]}', '<div> <div> Damage/Effect </div> <div> <i></i> Fire (...) </div> </div>', '00ac1d22-f104-4b4c-a774-3da7ec895e58'::uuid),
                    ('Description', 'description', '["Blazing orbs of fire plummet to the ground at four different points you can see within range. Each creature in a 40-foot-radius Sphere centered on each of those points makes a Dexterity saving throw. A creature takes 20d6 Fire damage and 20d6 Bludgeoning damage on a failed save or half as much damage on a successful one. A creature in the area of more than one fiery Sphere is affected only once.","A nonmagical object that isn’t being worn or carried also takes the damage if it’s in the spell’s area, and the object starts burning if it’s flammable."]', '<div> <p>Blazing orbs of fire plummet to the ground at four different points you can see within range. Each creature in a 40-foot-radius <a>Sphere</a> centered on each of those points makes a Dexterity saving throw. A creature takes 20d6 Fire damage and 20d6 Bludgeoning damage on a failed save or half as much damage on a successful one. A creature in the area of more than one fiery Sphere is affected only once.</p> <p>A nonmagical object that isn’t being worn or carried also takes the damage if it’s in the spell’s area, and the object starts <a>burning</a> if it’s flammable.</p> </div>', '00ac1d22-f104-4b4c-a774-3da7ec895e58'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', '00ac1d22-f104-4b4c-a774-3da7ec895e58'::uuid),
