                    ('Range/Area', 'rangeArea', '{"text":"Self","kind":"self","distanceValue":null,"distanceUnit":null,"area":null}', '<div> <div> Range/Area </div> <div> Self </div> </div>', '355599a6-76ea-4920-8b46-531cb9fe1d02'::uuid),
                    ('Components', 'components', '{"text":"V, S","verbal":true,"somatic":true,"material":{"required":false,"description":null,"consumed":null,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S</span> </div> </div>', '355599a6-76ea-4920-8b46-531cb9fe1d02'::uuid),
                    ('Duration', 'duration', '{"text":"1 Minute","kind":"timed","value":1,"unit":"minute","concentration":false,"endCondition":null}', '<div> <div>Duration</div> <div> 1 Minute </div> </div>', '355599a6-76ea-4920-8b46-531cb9fe1d02'::uuid),
                    ('School', 'school', 'Illusion', '<div> <div> School </div> <div> Illusion </div> </div>', '355599a6-76ea-4920-8b46-531cb9fe1d02'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"None","kind":"none","attackType":null,"ability":null}', '<div> <div> Attack/Save </div> <div> <span>None</span> </div> </div>', '355599a6-76ea-4920-8b46-531cb9fe1d02'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Deception (...)","damageTypes":[]}', '<div> <div> Damage/Effect </div> <div> Deception (...) </div> </div>', '355599a6-76ea-4920-8b46-531cb9fe1d02'::uuid),
                    ('Description', 'description', '["Three illusory duplicates of yourself appear in your space. Until the spell ends, the duplicates move with you and mimic your actions, shifting position so it’s impossible to track which image is real.","Each time a creature hits you with an attack roll during the spell’s duration, roll a d6 for each of your remaining duplicates. If any of the d6s rolls a 3 or higher, one of the duplicates is hit instead of you, and the duplicate is destroyed. The duplicates otherwise ignore all other damage and effects. The spell ends when all three duplicates are destroyed.","A creature is unaffected by this spell if it has the Blinded condition, Blindsight , or Truesight ."]', '<div> <p>Three illusory duplicates of yourself appear in your space. Until the spell ends, the duplicates move with you and mimic your actions, shifting position so it’s impossible to track which image is real.</p> <p>Each time a creature hits you with an attack roll during the spell’s duration, roll a d6 for each of your remaining duplicates. If any of the d6s rolls a 3 or higher, one of the duplicates is hit instead of you, and the duplicate is destroyed. The duplicates otherwise ignore all other damage and effects. The spell ends when all three duplicates are destroyed.</p> <p>A creature is unaffected by this spell if it has the <a>Blinded</a> condition, <a>Blindsight</a>, or <a>Truesight</a>.</p> </div>', '355599a6-76ea-4920-8b46-531cb9fe1d02'::uuid),
