                    ('Attack/Save', 'attackSave', '{"text":"None","kind":"none","attackType":null,"ability":null}', '<div> <div> Attack/Save </div> <div> <span>None</span> </div> </div>', 'e81c4a1e-ac86-4e14-b798-93b9e6e50d1b'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Teleportation","damageTypes":[]}', '<div> <div> Damage/Effect </div> <div> Teleportation </div> </div>', 'e81c4a1e-ac86-4e14-b798-93b9e6e50d1b'::uuid),
                    ('Description', 'description', '["Briefly surrounded by silvery mist, you teleport up to 30 feet to an unoccupied space you can see."]', '<div> <p>Briefly surrounded by silvery mist, you teleport up to 30 feet to an unoccupied space you can see.</p> </div>', 'e81c4a1e-ac86-4e14-b798-93b9e6e50d1b'::uuid),
