                    ('Source', 'source', 'Player’s Handbook, pg. 300', '', '58e50f30-b563-4bd0-808d-e8f7020c7194'::uuid),
                    ('Source URL', 'url', 'https://www.dndbeyond.com/spells/2619112-mordenkainens-magnificent-mansion', '', '58e50f30-b563-4bd0-808d-e8f7020c7194'::uuid),
                    ('Image', 'imageUrl', 'https://www.dndbeyond.com/attachments/2/708/conjuration.png', '', '58e50f30-b563-4bd0-808d-e8f7020c7194'::uuid),
                    ('Level', 'level', '{"levelNumber":"4","label":"4th"}', '<div> <div> Level </div> <div> 4th </div> </div>', '2577f046-b465-4df0-bb1e-9d66df0c10f0'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"10 Minutes","kind":"timed","value":10,"unit":"minute","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 10 Minutes </div> </div>', '2577f046-b465-4df0-bb1e-9d66df0c10f0'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"120 ft. (*)","kind":"distance","distanceValue":120,"distanceUnit":"ft","area":null}', '<div> <div> Range/Area </div> <div> 120 ft. <span>(<i></i>*)</span> </div> </div>', '2577f046-b465-4df0-bb1e-9d66df0c10f0'::uuid),
                    ('Components', 'components', '{"text":"V, S, M *","verbal":true,"somatic":true,"material":{"required":true,"description":"a thin sheet of lead","consumed":false,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S, M *</span> </div> </div>', '2577f046-b465-4df0-bb1e-9d66df0c10f0'::uuid),
                    ('Duration', 'duration', '{"text":"24 Hours","kind":"timed","value":24,"unit":"hour","concentration":false,"endCondition":null}', '<div> <div>Duration</div> <div> 24 Hours </div> </div>', '2577f046-b465-4df0-bb1e-9d66df0c10f0'::uuid),
                    ('School', 'school', 'Abjuration', '<div> <div> School </div> <div> Abjuration </div> </div>', '2577f046-b465-4df0-bb1e-9d66df0c10f0'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"None","kind":"none","attackType":null,"ability":null}', '<div> <div> Attack/Save </div> <div> <span>None</span> </div> </div>', '2577f046-b465-4df0-bb1e-9d66df0c10f0'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Control (...)","damageTypes":[]}', '<div> <div> Damage/Effect </div> <div> Control (...) </div> </div>', '2577f046-b465-4df0-bb1e-9d66df0c10f0'::uuid),
                    ('Description', 'description', '["You make an area within range magically secure. The area is a Cube that can be as small as 5 feet to as large as 100 feet on each side. The spell lasts for the duration.","When you cast the spell, you decide what sort of security the spell provides, choosing any of the following properties:","Casting this spell on the same spot every day for 365 days makes the spell last until dispelled.","Using a Higher-Level Spell Slot. You can increase the size of the Cube by 100 feet for each spell slot level above 4."]', '<div> <p>You make an area within range magically secure. The area is a <a>Cube</a> that can be as small as 5 feet to as large as 100 feet on each side. The spell lasts for the duration.</p> <p>When you cast the spell, you decide what sort of security the spell provides, choosing any of the following properties:</p> <ul> <li>Sound can’t pass through the barrier at the edge of the warded area.</li> <li>The barrier of the warded area appears dark and foggy, preventing vision (including <a>Darkvision</a>) through it.</li> <li>Sensors created by Divination spells can’t appear inside the protected area or pass through the barrier at its perimeter.</li> <li>Creatures in the area can’t be targeted by Divination spells.</li> <li>Nothing can teleport into or out of the warded area.</li> <li>Planar travel is blocked within the warded area.</li> </ul> <p>Casting this spell on the same spot every day for 365 days makes the spell last until dispelled.</p> <p><strong><em>Using a Higher-Level Spell Slot.</em></strong> You can increase the size of the Cube by 100 feet for each spell slot level above 4.</p> <span>* - (a thin sheet of lead)</span> </div>', '2577f046-b465-4df0-bb1e-9d66df0c10f0'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', '2577f046-b465-4df0-bb1e-9d66df0c10f0'::uuid);
                """);

