                    ('Image', 'imageUrl', 'https://www.dndbeyond.com/attachments/2/707/abjuration.png', '', '2577f046-b465-4df0-bb1e-9d66df0c10f0'::uuid),
                    ('Level', 'level', '{"levelNumber":"7","label":"7th"}', '<div> <div> Level </div> <div> 7th </div> </div>', 'aedba959-a35e-4c23-a70b-dec393276d92'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Action","kind":"action","value":1,"unit":"action","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Action </div> </div>', 'aedba959-a35e-4c23-a70b-dec393276d92'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"90 ft.","kind":"distance","distanceValue":90,"distanceUnit":"ft","area":null}', '<div> <div> Range/Area </div> <div> 90 ft. </div> </div>', 'aedba959-a35e-4c23-a70b-dec393276d92'::uuid),
                    ('Components', 'components', '{"text":"V, S, M *","verbal":true,"somatic":true,"material":{"required":true,"description":"a miniature sword worth 250+ GP","consumed":false,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S, M *</span> </div> </div>', 'aedba959-a35e-4c23-a70b-dec393276d92'::uuid),
                    ('Duration', 'duration', '{"text":"Concentration 1 Minute","kind":"timed","value":1,"unit":"minute","concentration":true,"endCondition":null}', '<div> <div>Duration</div> <div> <i>Concentration</i> 1 Minute </div> </div>', 'aedba959-a35e-4c23-a70b-dec393276d92'::uuid),
                    ('School', 'school', 'Evocation', '<div> <div> School </div> <div> Evocation </div> </div>', 'aedba959-a35e-4c23-a70b-dec393276d92'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"Melee","kind":"attack","attackType":"melee","ability":null}', '<div> <div> Attack/Save </div> <div> <i></i> <span>Melee</span> </div> </div>', 'aedba959-a35e-4c23-a70b-dec393276d92'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Force","damageTypes":["Force"]}', '<div> <div> Damage/Effect </div> <div> <i></i> Force </div> </div>', 'aedba959-a35e-4c23-a70b-dec393276d92'::uuid),
                    ('Description', 'description', '["You create a spectral sword that hovers within range. It lasts for the duration.","When the sword appears, you make a melee spell attack against a target within 5 feet of the sword. On a hit, the target takes Force damage equal to 4d12 plus your spellcasting ability modifier.","On your later turns, you can take a Bonus Action to move the sword up to 30 feet to a spot you can see and repeat the attack against the same target or a different one."]', '<div> <p>You create a spectral sword that hovers within range. It lasts for the duration.</p> <p>When the sword appears, you make a melee spell attack against a target within 5 feet of the sword. On a hit, the target takes Force damage equal to 4d12 plus your spellcasting ability modifier.</p> <p>On your later turns, you can take a Bonus Action to move the sword up to 30 feet to a spot you can see and repeat the attack against the same target or a different one.</p> <span>* - (a miniature sword worth 250+ GP)</span> </div>', 'aedba959-a35e-4c23-a70b-dec393276d92'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', 'aedba959-a35e-4c23-a70b-dec393276d92'::uuid),
                    ('Spell Tags', 'spellTags', '["Damage"]', '', 'aedba959-a35e-4c23-a70b-dec393276d92'::uuid),
