                    ('Image', 'imageUrl', 'https://www.dndbeyond.com/attachments/2/702/enchantment.png', '', '3592a79b-4910-4c2a-8e0e-2c3c9cce9000'::uuid),
                    ('Level', 'level', '{"levelNumber":"2","label":"2nd"}', '<div> <div> Level </div> <div> 2nd </div> </div>', '29969aed-5208-42df-9e1f-9224a16cd92f'::uuid),
