                    ('Range/Area', 'rangeArea', '{"text":"Self (30 ft.)","kind":"self","distanceValue":null,"distanceUnit":null,"area":{"shape":null,"value":30,"unit":"ft"}}', '<div> <div> Range/Area </div> <div> Self <span>(30 ft. <i></i>)</span> </div> </div>', '29969aed-5208-42df-9e1f-9224a16cd92f'::uuid),
                    ('Components', 'components', '{"text":"V, S, M *","verbal":true,"somatic":true,"material":{"required":true,"description":"ashes from burned mistletoe","consumed":false,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S, M *</span> </div> </div>', '29969aed-5208-42df-9e1f-9224a16cd92f'::uuid),
                    ('Duration', 'duration', '{"text":"Concentration 1 Hour","kind":"timed","value":1,"unit":"hour","concentration":true,"endCondition":null}', '<div> <div>Duration</div> <div> <i>Concentration</i> 1 Hour </div> </div>', '29969aed-5208-42df-9e1f-9224a16cd92f'::uuid),
                    ('School', 'school', 'Abjuration', '<div> <div> School </div> <div> Abjuration </div> </div>', '29969aed-5208-42df-9e1f-9224a16cd92f'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"None","kind":"none","attackType":null,"ability":null}', '<div> <div> Attack/Save </div> <div> <span>None</span> </div> </div>', '29969aed-5208-42df-9e1f-9224a16cd92f'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Buff (...)","damageTypes":[]}', '<div> <div> Damage/Effect </div> <div> Buff (...) </div> </div>', '29969aed-5208-42df-9e1f-9224a16cd92f'::uuid),
                    ('Description', 'description', '["You radiate a concealing aura in a 30-foot Emanation for the duration. While in the aura, you and each creature you choose have a +10 bonus to Dexterity ( Stealth ) checks and leave no tracks."]', '<div> <p>You radiate a concealing aura in a 30-foot <a>Emanation</a> for the duration. While in the aura, you and each creature you choose have a +10 bonus to Dexterity (<a>Stealth</a>) checks and leave no tracks.</p> <span>* - (ashes from burned mistletoe)</span> </div>', '29969aed-5208-42df-9e1f-9224a16cd92f'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', '29969aed-5208-42df-9e1f-9224a16cd92f'::uuid),
