                    ('Casting Time', 'castingTime', '{"text":"1 Action","kind":"action","value":1,"unit":"action","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Action </div> </div>', 'b71358dc-4b16-4e75-b64a-651b9c727917'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"30 ft.","kind":"distance","distanceValue":30,"distanceUnit":"ft","area":null}', '<div> <div> Range/Area </div> <div> 30 ft. </div> </div>', 'b71358dc-4b16-4e75-b64a-651b9c727917'::uuid),
                    ('Components', 'components', '{"text":"V, S, M *","verbal":true,"somatic":true,"material":{"required":true,"description":"a pinch of sesame seeds","consumed":false,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S, M *</span> </div> </div>', 'b71358dc-4b16-4e75-b64a-651b9c727917'::uuid),
                    ('Duration', 'duration', '{"text":"1 Hour","kind":"timed","value":1,"unit":"hour","concentration":false,"endCondition":null}', '<div> <div>Duration</div> <div> 1 Hour </div> </div>', 'b71358dc-4b16-4e75-b64a-651b9c727917'::uuid),
                    ('School', 'school', 'Transmutation', '<div> <div> School </div> <div> Transmutation </div> </div>', 'b71358dc-4b16-4e75-b64a-651b9c727917'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"None","kind":"none","attackType":null,"ability":null}', '<div> <div> Attack/Save </div> <div> <span>None</span> </div> </div>', 'b71358dc-4b16-4e75-b64a-651b9c727917'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Control","damageTypes":[]}', '<div> <div> Damage/Effect </div> <div> Control </div> </div>', 'b71358dc-4b16-4e75-b64a-651b9c727917'::uuid),
                    ('Description', 'description', '["A passage appears at a point that you can see on a wooden, plaster, or stone surface (such as a wall, ceiling, or floor) within range and lasts for the duration. You choose the opening’s dimensions: up to 5 feet wide, 8 feet tall, and 20 feet deep. The passage creates no instability in a structure surrounding it.","When the opening disappears, any creatures or objects still in the passage created by the spell are safely ejected to an unoccupied space nearest to the surface on which you cast the spell."]', '<div> <p>A passage appears at a point that you can see on a wooden, plaster, or stone surface (such as a wall, ceiling, or floor) within range and lasts for the duration. You choose the opening’s dimensions: up to 5 feet wide, 8 feet tall, and 20 feet deep. The passage creates no instability in a structure surrounding it.</p> <p>When the opening disappears, any creatures or objects still in the passage created by the spell are safely ejected to an unoccupied space nearest to the surface on which you cast the spell.</p> <span>* - (a pinch of sesame seeds)</span> </div>', 'b71358dc-4b16-4e75-b64a-651b9c727917'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', 'b71358dc-4b16-4e75-b64a-651b9c727917'::uuid),
