                    ('School', 'school', 'Enchantment', '<div> <div> School </div> <div> Enchantment </div> </div>', '9a8b67a3-9e6e-49e5-8f93-f6a863217f96'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"None","kind":"none","attackType":null,"ability":null}', '<div> <div> Attack/Save </div> <div> <span>None</span> </div> </div>', '9a8b67a3-9e6e-49e5-8f93-f6a863217f96'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Prone","damageTypes":[]}', '<div> <div> Damage/Effect </div> <div> <i></i> Prone </div> </div>', '9a8b67a3-9e6e-49e5-8f93-f6a863217f96'::uuid),
                    ('Description', 'description', '["A wave of healing energy washes over one creature you can see within range. The target regains all its Hit Points. If the creature has the Charmed , Frightened , Paralyzed , Poisoned , or Stunned condition, the condition ends. If the creature has the Prone condition, it can use its Reaction to stand up."]', '<div> <p>A wave of healing energy washes over one creature you can see within range. The target regains all its Hit Points. If the creature has the <a>Charmed</a>, <a>Frightened</a>, <a>Paralyzed</a>, <a>Poisoned</a>, or <a>Stunned</a> condition, the condition ends. If the creature has the <a>Prone</a> condition, it can use its Reaction to stand up.</p> </div>', '9a8b67a3-9e6e-49e5-8f93-f6a863217f96'::uuid),
