                    ('Attack/Save', 'attackSave', '{"text":"None","kind":"none","attackType":null,"ability":null}', '<div> <div> Attack/Save </div> <div> <span>None</span> </div> </div>', '7a1f8ac6-fd01-4cb1-9ab0-cc889d4fff56'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Psychic","damageTypes":["Psychic"]}', '<div> <div> Damage/Effect </div> <div> <i></i> Psychic </div> </div>', '7a1f8ac6-fd01-4cb1-9ab0-cc889d4fff56'::uuid),
                    ('Description', 'description', '["You compel one creature you can see within range to die. If the target has 100 Hit Points or fewer, it dies. Otherwise, it takes 12d12 Psychic damage."]', '<div> <p>You compel one creature you can see within range to die. If the target has 100 Hit Points or fewer, it dies. Otherwise, it takes 12d12 Psychic damage.</p> </div>', '7a1f8ac6-fd01-4cb1-9ab0-cc889d4fff56'::uuid),
