                    ('Image', 'imageUrl', 'https://www.dndbeyond.com/attachments/2/702/enchantment.png', '', '3f9f3703-b007-4ccf-ba7d-25c320bb4679'::uuid),
                    ('Level', 'level', '{"levelNumber":"2","label":"2nd"}', '<div> <div> Level </div> <div> 2nd </div> </div>', '0a089533-968e-4c08-af4e-77bf6d2a123c'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"10 Minutes","kind":"timed","value":10,"unit":"minute","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 10 Minutes </div> </div>', '0a089533-968e-4c08-af4e-77bf6d2a123c'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"30 ft.","kind":"distance","distanceValue":30,"distanceUnit":"ft","area":null}', '<div> <div> Range/Area </div> <div> 30 ft. </div> </div>', '0a089533-968e-4c08-af4e-77bf6d2a123c'::uuid),
                    ('Components', 'components', '{"text":"V","verbal":true,"somatic":false,"material":{"required":false,"description":null,"consumed":null,"costGp":null}}', '<div> <div> Components </div> <div> <span>V</span> </div> </div>', '0a089533-968e-4c08-af4e-77bf6d2a123c'::uuid),
                    ('Duration', 'duration', '{"text":"Instantaneous","kind":"instantaneous","value":null,"unit":null,"concentration":false,"endCondition":null}', '<div> <div>Duration</div> <div> Instantaneous </div> </div>', '0a089533-968e-4c08-af4e-77bf6d2a123c'::uuid),
                    ('School', 'school', 'Abjuration', '<div> <div> School </div> <div> Abjuration </div> </div>', '0a089533-968e-4c08-af4e-77bf6d2a123c'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"None","kind":"none","attackType":null,"ability":null}', '<div> <div> Attack/Save </div> <div> <span>None</span> </div> </div>', '0a089533-968e-4c08-af4e-77bf6d2a123c'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Healing","damageTypes":[]}', '<div> <div> Damage/Effect </div> <div> Healing </div> </div>', '0a089533-968e-4c08-af4e-77bf6d2a123c'::uuid),
                    ('Description', 'description', '["Up to five creatures of your choice who remain within range for the spell’s entire casting gain the benefits of a Short Rest and also regain 2d8 Hit Points. A creature can’t be affected by this spell again until that creature finishes a Long Rest.","Using a Higher-Level Spell Slot. The healing increases by 1d8 for each spell slot level above 2."]', '<div> <p>Up to five creatures of your choice who remain within range for the spell’s entire casting gain the benefits of a Short Rest and also regain 2d8 Hit Points. A creature can’t be affected by this spell again until that creature finishes a Long Rest.</p> <p><strong><em>Using a Higher-Level Spell Slot.</em></strong> The healing increases by 1d8 for each spell slot level above 2.</p> </div>', '0a089533-968e-4c08-af4e-77bf6d2a123c'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', '0a089533-968e-4c08-af4e-77bf6d2a123c'::uuid),
