                    ('Level', 'level', '{"levelNumber":"Cantrip","label":"Cantrip"}', '<div> <div> Level </div> <div> Cantrip </div> </div>', '2035fc59-584e-4aaf-a811-c592f071e3d2'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Action","kind":"action","value":1,"unit":"action","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Action </div> </div>', '2035fc59-584e-4aaf-a811-c592f071e3d2'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"10 ft.","kind":"distance","distanceValue":10,"distanceUnit":"ft","area":null}', '<div> <div> Range/Area </div> <div> 10 ft. </div> </div>', '2035fc59-584e-4aaf-a811-c592f071e3d2'::uuid),
                    ('Components', 'components', '{"text":"V, S","verbal":true,"somatic":true,"material":{"required":false,"description":null,"consumed":null,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S</span> </div> </div>', '2035fc59-584e-4aaf-a811-c592f071e3d2'::uuid),
                    ('Duration', 'duration', '{"text":"1 Hour","kind":"timed","value":1,"unit":"hour","concentration":false,"endCondition":null}', '<div> <div>Duration</div> <div> 1 Hour </div> </div>', '2035fc59-584e-4aaf-a811-c592f071e3d2'::uuid),
                    ('School', 'school', 'Transmutation', '<div> <div> School </div> <div> Transmutation </div> </div>', '2035fc59-584e-4aaf-a811-c592f071e3d2'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"None","kind":"none","attackType":null,"ability":null}', '<div> <div> Attack/Save </div> <div> <span>None</span> </div> </div>', '2035fc59-584e-4aaf-a811-c592f071e3d2'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Utility","damageTypes":[]}', '<div> <div> Damage/Effect </div> <div> Utility </div> </div>', '2035fc59-584e-4aaf-a811-c592f071e3d2'::uuid),
                    ('Description', 'description', '["You create a magical effect within range. Choose the effect from the options below. If you cast this spell multiple times, you can have up to three of its non-instantaneous effects active at a time.","Sensory Effect. You create an instantaneous, harmless sensory effect, such as a shower of sparks, a puff of wind, faint musical notes, or an odd odor.","Fire Play. You instantaneously light or snuff out a candle, a torch, or a small campfire.","Clean or Soil. You instantaneously clean or soil an object no larger than 1 cubic foot.","Minor Sensation. You chill, warm, or flavor up to 1 cubic foot of nonliving material for 1 hour.","Magic Mark. You make a color, a small mark, or a symbol appear on an object or a surface for 1 hour.","Minor Creation. You create a nonmagical trinket or an illusory image that can fit in your hand. It lasts until the end of your next turn. A trinket can deal no damage and has no monetary worth."]', '<div> <p>You create a magical effect within range. Choose the effect from the options below. If you cast this spell multiple times, you can have up to three of its non-instantaneous effects active at a time.</p> <p><strong><em>Sensory Effect.</em></strong> You create an instantaneous, harmless sensory effect, such as a shower of sparks, a puff of wind, faint musical notes, or an odd odor.</p> <p><strong><em>Fire Play.</em></strong> You instantaneously light or snuff out a candle, a torch, or a small campfire.</p> <p><strong><em>Clean or Soil.</em></strong> You instantaneously clean or soil an object no larger than 1 cubic foot.</p> <p><strong><em>Minor Sensation.</em></strong> You chill, warm, or flavor up to 1 cubic foot of nonliving material for 1 hour.</p> <p><strong><em>Magic Mark.</em></strong> You make a color, a small mark, or a symbol appear on an object or a surface for 1 hour.</p> <p><strong><em>Minor Creation.</em></strong> You create a nonmagical trinket or an illusory image that can fit in your hand. It lasts until the end of your next turn. A trinket can deal no damage and has no monetary worth.</p> </div>', '2035fc59-584e-4aaf-a811-c592f071e3d2'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', '2035fc59-584e-4aaf-a811-c592f071e3d2'::uuid),
