                    ('Level', 'level', '{"levelNumber":"Cantrip","label":"Cantrip"}', '<div> <div> Level </div> <div> Cantrip </div> </div>', '92abfb05-991b-442c-bccb-b1e2e2a8b2f1'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Bonus Action","kind":"bonus_action","value":1,"unit":"action","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Bonus Action </div> </div>', '92abfb05-991b-442c-bccb-b1e2e2a8b2f1'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"Self","kind":"self","distanceValue":null,"distanceUnit":null,"area":null}', '<div> <div> Range/Area </div> <div> Self </div> </div>', '92abfb05-991b-442c-bccb-b1e2e2a8b2f1'::uuid),
                    ('Components', 'components', '{"text":"V, S","verbal":true,"somatic":true,"material":{"required":false,"description":null,"consumed":null,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S</span> </div> </div>', '92abfb05-991b-442c-bccb-b1e2e2a8b2f1'::uuid),
                    ('Duration', 'duration', '{"text":"10 Minutes","kind":"timed","value":10,"unit":"minute","concentration":false,"endCondition":null}', '<div> <div>Duration</div> <div> 10 Minutes </div> </div>', '92abfb05-991b-442c-bccb-b1e2e2a8b2f1'::uuid),
                    ('School', 'school', 'Conjuration', '<div> <div> School </div> <div> Conjuration </div> </div>', '92abfb05-991b-442c-bccb-b1e2e2a8b2f1'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"Ranged","kind":"attack","attackType":"ranged","ability":null}', '<div> <div> Attack/Save </div> <div> <i></i> <span>Ranged</span> </div> </div>', '92abfb05-991b-442c-bccb-b1e2e2a8b2f1'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Fire","damageTypes":["Fire"]}', '<div> <div> Damage/Effect </div> <div> <i></i> Fire </div> </div>', '92abfb05-991b-442c-bccb-b1e2e2a8b2f1'::uuid),
                    ('Description', 'description', '["A flickering flame appears in your hand and remains there for the duration. While there, the flame emits no heat and ignites nothing, and it sheds Bright Light in a 20-foot radius and Dim Light for an additional 20 feet. The spell ends if you cast it again.","Until the spell ends, you can take a Magic action to hurl fire at a creature or an object within 60 feet of you. Make a ranged spell attack. On a hit, the target takes 1d8 Fire damage.","Cantrip Upgrade. The damage increases by 1d8 when you reach levels 5 (2d8), 11 (3d8), and 17 (4d8)."]', '<div> <p>A flickering flame appears in your hand and remains there for the duration. While there, the flame emits no heat and ignites nothing, and it sheds <a>Bright Light</a> in a 20-foot radius and <a>Dim Light</a> for an additional 20 feet. The spell ends if you cast it again.</p> <p>Until the spell ends, you can take a <a>Magic</a> action to hurl fire at a creature or an object within 60 feet of you. Make a ranged spell attack. On a hit, the target takes 1d8 Fire damage.</p> <p><strong><em>Cantrip Upgrade.</em></strong> The damage increases by 1d8 when you reach levels 5 (2d8), 11 (3d8), and 17 (4d8).</p> </div>', '92abfb05-991b-442c-bccb-b1e2e2a8b2f1'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', '92abfb05-991b-442c-bccb-b1e2e2a8b2f1'::uuid),
