                    ('School', 'school', 'Abjuration', '<div> <div> School </div> <div> Abjuration </div> </div>', '074c6238-8787-490e-bef0-7c0c048fdc03'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"None","kind":"none","attackType":null,"ability":null}', '<div> <div> Attack/Save </div> <div> <span>None</span> </div> </div>', '074c6238-8787-490e-bef0-7c0c048fdc03'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Buff (...)","damageTypes":[]}', '<div> <div> Damage/Effect </div> <div> Buff (...) </div> </div>', '074c6238-8787-490e-bef0-7c0c048fdc03'::uuid),
                    ('Description', 'description', '["For the duration, the willing creature you touch has Resistance to one damage type of your choice: Acid, Cold, Fire, Lightning, or Thunder."]', '<div> <p>For the duration, the willing creature you touch has Resistance to one damage type of your choice: Acid, Cold, Fire, Lightning, or Thunder.</p> </div>', '074c6238-8787-490e-bef0-7c0c048fdc03'::uuid),
