                    ('School', 'school', 'Transmutation', '<div> <div> School </div> <div> Transmutation </div> </div>', 'cb76d891-639d-482e-ab08-ef293e2f9632'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"None","kind":"none","attackType":null,"ability":null}', '<div> <div> Attack/Save </div> <div> <span>None</span> </div> </div>', 'cb76d891-639d-482e-ab08-ef293e2f9632'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Utility","damageTypes":[]}', '<div> <div> Damage/Effect </div> <div> Utility </div> </div>', 'cb76d891-639d-482e-ab08-ef293e2f9632'::uuid),
                    ('Description', 'description', '["You remove poison and rot from nonmagical food and drink in a 5-foot-radius Sphere centered on a point within range."]', '<div> <p>You remove poison and rot from nonmagical food and drink in a 5-foot-radius <a>Sphere</a> centered on a point within range.</p> </div>', 'cb76d891-639d-482e-ab08-ef293e2f9632'::uuid),
