                    ('Level', 'level', '{"levelNumber":"2","label":"2nd"}', '<div> <div> Level </div> <div> 2nd </div> </div>', 'd58657d9-4570-41bb-a1de-d89db46e8ccb'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Action","kind":"action","value":1,"unit":"action","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Action </div> </div>', 'd58657d9-4570-41bb-a1de-d89db46e8ccb'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"60 ft. (5 ft. *)","kind":"distance","distanceValue":60,"distanceUnit":"ft","area":{"shape":null,"value":5,"unit":"ft"}}', '<div> <div> Range/Area </div> <div> 60 ft. <span>(5 ft. <i></i> *)</span> </div> </div>', 'd58657d9-4570-41bb-a1de-d89db46e8ccb'::uuid),
                    ('Components', 'components', '{"text":"V, S","verbal":true,"somatic":true,"material":{"required":false,"description":null,"consumed":null,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S</span> </div> </div>', 'd58657d9-4570-41bb-a1de-d89db46e8ccb'::uuid),
                    ('Duration', 'duration', '{"text":"Instantaneous","kind":"instantaneous","value":null,"unit":null,"concentration":false,"endCondition":null}', '<div> <div>Duration</div> <div> Instantaneous </div> </div>', 'd58657d9-4570-41bb-a1de-d89db46e8ccb'::uuid),
                    ('School', 'school', 'Transmutation', '<div> <div> School </div> <div> Transmutation </div> </div>', 'd58657d9-4570-41bb-a1de-d89db46e8ccb'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"CON Save","kind":"save","attackType":null,"ability":"CON"}', '<div> <div> Attack/Save </div> <div> <i></i> <span>CON Save</span> </div> </div>', 'd58657d9-4570-41bb-a1de-d89db46e8ccb'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Blinded","damageTypes":[]}', '<div> <div> Damage/Effect </div> <div> <i></i> Blinded </div> </div>', 'd58657d9-4570-41bb-a1de-d89db46e8ccb'::uuid),
                    ('Description', 'description', '["Choose an area of nonmagical flame that you can see and that fits within a 5-foot cube within range. You can extinguish the fire in that area, and you create either fireworks or smoke when you do so.","Fireworks. The target explodes with a dazzling display of colors. Each creature within 10 feet of the target must succeed on a Constitution saving throw or become blinded until the end of your next turn.","Smoke. Thick black smoke spreads out from the target in a 20-foot radius, moving around corners. The area of the smoke is heavily obscured. The smoke persists for 1 minute or until a strong wind disperses it."]', '<div> <p>Choose an area of nonmagical flame that you can see and that fits within a 5-foot cube within range. You can extinguish the fire in that area, and you create either fireworks or smoke when you do so.</p> <p><em><strong>Fireworks.</strong></em> The target explodes with a dazzling display of colors. Each creature within 10 feet of the target must succeed on a Constitution saving throw or become <a>blinded</a> until the end of your next turn.</p> <p><em><strong>Smoke.</strong></em> Thick black smoke spreads out from the target in a 20-foot radius, moving around corners. The area of the smoke is heavily obscured. The smoke persists for 1 minute or until a strong wind disperses it.</p> </div>', 'd58657d9-4570-41bb-a1de-d89db46e8ccb'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', 'd58657d9-4570-41bb-a1de-d89db46e8ccb'::uuid),
