                    ('Level', 'level', '{"levelNumber":"5","label":"5th"}', '<div> <div> Level </div> <div> 5th </div> </div>', 'e00d1b18-2d4c-494b-8c7b-e6b7a5c8c1cb'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Hour","kind":"timed","value":1,"unit":"hour","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Hour </div> </div>', 'e00d1b18-2d4c-494b-8c7b-e6b7a5c8c1cb'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"Touch","kind":"touch","distanceValue":null,"distanceUnit":null,"area":null}', '<div> <div> Range/Area </div> <div> Touch </div> </div>', 'e00d1b18-2d4c-494b-8c7b-e6b7a5c8c1cb'::uuid),
                    ('Components', 'components', '{"text":"V, S, M *","verbal":true,"somatic":true,"material":{"required":true,"description":"a diamond worth 500+ GP, which the spell consumes","consumed":true,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S, M *</span> </div> </div>', 'e00d1b18-2d4c-494b-8c7b-e6b7a5c8c1cb'::uuid),
                    ('Duration', 'duration', '{"text":"Instantaneous","kind":"instantaneous","value":null,"unit":null,"concentration":false,"endCondition":null}', '<div> <div>Duration</div> <div> Instantaneous </div> </div>', 'e00d1b18-2d4c-494b-8c7b-e6b7a5c8c1cb'::uuid),
                    ('School', 'school', 'Necromancy', '<div> <div> School </div> <div> Necromancy </div> </div>', 'e00d1b18-2d4c-494b-8c7b-e6b7a5c8c1cb'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"None","kind":"none","attackType":null,"ability":null}', '<div> <div> Attack/Save </div> <div> <span>None</span> </div> </div>', 'e00d1b18-2d4c-494b-8c7b-e6b7a5c8c1cb'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Healing","damageTypes":[]}', '<div> <div> Damage/Effect </div> <div> Healing </div> </div>', 'e00d1b18-2d4c-494b-8c7b-e6b7a5c8c1cb'::uuid),
                    ('Description', 'description', '["With a touch, you revive a dead creature if it has been dead no longer than 10 days and it wasn’t Undead when it died.","The creature returns to life with 1 Hit Point. This spell also neutralizes any poisons that affected the creature at the time of death.","This spell closes all mortal wounds, but it doesn’t restore missing body parts. If the creature is lacking body parts or organs integral for its survival—its head, for instance—the spell automatically fails.","Coming back from the dead is an ordeal. The target takes a −4 penalty to D20 Tests . Every time the target finishes a Long Rest, the penalty is reduced by 1 until it becomes 0."]', '<div> <p>With a touch, you revive a dead creature if it has been dead no longer than 10 days and it wasn’t Undead when it died.</p> <p>The creature returns to life with 1 Hit Point. This spell also neutralizes any poisons that affected the creature at the time of death.</p> <p>This spell closes all mortal wounds, but it doesn’t restore missing body parts. If the creature is lacking body parts or organs integral for its survival—its head, for instance—the spell automatically fails.</p> <p>Coming back from the dead is an ordeal. The target takes a −4 penalty to <a>D20 Tests</a>. Every time the target finishes a Long Rest, the penalty is reduced by 1 until it becomes 0.</p> <span>* - (a diamond worth 500+ GP, which the spell consumes)</span> </div>', 'e00d1b18-2d4c-494b-8c7b-e6b7a5c8c1cb'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', 'e00d1b18-2d4c-494b-8c7b-e6b7a5c8c1cb'::uuid),
                    ('Spell Tags', 'spellTags', '["Healing"]', '', 'e00d1b18-2d4c-494b-8c7b-e6b7a5c8c1cb'::uuid),
                    ('Available For', 'availableFor', '["Bard (Legacy)","Cleric (Legacy)","Paladin (Legacy)","Bard","Cleric","Paladin","Cleric - Grave Domain (XGtE)"]', '', 'e00d1b18-2d4c-494b-8c7b-e6b7a5c8c1cb'::uuid),
                    ('Source', 'source', 'Player’s Handbook, pg. 310', '', 'e00d1b18-2d4c-494b-8c7b-e6b7a5c8c1cb'::uuid),
