                    ('Level', 'level', '{"levelNumber":"5","label":"5th"}', '<div> <div> Level </div> <div> 5th </div> </div>', 'edaab36e-697e-4b23-91ee-33369e8264d2'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Action Ritual","kind":"action","value":1,"unit":"action","trigger":null,"ritual":true}', '<div> <div> Casting Time </div> <div> 1 Action <i>Ritual</i> </div> </div>', 'edaab36e-697e-4b23-91ee-33369e8264d2'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"30 ft.","kind":"distance","distanceValue":30,"distanceUnit":"ft","area":null}', '<div> <div> Range/Area </div> <div> 30 ft. </div> </div>', 'edaab36e-697e-4b23-91ee-33369e8264d2'::uuid),
                    ('Components', 'components', '{"text":"V, S, M *","verbal":true,"somatic":true,"material":{"required":true,"description":"two eggs","consumed":false,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S, M *</span> </div> </div>', 'edaab36e-697e-4b23-91ee-33369e8264d2'::uuid),
                    ('Duration', 'duration', '{"text":"1 Hour","kind":"timed","value":1,"unit":"hour","concentration":false,"endCondition":null}', '<div> <div>Duration</div> <div> 1 Hour </div> </div>', 'edaab36e-697e-4b23-91ee-33369e8264d2'::uuid),
                    ('School', 'school', 'Divination', '<div> <div> School </div> <div> Divination </div> </div>', 'edaab36e-697e-4b23-91ee-33369e8264d2'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"None","kind":"none","attackType":null,"ability":null}', '<div> <div> Attack/Save </div> <div> <span>None</span> </div> </div>', 'edaab36e-697e-4b23-91ee-33369e8264d2'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Communication","damageTypes":[]}', '<div> <div> Damage/Effect </div> <div> Communication </div> </div>', 'edaab36e-697e-4b23-91ee-33369e8264d2'::uuid),
                    ('Description', 'description', '["You forge a telepathic link among up to eight willing creatures of your choice within range, psychically linking each creature to all the others for the duration. Creatures that can’t communicate in any languages aren’t affected by this spell.","Until the spell ends, the targets can communicate telepathically through the bond whether or not they share a language. The communication is possible over any distance, though it can’t extend to other planes of existence."]', '<div> <p>You forge a telepathic link among up to eight willing creatures of your choice within range, psychically linking each creature to all the others for the duration. Creatures that can’t communicate in any languages aren’t affected by this spell.</p> <p>Until the spell ends, the targets can communicate telepathically through the bond whether or not they share a language. The communication is possible over any distance, though it can’t extend to other planes of existence.</p> <span>* - (two eggs)</span> </div>', 'edaab36e-697e-4b23-91ee-33369e8264d2'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', 'edaab36e-697e-4b23-91ee-33369e8264d2'::uuid),
                    ('Spell Tags', 'spellTags', '["Communication"]', '', 'edaab36e-697e-4b23-91ee-33369e8264d2'::uuid),
                    ('Available For', 'availableFor', '["Bard (Legacy)","Wizard (Legacy)","Bard","Wizard","Warlock (Legacy) - The Many","Cleric - Peace Domain (TCoE)","Paladin - Oath of Revelry","Sorcerer - Aberrant Sorcery","Warlock - Future You Patron","Cleric - Keeper Domain (BoET)","Cleric - Community Domain (HCS)","Warlock - The Many"]', '', 'edaab36e-697e-4b23-91ee-33369e8264d2'::uuid),
                    ('Source', 'source', 'Player’s Handbook, pg. 311', '', 'edaab36e-697e-4b23-91ee-33369e8264d2'::uuid),
