                    ('Image', 'imageUrl', 'https://www.dndbeyond.com/attachments/2/709/divination.png', '', 'edaab36e-697e-4b23-91ee-33369e8264d2'::uuid),
                    ('Level', 'level', '{"levelNumber":"2","label":"2nd"}', '<div> <div> Level </div> <div> 2nd </div> </div>', '7ae6afcc-1f81-4db4-b28c-740ff84218bc'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Action","kind":"action","value":1,"unit":"action","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Action </div> </div>', '7ae6afcc-1f81-4db4-b28c-740ff84218bc'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"60 ft.","kind":"distance","distanceValue":60,"distanceUnit":"ft","area":null}', '<div> <div> Range/Area </div> <div> 60 ft. </div> </div>', '7ae6afcc-1f81-4db4-b28c-740ff84218bc'::uuid),
                    ('Components', 'components', '{"text":"V, S","verbal":true,"somatic":true,"material":{"required":false,"description":null,"consumed":null,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S</span> </div> </div>', '7ae6afcc-1f81-4db4-b28c-740ff84218bc'::uuid),
                    ('Duration', 'duration', '{"text":"Concentration 1 Minute","kind":"timed","value":1,"unit":"minute","concentration":true,"endCondition":null}', '<div> <div>Duration</div> <div> <i>Concentration</i> 1 Minute </div> </div>', '7ae6afcc-1f81-4db4-b28c-740ff84218bc'::uuid),
                    ('School', 'school', 'Necromancy', '<div> <div> School </div> <div> Necromancy </div> </div>', '7ae6afcc-1f81-4db4-b28c-740ff84218bc'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"CON Save","kind":"save","attackType":null,"ability":"CON"}', '<div> <div> Attack/Save </div> <div> <i></i> <span>CON Save</span> </div> </div>', '7ae6afcc-1f81-4db4-b28c-740ff84218bc'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Debuff","damageTypes":[]}', '<div> <div> Damage/Effect </div> <div> Debuff </div> </div>', '7ae6afcc-1f81-4db4-b28c-740ff84218bc'::uuid),
                    ('Description', 'description', '["A beam of enervating energy shoots from you toward a creature within range. The target must make a Constitution saving throw. On a successful save, the target has Disadvantage on the next attack roll it makes until the start of your next turn.","On a failed save, the target has Disadvantage on Strength-based D20 Tests for the duration. During that time, it also subtracts 1d8 from all its damage rolls. The target repeats the save at the end of each of its turns, ending the spell on a success."]', '<div> <p>A beam of enervating energy shoots from you toward a creature within range. The target must make a Constitution saving throw. On a successful save, the target has Disadvantage on the next attack roll it makes until the start of your next turn.</p> <p>On a failed save, the target has Disadvantage on Strength-based <a>D20 Tests</a> for the duration. During that time, it also subtracts 1d8 from all its damage rolls. The target repeats the save at the end of each of its turns, ending the spell on a success.</p> </div>', '7ae6afcc-1f81-4db4-b28c-740ff84218bc'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', '7ae6afcc-1f81-4db4-b28c-740ff84218bc'::uuid),
                    ('Spell Tags', 'spellTags', '["Debuff"]', '', '7ae6afcc-1f81-4db4-b28c-740ff84218bc'::uuid),
                    ('Available For', 'availableFor', '["Warlock (Legacy)","Wizard (Legacy)","Warlock","Wizard","Cleric - Grave Domain (XGtE)","Cleric - Death Domain (DMG)","Illrigger - Architect of Ruin","Cleric - Blood Domain (TCSR)"]', '', '7ae6afcc-1f81-4db4-b28c-740ff84218bc'::uuid),
                    ('Source', 'source', 'Player’s Handbook, pg. 311', '', '7ae6afcc-1f81-4db4-b28c-740ff84218bc'::uuid),
                    ('Source URL', 'url', 'https://www.dndbeyond.com/spells/2618926-ray-of-enfeeblement', '', '7ae6afcc-1f81-4db4-b28c-740ff84218bc'::uuid),
                    ('Image', 'imageUrl', 'https://www.dndbeyond.com/attachments/2/720/necromancy.png', '', '7ae6afcc-1f81-4db4-b28c-740ff84218bc'::uuid),
                    ('Level', 'level', '{"levelNumber":"Cantrip","label":"Cantrip"}', '<div> <div> Level </div> <div> Cantrip </div> </div>', 'eb63c142-330e-48a1-a211-79c4ebaee6ef'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Action","kind":"action","value":1,"unit":"action","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Action </div> </div>', 'eb63c142-330e-48a1-a211-79c4ebaee6ef'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"60 ft.","kind":"distance","distanceValue":60,"distanceUnit":"ft","area":null}', '<div> <div> Range/Area </div> <div> 60 ft. </div> </div>', 'eb63c142-330e-48a1-a211-79c4ebaee6ef'::uuid),
                    ('Components', 'components', '{"text":"V, S","verbal":true,"somatic":true,"material":{"required":false,"description":null,"consumed":null,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S</span> </div> </div>', 'eb63c142-330e-48a1-a211-79c4ebaee6ef'::uuid),
                    ('Duration', 'duration', '{"text":"Instantaneous","kind":"instantaneous","value":null,"unit":null,"concentration":false,"endCondition":null}', '<div> <div>Duration</div> <div> Instantaneous </div> </div>', 'eb63c142-330e-48a1-a211-79c4ebaee6ef'::uuid),
                    ('School', 'school', 'Evocation', '<div> <div> School </div> <div> Evocation </div> </div>', 'eb63c142-330e-48a1-a211-79c4ebaee6ef'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"Ranged","kind":"attack","attackType":"ranged","ability":null}', '<div> <div> Attack/Save </div> <div> <i></i> <span>Ranged</span> </div> </div>', 'eb63c142-330e-48a1-a211-79c4ebaee6ef'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Cold","damageTypes":["Cold"]}', '<div> <div> Damage/Effect </div> <div> <i></i> Cold </div> </div>', 'eb63c142-330e-48a1-a211-79c4ebaee6ef'::uuid),
                    ('Description', 'description', '["A frigid beam of blue-white light streaks toward a creature within range. Make a ranged spell attack against the target. On a hit, it takes 1d8 Cold damage, and its Speed is reduced by 10 feet until the start of your next turn.","Cantrip Upgrade. The damage increases by 1d8 when you reach levels 5 (2d8), 11 (3d8), and 17 (4d8)."]', '<div> <p>A frigid beam of blue-white light streaks toward a creature within range. Make a ranged spell attack against the target. On a hit, it takes 1d8 Cold damage, and its Speed is reduced by 10 feet until the start of your next turn.</p> <p><strong><em>Cantrip Upgrade.</em></strong> The damage increases by 1d8 when you reach levels 5 (2d8), 11 (3d8), and 17 (4d8).</p> </div>', 'eb63c142-330e-48a1-a211-79c4ebaee6ef'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', 'eb63c142-330e-48a1-a211-79c4ebaee6ef'::uuid);
                """);

