                    ('Components', 'components', '{"text":"V, S, M *","verbal":true,"somatic":true,"material":{"required":true,"description":"a prayer wheel","consumed":false,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S, M *</span> </div> </div>', '379105b4-6e2a-42d5-9173-96d485823a14'::uuid),
                    ('Duration', 'duration', '{"text":"1 Hour","kind":"timed","value":1,"unit":"hour","concentration":false,"endCondition":null}', '<div> <div>Duration</div> <div> 1 Hour </div> </div>', '379105b4-6e2a-42d5-9173-96d485823a14'::uuid),
                    ('School', 'school', 'Transmutation', '<div> <div> School </div> <div> Transmutation </div> </div>', '379105b4-6e2a-42d5-9173-96d485823a14'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"None","kind":"none","attackType":null,"ability":null}', '<div> <div> Attack/Save </div> <div> <span>None</span> </div> </div>', '379105b4-6e2a-42d5-9173-96d485823a14'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Healing","damageTypes":[]}', '<div> <div> Damage/Effect </div> <div> Healing </div> </div>', '379105b4-6e2a-42d5-9173-96d485823a14'::uuid),
                    ('Description', 'description', '["A creature you touch regains 4d8 + 15 Hit Points. For the duration, the target regains 1 Hit Point at the start of each of its turns, and any severed body parts regrow after 2 minutes."]', '<div> <p>A creature you touch regains 4d8 + 15 Hit Points. For the duration, the target regains 1 Hit Point at the start of each of its turns, and any severed body parts regrow after 2 minutes.</p> <span>* - (a prayer wheel)</span> </div>', '379105b4-6e2a-42d5-9173-96d485823a14'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', '379105b4-6e2a-42d5-9173-96d485823a14'::uuid),
