                    ('Components', 'components', '{"text":"V, S","verbal":true,"somatic":true,"material":{"required":false,"description":null,"consumed":null,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S</span> </div> </div>', 'd7a90aa2-eb67-4fde-8f5d-f269d9220454'::uuid),
                    ('Duration', 'duration', '{"text":"Instantaneous","kind":"instantaneous","value":null,"unit":null,"concentration":false,"endCondition":null}', '<div> <div>Duration</div> <div> Instantaneous </div> </div>', 'd7a90aa2-eb67-4fde-8f5d-f269d9220454'::uuid),
                    ('School', 'school', 'Abjuration', '<div> <div> School </div> <div> Abjuration </div> </div>', 'd7a90aa2-eb67-4fde-8f5d-f269d9220454'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"None","kind":"none","attackType":null,"ability":null}', '<div> <div> Attack/Save </div> <div> <span>None</span> </div> </div>', 'd7a90aa2-eb67-4fde-8f5d-f269d9220454'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Buff","damageTypes":[]}', '<div> <div> Damage/Effect </div> <div> Buff </div> </div>', 'd7a90aa2-eb67-4fde-8f5d-f269d9220454'::uuid),
                    ('Description', 'description', '["At your touch, all curses affecting one creature or object end. If the object is a cursed magic item, its curse remains, but the spell breaks its owner’s Attunement to the object so it can be removed or discarded."]', '<div> <p>At your touch, all <a>curses</a> affecting one creature or object end. If the object is a cursed magic item, its curse remains, but the spell breaks its owner’s Attunement to the object so it can be removed or discarded.</p> </div>', 'd7a90aa2-eb67-4fde-8f5d-f269d9220454'::uuid),
