                    ('Available For', 'availableFor', '["Druid (Legacy)","Sorcerer (Legacy)","Wizard (Legacy)","Druid","Sorcerer","Wizard"]', '', '26e35f34-da29-418c-acc1-1671208e4ac8'::uuid),
                    ('Source', 'source', 'Player’s Handbook, pg. 312', '', '26e35f34-da29-418c-acc1-1671208e4ac8'::uuid),
