                    ('Image', 'imageUrl', 'https://www.dndbeyond.com/attachments/2/722/transmutation.png', '', '26e35f34-da29-418c-acc1-1671208e4ac8'::uuid),
                    ('Level', 'level', '{"levelNumber":"3","label":"3rd"}', '<div> <div> Level </div> <div> 3rd </div> </div>', '7ff69c22-688c-427e-bb98-8d4ed91e3d2d'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Action","kind":"action","value":1,"unit":"action","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Action </div> </div>', '7ff69c22-688c-427e-bb98-8d4ed91e3d2d'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"Touch","kind":"touch","distanceValue":null,"distanceUnit":null,"area":null}', '<div> <div> Range/Area </div> <div> Touch </div> </div>', '7ff69c22-688c-427e-bb98-8d4ed91e3d2d'::uuid),
                    ('Components', 'components', '{"text":"V, S, M *","verbal":true,"somatic":true,"material":{"required":true,"description":"a diamond worth 300+ GP, which the spell consumes","consumed":true,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S, M *</span> </div> </div>', '7ff69c22-688c-427e-bb98-8d4ed91e3d2d'::uuid),
                    ('Duration', 'duration', '{"text":"Instantaneous","kind":"instantaneous","value":null,"unit":null,"concentration":false,"endCondition":null}', '<div> <div>Duration</div> <div> Instantaneous </div> </div>', '7ff69c22-688c-427e-bb98-8d4ed91e3d2d'::uuid),
                    ('School', 'school', 'Necromancy', '<div> <div> School </div> <div> Necromancy </div> </div>', '7ff69c22-688c-427e-bb98-8d4ed91e3d2d'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"None","kind":"none","attackType":null,"ability":null}', '<div> <div> Attack/Save </div> <div> <span>None</span> </div> </div>', '7ff69c22-688c-427e-bb98-8d4ed91e3d2d'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Healing","damageTypes":[]}', '<div> <div> Damage/Effect </div> <div> Healing </div> </div>', '7ff69c22-688c-427e-bb98-8d4ed91e3d2d'::uuid),
                    ('Description', 'description', '["You touch a creature that has died within the last minute. That creature revives with 1 Hit Point. This spell can’t revive a creature that has died of old age, nor does it restore any missing body parts."]', '<div> <p>You touch a creature that has died within the last minute. That creature revives with 1 Hit Point. This spell can’t revive a creature that has died of old age, nor does it restore any missing body parts.</p> <span>* - (a diamond worth 300+ GP, which the spell consumes)</span> </div>', '7ff69c22-688c-427e-bb98-8d4ed91e3d2d'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', '7ff69c22-688c-427e-bb98-8d4ed91e3d2d'::uuid),
                    ('Spell Tags', 'spellTags', '["Healing"]', '', '7ff69c22-688c-427e-bb98-8d4ed91e3d2d'::uuid),
                    ('Available For', 'availableFor', '["Cleric (Legacy)","Druid (Legacy)","Paladin (Legacy)","Ranger (Legacy)","Artificer (Legacy)","Cleric","Druid","Paladin","Ranger","Artificer","Warlock (Legacy) - The Celestial (Legacy)","Cleric - Life Domain","Cleric - Grave Domain (XGtE)","Druid - Circle of Wildfire (TCoE)","Warlock - Celestial Patron","Illrigger - Architect of Ruin"]', '', '7ff69c22-688c-427e-bb98-8d4ed91e3d2d'::uuid),
