                    ('Image', 'imageUrl', 'https://www.dndbeyond.com/attachments/2/707/abjuration.png', '', 'c6e7d6db-1092-47bd-8d91-6d2a58988dd0'::uuid),
                    ('Level', 'level', '{"levelNumber":"2","label":"2nd"}', '<div> <div> Level </div> <div> 2nd </div> </div>', '276ea8b9-f52b-4dae-a440-4c625e6c621b'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Action","kind":"action","value":1,"unit":"action","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Action </div> </div>', '276ea8b9-f52b-4dae-a440-4c625e6c621b'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"120 ft.","kind":"distance","distanceValue":120,"distanceUnit":"ft","area":null}', '<div> <div> Range/Area </div> <div> 120 ft. </div> </div>', '276ea8b9-f52b-4dae-a440-4c625e6c621b'::uuid),
                    ('Components', 'components', '{"text":"V, S","verbal":true,"somatic":true,"material":{"required":false,"description":null,"consumed":null,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S</span> </div> </div>', '276ea8b9-f52b-4dae-a440-4c625e6c621b'::uuid),
                    ('Duration', 'duration', '{"text":"Instantaneous","kind":"instantaneous","value":null,"unit":null,"concentration":false,"endCondition":null}', '<div> <div>Duration</div> <div> Instantaneous </div> </div>', '276ea8b9-f52b-4dae-a440-4c625e6c621b'::uuid),
                    ('School', 'school', 'Evocation', '<div> <div> School </div> <div> Evocation </div> </div>', '276ea8b9-f52b-4dae-a440-4c625e6c621b'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"Ranged","kind":"attack","attackType":"ranged","ability":null}', '<div> <div> Attack/Save </div> <div> <i></i> <span>Ranged</span> </div> </div>', '276ea8b9-f52b-4dae-a440-4c625e6c621b'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Fire","damageTypes":["Fire"]}', '<div> <div> Damage/Effect </div> <div> <i></i> Fire </div> </div>', '276ea8b9-f52b-4dae-a440-4c625e6c621b'::uuid),
                    ('Description', 'description', '["You hurl three fiery rays. You can hurl them at one target within range or at several. Make a ranged spell attack for each ray. On a hit, the target takes 2d6 Fire damage.","Using a Higher-Level Spell Slot. You create one additional ray for each spell slot level above 2."]', '<div> <p>You hurl three fiery rays. You can hurl them at one target within range or at several. Make a ranged spell attack for each ray. On a hit, the target takes 2d6 Fire damage.</p> <p><strong><em>Using a Higher-Level Spell Slot.</em></strong> You create one additional ray for each spell slot level above 2.</p> </div>', '276ea8b9-f52b-4dae-a440-4c625e6c621b'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', '276ea8b9-f52b-4dae-a440-4c625e6c621b'::uuid),
                    ('Spell Tags', 'spellTags', '["Damage"]', '', '276ea8b9-f52b-4dae-a440-4c625e6c621b'::uuid),
