                    ('Image', 'imageUrl', 'https://www.dndbeyond.com/attachments/2/722/transmutation.png', '', 'da036b61-a992-4b71-9987-c808f473339c'::uuid),
                    ('Level', 'level', '{"levelNumber":"9","label":"9th"}', '<div> <div> Level </div> <div> 9th </div> </div>', '4d9f472d-73dc-4e20-8cde-d7f9d452b2b7'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Action","kind":"action","value":1,"unit":"action","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Action </div> </div>', '4d9f472d-73dc-4e20-8cde-d7f9d452b2b7'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"Self","kind":"self","distanceValue":null,"distanceUnit":null,"area":null}', '<div> <div> Range/Area </div> <div> Self </div> </div>', '4d9f472d-73dc-4e20-8cde-d7f9d452b2b7'::uuid),
                    ('Components', 'components', '{"text":"V, S, M *","verbal":true,"somatic":true,"material":{"required":true,"description":"a jade circlet worth 1,500+ GP","consumed":false,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S, M *</span> </div> </div>', '4d9f472d-73dc-4e20-8cde-d7f9d452b2b7'::uuid),
                    ('Duration', 'duration', '{"text":"Concentration 1 Hour","kind":"timed","value":1,"unit":"hour","concentration":true,"endCondition":null}', '<div> <div>Duration</div> <div> <i>Concentration</i> 1 Hour </div> </div>', '4d9f472d-73dc-4e20-8cde-d7f9d452b2b7'::uuid),
                    ('School', 'school', 'Transmutation', '<div> <div> School </div> <div> Transmutation </div> </div>', '4d9f472d-73dc-4e20-8cde-d7f9d452b2b7'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"None","kind":"none","attackType":null,"ability":null}', '<div> <div> Attack/Save </div> <div> <span>None</span> </div> </div>', '4d9f472d-73dc-4e20-8cde-d7f9d452b2b7'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Shapechanging","damageTypes":[]}', '<div> <div> Damage/Effect </div> <div> Shapechanging </div> </div>', '4d9f472d-73dc-4e20-8cde-d7f9d452b2b7'::uuid),
                    ('Description', 'description', '["You shape-shift into another creature for the duration or until you take a Magic action to shape-shift into a different eligible form. The new form must be of a creature that has a Challenge Rating no higher than your level or Challenge Rating. You must have seen the sort of creature before, and it can’t be a Construct or an Undead.","When you cast the spell, you gain a number of Temporary Hit Points equal to the Hit Points of the first form into which you shape-shift. These Temporary Hit Points vanish if any remain when the spell ends.","Your game statistics are replaced by the stat block of the chosen form, but you retain your creature type; alignment; personality; Intelligence, Wisdom, and Charisma scores; Hit Points; Hit Point Dice; proficiencies; and ability to communicate. If you have the Spellcasting feature, you retain it too.","Upon shape-shifting, you determine whether your equipment drops to the ground or changes in size and shape to fit the new form while you’re in it."]', '<div> <p>You <a>shape-shift</a> into another creature for the duration or until you take a <a>Magic</a> action to shape-shift into a different eligible form. The new form must be of a creature that has a Challenge Rating no higher than your level or Challenge Rating. You must have seen the sort of creature before, and it can’t be a Construct or an Undead.</p> <p>When you cast the spell, you gain a number of <a>Temporary Hit Points</a> equal to the Hit Points of the first form into which you shape-shift. These Temporary Hit Points vanish if any remain when the spell ends.</p> <p>Your game statistics are replaced by the stat block of the chosen form, but you retain your creature type; alignment; personality; Intelligence, Wisdom, and Charisma scores; Hit Points; Hit Point Dice; proficiencies; and ability to communicate. If you have the Spellcasting feature, you retain it too.</p> <p>Upon shape-shifting, you determine whether your equipment drops to the ground or changes in size and shape to fit the new form while you’re in it.</p> <span>* - (a jade circlet worth 1,500+ GP)</span> </div>', '4d9f472d-73dc-4e20-8cde-d7f9d452b2b7'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', '4d9f472d-73dc-4e20-8cde-d7f9d452b2b7'::uuid),
                    ('Spell Tags', 'spellTags', '["Shapechanging"]', '', '4d9f472d-73dc-4e20-8cde-d7f9d452b2b7'::uuid),
