                    ('Level', 'level', '{"levelNumber":"2","label":"2nd"}', '<div> <div> Level </div> <div> 2nd </div> </div>', '4705a6ec-07e7-4f32-aaca-245d9e4dd898'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Action","kind":"action","value":1,"unit":"action","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Action </div> </div>', '4705a6ec-07e7-4f32-aaca-245d9e4dd898'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"60 ft. (10 ft.)","kind":"distance","distanceValue":60,"distanceUnit":"ft","area":{"shape":null,"value":10,"unit":"ft"}}', '<div> <div> Range/Area </div> <div> 60 ft. <span>(10 ft. <i></i>)</span> </div> </div>', '4705a6ec-07e7-4f32-aaca-245d9e4dd898'::uuid),
                    ('Components', 'components', '{"text":"V, S, M *","verbal":true,"somatic":true,"material":{"required":true,"description":"a chip of mica","consumed":false,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S, M *</span> </div> </div>', '4705a6ec-07e7-4f32-aaca-245d9e4dd898'::uuid),
                    ('Duration', 'duration', '{"text":"Instantaneous","kind":"instantaneous","value":null,"unit":null,"concentration":false,"endCondition":null}', '<div> <div>Duration</div> <div> Instantaneous </div> </div>', '4705a6ec-07e7-4f32-aaca-245d9e4dd898'::uuid),
                    ('School', 'school', 'Evocation', '<div> <div> School </div> <div> Evocation </div> </div>', '4705a6ec-07e7-4f32-aaca-245d9e4dd898'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"CON Save","kind":"save","attackType":null,"ability":"CON"}', '<div> <div> Attack/Save </div> <div> <i></i> <span>CON Save</span> </div> </div>', '4705a6ec-07e7-4f32-aaca-245d9e4dd898'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Thunder","damageTypes":["Thunder"]}', '<div> <div> Damage/Effect </div> <div> <i></i> Thunder </div> </div>', '4705a6ec-07e7-4f32-aaca-245d9e4dd898'::uuid),
                    ('Description', 'description', '["A loud noise erupts from a point of your choice within range. Each creature in a 10-foot-radius Sphere centered there makes a Constitution saving throw, taking 3d8 Thunder damage on a failed save or half as much damage on a successful one. A Construct has Disadvantage on the save.","A nonmagical object that isn’t being worn or carried also takes the damage if it’s in the spell’s area.","Using a Higher-Level Spell Slot. The damage increases by 1d8 for each spell slot level above 2."]', '<div> <p>A loud noise erupts from a point of your choice within range. Each creature in a 10-foot-radius <a>Sphere</a> centered there makes a Constitution saving throw, taking 3d8 Thunder damage on a failed save or half as much damage on a successful one. A Construct has Disadvantage on the save.</p> <p>A nonmagical object that isn’t being worn or carried also takes the damage if it’s in the spell’s area.</p> <p><strong><em>Using a Higher-Level Spell Slot.</em></strong> The damage increases by 1d8 for each spell slot level above 2.</p> <span>* - (a chip of mica)</span> </div>', '4705a6ec-07e7-4f32-aaca-245d9e4dd898'::uuid),
