                    ('Damage/Effect', 'damageEffect', '{"text":"Buff (...)","damageTypes":[]}', '<div> <div> Damage/Effect </div> <div> Buff (...) </div> </div>', '47825715-216e-4151-931a-f1d68c901a56'::uuid),
                    ('Description', 'description', '["A shimmering field surrounds a creature of your choice within range, granting it a +2 bonus to AC for the duration."]', '<div> <p>A shimmering field surrounds a creature of your choice within range, granting it a +2 bonus to AC for the duration.</p> <span>* - (a prayer scroll)</span> </div>', '47825715-216e-4151-931a-f1d68c901a56'::uuid),
