                    ('Casting Time', 'castingTime', '{"text":"1 Reaction *","kind":"reaction","value":1,"unit":"action","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Reaction * </div> </div>', 'ad65393b-1ab2-4565-a82c-9760a1bb655e'::uuid),
