                    ('Level', 'level', '{"levelNumber":"Cantrip","label":"Cantrip"}', '<div> <div> Level </div> <div> Cantrip </div> </div>', 'dd34cfcd-a7bb-4082-b1b7-26caab468070'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Bonus Action","kind":"bonus_action","value":1,"unit":"action","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Bonus Action </div> </div>', 'dd34cfcd-a7bb-4082-b1b7-26caab468070'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"Self","kind":"self","distanceValue":null,"distanceUnit":null,"area":null}', '<div> <div> Range/Area </div> <div> Self </div> </div>', 'dd34cfcd-a7bb-4082-b1b7-26caab468070'::uuid),
                    ('Components', 'components', '{"text":"V, S, M *","verbal":true,"somatic":true,"material":{"required":true,"description":"mistletoe","consumed":false,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S, M *</span> </div> </div>', 'dd34cfcd-a7bb-4082-b1b7-26caab468070'::uuid),
                    ('Duration', 'duration', '{"text":"1 Minute","kind":"timed","value":1,"unit":"minute","concentration":false,"endCondition":null}', '<div> <div>Duration</div> <div> 1 Minute </div> </div>', 'dd34cfcd-a7bb-4082-b1b7-26caab468070'::uuid),
                    ('School', 'school', 'Transmutation', '<div> <div> School </div> <div> Transmutation </div> </div>', 'dd34cfcd-a7bb-4082-b1b7-26caab468070'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"Melee","kind":"attack","attackType":"melee","ability":null}', '<div> <div> Attack/Save </div> <div> <i></i> <span>Melee</span> </div> </div>', 'dd34cfcd-a7bb-4082-b1b7-26caab468070'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Bludgeoning (...)","damageTypes":["Bludgeoning"]}', '<div> <div> Damage/Effect </div> <div> <i></i> Bludgeoning (...) </div> </div>', 'dd34cfcd-a7bb-4082-b1b7-26caab468070'::uuid),
                    ('Description', 'description', '["A Club or Quarterstaff you are holding is imbued with nature’s power. For the duration, you can use your spellcasting ability instead of Strength for the attack and damage rolls of melee attacks using that weapon, and the weapon’s damage die becomes a d8. If the attack deals damage, it can be Force damage or the weapon’s normal damage type (your choice).","The spell ends early if you cast it again or if you let go of the weapon.","Cantrip Upgrade. The damage die changes when you reach levels 5 (d10), 11 (d12), and 17 (2d6)."]', '<div> <p>A <a>Club</a> or <a>Quarterstaff</a> you are holding is imbued with nature’s power. For the duration, you can use your spellcasting ability instead of Strength for the attack and damage rolls of melee attacks using that weapon, and the weapon’s damage die becomes a d8. If the attack deals damage, it can be Force damage or the weapon’s normal damage type (your choice).</p> <p>The spell ends early if you cast it again or if you let go of the weapon.</p> <p><strong><em>Cantrip Upgrade.</em></strong> The damage die changes when you reach levels 5 (d10), 11 (d12), and 17 (2d6).</p> <span>* - (mistletoe)</span> </div>', 'dd34cfcd-a7bb-4082-b1b7-26caab468070'::uuid),
