                    ('Components', 'components', '{"text":"V","verbal":true,"somatic":false,"material":{"required":false,"description":null,"consumed":null,"costGp":null}}', '<div> <div> Components </div> <div> <span>V</span> </div> </div>', '8f1f7b1d-7b26-4dd6-99ee-5bd31a165e47'::uuid),
