                    ('Source URL', 'url', 'https://www.dndbeyond.com/spells/2618838-shining-smite', '', '8f1f7b1d-7b26-4dd6-99ee-5bd31a165e47'::uuid),
                    ('Image', 'imageUrl', 'https://www.dndbeyond.com/attachments/2/722/transmutation.png', '', '8f1f7b1d-7b26-4dd6-99ee-5bd31a165e47'::uuid),
                    ('Level', 'level', '{"levelNumber":"Cantrip","label":"Cantrip"}', '<div> <div> Level </div> <div> Cantrip </div> </div>', 'a3f25da8-6957-4081-953a-e9a554efbc41'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Action","kind":"action","value":1,"unit":"action","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Action </div> </div>', 'a3f25da8-6957-4081-953a-e9a554efbc41'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"Touch","kind":"touch","distanceValue":null,"distanceUnit":null,"area":null}', '<div> <div> Range/Area </div> <div> Touch </div> </div>', 'a3f25da8-6957-4081-953a-e9a554efbc41'::uuid),
                    ('Components', 'components', '{"text":"V, S","verbal":true,"somatic":true,"material":{"required":false,"description":null,"consumed":null,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S</span> </div> </div>', 'a3f25da8-6957-4081-953a-e9a554efbc41'::uuid),
                    ('Duration', 'duration', '{"text":"Instantaneous","kind":"instantaneous","value":null,"unit":null,"concentration":false,"endCondition":null}', '<div> <div>Duration</div> <div> Instantaneous </div> </div>', 'a3f25da8-6957-4081-953a-e9a554efbc41'::uuid),
                    ('School', 'school', 'Evocation', '<div> <div> School </div> <div> Evocation </div> </div>', 'a3f25da8-6957-4081-953a-e9a554efbc41'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"Melee","kind":"attack","attackType":"melee","ability":null}', '<div> <div> Attack/Save </div> <div> <i></i> <span>Melee</span> </div> </div>', 'a3f25da8-6957-4081-953a-e9a554efbc41'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Lightning","damageTypes":["Lightning"]}', '<div> <div> Damage/Effect </div> <div> <i></i> Lightning </div> </div>', 'a3f25da8-6957-4081-953a-e9a554efbc41'::uuid),
                    ('Description', 'description', '["Lightning springs from you to a creature that you try to touch. Make a melee spell attack against the target. On a hit, the target takes 1d8 Lightning damage, and it can’t make Opportunity Attacks until the start of its next turn.","Cantrip Upgrade. The damage increases by 1d8 when you reach levels 5 (2d8), 11 (3d8), and 17 (4d8)."]', '<div> <p>Lightning springs from you to a creature that you try to touch. Make a melee spell attack against the target. On a hit, the target takes 1d8 Lightning damage, and it can’t make <a>Opportunity Attacks</a> until the start of its next turn.</p> <p><strong><em>Cantrip Upgrade.</em></strong> The damage increases by 1d8 when you reach levels 5 (2d8), 11 (3d8), and 17 (4d8).</p> </div>', 'a3f25da8-6957-4081-953a-e9a554efbc41'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', 'a3f25da8-6957-4081-953a-e9a554efbc41'::uuid),
