                    ('Casting Time', 'castingTime', '{"text":"1 Action Ritual","kind":"action","value":1,"unit":"action","trigger":null,"ritual":true}', '<div> <div> Casting Time </div> <div> 1 Action <i>Ritual</i> </div> </div>', 'd97c28af-71eb-49ba-a978-106c41930a4c'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"120 ft. (20 ft.)","kind":"distance","distanceValue":120,"distanceUnit":"ft","area":{"shape":null,"value":20,"unit":"ft"}}', '<div> <div> Range/Area </div> <div> 120 ft. <span>(20 ft. <i></i>)</span> </div> </div>', 'd97c28af-71eb-49ba-a978-106c41930a4c'::uuid),
                    ('Components', 'components', '{"text":"V, S","verbal":true,"somatic":true,"material":{"required":false,"description":null,"consumed":null,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S</span> </div> </div>', 'd97c28af-71eb-49ba-a978-106c41930a4c'::uuid),
                    ('Duration', 'duration', '{"text":"Concentration 10 Minutes","kind":"timed","value":10,"unit":"minute","concentration":true,"endCondition":null}', '<div> <div>Duration</div> <div> <i>Concentration</i> 10 Minutes </div> </div>', 'd97c28af-71eb-49ba-a978-106c41930a4c'::uuid),
                    ('School', 'school', 'Illusion', '<div> <div> School </div> <div> Illusion </div> </div>', 'd97c28af-71eb-49ba-a978-106c41930a4c'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"None","kind":"none","attackType":null,"ability":null}', '<div> <div> Attack/Save </div> <div> <span>None</span> </div> </div>', 'd97c28af-71eb-49ba-a978-106c41930a4c'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Control","damageTypes":[]}', '<div> <div> Damage/Effect </div> <div> Control </div> </div>', 'd97c28af-71eb-49ba-a978-106c41930a4c'::uuid),
                    ('Description', 'description', '["For the duration, no sound can be created within or pass through a 20-foot-radius Sphere centered on a point you choose within range. Any creature or object entirely inside the Sphere has Immunity to Thunder damage, and creatures have the Deafened condition while entirely inside it. Casting a spell that includes a Verbal component is impossible there."]', '<div> <p>For the duration, no sound can be created within or pass through a 20-foot-radius <a>Sphere</a> centered on a point you choose within range. Any creature or object entirely inside the Sphere has Immunity to Thunder damage, and creatures have the <a>Deafened</a> condition while entirely inside it. Casting a spell that includes a Verbal component is impossible there.</p> </div>', 'd97c28af-71eb-49ba-a978-106c41930a4c'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', 'd97c28af-71eb-49ba-a978-106c41930a4c'::uuid),
                    ('Spell Tags', 'spellTags', '["Control"]', '', 'd97c28af-71eb-49ba-a978-106c41930a4c'::uuid),
                    ('Available For', 'availableFor', '["Bard (Legacy)","Cleric (Legacy)","Ranger (Legacy)","Bard","Cleric","Ranger","Warlock - The Fathomless (TCoE)","Warlock - The Undying (SCAG)","Illrigger - Architect of Ruin","Warlock - Mother of Sorrows (BoET)"]', '', 'd97c28af-71eb-49ba-a978-106c41930a4c'::uuid),
                    ('Source', 'source', 'Player’s Handbook, pg. 316', '', 'd97c28af-71eb-49ba-a978-106c41930a4c'::uuid),
                    ('Source URL', 'url', 'https://www.dndbeyond.com/spells/2619061-silence', '', 'd97c28af-71eb-49ba-a978-106c41930a4c'::uuid),
