                    ('Casting Time', 'castingTime', '{"text":"1 Action Ritual","kind":"action","value":1,"unit":"action","trigger":null,"ritual":true}', '<div> <div> Casting Time </div> <div> 1 Action <i>Ritual</i> </div> </div>', '12e4c6ff-9f95-4791-96c7-ef2d8c3ceeef'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"Sight","kind":"sight","distanceValue":null,"distanceUnit":null,"area":null}', '<div> <div> Range/Area </div> <div> Sight </div> </div>', '12e4c6ff-9f95-4791-96c7-ef2d8c3ceeef'::uuid),
                    ('Components', 'components', '{"text":"V, S","verbal":true,"somatic":true,"material":{"required":false,"description":null,"consumed":null,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S</span> </div> </div>', '12e4c6ff-9f95-4791-96c7-ef2d8c3ceeef'::uuid),
                    ('Duration', 'duration', '{"text":"Concentration 1 Hour","kind":"timed","value":1,"unit":"hour","concentration":true,"endCondition":null}', '<div> <div>Duration</div> <div> <i>Concentration</i> 1 Hour </div> </div>', '12e4c6ff-9f95-4791-96c7-ef2d8c3ceeef'::uuid),
                    ('School', 'school', 'Transmutation', '<div> <div> School </div> <div> Transmutation </div> </div>', '12e4c6ff-9f95-4791-96c7-ef2d8c3ceeef'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"None","kind":"none","attackType":null,"ability":null}', '<div> <div> Attack/Save </div> <div> <span>None</span> </div> </div>', '12e4c6ff-9f95-4791-96c7-ef2d8c3ceeef'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Communication (...)","damageTypes":[]}', '<div> <div> Damage/Effect </div> <div> Communication (...) </div> </div>', '12e4c6ff-9f95-4791-96c7-ef2d8c3ceeef'::uuid),
                    ('Description', 'description', '["You cause up to ten words to form in a part of the sky you can see. The words appear to be made of cloud and remain in place for the spell’s duration. The words dissipate when the spell ends. A strong wind can disperse the clouds and end the spell early."]', '<div> <p>You cause up to ten words to form in a part of the sky you can see. The words appear to be made of cloud and remain in place for the spell’s duration. The words dissipate when the spell ends. A strong wind can disperse the clouds and end the spell early.</p> </div>', '12e4c6ff-9f95-4791-96c7-ef2d8c3ceeef'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', '12e4c6ff-9f95-4791-96c7-ef2d8c3ceeef'::uuid),
