                    ('Level', 'level', '{"levelNumber":"1","label":"1st"}', '<div> <div> Level </div> <div> 1st </div> </div>', '116ea64d-080d-4d24-9f96-6d4e5a05979b'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Action","kind":"action","value":1,"unit":"action","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Action </div> </div>', '116ea64d-080d-4d24-9f96-6d4e5a05979b'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"60 ft. (5 ft.)","kind":"distance","distanceValue":60,"distanceUnit":"ft","area":{"shape":null,"value":5,"unit":"ft"}}', '<div> <div> Range/Area </div> <div> 60 ft. <span>(5 ft. <i></i>)</span> </div> </div>', '116ea64d-080d-4d24-9f96-6d4e5a05979b'::uuid),
                    ('Components', 'components', '{"text":"V, S, M *","verbal":true,"somatic":true,"material":{"required":true,"description":"a pinch of sand or rose petals","consumed":false,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S, M *</span> </div> </div>', '116ea64d-080d-4d24-9f96-6d4e5a05979b'::uuid),
                    ('Duration', 'duration', '{"text":"Concentration 1 Minute","kind":"timed","value":1,"unit":"minute","concentration":true,"endCondition":null}', '<div> <div>Duration</div> <div> <i>Concentration</i> 1 Minute </div> </div>', '116ea64d-080d-4d24-9f96-6d4e5a05979b'::uuid),
                    ('School', 'school', 'Enchantment', '<div> <div> School </div> <div> Enchantment </div> </div>', '116ea64d-080d-4d24-9f96-6d4e5a05979b'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"WIS Save","kind":"save","attackType":null,"ability":"WIS"}', '<div> <div> Attack/Save </div> <div> <i></i> <span>WIS Save</span> </div> </div>', '116ea64d-080d-4d24-9f96-6d4e5a05979b'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Incapacitated (...)","damageTypes":[]}', '<div> <div> Damage/Effect </div> <div> <i></i> Incapacitated (...) </div> </div>', '116ea64d-080d-4d24-9f96-6d4e5a05979b'::uuid),
                    ('Description', 'description', '["Each creature of your choice in a 5-foot-radius Sphere centered on a point within range must succeed on a Wisdom saving throw or have the Incapacitated condition until the end of its next turn, at which point it must repeat the save. If the target fails the second save, the target has the Unconscious condition for the duration. The spell ends on a target if it takes damage or someone within 5 feet of it takes an action to shake it out of the spell’s effect.","Creatures that don’t sleep, such as elves, or that have Immunity to the Exhaustion condition automatically succeed on saves against this spell."]', '<div> <p>Each creature of your choice in a 5-foot-radius <a>Sphere</a> centered on a point within range must succeed on a Wisdom saving throw or have the <a>Incapacitated</a> condition until the end of its next turn, at which point it must repeat the save. If the target fails the second save, the target has the <a>Unconscious</a> condition for the duration. The spell ends on a target if it takes damage or someone within 5 feet of it takes an action to shake it out of the spell’s effect.</p> <p>Creatures that don’t sleep, such as elves, or that have Immunity to the <a>Exhaustion</a> condition automatically succeed on saves against this spell.</p> <span>* - (a pinch of sand or rose petals)</span> </div>', '116ea64d-080d-4d24-9f96-6d4e5a05979b'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', '116ea64d-080d-4d24-9f96-6d4e5a05979b'::uuid),
