                    ('Level', 'level', '{"levelNumber":"3","label":"3rd"}', '<div> <div> Level </div> <div> 3rd </div> </div>', '0f21f716-79ec-45aa-977b-b3bb597498e1'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Action","kind":"action","value":1,"unit":"action","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Action </div> </div>', '0f21f716-79ec-45aa-977b-b3bb597498e1'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"150 ft. (40 ft. *)","kind":"distance","distanceValue":150,"distanceUnit":"ft","area":{"shape":null,"value":40,"unit":"ft"}}', '<div> <div> Range/Area </div> <div> 150 ft. <span>(40 ft. <i></i> *)</span> </div> </div>', '0f21f716-79ec-45aa-977b-b3bb597498e1'::uuid),
                    ('Components', 'components', '{"text":"V, S, M *","verbal":true,"somatic":true,"material":{"required":true,"description":"a miniature umbrella","consumed":false,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S, M *</span> </div> </div>', '0f21f716-79ec-45aa-977b-b3bb597498e1'::uuid),
                    ('Duration', 'duration', '{"text":"Concentration 1 Minute","kind":"timed","value":1,"unit":"minute","concentration":true,"endCondition":null}', '<div> <div>Duration</div> <div> <i>Concentration</i> 1 Minute </div> </div>', '0f21f716-79ec-45aa-977b-b3bb597498e1'::uuid),
                    ('School', 'school', 'Conjuration', '<div> <div> School </div> <div> Conjuration </div> </div>', '0f21f716-79ec-45aa-977b-b3bb597498e1'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"DEX Save","kind":"save","attackType":null,"ability":"DEX"}', '<div> <div> Attack/Save </div> <div> <i></i> <span>DEX Save</span> </div> </div>', '0f21f716-79ec-45aa-977b-b3bb597498e1'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Prone","damageTypes":[]}', '<div> <div> Damage/Effect </div> <div> <i></i> Prone </div> </div>', '0f21f716-79ec-45aa-977b-b3bb597498e1'::uuid),
                    ('Description', 'description', '["Until the spell ends, sleet falls in a 40-foot-tall, 20-foot-radius Cylinder centered on a point you choose within range. The area is Heavily Obscured , and exposed flames in the area are doused.","Ground in the Cylinder is Difficult Terrain . When a creature enters the Cylinder for the first time on a turn or starts its turn there, it must succeed on a Dexterity saving throw or have the Prone condition and lose Concentration ."]', '<div> <p>Until the spell ends, sleet falls in a 40-foot-tall, 20-foot-radius <a>Cylinder</a> centered on a point you choose within range. The area is <a>Heavily Obscured</a>, and exposed flames in the area are doused.</p> <p>Ground in the Cylinder is <a>Difficult Terrain</a>. When a creature enters the Cylinder for the first time on a turn or starts its turn there, it must succeed on a Dexterity saving throw or have the <a>Prone</a> condition and lose <a>Concentration</a>.</p> <span>* - (a miniature umbrella)</span> </div>', '0f21f716-79ec-45aa-977b-b3bb597498e1'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', '0f21f716-79ec-45aa-977b-b3bb597498e1'::uuid),
