                    ('Casting Time', 'castingTime', '{"text":"1 Action","kind":"action","value":1,"unit":"action","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Action </div> </div>', '67cb627e-a153-4a05-8c41-d9eb5b303f0b'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"90 ft. (5 ft.)","kind":"distance","distanceValue":90,"distanceUnit":"ft","area":{"shape":null,"value":5,"unit":"ft"}}', '<div> <div> Range/Area </div> <div> 90 ft. <span>(5 ft. <i></i>)</span> </div> </div>', '67cb627e-a153-4a05-8c41-d9eb5b303f0b'::uuid),
                    ('Components', 'components', '{"text":"V, S, M *","verbal":true,"somatic":true,"material":{"required":true,"description":"a piece of ice or a small white rock chip","consumed":false,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S, M *</span> </div> </div>', '67cb627e-a153-4a05-8c41-d9eb5b303f0b'::uuid),
                    ('Duration', 'duration', '{"text":"Instantaneous","kind":"instantaneous","value":null,"unit":null,"concentration":false,"endCondition":null}', '<div> <div>Duration</div> <div> Instantaneous </div> </div>', '67cb627e-a153-4a05-8c41-d9eb5b303f0b'::uuid),
                    ('School', 'school', 'Evocation', '<div> <div> School </div> <div> Evocation </div> </div>', '67cb627e-a153-4a05-8c41-d9eb5b303f0b'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"DEX Save","kind":"save","attackType":null,"ability":"DEX"}', '<div> <div> Attack/Save </div> <div> <i></i> <span>DEX Save</span> </div> </div>', '67cb627e-a153-4a05-8c41-d9eb5b303f0b'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Cold","damageTypes":["Cold"]}', '<div> <div> Damage/Effect </div> <div> <i></i> Cold </div> </div>', '67cb627e-a153-4a05-8c41-d9eb5b303f0b'::uuid),
                    ('Description', 'description', '["A flurry of magic snowballs erupts from a point you choose within range. Each creature in a 5-foot-radius sphere centered on that point must make a Dexterity saving throw. A creature takes 3d6 cold damage on a failed save, or half as much damage on a successful one.","At Higher Levels. When you cast this spell using a spell slot of 3rd level or higher, the damage increases by 1d6 for each slot level above 2nd."]', '<div> <p>A flurry of magic snowballs erupts from a point you choose within range. Each creature in a 5-foot-radius sphere centered on that point must make a Dexterity saving throw. A creature takes 3d6 cold damage on a failed save, or half as much damage on a successful one.</p> <p><strong>At Higher Levels.</strong> <span>When you cast this spell using a spell slot of 3rd level or higher, the damage increases by 1d6 for each slot level above 2nd.</span></p> <span>* - (a piece of ice or a small white rock chip)</span> </div>', '67cb627e-a153-4a05-8c41-d9eb5b303f0b'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', '67cb627e-a153-4a05-8c41-d9eb5b303f0b'::uuid),
