                    ('Available For', 'availableFor', '["Sorcerer (Legacy)","Wizard (Legacy)","Sorcerer","Wizard"]', '', '67cb627e-a153-4a05-8c41-d9eb5b303f0b'::uuid),
                    ('Source', 'source', 'Elemental Evil Player''s Companion, pg. 165', '', '67cb627e-a153-4a05-8c41-d9eb5b303f0b'::uuid),
                    ('Source URL', 'url', 'https://www.dndbeyond.com/spells/2399-snillocs-snowball-swarm', '', '67cb627e-a153-4a05-8c41-d9eb5b303f0b'::uuid),
                    ('Image', 'imageUrl', 'https://www.dndbeyond.com/attachments/2/703/evocation.png', '', '67cb627e-a153-4a05-8c41-d9eb5b303f0b'::uuid),
                    ('Level', 'level', '{"levelNumber":"Cantrip","label":"Cantrip"}', '<div> <div> Level </div> <div> Cantrip </div> </div>', 'a61fb382-4354-403b-87b5-89b2a22014ad'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Action","kind":"action","value":1,"unit":"action","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Action </div> </div>', 'a61fb382-4354-403b-87b5-89b2a22014ad'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"120 ft.","kind":"distance","distanceValue":120,"distanceUnit":"ft","area":null}', '<div> <div> Range/Area </div> <div> 120 ft. </div> </div>', 'a61fb382-4354-403b-87b5-89b2a22014ad'::uuid),
                    ('Components', 'components', '{"text":"V, S","verbal":true,"somatic":true,"material":{"required":false,"description":null,"consumed":null,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S</span> </div> </div>', 'a61fb382-4354-403b-87b5-89b2a22014ad'::uuid),
                    ('Duration', 'duration', '{"text":"Instantaneous","kind":"instantaneous","value":null,"unit":null,"concentration":false,"endCondition":null}', '<div> <div>Duration</div> <div> Instantaneous </div> </div>', 'a61fb382-4354-403b-87b5-89b2a22014ad'::uuid),
                    ('School', 'school', 'Evocation', '<div> <div> School </div> <div> Evocation </div> </div>', 'a61fb382-4354-403b-87b5-89b2a22014ad'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"Ranged","kind":"attack","attackType":"ranged","ability":null}', '<div> <div> Attack/Save </div> <div> <i></i> <span>Ranged</span> </div> </div>', 'a61fb382-4354-403b-87b5-89b2a22014ad'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Acid (...)","damageTypes":["Acid"]}', '<div> <div> Damage/Effect </div> <div> <i></i> Acid (...) </div> </div>', 'a61fb382-4354-403b-87b5-89b2a22014ad'::uuid),
                    ('Description', 'description', '["You cast sorcerous energy at one creature or object within range. Make a ranged spell attack against the target. On a hit, the target takes 1d8 damage of a type you choose: Acid, Cold, Fire, Lightning, Poison, Psychic, or Thunder.","If you roll an 8 on a d8 for this spell, you can roll another d8, and add it to the damage. When you cast this spell, the maximum number of these d8s you can add to the spell’s damage equals your spellcasting ability modifier.","Cantrip Upgrade. The damage increases by 1d8 when you reach levels 5 (2d8), 11 (3d8), and 17 (4d8)."]', '<div> <p>You cast sorcerous energy at one creature or object within range. Make a ranged spell attack against the target. On a hit, the target takes 1d8 damage of a type you choose: Acid, Cold, Fire, Lightning, Poison, Psychic, or Thunder.</p> <p>If you roll an 8 on a d8 for this spell, you can roll another d8, and add it to the damage. When you cast this spell, the maximum number of these d8s you can add to the spell’s damage equals your spellcasting ability modifier.</p> <p><em><strong>Cantrip Upgrade.</strong></em> The damage increases by 1d8 when you reach levels 5 (2d8), 11 (3d8), and 17 (4d8).</p> </div>', 'a61fb382-4354-403b-87b5-89b2a22014ad'::uuid),
