                    ('School', 'school', 'Necromancy', '<div> <div> School </div> <div> Necromancy </div> </div>', '19b79798-9319-42be-b69b-faf62682f4a5'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"None","kind":"none","attackType":null,"ability":null}', '<div> <div> Attack/Save </div> <div> <span>None</span> </div> </div>', '19b79798-9319-42be-b69b-faf62682f4a5'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Healing","damageTypes":[]}', '<div> <div> Damage/Effect </div> <div> Healing </div> </div>', '19b79798-9319-42be-b69b-faf62682f4a5'::uuid),
                    ('Description', 'description', '["Choose a creature within range that has 0 Hit Points and isn’t dead . The creature becomes Stable .","Cantrip Upgrade. The range doubles when you reach levels 5 (30 feet), 11 (60 feet), and 17 (120 feet)."]', '<div> <p>Choose a creature within range that has 0 Hit Points and isn’t <a>dead</a>. The creature becomes <a>Stable</a>.</p> <p><strong><em>Cantrip Upgrade.</em></strong> The range doubles when you reach levels 5 (30 feet), 11 (60 feet), and 17 (120 feet).</p> </div>', '19b79798-9319-42be-b69b-faf62682f4a5'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', '19b79798-9319-42be-b69b-faf62682f4a5'::uuid),
