                    ('Available For', 'availableFor', '["Cleric (Legacy)","Druid (Legacy)","Artificer (Legacy)","Cleric","Druid","Artificer","Fighter - Bonesmith"]', '', '19b79798-9319-42be-b69b-faf62682f4a5'::uuid),
                    ('Source', 'source', 'Player’s Handbook, pg. 318', '', '19b79798-9319-42be-b69b-faf62682f4a5'::uuid),
                    ('Source URL', 'url', 'https://www.dndbeyond.com/spells/2619067-spare-the-dying', '', '19b79798-9319-42be-b69b-faf62682f4a5'::uuid),
                    ('Image', 'imageUrl', 'https://www.dndbeyond.com/attachments/2/720/necromancy.png', '', '19b79798-9319-42be-b69b-faf62682f4a5'::uuid),
                    ('Level', 'level', '{"levelNumber":"1","label":"1st"}', '<div> <div> Level </div> <div> 1st </div> </div>', '9fe6d89e-d5a8-4999-9698-c721d81e13b2'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Action Ritual","kind":"action","value":1,"unit":"action","trigger":null,"ritual":true}', '<div> <div> Casting Time </div> <div> 1 Action <i>Ritual</i> </div> </div>', '9fe6d89e-d5a8-4999-9698-c721d81e13b2'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"Self","kind":"self","distanceValue":null,"distanceUnit":null,"area":null}', '<div> <div> Range/Area </div> <div> Self </div> </div>', '9fe6d89e-d5a8-4999-9698-c721d81e13b2'::uuid),
                    ('Components', 'components', '{"text":"V, S","verbal":true,"somatic":true,"material":{"required":false,"description":null,"consumed":null,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S</span> </div> </div>', '9fe6d89e-d5a8-4999-9698-c721d81e13b2'::uuid),
                    ('Duration', 'duration', '{"text":"10 Minutes","kind":"timed","value":10,"unit":"minute","concentration":false,"endCondition":null}', '<div> <div>Duration</div> <div> 10 Minutes </div> </div>', '9fe6d89e-d5a8-4999-9698-c721d81e13b2'::uuid),
                    ('School', 'school', 'Divination', '<div> <div> School </div> <div> Divination </div> </div>', '9fe6d89e-d5a8-4999-9698-c721d81e13b2'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"None","kind":"none","attackType":null,"ability":null}', '<div> <div> Attack/Save </div> <div> <span>None</span> </div> </div>', '9fe6d89e-d5a8-4999-9698-c721d81e13b2'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Communication (...)","damageTypes":[]}', '<div> <div> Damage/Effect </div> <div> Communication (...) </div> </div>', '9fe6d89e-d5a8-4999-9698-c721d81e13b2'::uuid),
                    ('Description', 'description', '["For the duration, you can comprehend and verbally communicate with Beasts, and you can use any of the Influence action’s skill options with them.","Most Beasts have little to say about topics that don’t pertain to survival or companionship, but at minimum, a Beast can give you information about nearby locations and monsters, including whatever it has perceived within the past day."]', '<div> <p>For the duration, you can comprehend and verbally communicate with Beasts, and you can use any of the <a>Influence</a> action’s skill options with them.</p> <p>Most Beasts have little to say about topics that don’t pertain to survival or companionship, but at minimum, a Beast can give you information about nearby locations and monsters, including whatever it has perceived within the past day.</p> </div>', '9fe6d89e-d5a8-4999-9698-c721d81e13b2'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', '9fe6d89e-d5a8-4999-9698-c721d81e13b2'::uuid);
                """);

            migrationBuilder.Sql("""
                INSERT INTO "SpellComponents" ("Label", "Key", "Value", "Html", "SpellId") VALUES
                    ('Spell Tags', 'spellTags', '["Communication","Social"]', '', '9fe6d89e-d5a8-4999-9698-c721d81e13b2'::uuid),
                    ('Available For', 'availableFor', '["Bard (Legacy)","Druid (Legacy)","Ranger (Legacy)","Warlock (Legacy)","Bard","Druid","Ranger","Warlock","Cleric - Nature Domain (PHB)","Paladin - Oath of the Ancients"]', '', '9fe6d89e-d5a8-4999-9698-c721d81e13b2'::uuid),
                    ('Source', 'source', 'Player’s Handbook, pg. 318', '', '9fe6d89e-d5a8-4999-9698-c721d81e13b2'::uuid),
                    ('Source URL', 'url', 'https://www.dndbeyond.com/spells/2619059-speak-with-animals', '', '9fe6d89e-d5a8-4999-9698-c721d81e13b2'::uuid),
                    ('Image', 'imageUrl', 'https://www.dndbeyond.com/attachments/2/709/divination.png', '', '9fe6d89e-d5a8-4999-9698-c721d81e13b2'::uuid),
                    ('Level', 'level', '{"levelNumber":"3","label":"3rd"}', '<div> <div> Level </div> <div> 3rd </div> </div>', 'ab8b2d33-fbdc-4705-8e1f-9e290167ffa2'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Action","kind":"action","value":1,"unit":"action","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Action </div> </div>', 'ab8b2d33-fbdc-4705-8e1f-9e290167ffa2'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"10 ft.","kind":"distance","distanceValue":10,"distanceUnit":"ft","area":null}', '<div> <div> Range/Area </div> <div> 10 ft. </div> </div>', 'ab8b2d33-fbdc-4705-8e1f-9e290167ffa2'::uuid),
                    ('Components', 'components', '{"text":"V, S, M *","verbal":true,"somatic":true,"material":{"required":true,"description":"burning incense","consumed":false,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S, M *</span> </div> </div>', 'ab8b2d33-fbdc-4705-8e1f-9e290167ffa2'::uuid),
                    ('Duration', 'duration', '{"text":"10 Minutes","kind":"timed","value":10,"unit":"minute","concentration":false,"endCondition":null}', '<div> <div>Duration</div> <div> 10 Minutes </div> </div>', 'ab8b2d33-fbdc-4705-8e1f-9e290167ffa2'::uuid),
                    ('School', 'school', 'Necromancy', '<div> <div> School </div> <div> Necromancy </div> </div>', 'ab8b2d33-fbdc-4705-8e1f-9e290167ffa2'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"None","kind":"none","attackType":null,"ability":null}', '<div> <div> Attack/Save </div> <div> <span>None</span> </div> </div>', 'ab8b2d33-fbdc-4705-8e1f-9e290167ffa2'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Communication (...)","damageTypes":[]}', '<div> <div> Damage/Effect </div> <div> Communication (...) </div> </div>', 'ab8b2d33-fbdc-4705-8e1f-9e290167ffa2'::uuid),
                    ('Description', 'description', '["You grant the semblance of life to a corpse of your choice within range, allowing it to answer questions you pose. The corpse must have a mouth, and this spell fails if the deceased creature was Undead when it died. The spell also fails if the corpse was the target of this spell within the past 10 days.","Until the spell ends, you can ask the corpse up to five questions. The corpse knows only what it knew in life, including the languages it knew. Answers are usually brief, cryptic, or repetitive, and the corpse is under no compulsion to offer a truthful answer if you are antagonistic toward it or it recognizes you as an enemy. This spell doesn’t return the creature’s soul to its body, only its animating spirit. Thus, the corpse can’t learn new information, doesn’t comprehend anything that has happened since it died, and can’t speculate about future events."]', '<div> <p>You grant the semblance of life to a corpse of your choice within range, allowing it to answer questions you pose. The corpse must have a mouth, and this spell fails if the deceased creature was Undead when it died. The spell also fails if the corpse was the target of this spell within the past 10 days.</p> <p>Until the spell ends, you can ask the corpse up to five questions. The corpse knows only what it knew in life, including the languages it knew. Answers are usually brief, cryptic, or repetitive, and the corpse is under no compulsion to offer a truthful answer if you are antagonistic toward it or it recognizes you as an enemy. This spell doesn’t return the creature’s soul to its body, only its animating spirit. Thus, the corpse can’t learn new information, doesn’t comprehend anything that has happened since it died, and can’t speculate about future events.</p> <span>* - (burning incense)</span> </div>', 'ab8b2d33-fbdc-4705-8e1f-9e290167ffa2'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', 'ab8b2d33-fbdc-4705-8e1f-9e290167ffa2'::uuid),
                    ('Spell Tags', 'spellTags', '["Communication","Social"]', '', 'ab8b2d33-fbdc-4705-8e1f-9e290167ffa2'::uuid),
                    ('Available For', 'availableFor', '["Bard (Legacy)","Cleric (Legacy)","Wizard (Legacy)","Bard","Cleric","Wizard","Cleric - Knowledge Domain (Legacy)","Paladin - Oath of Castigation","Warlock - The Undead (VRGtR)","Warlock - The Undying (SCAG)"]', '', 'ab8b2d33-fbdc-4705-8e1f-9e290167ffa2'::uuid),
                    ('Source', 'source', 'Player’s Handbook, pg. 318', '', 'ab8b2d33-fbdc-4705-8e1f-9e290167ffa2'::uuid),
                    ('Source URL', 'url', 'https://www.dndbeyond.com/spells/2619068-speak-with-dead', '', 'ab8b2d33-fbdc-4705-8e1f-9e290167ffa2'::uuid),
                    ('Image', 'imageUrl', 'https://www.dndbeyond.com/attachments/2/720/necromancy.png', '', 'ab8b2d33-fbdc-4705-8e1f-9e290167ffa2'::uuid),
                    ('Level', 'level', '{"levelNumber":"3","label":"3rd"}', '<div> <div> Level </div> <div> 3rd </div> </div>', '6174ac74-af33-44e8-bb2a-21e2dd46ca8a'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Action","kind":"action","value":1,"unit":"action","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Action </div> </div>', '6174ac74-af33-44e8-bb2a-21e2dd46ca8a'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"Self","kind":"self","distanceValue":null,"distanceUnit":null,"area":null}', '<div> <div> Range/Area </div> <div> Self </div> </div>', '6174ac74-af33-44e8-bb2a-21e2dd46ca8a'::uuid),
                    ('Components', 'components', '{"text":"V, S","verbal":true,"somatic":true,"material":{"required":false,"description":null,"consumed":null,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S</span> </div> </div>', '6174ac74-af33-44e8-bb2a-21e2dd46ca8a'::uuid),
                    ('Duration', 'duration', '{"text":"10 Minutes","kind":"timed","value":10,"unit":"minute","concentration":false,"endCondition":null}', '<div> <div>Duration</div> <div> 10 Minutes </div> </div>', '6174ac74-af33-44e8-bb2a-21e2dd46ca8a'::uuid),
                    ('School', 'school', 'Transmutation', '<div> <div> School </div> <div> Transmutation </div> </div>', '6174ac74-af33-44e8-bb2a-21e2dd46ca8a'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"None","kind":"none","attackType":null,"ability":null}', '<div> <div> Attack/Save </div> <div> <span>None</span> </div> </div>', '6174ac74-af33-44e8-bb2a-21e2dd46ca8a'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Communication (...)","damageTypes":[]}', '<div> <div> Damage/Effect </div> <div> Communication (...) </div> </div>', '6174ac74-af33-44e8-bb2a-21e2dd46ca8a'::uuid),
                    ('Description', 'description', '["You imbue plants in an immobile 30-foot Emanation with limited sentience and animation, giving them the ability to communicate with you and follow your simple commands. You can question plants about events in the spell’s area within the past day, gaining information about creatures that have passed, weather, and other circumstances.","You can also turn Difficult Terrain caused by plant growth (such as thickets and undergrowth) into ordinary terrain that lasts for the duration. Or you can turn ordinary terrain where plants are present into Difficult Terrain that lasts for the duration.","The spell doesn’t enable plants to uproot themselves and move about, but they can move their branches, tendrils, and stalks for you.","If a Plant creature is in the area, you can communicate with it as if you shared a common language."]', '<div> <p>You imbue plants in an immobile 30-foot <a>Emanation</a> with limited sentience and animation, giving them the ability to communicate with you and follow your simple commands. You can question plants about events in the spell’s area within the past day, gaining information about creatures that have passed, weather, and other circumstances.</p> <p>You can also turn <a>Difficult Terrain</a> caused by plant growth (such as thickets and undergrowth) into ordinary terrain that lasts for the duration. Or you can turn ordinary terrain where plants are present into Difficult Terrain that lasts for the duration.</p> <p>The spell doesn’t enable plants to uproot themselves and move about, but they can move their branches, tendrils, and stalks for you.</p> <p>If a Plant creature is in the area, you can communicate with it as if you shared a common language.</p> </div>', '6174ac74-af33-44e8-bb2a-21e2dd46ca8a'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', '6174ac74-af33-44e8-bb2a-21e2dd46ca8a'::uuid),
                    ('Spell Tags', 'spellTags', '["Communication","Social"]', '', '6174ac74-af33-44e8-bb2a-21e2dd46ca8a'::uuid),
                    ('Available For', 'availableFor', '["Bard (Legacy)","Druid (Legacy)","Ranger (Legacy)","Bard","Druid","Ranger"]', '', '6174ac74-af33-44e8-bb2a-21e2dd46ca8a'::uuid),
                    ('Source', 'source', 'Player’s Handbook, pg. 318', '', '6174ac74-af33-44e8-bb2a-21e2dd46ca8a'::uuid),
                    ('Source URL', 'url', 'https://www.dndbeyond.com/spells/2619069-speak-with-plants', '', '6174ac74-af33-44e8-bb2a-21e2dd46ca8a'::uuid),
                    ('Image', 'imageUrl', 'https://www.dndbeyond.com/attachments/2/722/transmutation.png', '', '6174ac74-af33-44e8-bb2a-21e2dd46ca8a'::uuid),
                    ('Level', 'level', '{"levelNumber":"2","label":"2nd"}', '<div> <div> Level </div> <div> 2nd </div> </div>', 'e469f2d1-ed7b-4d20-8801-d210df78e63d'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Action","kind":"action","value":1,"unit":"action","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Action </div> </div>', 'e469f2d1-ed7b-4d20-8801-d210df78e63d'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"Touch","kind":"touch","distanceValue":null,"distanceUnit":null,"area":null}', '<div> <div> Range/Area </div> <div> Touch </div> </div>', 'e469f2d1-ed7b-4d20-8801-d210df78e63d'::uuid),
                    ('Components', 'components', '{"text":"V, S, M *","verbal":true,"somatic":true,"material":{"required":true,"description":"a drop of bitumen and a spider","consumed":false,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S, M *</span> </div> </div>', 'e469f2d1-ed7b-4d20-8801-d210df78e63d'::uuid),
                    ('Duration', 'duration', '{"text":"Concentration 1 Hour","kind":"timed","value":1,"unit":"hour","concentration":true,"endCondition":null}', '<div> <div>Duration</div> <div> <i>Concentration</i> 1 Hour </div> </div>', 'e469f2d1-ed7b-4d20-8801-d210df78e63d'::uuid),
                    ('School', 'school', 'Transmutation', '<div> <div> School </div> <div> Transmutation </div> </div>', 'e469f2d1-ed7b-4d20-8801-d210df78e63d'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"None","kind":"none","attackType":null,"ability":null}', '<div> <div> Attack/Save </div> <div> <span>None</span> </div> </div>', 'e469f2d1-ed7b-4d20-8801-d210df78e63d'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Buff (...)","damageTypes":[]}', '<div> <div> Damage/Effect </div> <div> Buff (...) </div> </div>', 'e469f2d1-ed7b-4d20-8801-d210df78e63d'::uuid),
                    ('Description', 'description', '["Until the spell ends, one willing creature you touch gains the ability to move up, down, and across vertical surfaces and along ceilings, while leaving its hands free. The target also gains a Climb Speed equal to its Speed.","Using a Higher-Level Spell Slot. You can target one additional creature for each spell slot level above 2."]', '<div> <p>Until the spell ends, one willing creature you touch gains the ability to move up, down, and across vertical surfaces and along ceilings, while leaving its hands free. The target also gains a Climb Speed equal to its Speed.</p> <p><strong><em>Using a Higher-Level Spell Slot.</em></strong> You can target one additional creature for each spell slot level above 2.</p> <span>* - (a drop of bitumen and a spider)</span> </div>', 'e469f2d1-ed7b-4d20-8801-d210df78e63d'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', 'e469f2d1-ed7b-4d20-8801-d210df78e63d'::uuid),
                    ('Spell Tags', 'spellTags', '["Buff","Movement"]', '', 'e469f2d1-ed7b-4d20-8801-d210df78e63d'::uuid),
                    ('Available For', 'availableFor', '["Sorcerer (Legacy)","Warlock (Legacy)","Wizard (Legacy)","Artificer (Legacy)","Sorcerer","Warlock","Wizard","Artificer"]', '', 'e469f2d1-ed7b-4d20-8801-d210df78e63d'::uuid),
                    ('Source', 'source', 'Player’s Handbook, pg. 318', '', 'e469f2d1-ed7b-4d20-8801-d210df78e63d'::uuid),
                    ('Source URL', 'url', 'https://www.dndbeyond.com/spells/2619071-spider-climb', '', 'e469f2d1-ed7b-4d20-8801-d210df78e63d'::uuid),
