                    ('Level', 'level', '{"levelNumber":"2","label":"2nd"}', '<div> <div> Level </div> <div> 2nd </div> </div>', '40c4be42-38e4-413c-ad9f-01a2ea79c69f'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Action","kind":"action","value":1,"unit":"action","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Action </div> </div>', '40c4be42-38e4-413c-ad9f-01a2ea79c69f'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"150 ft. (20 ft.)","kind":"distance","distanceValue":150,"distanceUnit":"ft","area":{"shape":null,"value":20,"unit":"ft"}}', '<div> <div> Range/Area </div> <div> 150 ft. <span>(20 ft. <i></i>)</span> </div> </div>', '40c4be42-38e4-413c-ad9f-01a2ea79c69f'::uuid),
                    ('Components', 'components', '{"text":"V, S, M *","verbal":true,"somatic":true,"material":{"required":true,"description":"seven thorns","consumed":false,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S, M *</span> </div> </div>', '40c4be42-38e4-413c-ad9f-01a2ea79c69f'::uuid),
                    ('Duration', 'duration', '{"text":"Concentration 10 Minutes","kind":"timed","value":10,"unit":"minute","concentration":true,"endCondition":null}', '<div> <div>Duration</div> <div> <i>Concentration</i> 10 Minutes </div> </div>', '40c4be42-38e4-413c-ad9f-01a2ea79c69f'::uuid),
                    ('School', 'school', 'Transmutation', '<div> <div> School </div> <div> Transmutation </div> </div>', '40c4be42-38e4-413c-ad9f-01a2ea79c69f'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"None","kind":"none","attackType":null,"ability":null}', '<div> <div> Attack/Save </div> <div> <span>None</span> </div> </div>', '40c4be42-38e4-413c-ad9f-01a2ea79c69f'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Control (...)","damageTypes":[]}', '<div> <div> Damage/Effect </div> <div> Control (...) </div> </div>', '40c4be42-38e4-413c-ad9f-01a2ea79c69f'::uuid),
                    ('Description', 'description', '["The ground in a 20-foot-radius Sphere centered on a point within range sprouts hard spikes and thorns. The area becomes Difficult Terrain for the duration. When a creature moves into or within the area, it takes 2d4 Piercing damage for every 5 feet it travels.","The transformation of the ground is camouflaged to look natural. Any creature that can’t see the area when the spell is cast must take a Search action and succeed on a Wisdom ( Perception or Survival ) check against your spell save DC to recognize the terrain as hazardous before entering it."]', '<div> <p>The ground in a 20-foot-radius <a>Sphere</a> centered on a point within range sprouts hard spikes and thorns. The area becomes <a>Difficult Terrain</a> for the duration. When a creature moves into or within the area, it takes 2d4 Piercing damage for every 5 feet it travels.</p> <p>The transformation of the ground is camouflaged to look natural. Any creature that can’t see the area when the spell is cast must take a <a>Search</a> action and succeed on a Wisdom (<a>Perception</a> or <a>Survival</a>) check against your spell save DC to recognize the terrain as hazardous before entering it.</p> <span>* - (seven thorns)</span> </div>', '40c4be42-38e4-413c-ad9f-01a2ea79c69f'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', '40c4be42-38e4-413c-ad9f-01a2ea79c69f'::uuid),
                    ('Spell Tags', 'spellTags', '["Damage","Control"]', '', '40c4be42-38e4-413c-ad9f-01a2ea79c69f'::uuid),
                    ('Available For', 'availableFor', '["Druid (Legacy)","Ranger (Legacy)","Druid","Ranger","Cleric - Nature Domain (PHB)","Warlock - The Genie (TCoE)","Warlock - Horned King Patron"]', '', '40c4be42-38e4-413c-ad9f-01a2ea79c69f'::uuid),
                    ('Source', 'source', 'Player’s Handbook, pg. 318', '', '40c4be42-38e4-413c-ad9f-01a2ea79c69f'::uuid),
                    ('Source URL', 'url', 'https://www.dndbeyond.com/spells/2619075-spike-growth', '', '40c4be42-38e4-413c-ad9f-01a2ea79c69f'::uuid),
                    ('Image', 'imageUrl', 'https://www.dndbeyond.com/attachments/2/722/transmutation.png', '', '40c4be42-38e4-413c-ad9f-01a2ea79c69f'::uuid),
                    ('Level', 'level', '{"levelNumber":"3","label":"3rd"}', '<div> <div> Level </div> <div> 3rd </div> </div>', '9fe951a6-4e12-4eff-bae4-2e96a8a5bcd3'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Action","kind":"action","value":1,"unit":"action","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Action </div> </div>', '9fe951a6-4e12-4eff-bae4-2e96a8a5bcd3'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"Self (15 ft.)","kind":"self","distanceValue":null,"distanceUnit":null,"area":{"shape":null,"value":15,"unit":"ft"}}', '<div> <div> Range/Area </div> <div> Self <span>(15 ft. <i></i>)</span> </div> </div>', '9fe951a6-4e12-4eff-bae4-2e96a8a5bcd3'::uuid),
                    ('Components', 'components', '{"text":"V, S, M *","verbal":true,"somatic":true,"material":{"required":true,"description":"a prayer scroll","consumed":false,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S, M *</span> </div> </div>', '9fe951a6-4e12-4eff-bae4-2e96a8a5bcd3'::uuid),
                    ('Duration', 'duration', '{"text":"Concentration 10 Minutes","kind":"timed","value":10,"unit":"minute","concentration":true,"endCondition":null}', '<div> <div>Duration</div> <div> <i>Concentration</i> 10 Minutes </div> </div>', '9fe951a6-4e12-4eff-bae4-2e96a8a5bcd3'::uuid),
                    ('School', 'school', 'Conjuration', '<div> <div> School </div> <div> Conjuration </div> </div>', '9fe951a6-4e12-4eff-bae4-2e96a8a5bcd3'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"WIS Save","kind":"save","attackType":null,"ability":"WIS"}', '<div> <div> Attack/Save </div> <div> <i></i> <span>WIS Save</span> </div> </div>', '9fe951a6-4e12-4eff-bae4-2e96a8a5bcd3'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Radiant (...)","damageTypes":["Radiant"]}', '<div> <div> Damage/Effect </div> <div> <i></i> Radiant (...) </div> </div>', '9fe951a6-4e12-4eff-bae4-2e96a8a5bcd3'::uuid),
                    ('Description', 'description', '["Protective spirits flit around you in a 15-foot Emanation for the duration. If you are good or neutral, their spectral form appears angelic or fey (your choice). If you are evil, they appear fiendish.","When you cast this spell, you can designate creatures to be unaffected by it. Any other creature’s Speed is halved in the Emanation, and whenever the Emanation enters a creature’s space and whenever a creature enters the Emanation or ends its turn there, the creature must make a Wisdom saving throw. On a failed save, the creature takes 3d8 Radiant damage (if you are good or neutral) or 3d8 Necrotic damage (if you are evil). On a successful save, the creature takes half as much damage. A creature makes this save only once per turn.","Using a Higher-Level Spell Slot. The damage increases by 1d8 for each spell slot level above 3."]', '<div> <p>Protective spirits flit around you in a 15-foot <a>Emanation</a> for the duration. If you are good or neutral, their spectral form appears angelic or fey (your choice). If you are evil, they appear fiendish.</p> <p>When you cast this spell, you can designate creatures to be unaffected by it. Any other creature’s Speed is halved in the Emanation, and whenever the Emanation enters a creature’s space and whenever a creature enters the Emanation or ends its turn there, the creature must make a Wisdom saving throw. On a failed save, the creature takes 3d8 Radiant damage (if you are good or neutral) or 3d8 Necrotic damage (if you are evil). On a successful save, the creature takes half as much damage. A creature makes this save only once per turn.</p> <p><strong><em>Using a Higher-Level Spell Slot.</em></strong> The damage increases by 1d8 for each spell slot level above 3.</p> <span>* - (a prayer scroll)</span> </div>', '9fe951a6-4e12-4eff-bae4-2e96a8a5bcd3'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', '9fe951a6-4e12-4eff-bae4-2e96a8a5bcd3'::uuid),
