                    ('Source', 'source', 'Player’s Handbook, pg. 318', '', '9fe951a6-4e12-4eff-bae4-2e96a8a5bcd3'::uuid),
                    ('Source URL', 'url', 'https://www.dndbeyond.com/spells/2619078-spirit-guardians', '', '9fe951a6-4e12-4eff-bae4-2e96a8a5bcd3'::uuid),
                    ('Image', 'imageUrl', 'https://www.dndbeyond.com/attachments/2/708/conjuration.png', '', '9fe951a6-4e12-4eff-bae4-2e96a8a5bcd3'::uuid),
                    ('Level', 'level', '{"levelNumber":"2","label":"2nd"}', '<div> <div> Level </div> <div> 2nd </div> </div>', '5a15674b-4bfb-42a1-8583-376369b92742'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Bonus Action","kind":"bonus_action","value":1,"unit":"action","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Bonus Action </div> </div>', '5a15674b-4bfb-42a1-8583-376369b92742'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"60 ft.","kind":"distance","distanceValue":60,"distanceUnit":"ft","area":null}', '<div> <div> Range/Area </div> <div> 60 ft. </div> </div>', '5a15674b-4bfb-42a1-8583-376369b92742'::uuid),
                    ('Components', 'components', '{"text":"V, S","verbal":true,"somatic":true,"material":{"required":false,"description":null,"consumed":null,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S</span> </div> </div>', '5a15674b-4bfb-42a1-8583-376369b92742'::uuid),
                    ('Duration', 'duration', '{"text":"Concentration 1 Minute","kind":"timed","value":1,"unit":"minute","concentration":true,"endCondition":null}', '<div> <div>Duration</div> <div> <i>Concentration</i> 1 Minute </div> </div>', '5a15674b-4bfb-42a1-8583-376369b92742'::uuid),
                    ('School', 'school', 'Evocation', '<div> <div> School </div> <div> Evocation </div> </div>', '5a15674b-4bfb-42a1-8583-376369b92742'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"Melee","kind":"attack","attackType":"melee","ability":null}', '<div> <div> Attack/Save </div> <div> <i></i> <span>Melee</span> </div> </div>', '5a15674b-4bfb-42a1-8583-376369b92742'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Force","damageTypes":["Force"]}', '<div> <div> Damage/Effect </div> <div> <i></i> Force </div> </div>', '5a15674b-4bfb-42a1-8583-376369b92742'::uuid),
                    ('Description', 'description', '["You create a floating, spectral force that resembles a weapon of your choice and lasts for the duration. The force appears within range in a space of your choice, and you can immediately make one melee spell attack against one creature within 5 feet of the force. On a hit, the target takes Force damage equal to 1d8 plus your spellcasting ability modifier.","As a Bonus Action on your later turns, you can move the force up to 20 feet and repeat the attack against a creature within 5 feet of it.","Using a Higher-Level Spell Slot. The damage increases by 1d8 for every slot level above 2."]', '<div> <p>You create a floating, spectral force that resembles a weapon of your choice and lasts for the duration. The force appears within range in a space of your choice, and you can immediately make one melee spell attack against one creature within 5 feet of the force. On a hit, the target takes Force damage equal to 1d8 plus your spellcasting ability modifier.</p> <p>As a Bonus Action on your later turns, you can move the force up to 20 feet and repeat the attack against a creature within 5 feet of it.</p> <p><strong><em>Using a Higher-Level Spell Slot.</em></strong> The damage increases by 1d8 for every slot level above 2.</p> </div>', '5a15674b-4bfb-42a1-8583-376369b92742'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', '5a15674b-4bfb-42a1-8583-376369b92742'::uuid),
