                    ('Level', 'level', '{"levelNumber":"Cantrip","label":"Cantrip"}', '<div> <div> Level </div> <div> Cantrip </div> </div>', '92f37fac-7da4-4df3-9441-15aa71549921'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Action","kind":"action","value":1,"unit":"action","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Action </div> </div>', '92f37fac-7da4-4df3-9441-15aa71549921'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"60 ft.","kind":"distance","distanceValue":60,"distanceUnit":"ft","area":null}', '<div> <div> Range/Area </div> <div> 60 ft. </div> </div>', '92f37fac-7da4-4df3-9441-15aa71549921'::uuid),
                    ('Components', 'components', '{"text":"V, S","verbal":true,"somatic":true,"material":{"required":false,"description":null,"consumed":null,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S</span> </div> </div>', '92f37fac-7da4-4df3-9441-15aa71549921'::uuid),
                    ('Duration', 'duration', '{"text":"Instantaneous","kind":"instantaneous","value":null,"unit":null,"concentration":false,"endCondition":null}', '<div> <div>Duration</div> <div> Instantaneous </div> </div>', '92f37fac-7da4-4df3-9441-15aa71549921'::uuid),
                    ('School', 'school', 'Evocation', '<div> <div> School </div> <div> Evocation </div> </div>', '92f37fac-7da4-4df3-9441-15aa71549921'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"Ranged","kind":"attack","attackType":"ranged","ability":null}', '<div> <div> Attack/Save </div> <div> <i></i> <span>Ranged</span> </div> </div>', '92f37fac-7da4-4df3-9441-15aa71549921'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Radiant","damageTypes":["Radiant"]}', '<div> <div> Damage/Effect </div> <div> <i></i> Radiant </div> </div>', '92f37fac-7da4-4df3-9441-15aa71549921'::uuid),
                    ('Description', 'description', '["You launch a mote of light at one creature or object within range. Make a ranged spell attack against the target. On a hit, the target takes 1d8 Radiant damage, and until the end of your next turn, it emits Dim Light in a 10-foot radius and can’t benefit from the Invisible condition.","Cantrip Upgrade. The damage increases by 1d8 when you reach levels 5 (2d8), 11 (3d8), and 17 (4d8)."]', '<div> <p>You launch a mote of light at one creature or object within range. Make a ranged spell attack against the target. On a hit, the target takes 1d8 Radiant damage, and until the end of your next turn, it emits <a>Dim Light</a> in a 10-foot radius and can’t benefit from the <a>Invisible</a> condition.</p> <p><em><strong>Cantrip Upgrade.</strong></em> The damage increases by 1d8 when you reach levels 5 (2d8), 11 (3d8), and 17 (4d8).</p> </div>', '92f37fac-7da4-4df3-9441-15aa71549921'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', '92f37fac-7da4-4df3-9441-15aa71549921'::uuid),
