                    ('Range/Area', 'rangeArea', '{"text":"30 ft.","kind":"distance","distanceValue":30,"distanceUnit":"ft","area":null}', '', 'c048f24e-c0cd-41d5-9e57-88912264f984'::uuid),
                    ('Components', 'components', '{"text":"S, M *","verbal":false,"somatic":true,"material":{"required":true,"description":null,"consumed":null,"costGp":null}}', '', 'c048f24e-c0cd-41d5-9e57-88912264f984'::uuid),
                    ('Duration', 'duration', '{"text":"Instantaneous","kind":"instantaneous","value":null,"unit":null,"concentration":false,"endCondition":null}', '', 'c048f24e-c0cd-41d5-9e57-88912264f984'::uuid),
                    ('School', 'school', 'Conjuration', '', 'c048f24e-c0cd-41d5-9e57-88912264f984'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"Melee","kind":"attack","attackType":"melee","ability":null}', '', 'c048f24e-c0cd-41d5-9e57-88912264f984'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Force","damageTypes":["Force"]}', '', 'c048f24e-c0cd-41d5-9e57-88912264f984'::uuid),
                    ('Description', 'description', '["You flourish the weapon used in the casting and then vanish to strike like the wind. Choose up to five creatures you can see within range. Make a melee spell attack against each target. On a hit, a target takes 6d10 Force damage.","You then teleport to an unoccupied space you can see within 5 feet of one of the targets."]', '<p>You flourish the weapon used in the casting and then vanish to strike like the wind. Choose up to five creatures you can see within range. Make a melee spell attack against each target. On a hit, a target takes 6d10 Force damage.</p> <p>You then teleport to an unoccupied space you can see within 5 feet of one of the targets.</p>', 'c048f24e-c0cd-41d5-9e57-88912264f984'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', 'c048f24e-c0cd-41d5-9e57-88912264f984'::uuid),
