                    ('Level', 'level', '{"levelNumber":"4","label":"4th"}', '<div> <div> Level </div> <div> 4th </div> </div>', '6f0392e2-eb17-4f01-9609-3f0819fe01f7'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Action","kind":"action","value":1,"unit":"action","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Action </div> </div>', '6f0392e2-eb17-4f01-9609-3f0819fe01f7'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"Touch","kind":"touch","distanceValue":null,"distanceUnit":null,"area":null}', '<div> <div> Range/Area </div> <div> Touch </div> </div>', '6f0392e2-eb17-4f01-9609-3f0819fe01f7'::uuid),
                    ('Components', 'components', '{"text":"V, S, M *","verbal":true,"somatic":true,"material":{"required":true,"description":"diamond dust worth 100+ GP, which the spell consumes","consumed":true,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S, M *</span> </div> </div>', '6f0392e2-eb17-4f01-9609-3f0819fe01f7'::uuid),
                    ('Duration', 'duration', '{"text":"Concentration 1 Hour","kind":"timed","value":1,"unit":"hour","concentration":true,"endCondition":null}', '<div> <div>Duration</div> <div> <i>Concentration</i> 1 Hour </div> </div>', '6f0392e2-eb17-4f01-9609-3f0819fe01f7'::uuid),
                    ('School', 'school', 'Transmutation', '<div> <div> School </div> <div> Transmutation </div> </div>', '6f0392e2-eb17-4f01-9609-3f0819fe01f7'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"None","kind":"none","attackType":null,"ability":null}', '<div> <div> Attack/Save </div> <div> <span>None</span> </div> </div>', '6f0392e2-eb17-4f01-9609-3f0819fe01f7'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Buff","damageTypes":[]}', '<div> <div> Damage/Effect </div> <div> Buff </div> </div>', '6f0392e2-eb17-4f01-9609-3f0819fe01f7'::uuid),
                    ('Description', 'description', '["Until the spell ends, one willing creature you touch has Resistance to Bludgeoning, Piercing, and Slashing damage."]', '<div> <p>Until the spell ends, one willing creature you touch has Resistance to Bludgeoning, Piercing, and Slashing damage.</p> <span>* - (diamond dust worth 100+ GP, which the spell consumes)</span> </div>', '6f0392e2-eb17-4f01-9609-3f0819fe01f7'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', '6f0392e2-eb17-4f01-9609-3f0819fe01f7'::uuid),
                    ('Spell Tags', 'spellTags', '["Buff"]', '', '6f0392e2-eb17-4f01-9609-3f0819fe01f7'::uuid),
                    ('Available For', 'availableFor', '["Druid (Legacy)","Ranger (Legacy)","Sorcerer (Legacy)","Wizard (Legacy)","Artificer (Legacy)","Druid","Ranger","Sorcerer","Wizard","Artificer","Paladin - Oath of Conquest (XGtE)","Paladin - Oath of Redemption (XGtE)","Paladin - Oath of the Ancients","Cleric - Blood Domain (TCSR)"]', '', '6f0392e2-eb17-4f01-9609-3f0819fe01f7'::uuid),
                    ('Source', 'source', 'Player’s Handbook, pg. 320', '', '6f0392e2-eb17-4f01-9609-3f0819fe01f7'::uuid),
                    ('Source URL', 'url', 'https://www.dndbeyond.com/spells/2619095-stoneskin', '', '6f0392e2-eb17-4f01-9609-3f0819fe01f7'::uuid),
                    ('Image', 'imageUrl', 'https://www.dndbeyond.com/attachments/2/722/transmutation.png', '', '6f0392e2-eb17-4f01-9609-3f0819fe01f7'::uuid),
                    ('Level', 'level', '{"levelNumber":"9","label":"9th"}', '<div> <div> Level </div> <div> 9th </div> </div>', '54fc4526-3574-4d6d-bd08-d5fb8a205f93'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Action","kind":"action","value":1,"unit":"action","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Action </div> </div>', '54fc4526-3574-4d6d-bd08-d5fb8a205f93'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"1 mile","kind":"distance","distanceValue":1,"distanceUnit":"mile","area":null}', '<div> <div> Range/Area </div> <div> 1 mile </div> </div>', '54fc4526-3574-4d6d-bd08-d5fb8a205f93'::uuid),
                    ('Components', 'components', '{"text":"V, S","verbal":true,"somatic":true,"material":{"required":false,"description":null,"consumed":null,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S</span> </div> </div>', '54fc4526-3574-4d6d-bd08-d5fb8a205f93'::uuid),
                    ('Duration', 'duration', '{"text":"Concentration 1 Minute","kind":"timed","value":1,"unit":"minute","concentration":true,"endCondition":null}', '<div> <div>Duration</div> <div> <i>Concentration</i> 1 Minute </div> </div>', '54fc4526-3574-4d6d-bd08-d5fb8a205f93'::uuid),
                    ('School', 'school', 'Conjuration', '<div> <div> School </div> <div> Conjuration </div> </div>', '54fc4526-3574-4d6d-bd08-d5fb8a205f93'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"CON Save","kind":"save","attackType":null,"ability":"CON"}', '<div> <div> Attack/Save </div> <div> <i></i> <span>CON Save</span> </div> </div>', '54fc4526-3574-4d6d-bd08-d5fb8a205f93'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Thunder (...)","damageTypes":["Thunder"]}', '<div> <div> Damage/Effect </div> <div> <i></i> Thunder (...) </div> </div>', '54fc4526-3574-4d6d-bd08-d5fb8a205f93'::uuid),
                    ('Description', 'description', '["A churning storm cloud forms for the duration, centered on a point within range and spreading to a radius of 300 feet. Each creature under the cloud when it appears must succeed on a Constitution saving throw or take 2d6 Thunder damage and have the Deafened condition for the duration.","At the start of each of your later turns, the storm produces different effects, as detailed below.","Turn 2. Acidic rain falls. Each creature and object under the cloud takes 4d6 Acid damage.","Turn 3. You call six bolts of lightning from the cloud to strike six different creatures or objects beneath it. Each target makes a Dexterity saving throw, taking 10d6 Lightning damage on a failed save or half as much damage on a successful one.","Turn 4. Hailstones rain down. Each creature under the cloud takes 2d6 Bludgeoning damage.","Turns 5–10. Gusts and freezing rain assail the area under the cloud. Each creature there takes 1d6 Cold damage. Until the spell ends, the area is Difficult Terrain and Heavily Obscured , ranged attacks with weapons are impossible there, and strong wind blows through the area."]', '<div> <p>A churning storm cloud forms for the duration, centered on a point within range and spreading to a radius of 300 feet. Each creature under the cloud when it appears must succeed on a Constitution saving throw or take 2d6 Thunder damage and have the <a>Deafened</a> condition for the duration.</p> <p>At the start of each of your later turns, the storm produces different effects, as detailed below.</p> <p><strong><em>Turn 2.</em></strong> Acidic rain falls. Each creature and object under the cloud takes 4d6 Acid damage.</p> <p><strong><em>Turn 3.</em></strong> You call six bolts of lightning from the cloud to strike six different creatures or objects beneath it. Each target makes a Dexterity saving throw, taking 10d6 Lightning damage on a failed save or half as much damage on a successful one.</p> <p><strong><em>Turn 4.</em></strong> Hailstones rain down. Each creature under the cloud takes 2d6 Bludgeoning damage.</p> <p><strong><em>Turns 5–10.</em></strong> Gusts and freezing rain assail the area under the cloud. Each creature there takes 1d6 Cold damage. Until the spell ends, the area is <a>Difficult Terrain</a> and <a>Heavily Obscured</a>, ranged attacks with weapons are impossible there, and strong wind blows through the area.</p> </div>', '54fc4526-3574-4d6d-bd08-d5fb8a205f93'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', '54fc4526-3574-4d6d-bd08-d5fb8a205f93'::uuid),
                    ('Spell Tags', 'spellTags', '["Damage","Control","Debuff"]', '', '54fc4526-3574-4d6d-bd08-d5fb8a205f93'::uuid),
                    ('Available For', 'availableFor', '["Druid (Legacy)","Druid"]', '', '54fc4526-3574-4d6d-bd08-d5fb8a205f93'::uuid),
                    ('Source', 'source', 'Player’s Handbook, pg. 320', '', '54fc4526-3574-4d6d-bd08-d5fb8a205f93'::uuid),
                    ('Source URL', 'url', 'https://www.dndbeyond.com/spells/2619098-storm-of-vengeance', '', '54fc4526-3574-4d6d-bd08-d5fb8a205f93'::uuid),
                    ('Image', 'imageUrl', 'https://www.dndbeyond.com/attachments/2/708/conjuration.png', '', '54fc4526-3574-4d6d-bd08-d5fb8a205f93'::uuid);
