                    ('Available For', 'availableFor', '["Cleric (Legacy)","Druid (Legacy)","Sorcerer (Legacy)","Wizard (Legacy)","Cleric","Druid","Sorcerer","Wizard"]', '', 'beab53d0-e244-499a-8540-88f6fa9e1b8b'::uuid),
                    ('Source', 'source', 'Player’s Handbook, pg. 329', '', 'beab53d0-e244-499a-8540-88f6fa9e1b8b'::uuid),
                    ('Source URL', 'url', 'https://www.dndbeyond.com/spells/2619123-sunburst', '', 'beab53d0-e244-499a-8540-88f6fa9e1b8b'::uuid),
