                    ('Source URL', 'url', 'https://www.dndbeyond.com/spells/2619167-teleportation-circle', '', '65d50ae0-1ee0-4a9e-b56d-fabcdfb0f51f'::uuid),
                    ('Image', 'imageUrl', 'https://www.dndbeyond.com/attachments/2/708/conjuration.png', '', '65d50ae0-1ee0-4a9e-b56d-fabcdfb0f51f'::uuid),
                    ('Level', 'level', '{"levelNumber":"1","label":"1st"}', '<div> <div> Level </div> <div> 1st </div> </div>', '5b040144-3dd6-4ed7-9c5c-6e29f8cfe4db'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Action Ritual","kind":"action","value":1,"unit":"action","trigger":null,"ritual":true}', '<div> <div> Casting Time </div> <div> 1 Action <i>Ritual</i> </div> </div>', '5b040144-3dd6-4ed7-9c5c-6e29f8cfe4db'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"30 ft.","kind":"distance","distanceValue":30,"distanceUnit":"ft","area":null}', '<div> <div> Range/Area </div> <div> 30 ft. </div> </div>', '5b040144-3dd6-4ed7-9c5c-6e29f8cfe4db'::uuid),
                    ('Components', 'components', '{"text":"V, S, M *","verbal":true,"somatic":true,"material":{"required":true,"description":"a drop of mercury","consumed":false,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S, M *</span> </div> </div>', '5b040144-3dd6-4ed7-9c5c-6e29f8cfe4db'::uuid),
                    ('Duration', 'duration', '{"text":"1 Hour","kind":"timed","value":1,"unit":"hour","concentration":false,"endCondition":null}', '<div> <div>Duration</div> <div> 1 Hour </div> </div>', '5b040144-3dd6-4ed7-9c5c-6e29f8cfe4db'::uuid),
                    ('School', 'school', 'Conjuration', '<div> <div> School </div> <div> Conjuration </div> </div>', '5b040144-3dd6-4ed7-9c5c-6e29f8cfe4db'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"None","kind":"none","attackType":null,"ability":null}', '<div> <div> Attack/Save </div> <div> <span>None</span> </div> </div>', '5b040144-3dd6-4ed7-9c5c-6e29f8cfe4db'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Movement (...)","damageTypes":[]}', '<div> <div> Damage/Effect </div> <div> Movement (...) </div> </div>', '5b040144-3dd6-4ed7-9c5c-6e29f8cfe4db'::uuid),
                    ('Description', 'description', '["This spell creates a circular, horizontal plane of force, 3 feet in diameter and 1 inch thick, that floats 3 feet above the ground in an unoccupied space of your choice that you can see within range. The disk remains for the duration and can hold up to 500 pounds. If more weight is placed on it, the spell ends, and everything on the disk falls to the ground.","The disk is immobile while you are within 20 feet of it. If you move more than 20 feet away from it, the disk follows you so that it remains within 20 feet of you. It can move across uneven terrain, up or down stairs, slopes and the like, but it can’t cross an elevation change of 10 feet or more. For example, the disk can’t move across a 10-foot-deep pit, nor could it leave such a pit if it was created at the bottom.","If you move more than 100 feet from the disk (typically because it can’t move around an obstacle to follow you), the spell ends."]', '<div> <p>This spell creates a circular, horizontal plane of force, 3 feet in diameter and 1 inch thick, that floats 3 feet above the ground in an unoccupied space of your choice that you can see within range. The disk remains for the duration and can hold up to 500 pounds. If more weight is placed on it, the spell ends, and everything on the disk falls to the ground.</p> <p>The disk is immobile while you are within 20 feet of it. If you move more than 20 feet away from it, the disk follows you so that it remains within 20 feet of you. It can move across uneven terrain, up or down stairs, slopes and the like, but it can’t cross an elevation change of 10 feet or more. For example, the disk can’t move across a 10-foot-deep pit, nor could it leave such a pit if it was created at the bottom.</p> <p>If you move more than 100 feet from the disk (typically because it can’t move around an obstacle to follow you), the spell ends.</p> <span>* - (a drop of mercury)</span> </div>', '5b040144-3dd6-4ed7-9c5c-6e29f8cfe4db'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', '5b040144-3dd6-4ed7-9c5c-6e29f8cfe4db'::uuid),
