                    ('Available For', 'availableFor', '["Wizard (Legacy)","Wizard"]', '', '5b040144-3dd6-4ed7-9c5c-6e29f8cfe4db'::uuid),
                    ('Source', 'source', 'Player’s Handbook, pg. 332', '', '5b040144-3dd6-4ed7-9c5c-6e29f8cfe4db'::uuid),
                    ('Source URL', 'url', 'https://www.dndbeyond.com/spells/2619169-tensers-floating-disk', '', '5b040144-3dd6-4ed7-9c5c-6e29f8cfe4db'::uuid),
                    ('Image', 'imageUrl', 'https://www.dndbeyond.com/attachments/2/708/conjuration.png', '', '5b040144-3dd6-4ed7-9c5c-6e29f8cfe4db'::uuid),
                    ('Level', 'level', '{"levelNumber":"Cantrip","label":"Cantrip"}', '<div> <div> Level </div> <div> Cantrip </div> </div>', 'bfda4984-a819-4000-b884-ffca3b94f6f1'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Action","kind":"action","value":1,"unit":"action","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Action </div> </div>', 'bfda4984-a819-4000-b884-ffca3b94f6f1'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"30 ft.","kind":"distance","distanceValue":30,"distanceUnit":"ft","area":null}', '<div> <div> Range/Area </div> <div> 30 ft. </div> </div>', 'bfda4984-a819-4000-b884-ffca3b94f6f1'::uuid),
                    ('Components', 'components', '{"text":"V","verbal":true,"somatic":false,"material":{"required":false,"description":null,"consumed":null,"costGp":null}}', '<div> <div> Components </div> <div> <span>V</span> </div> </div>', 'bfda4984-a819-4000-b884-ffca3b94f6f1'::uuid),
                    ('Duration', 'duration', '{"text":"1 Minute","kind":"timed","value":1,"unit":"minute","concentration":false,"endCondition":null}', '<div> <div>Duration</div> <div> 1 Minute </div> </div>', 'bfda4984-a819-4000-b884-ffca3b94f6f1'::uuid),
                    ('School', 'school', 'Transmutation', '<div> <div> School </div> <div> Transmutation </div> </div>', 'bfda4984-a819-4000-b884-ffca3b94f6f1'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"None","kind":"none","attackType":null,"ability":null}', '<div> <div> Attack/Save </div> <div> <span>None</span> </div> </div>', 'bfda4984-a819-4000-b884-ffca3b94f6f1'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Control","damageTypes":[]}', '<div> <div> Damage/Effect </div> <div> Control </div> </div>', 'bfda4984-a819-4000-b884-ffca3b94f6f1'::uuid),
                    ('Description', 'description', '["You manifest a minor wonder within range. You create one of the effects below within range. If you cast this spell multiple times, you can have up to three of its 1-minute effects active at a time.","Altered Eyes. You alter the appearance of your eyes for 1 minute.","Booming Voice. Your voice booms up to three times as loud as normal for 1 minute. For the duration, you have Advantage on Charisma ( Intimidation ) checks.","Fire Play. You cause flames to flicker, brighten, dim, or change color for 1 minute.","Invisible Hand. You instantaneously cause an unlocked door or window to fly open or slam shut.","Phantom Sound. You create an instantaneous sound that originates from a point of your choice within range, such as a rumble of thunder, the cry of a raven, or ominous whispers.","Tremors. You cause harmless tremors in the ground for 1 minute."]', '<div> <p>You manifest a minor wonder within range. You create one of the effects below within range. If you cast this spell multiple times, you can have up to three of its 1-minute effects active at a time.</p> <p><strong><em>Altered Eyes.</em></strong> You alter the appearance of your eyes for 1 minute.</p> <p><strong><em>Booming Voice.</em></strong> Your voice booms up to three times as loud as normal for 1 minute. For the duration, you have Advantage on Charisma (<a>Intimidation</a>) checks.</p> <p><strong><em>Fire Play.</em></strong> You cause flames to flicker, brighten, dim, or change color for 1 minute.</p> <p><strong><em>Invisible Hand.</em></strong> You instantaneously cause an unlocked door or window to fly open or slam shut.</p> <p><strong><em>Phantom Sound.</em></strong> You create an instantaneous sound that originates from a point of your choice within range, such as a rumble of thunder, the cry of a raven, or ominous whispers.</p> <p><strong><em>Tremors.</em></strong> You cause harmless tremors in the ground for 1 minute.</p> </div>', 'bfda4984-a819-4000-b884-ffca3b94f6f1'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', 'bfda4984-a819-4000-b884-ffca3b94f6f1'::uuid),
