                    ('Range/Area', 'rangeArea', '{"text":"Self (5 ft.)","kind":"self","distanceValue":null,"distanceUnit":null,"area":{"shape":"Emanation","value":5,"unit":"ft"}}', '<div> <div> Range/Area </div> <div> Self (5 ft.) </div> </div>', '05025bbd-c57f-4b5d-ac83-74ccd737c36c'::uuid),
                    ('Components', 'components', '{"text":"S","verbal":false,"somatic":true,"material":{"required":false,"description":null,"consumed":null,"costGp":null}}', '<div> <div> Components </div> <div> <span>S</span> </div> </div>', '05025bbd-c57f-4b5d-ac83-74ccd737c36c'::uuid),
                    ('Duration', 'duration', '{"text":"Instantaneous","kind":"instantaneous","value":null,"unit":null,"concentration":false,"endCondition":null}', '<div> <div>Duration</div> <div> Instantaneous </div> </div>', '05025bbd-c57f-4b5d-ac83-74ccd737c36c'::uuid),
                    ('School', 'school', 'Evocation', '<div> <div> School </div> <div> Evocation </div> </div>', '05025bbd-c57f-4b5d-ac83-74ccd737c36c'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"CON Save","kind":"save","attackType":null,"ability":"CON"}', '<div> <div> Attack/Save </div> <div> <i></i> <span>CON Save</span> </div> </div>', '05025bbd-c57f-4b5d-ac83-74ccd737c36c'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Thunder","damageTypes":["Thunder"]}', '<div> <div> Damage/Effect </div> <div> <i></i> Thunder </div> </div>', '05025bbd-c57f-4b5d-ac83-74ccd737c36c'::uuid),
                    ('Description', 'description', '["Each creature in a 5-foot Emanation originating from you must succeed on a Constitution saving throw or take 1d6 Thunder damage. The spell’s thunderous sound can be heard up to 100 feet away.","Cantrip Upgrade. The damage increases by 1d6 when you reach levels 5 (2d6), 11 (3d6), and 17 (4d6)."]', '<div> <p>Each creature in a 5-foot Emanation originating from you must succeed on a Constitution saving throw or take 1d6 Thunder damage. The spell’s thunderous sound can be heard up to 100 feet away.</p> <p><strong><em>Cantrip Upgrade.</em></strong> The damage increases by 1d6 when you reach levels 5 (2d6), 11 (3d6), and 17 (4d6).</p> </div>', '05025bbd-c57f-4b5d-ac83-74ccd737c36c'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', '05025bbd-c57f-4b5d-ac83-74ccd737c36c'::uuid);
