            migrationBuilder.Sql("""
                INSERT INTO "SpellComponents" ("Label", "Key", "Value", "Html", "SpellId") VALUES
                    ('Spell Tags', 'spellTags', '["Damage"]', '', '05025bbd-c57f-4b5d-ac83-74ccd737c36c'::uuid),
                    ('Available For', 'availableFor', '["Bard","Druid","Sorcerer","Warlock","Wizard"]', '', '05025bbd-c57f-4b5d-ac83-74ccd737c36c'::uuid),
                    ('Source', 'source', 'Player’s Handbook', '', '05025bbd-c57f-4b5d-ac83-74ccd737c36c'::uuid),
                    ('Source URL', 'url', 'https://www.dndbeyond.com/spells/2619179-thunderclap', '', '05025bbd-c57f-4b5d-ac83-74ccd737c36c'::uuid),
                    ('Image', 'imageUrl', 'https://www.dndbeyond.com/attachments/2/703/evocation.png', '', '05025bbd-c57f-4b5d-ac83-74ccd737c36c'::uuid),
                    ('Level', 'level', '{"levelNumber":"1","label":"1st"}', '', 'f1cda7ae-4e11-4a96-b2d2-ec976f9831b2'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Bonus Action *","kind":"bonus_action","value":1,"unit":"action","trigger":null,"ritual":false}', '', 'f1cda7ae-4e11-4a96-b2d2-ec976f9831b2'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"Self","kind":"self","distanceValue":null,"distanceUnit":null,"area":null}', '', 'f1cda7ae-4e11-4a96-b2d2-ec976f9831b2'::uuid),
                    ('Components', 'components', '{"text":"V","verbal":true,"somatic":false,"material":{"required":false,"description":null,"consumed":null,"costGp":null}}', '', 'f1cda7ae-4e11-4a96-b2d2-ec976f9831b2'::uuid),
                    ('Duration', 'duration', '{"text":"Instantaneous","kind":"instantaneous","value":null,"unit":null,"concentration":false,"endCondition":null}', '', 'f1cda7ae-4e11-4a96-b2d2-ec976f9831b2'::uuid),
                    ('School', 'school', 'Evocation', '', 'f1cda7ae-4e11-4a96-b2d2-ec976f9831b2'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"STR Save","kind":"save","attackType":null,"ability":"STR"}', '', 'f1cda7ae-4e11-4a96-b2d2-ec976f9831b2'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Thunder","damageTypes":["Thunder"]}', '', 'f1cda7ae-4e11-4a96-b2d2-ec976f9831b2'::uuid),
                    ('Description', 'description', '["Your strike rings with thunder that is audible within 300 feet of you, and the target takes an extra 2d6 Thunder damage from the attack. Additionally, if the target is a creature, it must succeed on a Strength saving throw or be pushed 10 feet away from you and have the Prone condition.","Using a Higher-Level Spell Slot. The damage increases by 1d6 for each spell slot level above 1."]', '<p>Your strike rings with thunder that is audible within 300 feet of you, and the target takes an extra 2d6 Thunder damage from the attack. Additionally, if the target is a creature, it must succeed on a Strength saving throw or be pushed 10 feet away from you and have the Prone condition.</p> <p>Using a Higher-Level Spell Slot. The damage increases by 1d6 for each spell slot level above 1.</p>', 'f1cda7ae-4e11-4a96-b2d2-ec976f9831b2'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', 'f1cda7ae-4e11-4a96-b2d2-ec976f9831b2'::uuid),
                    ('Spell Tags', 'spellTags', '[]', '', 'f1cda7ae-4e11-4a96-b2d2-ec976f9831b2'::uuid),
                    ('Available For', 'availableFor', '["Paladin"]', '', 'f1cda7ae-4e11-4a96-b2d2-ec976f9831b2'::uuid),
                    ('Source', 'source', 'Player’s Handbook (2024)', '', 'f1cda7ae-4e11-4a96-b2d2-ec976f9831b2'::uuid),
                    ('Source URL', 'url', 'https://www.dndbeyond.com/spells/2619182-thunderous-smite', '', 'f1cda7ae-4e11-4a96-b2d2-ec976f9831b2'::uuid),
                    ('Image', 'imageUrl', '', '', 'f1cda7ae-4e11-4a96-b2d2-ec976f9831b2'::uuid),
                    ('Level', 'level', '{"levelNumber":"1","label":"1st"}', '<div> <div> Level </div> <div> 1st </div> </div>', '6a34b5ed-b2da-4918-807e-aa327c0cfd23'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Action","kind":"action","value":1,"unit":"action","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Action </div> </div>', '6a34b5ed-b2da-4918-807e-aa327c0cfd23'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"Self (15 ft.)","kind":"self","distanceValue":null,"distanceUnit":null,"area":{"shape":null,"value":15,"unit":"ft"}}', '<div> <div> Range/Area </div> <div> Self <span>(15 ft. <i></i>)</span> </div> </div>', '6a34b5ed-b2da-4918-807e-aa327c0cfd23'::uuid),
                    ('Components', 'components', '{"text":"V, S","verbal":true,"somatic":true,"material":{"required":false,"description":null,"consumed":null,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S</span> </div> </div>', '6a34b5ed-b2da-4918-807e-aa327c0cfd23'::uuid),
                    ('Duration', 'duration', '{"text":"Instantaneous","kind":"instantaneous","value":null,"unit":null,"concentration":false,"endCondition":null}', '<div> <div>Duration</div> <div> Instantaneous </div> </div>', '6a34b5ed-b2da-4918-807e-aa327c0cfd23'::uuid),
                    ('School', 'school', 'Evocation', '<div> <div> School </div> <div> Evocation </div> </div>', '6a34b5ed-b2da-4918-807e-aa327c0cfd23'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"CON Save","kind":"save","attackType":null,"ability":"CON"}', '<div> <div> Attack/Save </div> <div> <i></i> <span>CON Save</span> </div> </div>', '6a34b5ed-b2da-4918-807e-aa327c0cfd23'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Thunder","damageTypes":["Thunder"]}', '<div> <div> Damage/Effect </div> <div> <i></i> Thunder </div> </div>', '6a34b5ed-b2da-4918-807e-aa327c0cfd23'::uuid),
                    ('Description', 'description', '["You unleash a wave of thunderous energy. Each creature in a 15-foot Cube originating from you makes a Constitution saving throw. On a failed save, a creature takes 2d8 Thunder damage and is pushed 10 feet away from you. On a successful save, a creature takes half as much damage only.","In addition, unsecured objects that are entirely within the Cube are pushed 10 feet away from you, and a thunderous boom is audible within 300 feet.","Using a Higher-Level Spell Slot. The damage increases by 1d8 for each spell slot level above 1."]', '<div> <p>You unleash a wave of thunderous energy. Each creature in a 15-foot <a>Cube</a> originating from you makes a Constitution saving throw. On a failed save, a creature takes 2d8 Thunder damage and is pushed 10 feet away from you. On a successful save, a creature takes half as much damage only.</p> <p>In addition, unsecured objects that are entirely within the Cube are pushed 10 feet away from you, and a thunderous boom is audible within 300 feet.</p> <p><strong><em>Using a Higher-Level Spell Slot.</em></strong> The damage increases by 1d8 for each spell slot level above 1.</p> </div>', '6a34b5ed-b2da-4918-807e-aa327c0cfd23'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', '6a34b5ed-b2da-4918-807e-aa327c0cfd23'::uuid),
