                    ('Components', 'components', '{"text":"V, S, M *","verbal":true,"somatic":true,"material":{"required":true,"description":"a drop of water","consumed":false,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S, M *</span> </div> </div>', '5c53a929-2c75-4a9a-b6b5-202d66b7a3ac'::uuid),
