                    ('Source', 'source', 'Player’s Handbook, pg. 335', '', 'dfd20c85-731f-4e94-a3b7-97e178b0dea2'::uuid),
                    ('Source URL', 'url', 'https://www.dndbeyond.com/spells/2619198-true-polymorph', '', 'dfd20c85-731f-4e94-a3b7-97e178b0dea2'::uuid),
                    ('Image', 'imageUrl', 'https://www.dndbeyond.com/attachments/2/722/transmutation.png', '', 'dfd20c85-731f-4e94-a3b7-97e178b0dea2'::uuid),
                    ('Level', 'level', '{"levelNumber":"9","label":"9th"}', '<div> <div> Level </div> <div> 9th </div> </div>', '6545d659-1b8c-4a2c-ae3a-62ff5082261b'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Hour","kind":"timed","value":1,"unit":"hour","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Hour </div> </div>', '6545d659-1b8c-4a2c-ae3a-62ff5082261b'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"Touch","kind":"touch","distanceValue":null,"distanceUnit":null,"area":null}', '<div> <div> Range/Area </div> <div> Touch </div> </div>', '6545d659-1b8c-4a2c-ae3a-62ff5082261b'::uuid),
                    ('Components', 'components', '{"text":"V, S, M *","verbal":true,"somatic":true,"material":{"required":true,"description":"diamonds worth 25,000+ GP, which the spell consumes","consumed":true,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S, M *</span> </div> </div>', '6545d659-1b8c-4a2c-ae3a-62ff5082261b'::uuid),
                    ('Duration', 'duration', '{"text":"Instantaneous","kind":"instantaneous","value":null,"unit":null,"concentration":false,"endCondition":null}', '<div> <div>Duration</div> <div> Instantaneous </div> </div>', '6545d659-1b8c-4a2c-ae3a-62ff5082261b'::uuid),
                    ('School', 'school', 'Necromancy', '<div> <div> School </div> <div> Necromancy </div> </div>', '6545d659-1b8c-4a2c-ae3a-62ff5082261b'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"None","kind":"none","attackType":null,"ability":null}', '<div> <div> Attack/Save </div> <div> <span>None</span> </div> </div>', '6545d659-1b8c-4a2c-ae3a-62ff5082261b'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Healing","damageTypes":[]}', '<div> <div> Damage/Effect </div> <div> Healing </div> </div>', '6545d659-1b8c-4a2c-ae3a-62ff5082261b'::uuid),
                    ('Description', 'description', '["You touch a creature that has been dead for no longer than 200 years and that died for any reason except old age. The creature is revived with all its Hit Points.","This spell closes all wounds, neutralizes any poison, cures all magical contagions, and lifts any curses affecting the creature when it died. The spell replaces damaged or missing organs and limbs. If the creature was Undead, it is restored to its non-Undead form.","The spell can provide a new body if the original no longer exists, in which case you must speak the creature’s name. The creature then appears in an unoccupied space you choose within 10 feet of you."]', '<div> <p>You touch a creature that has been dead for no longer than 200 years and that died for any reason except old age. The creature is revived with all its Hit Points.</p> <p>This spell closes all wounds, neutralizes any poison, cures all magical contagions, and lifts any <a>curses</a> affecting the creature when it died. The spell replaces damaged or missing organs and limbs. If the creature was Undead, it is restored to its non-Undead form.</p> <p>The spell can provide a new body if the original no longer exists, in which case you must speak the creature’s name. The creature then appears in an unoccupied space you choose within 10 feet of you.</p> <span>* - (diamonds worth 25,000+ GP, which the spell consumes)</span> </div>', '6545d659-1b8c-4a2c-ae3a-62ff5082261b'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', '6545d659-1b8c-4a2c-ae3a-62ff5082261b'::uuid),
                    ('Spell Tags', 'spellTags', '["Healing"]', '', '6545d659-1b8c-4a2c-ae3a-62ff5082261b'::uuid),
                    ('Available For', 'availableFor', '["Cleric (Legacy)","Druid (Legacy)","Cleric","Druid"]', '', '6545d659-1b8c-4a2c-ae3a-62ff5082261b'::uuid),
                    ('Source', 'source', 'Player’s Handbook, pg. 336', '', '6545d659-1b8c-4a2c-ae3a-62ff5082261b'::uuid),
