                    ('Image', 'imageUrl', 'https://www.dndbeyond.com/attachments/2/720/necromancy.png', '', '6545d659-1b8c-4a2c-ae3a-62ff5082261b'::uuid),
                    ('Level', 'level', '{"levelNumber":"6","label":"6th"}', '<div> <div> Level </div> <div> 6th </div> </div>', '83aa3428-cec0-4e08-a74a-6b6546e48f08'::uuid),
                    ('Casting Time', 'castingTime', '{"text":"1 Action","kind":"action","value":1,"unit":"action","trigger":null,"ritual":false}', '<div> <div> Casting Time </div> <div> 1 Action </div> </div>', '83aa3428-cec0-4e08-a74a-6b6546e48f08'::uuid),
                    ('Range/Area', 'rangeArea', '{"text":"Touch","kind":"touch","distanceValue":null,"distanceUnit":null,"area":null}', '<div> <div> Range/Area </div> <div> Touch </div> </div>', '83aa3428-cec0-4e08-a74a-6b6546e48f08'::uuid),
                    ('Components', 'components', '{"text":"V, S, M *","verbal":true,"somatic":true,"material":{"required":true,"description":"mushroom powder worth 25+ GP, which the spell consumes","consumed":true,"costGp":null}}', '<div> <div> Components </div> <div> <span>V, S, M *</span> </div> </div>', '83aa3428-cec0-4e08-a74a-6b6546e48f08'::uuid),
                    ('Duration', 'duration', '{"text":"1 Hour","kind":"timed","value":1,"unit":"hour","concentration":false,"endCondition":null}', '<div> <div>Duration</div> <div> 1 Hour </div> </div>', '83aa3428-cec0-4e08-a74a-6b6546e48f08'::uuid),
                    ('School', 'school', 'Divination', '<div> <div> School </div> <div> Divination </div> </div>', '83aa3428-cec0-4e08-a74a-6b6546e48f08'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"None","kind":"none","attackType":null,"ability":null}', '<div> <div> Attack/Save </div> <div> <span>None</span> </div> </div>', '83aa3428-cec0-4e08-a74a-6b6546e48f08'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Detection","damageTypes":[]}', '<div> <div> Damage/Effect </div> <div> Detection </div> </div>', '83aa3428-cec0-4e08-a74a-6b6546e48f08'::uuid),
                    ('Description', 'description', '["For the duration, the willing creature you touch has Truesight with a range of 120 feet."]', '<div> <p>For the duration, the willing creature you touch has <a>Truesight</a> with a range of 120 feet.</p> <span>* - (mushroom powder worth 25+ GP, which the spell consumes)</span> </div>', '83aa3428-cec0-4e08-a74a-6b6546e48f08'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', '83aa3428-cec0-4e08-a74a-6b6546e48f08'::uuid),
