                    ('Range/Area', 'rangeArea', '{"text":"60 ft.","kind":"distance","distanceValue":60,"distanceUnit":"ft","area":null}', '<div> <div> Range/Area </div> <div> 60 ft. </div> </div>', '15ad555b-c9f4-44db-acb2-877d4a1ad0cc'::uuid),
                    ('Components', 'components', '{"text":"V","verbal":true,"somatic":false,"material":{"required":false,"description":null,"consumed":null,"costGp":null}}', '<div> <div> Components </div> <div> <span>V</span> </div> </div>', '15ad555b-c9f4-44db-acb2-877d4a1ad0cc'::uuid),
                    ('Duration', 'duration', '{"text":"Instantaneous","kind":"instantaneous","value":null,"unit":null,"concentration":false,"endCondition":null}', '<div> <div>Duration</div> <div> Instantaneous </div> </div>', '15ad555b-c9f4-44db-acb2-877d4a1ad0cc'::uuid),
                    ('School', 'school', 'Enchantment', '<div> <div> School </div> <div> Enchantment </div> </div>', '15ad555b-c9f4-44db-acb2-877d4a1ad0cc'::uuid),
                    ('Attack/Save', 'attackSave', '{"text":"WIS Save","kind":"save","attackType":null,"ability":"WIS"}', '<div> <div> Attack/Save </div> <div> <i></i> <span>WIS Save</span> </div> </div>', '15ad555b-c9f4-44db-acb2-877d4a1ad0cc'::uuid),
                    ('Damage/Effect', 'damageEffect', '{"text":"Psychic","damageTypes":["Psychic"]}', '<div> <div> Damage/Effect </div> <div> <i></i> Psychic </div> </div>', '15ad555b-c9f4-44db-acb2-877d4a1ad0cc'::uuid),
                    ('Description', 'description', '["You unleash a string of insults laced with subtle enchantments at one creature you can see or hear within range. The target must succeed on a Wisdom saving throw or take 1d6 Psychic damage and have Disadvantage on the next attack roll it makes before the end of its next turn.","Cantrip Upgrade. The damage increases by 1d6 when you reach levels 5 (2d6), 11 (3d6), and 17 (4d6)."]', '<div> <p>You unleash a string of insults laced with subtle enchantments at one creature you can see or hear within range. The target must succeed on a Wisdom saving throw or take 1d6 Psychic damage and have Disadvantage on the next attack roll it makes before the end of its next turn.</p> <p><strong><em>Cantrip Upgrade.</em></strong> The damage increases by 1d6 when you reach levels 5 (2d6), 11 (3d6), and 17 (4d6).</p> </div>', '15ad555b-c9f4-44db-acb2-877d4a1ad0cc'::uuid),
                    ('Casting Time Note', 'castingTimeBlurb', '', '', '15ad555b-c9f4-44db-acb2-877d4a1ad0cc'::uuid),
