                    ('Source', 'source', 'Player’s Handbook (2024)', '', 'b8e02d20-efce-4316-98bb-ecec10b15a3b'::uuid),
                    ('Source URL', 'url', 'https://www.dndbeyond.com/spells/2619220-wrathful-smite', '', 'b8e02d20-efce-4316-98bb-ecec10b15a3b'::uuid),
                    ('Image', 'imageUrl', '', '', 'b8e02d20-efce-4316-98bb-ecec10b15a3b'::uuid),
